@import url("https://fonts.googleapis.com/css2?family=Inclusive+Sans:ital,wght@0,300..700;1,300..700&display=swap");

/* 1. ALL @imports must be at the very top */
@import "tailwindcss";
@import "../../../node_modules/preline/variants.css";

/* 2. Then @plugin and @source */
@plugin "@tailwindcss/forms";
@source "../../../node_modules/preline/dist/*.js";

/* 3. Then @layer and @custom-variant */
@layer theme, base, components, pages, utilities;
@variant dark (&:where(.dark, .dark *));

/* ================================================================
   ICU COMMAND CENTER · icu.html (page-exclusive)
   Mission-Control critical-care ops.
   Namespace: ic-   ·   FULLY theme-aware: light widgets in light
   mode, dark widgets in dark mode. Only the hero banner and the
   small ECG "screen" inset stay dark (like a real monitor).
   Do not reuse these classes in other modules.
   ================================================================ */
#ic-page {
    --ic-c: var(--color-primary);
    --ic-surface: var(--color-white);
    --ic-panel: var(--color-gray-50);
    --ic-border: var(--color-border-color);
    --ic-text: var(--color-gray-900);
    --ic-mut: var(--color-gray-500);
    --ic-elev: var(--color-white);
    --ic-hover: var(--color-gray-100);
    --ic-screen: #0a1120; /* device screen — always dark */
    --ic-grid: rgba(100, 116, 139, 0.09);
    --ic-track: color-mix(in srgb, var(--color-gray-500) 20%, transparent);
}
.dark #ic-page {
    --ic-surface: #0b1120;
    --ic-panel: rgba(148, 163, 184, 0.06);
    --ic-border: rgba(148, 163, 184, 0.16);
    --ic-text: #e2e8f0;
    --ic-mut: #94a3b8;
    --ic-elev: #0d1526;
    --ic-hover: rgba(148, 163, 184, 0.12);
    --ic-grid: rgba(148, 163, 184, 0.05);
    --ic-track: rgba(148, 163, 184, 0.2);
}

.ic-canvas {
    background: var(--ic-surface);
    border: 1px solid var(--ic-border);
    border-radius: 1.25rem;
    color: var(--ic-text);
    box-shadow: 0 20px 45px -38px rgba(15, 23, 42, 0.35);
}
.ic-glass {
    background: var(--ic-panel);
    border: 1px solid var(--ic-border);
    border-radius: 1rem;
}
.ic-glass2 {
    background: var(--ic-panel);
    border: 1px solid var(--ic-border);
    border-radius: 0.9rem;
}
.ic-mut {
    color: var(--ic-mut);
}
.ic-head {
    color: var(--ic-text);
}
.ic-grid-bg {
    background-image:
        linear-gradient(var(--ic-grid) 1px, transparent 1px),
        linear-gradient(90deg, var(--ic-grid) 1px, transparent 1px);
    background-size: 26px 26px;
}

/* ---------- HERO (dark banner in both themes, like other flagship pages) ---------- */
.ic-hero {
    position: relative;
    overflow: hidden;
    border-radius: 1.25rem;
    color: #fff;
    background:
        radial-gradient(
            120% 90% at 0% 0%,
            rgba(56, 189, 248, 0.18),
            transparent 55%
        ),
        radial-gradient(
            120% 90% at 100% 0%,
            rgba(244, 63, 94, 0.16),
            transparent 50%
        ),
        linear-gradient(160deg, #070b16, #0b1120 60%, #070a12);
    border: 1px solid rgba(148, 163, 184, 0.2);
    box-shadow: 0 30px 60px -30px rgba(2, 6, 15, 0.7);
}

.text-xs{
    font-size:12px;
}
.ic-hero .ic-hgrid {
    position: absolute;
    inset: 0;
    background-image:
        linear-gradient(rgba(148, 163, 184, 0.06) 1px, transparent 1px),
        linear-gradient(90deg, rgba(148, 163, 184, 0.06) 1px, transparent 1px);
    background-size: 26px 26px;
    pointer-events: none;
}
.ic-hstat {
    background: rgba(148, 163, 184, 0.08);
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 0.9rem;
    padding: 0.6rem 0.8rem;
}

.ic-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.68rem;
    font-weight: 700;
    padding: 0.22rem 0.55rem;
    border-radius: 999px;
    letter-spacing: 0.02em;
}
.ic-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    display: inline-block;
}
@keyframes ic-pulse {
    0%,
    100% {
        opacity: 1;
        transform: scale(1);
    }
    50% {
        opacity: 0.35;
        transform: scale(0.82);
    }
}
.ic-live {
    animation: ic-pulse 1.4s infinite;
}
@keyframes ic-blink {
    0%,
    100% {
        opacity: 1;
    }
    50% {
        opacity: 0.25;
    }
}

/* status colors */
.st-green {
    --sc: #16a34a;
}
.st-yellow {
    --sc: #ca8a04;
}
.st-orange {
    --sc: #ea580c;
}
.st-red {
    --sc: #dc2626;
}
.st-gray {
    --sc: #64748b;
}
.dark .st-green {
    --sc: #22c55e;
}
.dark .st-yellow {
    --sc: #eab308;
}
.dark .st-orange {
    --sc: #f97316;
}
.dark .st-red {
    --sc: #ef4444;
}
.dark .st-gray {
    --sc: #94a3b8;
}

/* ---------- ALERT RIBBON ---------- */
.ic-ribbon {
    overflow: hidden;
    position: relative;
}
.ic-ribbon-track {
    display: flex;
    gap: 0.6rem;
    width: max-content;
    animation: ic-marquee 28s linear infinite;
}
.ic-ribbon:hover .ic-ribbon-track {
    animation-play-state: paused;
}
@keyframes ic-marquee {
    from {
        transform: translateX(0);
    }
    to {
        transform: translateX(-50%);
    }
}
.ic-alert {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    font-size: 0.76rem;
    font-weight: 700;
    padding: 0.4rem 0.8rem;
    border-radius: 0.6rem;
    white-space: nowrap;
    border: 1px solid;
}

/* ---------- BED TILE ---------- */
.ic-bed {
    position: relative;
    border-radius: 0.9rem;
    padding: 0.7rem;
    cursor: pointer;
    overflow: hidden;
    background: var(--ic-panel);
    border: 1px solid color-mix(in srgb, var(--sc) 40%, var(--ic-border));
    transition:
        transform 0.18s,
        box-shadow 0.18s;
}
.ic-bed:hover {
    transform: translateY(-3px);
    box-shadow:
        0 18px 34px -22px rgba(15, 23, 42, 0.45),
        0 0 0 1px var(--sc);
}
.ic-bed::before {
    content: "";
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    width: 4px;
    background: var(--sc);
    box-shadow: 0 0 10px var(--sc);
}
.ic-bed .risk {
    background: color-mix(in srgb, var(--sc) 18%, transparent);
    color: var(--sc);
}
.ic-bed-empty {
    border-style: dashed;
}
.ic-bed .preview {
    position: absolute;
    inset: auto 0.5rem 0.5rem;
    opacity: 0;
    transform: translateY(6px);
    transition: 0.2s;
    pointer-events: none;
}
.ic-bed:hover .preview {
    opacity: 1;
    transform: none;
}

/* ---------- MONITOR ---------- */
.ic-monitor {
    background: var(--ic-panel);
    border: 1px solid var(--ic-border);
    border-radius: 1rem;
    overflow: hidden;
}
.ic-screen {
    background: var(--ic-screen);
    border-radius: 0.6rem;
}
.ic-vital {
    font-variant-numeric: tabular-nums;
}
.ic-ecg polyline {
    filter: drop-shadow(0 0 3px currentColor);
}
.ic-stability {
    height: 6px;
    border-radius: 999px;
    background: var(--ic-track);
    overflow: hidden;
}
.ic-stability > span {
    display: block;
    height: 100%;
    border-radius: 999px;
    transition: width 0.6s;
}

/* ---------- HEATMAP ---------- */
.ic-heat {
    border-radius: 0.6rem;
    padding: 0.5rem;
    text-align: center;
    border: 1px solid;
}

/* ---------- MENU / MODAL / DRAWER ---------- */
.ic-menu {
    position: fixed;
    z-index: 120;
    width: 210px;
    max-height: 70vh;
    overflow-y: auto;
    background: var(--ic-elev);
    border: 1px solid var(--ic-border);
    border-radius: 0.9rem;
    box-shadow: 0 30px 60px -20px rgba(15, 23, 42, 0.5);
    padding: 0.35rem;
    color: var(--ic-text);
}
.ic-menu button {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    width: 100%;
    text-align: left;
    font-size: 0.8rem;
    padding: 0.5rem 0.6rem;
    border-radius: 0.5rem;
    color: var(--ic-text);
}
.ic-menu button:hover {
    background: var(--ic-hover);
}
.ic-menu button.danger {
    color: #dc2626;
}
.ic-menu button.danger:hover {
    background: color-mix(in srgb, #ef4444 12%, transparent);
}

.ic-formlabel {
    font-size: 0.72rem;
    font-weight: 600;
    color: var(--ic-mut);
    text-transform: uppercase;
    letter-spacing: 0.03em;
}
.ic-btn {
    font-size: 0.82rem;
    font-weight: 600;
    padding: 0.55rem 0.95rem;
    border-radius: 0.55rem;
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    transition: 0.15s;
}
.ic-btn-primary {
    background: var(--ic-c);
    color: #fff;
}
.ic-btn-primary:hover {
    opacity: 0.92;
}
.ic-btn-ghost {
    background: transparent;
    border: 1px solid var(--ic-border);
    color: var(--ic-text);
}
.ic-btn-ghost:hover {
    background: var(--ic-hover);
}
.ic-btn-danger {
    background: #dc2626;
    color: #fff;
}
.ic-btn-danger:hover {
    background: #b91c1c;
}
.ic-drawer {
    position: fixed;
    top: 0;
    right: 0;
    height: 100%;
    width: min(460px, 96vw);
    background: var(--ic-elev);
    color: var(--ic-text);
    z-index: 125;
    transform: translateX(100%);
    transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    box-shadow: -30px 0 70px -30px rgba(15, 23, 42, 0.5);
    overflow-y: auto;
    border-left: 1px solid var(--ic-border);
}
.ic-drawer.open {
    transform: none;
}
.ic-in {
    width: 100%;
    padding: 0.5rem 0.7rem;
    font-size: 0.82rem;
    border: 1px solid var(--ic-border);
    border-radius: 0.6rem;
    background: var(--ic-panel);
    color: var(--ic-text);
}
.ic-in:focus {
    outline: none;
    border-color: var(--ic-c);
    box-shadow: 0 0 0 3px color-mix(in srgb, var(--ic-c) 20%, transparent);
}
.ic-in::placeholder {
    color: var(--ic-mut);
}

.ic-toast {
    position: fixed;
    bottom: 1.25rem;
    left: 50%;
    transform: translateX(-50%) translateY(120%);
    z-index: 140;
    background: #0d1526;
    color: #fff;
    border: 1px solid rgba(148, 163, 184, 0.25);
    padding: 0.7rem 1.1rem;
    border-radius: 0.8rem;
    font-size: 0.82rem;
    font-weight: 500;
    box-shadow: 0 20px 40px -18px rgba(0, 0, 0, 0.55);
    display: flex;
    align-items: center;
    gap: 0.5rem;
    transition: transform 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}
.ic-toast.show {
    transform: translateX(-50%) translateY(0);
}

/* ---------- SKELETON ---------- */
.ic-sk {
    position: relative;
    overflow: hidden;
    background: var(--color-gray-200);
    border-radius: 1rem;
}
.ic-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in srgb, var(--color-white) 55%, transparent),
        transparent
    );
    animation: ic-shim 1.4s infinite;
}
@keyframes ic-shim {
    100% {
        transform: translateX(100%);
    }
}
.ic-drop {
    background-image: repeating-linear-gradient(
        0deg,
        var(--ic-border) 0,
        var(--ic-border) 6px,
        transparent 6px,
        transparent 12px
    );
}

/* ================================================================
   OT CALENDAR & SURGICAL SCHEDULING CENTER · ot-calendar.html (page-exclusive)
   Namespace: oc-  ·  Theme-aware · Lucide icons (icon-*).
   Planning-focused — distinct from live-ops operation-theater.
   Do not reuse these classes in other modules.
   ================================================================ */
body:has(#oc-page) {
    --oc-c: var(--color-primary);
    --oc-accent: #0d9488;
    --oc-surface: var(--color-white);
    --oc-panel: var(--color-gray-50);
    --oc-border: var(--color-border-color);
    --oc-text: var(--color-gray-900);
    --oc-mut: var(--color-gray-500);
    --oc-soft: var(--color-gray-400);
    --oc-elev: var(--color-white);
    --oc-hover: var(--color-gray-100);
    --oc-track: color-mix(in srgb, var(--color-gray-500) 18%, transparent);
    --oc-neutral: color-mix(in srgb, var(--color-gray-500) 12%, transparent);
}
.dark body:has(#oc-page) {
    --oc-accent: #2dd4bf;
    --oc-surface: #0e1626;
    --oc-panel: #131c2e;
    --oc-border: rgba(148, 163, 184, 0.16);
    --oc-text: #e2e8f0;
    --oc-mut: #94a3b8;
    --oc-soft: #64748b;
    --oc-elev: #131c2e;
    --oc-hover: rgba(148, 163, 184, 0.1);
    --oc-track: rgba(148, 163, 184, 0.18);
    --oc-neutral: rgba(148, 163, 184, 0.1);
}
.oc-card {
    background: var(--oc-surface);
    border: 1px solid var(--oc-border);
    border-radius: 1rem;
    color: var(--oc-text);
    box-shadow:
        0 1px 2px rgba(15, 23, 42, 0.04),
        0 14px 40px -34px rgba(15, 23, 42, 0.3);
}
.oc-panel {
    background: var(--oc-panel);
    border: 1px solid var(--oc-border);
    border-radius: 0.75rem;
}
.oc-mut {
    color: var(--oc-mut);
}
.oc-head {
    color: var(--oc-text);
}
.oc-hicon {
    color: var(--oc-accent);
}
.oc-npill {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    font-size: 0.68rem;
    font-weight: 600;
    padding: 0.2rem 0.5rem;
    border-radius: 0.4rem;
    background: var(--oc-neutral);
    color: var(--oc-mut);
}
.oc-iconbadge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 0.5rem;
    background: var(--oc-neutral);
    color: var(--oc-mut);
}

/* ---------- HERO ---------- */
.oc-hero {
    position: relative;
    overflow: hidden;
    border-radius: 1rem;
    color: #e5edf5;
    background: linear-gradient(135deg, #0a1526 0%, #141a33 50%, #0b1526 100%);
    border: 1px solid rgba(148, 163, 184, 0.16);
    box-shadow: 0 20px 50px -34px rgba(2, 6, 15, 0.7);
}
.oc-hgrid {
    position: absolute;
    inset: 0;
    background-image:
        linear-gradient(rgba(148, 163, 184, 0.05) 1px, transparent 1px),
        linear-gradient(90deg, rgba(148, 163, 184, 0.05) 1px, transparent 1px);
    background-size: 28px 28px;
    pointer-events: none;
}
.oc-hbadge {
    background: rgba(148, 163, 184, 0.1);
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 0.6rem;
    padding: 0.6rem 0.8rem;
}

.oc-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.68rem;
    font-weight: 700;
    padding: 0.2rem 0.55rem;
    border-radius: 0.4rem;
}
.oc-dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    display: inline-block;
}
@keyframes oc-pulse {
    0%,
    100% {
        opacity: 1;
    }
    50% {
        opacity: 0.35;
    }
}
.oc-live {
    animation: oc-pulse 1.5s infinite;
}
.oc-btn {
    font-size: 0.82rem;
    font-weight: 600;
    padding: 0.55rem 0.95rem;
    border-radius: 0.55rem;
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    transition: 0.15s;
}
.oc-btn-primary {
    background: var(--oc-c);
    color: #fff;
}
.oc-btn-primary:hover {
    opacity: 0.92;
}
.oc-btn-ghost {
    background: transparent;
    border: 1px solid var(--oc-border);
    color: var(--oc-text);
}
.oc-btn-ghost:hover {
    background: var(--oc-hover);
}
.oc-btn-danger {
    background: #dc2626;
    color: #fff;
}
.oc-btn-danger:hover {
    background: #b91c1c;
}

/* priority palette */
.pr-emerg {
    --pv: #dc2626;
}
.pr-high {
    --pv: #e06c1f;
}
.pr-med {
    --pv: #1d4ed8;
}
.pr-routine {
    --pv: #0f766e;
}
.dark .pr-emerg {
    --pv: #f87171;
}
.dark .pr-high {
    --pv: #fb923c;
}
.dark .pr-med {
    --pv: #60a5fa;
}
.dark .pr-routine {
    --pv: #2dd4bf;
}

/* ---------- MONTH CALENDAR ---------- */
.oc-monthgrid {
    display: grid;
    grid-template-columns: repeat(7, 1fr);
    gap: 1px;
    background: var(--oc-border);
    border: 1px solid var(--oc-border);
    border-radius: 0.75rem;
    overflow: hidden;
}
.oc-daycell {
    background: var(--oc-surface);
    min-height: 104px;
    padding: 0.4rem;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
    transition: background 0.15s;
}
.oc-daycell.dim {
    background: var(--oc-panel);
}
.oc-daycell.today .oc-daynum {
    background: var(--oc-c);
    color: #fff;
}
.oc-daycell.dragover {
    outline: 2px dashed color-mix(in srgb, var(--oc-accent) 55%, transparent);
    outline-offset: -3px;
}
.oc-daynum {
    width: 22px;
    height: 22px;
    border-radius: 50%;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-size: 0.72rem;
    font-weight: 600;
}
.oc-evt {
    border-radius: 0.4rem;
    padding: 0.2rem 0.4rem;
    font-size: 0.66rem;
    font-weight: 600;
    color: #fff;
    cursor: grab;
    display: flex;
    align-items: center;
    gap: 0.25rem;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}
.oc-evt.conflict {
    box-shadow:
        0 0 0 2px #dc2626,
        0 0 0 3px rgba(220, 38, 38, 0.3);
}
.oc-evt.drag {
    opacity: 0.45;
}

/* ---------- WEEK / DAY / RESOURCE GRID ---------- */
.oc-tgrid {
    display: grid;
    gap: 0;
    min-width: 640px;
}
.oc-tcell {
    border-right: 1px solid var(--oc-border);
    border-bottom: 1px solid var(--oc-border);
    min-height: 46px;
    position: relative;
}
.oc-tcell.dropcol.dragover {
    background: color-mix(in srgb, var(--oc-accent) 8%, transparent);
}
.oc-block {
    position: absolute;
    left: 3px;
    right: 3px;
    border-radius: 0.45rem;
    padding: 0.3rem 0.45rem;
    font-size: 0.66rem;
    color: #fff;
    overflow: hidden;
    cursor: grab;
    box-shadow: 0 4px 10px -6px rgba(0, 0, 0, 0.5);
}
.oc-block.conflict {
    box-shadow: 0 0 0 2px #dc2626;
}
.oc-buffer {
    position: absolute;
    left: 3px;
    right: 3px;
    border-radius: 0.35rem;
    font-size: 0.6rem;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
}
.oc-thead {
    font-size: 0.66rem;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    color: var(--oc-mut);
    font-weight: 700;
    padding: 0.4rem;
    text-align: center;
    border-right: 1px solid var(--oc-border);
    border-bottom: 2px solid var(--oc-border);
}
.oc-hourlabel {
    font-size: 0.62rem;
    color: var(--oc-mut);
    padding: 0.2rem 0.35rem;
    border-right: 1px solid var(--oc-border);
    border-bottom: 1px solid var(--oc-border);
    text-align: right;
}

/* ---------- TIMELINE (surgery workflow) ---------- */
.oc-tl {
    position: relative;
    padding-left: 1.5rem;
}
.oc-tl::before {
    content: "";
    position: absolute;
    left: 0.42rem;
    top: 0.3rem;
    bottom: 0.3rem;
    width: 2px;
    background: var(--oc-border);
}
.oc-tl-item {
    position: relative;
    padding-bottom: 0.95rem;
}
.oc-tl-item::before {
    content: "";
    position: absolute;
    left: -1.28rem;
    top: 0.15rem;
    width: 12px;
    height: 12px;
    border-radius: 50%;
    background: var(--oc-surface);
    border: 2.5px solid var(--tc, var(--oc-accent));
}
.oc-stab {
    height: 6px;
    border-radius: 999px;
    background: var(--oc-track);
    overflow: hidden;
}
.oc-stab > span {
    display: block;
    height: 100%;
    border-radius: 999px;
}
.oc-avatar {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    object-fit: cover;
    font-weight: 600;
    color: #fff;
    border-radius: 0.5rem;
}

/* ---------- MENU / MODAL / DRAWER ---------- */
.oc-menu {
    position: fixed;
    z-index: 120;
    width: 210px;
    max-height: 72vh;
    overflow-y: auto;
    background: var(--oc-elev);
    border: 1px solid var(--oc-border);
    border-radius: 0.75rem;
    box-shadow: 0 24px 50px -18px rgba(15, 23, 42, 0.45);
    padding: 0.35rem;
    color: var(--oc-text);
}
.oc-menu button {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    width: 100%;
    text-align: left;
    font-size: 0.8rem;
    padding: 0.5rem 0.55rem;
    border-radius: 0.45rem;
    color: var(--oc-text);
}
.oc-menu button i {
    color: var(--oc-mut);
    font-size: 0.95rem;
}
.oc-menu button:hover {
    background: var(--oc-hover);
}
.oc-menu button.danger {
    color: #dc2626;
}
.oc-menu button.danger i {
    color: #dc2626;
}
.oc-menu button.danger:hover {
    background: color-mix(in srgb, #ef4444 10%, transparent);
}
.oc-menu-sep {
    height: 1px;
    background: var(--oc-border);
    margin: 0.3rem 0.2rem;
}

.oc-modal-wrap {
    position: fixed;
    inset: 0;
    z-index: 130;
    display: none;
}
.oc-modal-wrap.open {
    display: block;
}
.oc-modal-bg {
    position: absolute;
    inset: 0;
    background: rgba(8, 15, 26, 0.6);
    backdrop-filter: blur(5px);
    animation: oc-fade 0.2s;
}
@keyframes oc-fade {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}
.oc-modal {
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
    width: min(600px, 94vw);
    max-height: 90vh;
    display: flex;
    flex-direction: column;
    background: var(--oc-elev);
    color: var(--oc-text);
    border: 1px solid var(--oc-border);
    border-radius: 1rem;
    box-shadow: 0 40px 90px -24px rgba(2, 6, 15, 0.55);
    animation: oc-pop 0.22s cubic-bezier(0.4, 0, 0.2, 1);
    overflow: hidden;
}
@keyframes oc-pop {
    from {
        opacity: 0;
        transform: translate(-50%, -47%) scale(0.98);
    }
    to {
        opacity: 1;
        transform: translate(-50%, -50%) scale(1);
    }
}
.oc-modal-head {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 1rem 1.15rem;
    border-bottom: 1px solid var(--oc-border);
}
.oc-modal-badge {
    width: 38px;
    height: 38px;
    border-radius: 0.6rem;
    display: flex;
    align-items: center;
    justify-content: center;
    background: color-mix(in srgb, var(--oc-accent) 15%, transparent);
    color: var(--oc-accent);
    font-size: 1.05rem;
    flex: none;
}
.oc-modal-body {
    padding: 1.15rem;
    overflow-y: auto;
}
.oc-modal-foot {
    display: flex;
    justify-content: flex-end;
    gap: 0.5rem;
    padding: 0.9rem 1.15rem;
    border-top: 1px solid var(--oc-border);
    background: var(--oc-panel);
}
.oc-formlabel {
    font-size: 0.72rem;
    font-weight: 600;
    color: var(--oc-mut);
    text-transform: uppercase;
    letter-spacing: 0.03em;
}
.oc-in {
    width: 100%;
    padding: 0.55rem 0.7rem;
    font-size: 0.82rem;
    border: 1px solid var(--oc-border);
    border-radius: 0.55rem;
    background: var(--oc-surface);
    color: var(--oc-text);
    transition:
        border-color 0.15s,
        box-shadow 0.15s;
}
.oc-in:focus {
    outline: none;
    border-color: var(--oc-accent);
    box-shadow: 0 0 0 3px color-mix(in srgb, var(--oc-accent) 18%, transparent);
}
.oc-in::placeholder {
    color: var(--oc-soft);
}
.oc-drawer {
    position: fixed;
    top: 0;
    right: 0;
    height: 100%;
    width: min(460px, 96vw);
    background: var(--oc-elev);
    color: var(--oc-text);
    z-index: 125;
    transform: translateX(100%);
    transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    box-shadow: -30px 0 70px -30px rgba(2, 6, 15, 0.5);
    overflow-y: auto;
    border-left: 1px solid var(--oc-border);
}
.oc-drawer.open {
    transform: none;
}

.oc-toast {
    position: fixed;
    bottom: 1.25rem;
    left: 50%;
    transform: translateX(-50%) translateY(120%);
    z-index: 140;
    background: #0f1b2d;
    color: #e5edf5;
    border: 1px solid rgba(148, 163, 184, 0.2);
    padding: 0.7rem 1.05rem;
    border-radius: 0.65rem;
    font-size: 0.82rem;
    font-weight: 500;
    box-shadow: 0 18px 40px -18px rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    gap: 0.5rem;
    transition: transform 0.32s cubic-bezier(0.4, 0, 0.2, 1);
}
.oc-toast.show {
    transform: translateX(-50%) translateY(0);
}

.oc-sk {
    position: relative;
    overflow: hidden;
    background: var(--oc-panel);
    border-radius: 0.85rem;
}
.oc-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in srgb, var(--color-white) 45%, transparent),
        transparent
    );
    animation: oc-shim 1.4s infinite;
}
@keyframes oc-shim {
    100% {
        transform: translateX(100%);
    }
}
.oc-drop {
    background-image: repeating-linear-gradient(
        0deg,
        var(--oc-border) 0,
        var(--oc-border) 6px,
        transparent 6px,
        transparent 12px
    );
}
.oc-seg {
    display: inline-flex;
    background: var(--oc-panel);
    border: 1px solid var(--oc-border);
    border-radius: 0.6rem;
    padding: 0.18rem;
    gap: 0.12rem;
    flex-wrap: wrap;
}
.oc-seg button {
    padding: 0.35rem 0.7rem;
    font-size: 0.74rem;
    font-weight: 600;
    border-radius: 0.42rem;
    color: var(--oc-mut);
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
}
.oc-seg button.on {
    background: var(--oc-surface);
    color: var(--oc-text);
    box-shadow: 0 1px 3px rgba(15, 23, 42, 0.15);
}

@theme {
    --font-family-primary: "Inclusive Sans", sans-serif;
    --font-awesome: "Fontawesome";
    --font-lucide: "lucide";

    --color-primary: #0371c6;
    --color-primary-text: #0371c6;
    --color-primary-hover: #045aa0;
    --color-secondary: #f9f0d9;
    --color-secondary-hover: #06446f;
    --color-danger: #e7000b;
    --color-success: #009966;
    --color-dark: #0c0c0c;
    --color-light: #f8fafc;
    --color-warning: #f59e0b;
    --color-purple: #7c3aed;
    --color-pink: #ff46b2;
    --color-info: #008cff;

    --color-white: #ffffff;
    --color-white-50: #ffffff80;
    --color-white-400: #ffffff73;
    --color-white-500: #ffffff66;
    --color-dark-white: #fff;

    --color-primary-100: #e0effe;
    --color-primary-200: #bae0fd;
    --color-primary-300: #7ec7fb;
    --color-primary-400: #36a9f7;
    --color-primary-500: #0f90e8;
    --color-primary-600: #0371c6;
    --color-primary-700: color-mix(in srgb, black 15%, var(--color-primary));
    --color-primary-800: color-mix(in srgb, black 30%, var(--color-primary));
    --color-primary-900: color-mix(in srgb, black 45%, var(--color-primary));

    /* Numbered tint/shade scales + hover, generated from each brand color
       via color-mix() so every "-100..900"/"-hover" utility used across the
       UI kit (bg-info-500, bg-danger-100, ...) resolves to a real color. */
    --color-info-100: color-mix(in srgb, white 88%, var(--color-info));
    --color-info-200: color-mix(in srgb, white 74%, var(--color-info));
    --color-info-300: color-mix(in srgb, white 56%, var(--color-info));
    --color-info-400: color-mix(in srgb, white 30%, var(--color-info));
    --color-info-500: color-mix(in srgb, white 10%, var(--color-info));
    --color-info-600: var(--color-info);
    --color-info-700: color-mix(in srgb, black 15%, var(--color-info));
    --color-info-800: color-mix(in srgb, black 30%, var(--color-info));
    --color-info-900: color-mix(in srgb, black 45%, var(--color-info));
    --color-info-hover: color-mix(in srgb, black 12%, var(--color-info));

    --color-warning-100: color-mix(in srgb, white 88%, var(--color-warning));
    --color-warning-200: color-mix(in srgb, white 74%, var(--color-warning));
    --color-warning-300: color-mix(in srgb, white 56%, var(--color-warning));
    --color-warning-400: color-mix(in srgb, white 30%, var(--color-warning));
    --color-warning-500: color-mix(in srgb, white 10%, var(--color-warning));
    --color-warning-600: var(--color-warning);
    --color-warning-700: color-mix(in srgb, black 15%, var(--color-warning));
    --color-warning-800: color-mix(in srgb, black 30%, var(--color-warning));
    --color-warning-900: color-mix(in srgb, black 45%, var(--color-warning));
    --color-warning-hover: color-mix(in srgb, black 12%, var(--color-warning));

    --color-success-100: color-mix(in srgb, white 88%, var(--color-success));
    --color-success-200: color-mix(in srgb, white 74%, var(--color-success));
    --color-success-300: color-mix(in srgb, white 56%, var(--color-success));
    --color-success-400: color-mix(in srgb, white 30%, var(--color-success));
    --color-success-500: color-mix(in srgb, white 10%, var(--color-success));
    --color-success-600: var(--color-success);
    --color-success-700: color-mix(in srgb, black 15%, var(--color-success));
    --color-success-800: color-mix(in srgb, black 30%, var(--color-success));
    --color-success-900: color-mix(in srgb, black 45%, var(--color-success));
    --color-success-hover: color-mix(in srgb, black 12%, var(--color-success));

    --color-danger-100: color-mix(in srgb, white 88%, var(--color-danger));
    --color-danger-200: color-mix(in srgb, white 74%, var(--color-danger));
    --color-danger-300: color-mix(in srgb, white 56%, var(--color-danger));
    --color-danger-400: color-mix(in srgb, white 30%, var(--color-danger));
    --color-danger-500: color-mix(in srgb, white 10%, var(--color-danger));
    --color-danger-600: var(--color-danger);
    --color-danger-700: color-mix(in srgb, black 15%, var(--color-danger));
    --color-danger-800: color-mix(in srgb, black 30%, var(--color-danger));
    --color-danger-900: color-mix(in srgb, black 45%, var(--color-danger));
    --color-danger-hover: color-mix(in srgb, black 12%, var(--color-danger));

    --color-pink-100: color-mix(in srgb, white 88%, var(--color-pink));
    --color-pink-200: color-mix(in srgb, white 74%, var(--color-pink));
    --color-pink-300: color-mix(in srgb, white 56%, var(--color-pink));
    --color-pink-400: color-mix(in srgb, white 30%, var(--color-pink));
    --color-pink-500: color-mix(in srgb, white 10%, var(--color-pink));
    --color-pink-600: var(--color-pink);
    --color-pink-700: color-mix(in srgb, black 15%, var(--color-pink));
    --color-pink-800: color-mix(in srgb, black 30%, var(--color-pink));
    --color-pink-900: color-mix(in srgb, black 45%, var(--color-pink));
    --color-pink-hover: color-mix(in srgb, black 12%, var(--color-pink));

    --color-purple-100: color-mix(in srgb, white 88%, var(--color-purple));
    --color-purple-200: color-mix(in srgb, white 74%, var(--color-purple));
    --color-purple-300: color-mix(in srgb, white 56%, var(--color-purple));
    --color-purple-400: color-mix(in srgb, white 30%, var(--color-purple));
    --color-purple-500: color-mix(in srgb, white 10%, var(--color-purple));
    --color-purple-600: var(--color-purple);
    --color-purple-700: color-mix(in srgb, black 15%, var(--color-purple));
    --color-purple-800: color-mix(in srgb, black 30%, var(--color-purple));
    --color-purple-900: color-mix(in srgb, black 45%, var(--color-purple));
    --color-purple-hover: color-mix(in srgb, black 12%, var(--color-purple));

    /* These four ride on Tailwind's built-in default palette (no brand
       override), so the hover mix is taken from that palette's own 600
       shade rather than a custom --color-orange/-indigo/-cyan/-teal. */
    --color-orange-hover: color-mix(in srgb, black 12%, var(--color-orange-600));
    --color-indigo-hover: color-mix(in srgb, black 12%, var(--color-indigo-600));
    --color-cyan-hover: color-mix(in srgb, black 12%, var(--color-cyan-600));
    --color-teal-hover: color-mix(in srgb, black 12%, var(--color-teal-600));

    --color-gray-100: #f3f4f6;
    --color-gray-200: #ebe6e7;
    --color-gray-600: #4b5563;
    --color-gray-900: #111827;
    --color-gray-hover: color-mix(in srgb, black 12%, var(--color-gray-600));
    --color-border-color: var(--color-gray-200);

    --sidenav-width: 242px;
    --sidebar-mini-width: 60px;
    --expand-mini-width: 92px;
    --sidebar-bg: #0c0c0c;
    --sidebar-border: #fff;
    --sidebar-menu-item: #fff;
    --sidebar-menu-active-item: #fff;
    --sidebar-menu-active-bg: var(--background-image-primary-gradient);
    --sidebar-submenu-item: #fff;
    --sidebar-submenu-icon: var(--color-primary);
    --sidebar-submenu-active-item: var(--color-primary);
    --sidebar-submenu-active-icon: var(--color-primary);
    --sidebar-icon-item: var(--color-gray-900);
    --sidebar-icon-bg: var(--color-white);
    --sidebar-icon-active-item: var(--color-primary);
    --sidebar-icon-active-bg: var(--color-light);
    --sidebar-title: var(--color-gray-900);
    --menu-toggle-color: var(--color-gray-900);

    --topbar-height: 56px;

    --background-image-primary-gradient: linear-gradient(
        90deg,
        #0371c6 0%,
        #2ba1db 50%,
        #ffa339 100%
    );
    --background-image-success-gradient: linear-gradient(
        90deg,
        #009966 0%,
        #34d399 100%
    );
    --background-image-info-gradient: linear-gradient(
        90deg,
        #008cff 0%,
        #7dd3fc 100%
    );
    --background-image-dark-gradient: linear-gradient(
        90deg,
        #0c0c0c 0%,
        #475569 100%
    );
    --background-image-danger-gradient: linear-gradient(
        90deg,
        #e7000b 0%,
        #fb7185 100%
    );
    --background-image-linear-gradient: linear-gradient(
        291.19deg,
        #50e8ff 2.37%,
        #6bbb3a 59.48%,
        #75d53a 100%
    );

    --breakpoint-sm: 576px;
    --breakpoint-md: 768px;
    --breakpoint-lg: 992px;
    --breakpoint-xl: 1200px;
    --breakpoint-xxl: 1400px;

    --rounded-lg: 10px;

    --shadow: 0px 6px 7px 0px rgba(182, 182, 182, 0.18);
}

@layer base {
    body {
        @apply font-family-primary text-sm;
    }

    /* Scrollbar */
    ::-webkit-scrollbar {
        @apply w-1.5 h-1.5;
    }

    ::-webkit-scrollbar-track {
        @apply bg-transparent;
    }

    ::-webkit-scrollbar-thumb {
        @apply bg-[#cbd5e1] rounded-[3px] dark:bg-[#475569];
    }
}

@layer components {
    /* Sidebar Styles */
    .sidebar {
        @apply bg-(--sidebar-bg) w-(--sidenav-width) z-45 fixed transition-all duration-[0.25s] ease-[ease] border border-0 shadow-sm left-0 top-0 bottom-0 max-lg:left-0 max-lg:top-0 max-lg:start-0 max-lg:bottom-0 max-lg:-ml-(--sidenav-width) max-lg:rounded-none! max-lg:shadow-none max-lg:border-l-0 max-lg:border-t-0 max-lg:border-b-0 flex justify-between flex-col backdrop-blur-[94px];
        /* The sidebar's own background never changes with the theme toggle
           (--sidebar-bg is untouched inside .dark{}), but dozens of its
           utilities (text-white/60, bg-white/12, border-white/10, ...) are
           built on the *shared* --color-white token, which .dark{} redefines
           to a dark slate for surfaces that do invert (cards, etc). Pinning
           --color-white back to real white for every descendant here is what
           keeps all of those translucent-white utilities readable in dark
           mode too, without touching the many individual rules that use them. */
        --color-white: #ffffff;
    }

    .sidebar ul {
        @apply p-0;
    }

    .sidebar li {
        @apply list-none m-0;
    }

    .sidebar .sidebar-menu > ul > li:first-child.menu-title {
        @apply mt-0 pt-0! before:content-none;
    }

    .sidebar .sidebar-menu > ul li.menu-title {
        @apply text-sm font-bold text-gray-600 mt-6 mb-3 uppercase relative dark:before:bg-none dark:before:bg-border-color;
    }

    .sidebar .sidebar-menu > ul > li {
        @apply mt-1;
    }

    .sidebar .sidebar-logo {
        @apply absolute top-0 left-0 w-full leading-(--topbar-height) p-4 z-1 before:content-[''] before:absolute before:bottom-[-50px] before:bg-[url('../img/elements/shadow-1.png')] before:bg-no-repeat before:bg-top before:bg-cover before:w-full before:h-[100px] before:left-0  before:-z-1;
    }

    .sidebar .sidebar-logo .logo {
        @apply block max-w-[170px];
    }

    .sidebar .sidebar-logo .logo-small,
    .sidebar .sidebar-logo .dark-logo {
        @apply hidden;
    }

    .sidebar .sidebar-logo #toggle_btn {
        @apply lg:absolute lg:-translate-y-2/4 lg:w-5 lg:h-7 lg:rounded-l-md lg:right-0 lg:p-3 lg:text-(--menu-toggle-color) lg:text-base lg:right-0 lg:top-2/4 max-lg:hidden font-normal lg:bg-white lg:border lg:border-white lg:hover:bg-primary lg:hover:border-primary lg:hover:text-white flex items-center justify-center leading-0 cursor-pointer;
    }

    .sidebar [data-simplebar] {
        @apply top-[50px] bottom-[136px] h-[calc(100%_-186px)] w-full;
    }

    .sidebar [data-simplebar] .sidebar-menu {
        @apply flex flex-col justify-between mt-0 mb-5 pt-4;
    }

    .sidebar .sidebar-inner {
        @apply w-full bg-(--sidebar-bg) rounded-xl mt-5 mb-5 z-2;
    }

    .sidebar ul.bottom-menu-nivgation {
        @apply py-4 px-5 relative before:content-[''] before:absolute before:top-[-80px] before:left-0 before:bg-[url('../img/elements/shadow-1.png')] before:bg-no-repeat before:bg-top before:bg-cover before:w-full before:h-[130px];
    }

    .bottom-menu-nivgation li {
        @apply mt-2;
    }

    .bottom-menu-nivgation li a {
        @apply relative py-2 rounded-xl overflow-hidden text-sm font-semibold gap-2 flex items-center text-(--sidebar-menu-item) hover:text-primary;
    }

    .sidebar .sidebar-menu {
        @apply mt-(--topbar-height) p-4 pb-0;
    }

    .sidebar .sidebar-menu > ul > li:last-child ul {
        @apply mb-0;
    }

    .sidebar .sidebar-menu > ul > li > a {
        @apply flex items-center overflow-hidden rounded-xl text-[14px] text-[var(--sidebar-menu-item)] font-medium relative w-full px-[12px] py-[10px] before:absolute before:opacity-0 before:left-auto before:right-[-13px] before:w-5 before:h-5 before:bg-white before:rounded-full;
    }

    .sidebar .sidebar-menu > ul > li > a > i {
        @apply text-base;
    }

    .sidebar .sidebar-menu > ul > li.submenu > a {
        @apply uppercase text-xs;
    }

    .sidebar .sidebar-menu > ul > li.submenu > a span {
        @apply text-xs;
    }

    .sidebar .sidebar-menu > ul > li.submenu > a i {
        @apply text-gray-500 text-base!;
    }

    .sidebar .sidebar-menu > ul > li > a.active,
    .sidebar .sidebar-menu > ul > li > a:hover,
    .sidebar .sidebar-menu > ul > li > a.subdrop {
        @apply text-(--sidebar-menu-active-item);
    }

    .sidebar .sidebar-menu > ul > li > a.subdrop {
        @apply font-bold text-primary-text;
    }

    .sidebar .sidebar-menu > ul > li > a.subdrop > span {
        @apply font-bold;
    }

    .sidebar .sidebar-menu > ul > li a.subdrop {
        @apply text-primary-text;
    }

    .sidebar .sidebar-menu > ul > li > a span {
        @apply text-sm font-medium whitespace-nowrap ml-2;
    }

    .sidebar .sidebar-menu > ul > li > a .count {
        @apply w-3.5 h-3.5 text-[10px] flex items-center justify-center text-[color:var(--white)] shrink-0 font-normal ml-auto rounded-[50%];
    }

    .sidebar .sidebar-menu > ul > li.submenu ul {
        @apply hidden;
    }

    .sidebar .sidebar-menu > ul > li.submenu > ul {
        @apply my-2 relative before:content-none;
    }

    .sidebar .sidebar-menu > ul > li.submenu ul li a {
        @apply text-sm font-medium rounded-xl overflow-hidden relative text-(--sidebar-submenu-item) px-4 py-1.5 hover:text-(--sidebar-submenu-active-item) hover:bg-transparent hover:after:bg-(--sidebar-submenu-active-icon);
    }

    .sidebar .sidebar-menu > ul > li.submenu ul li a.active {
        @apply text-(--sidebar-submenu-active-item) after:bg-(--sidebar-submenu-active-icon);
    }

    .sidebar .sidebar-menu > ul > li.submenu ul li a.subdrop {
        @apply text-(--sidebar-submenu-active-item);
    }

    .sidebar .sidebar-menu > ul > li.submenu ul li > a.active {
        @apply bg-[image:var(--sidebar-menu-active-bg)] text-(--sidebar-menu-active-item) relative border-l border-white;
    }

    .sidebar .sidebar-menu > ul > li ul {
        @apply flex flex-col;
    }

    .sidebar .sidebar-menu > ul > li ul li {
        @apply overflow-hidden mt-2;
    }

    .sidebar .sidebar-menu > ul > li ul li a {
        @apply flex items-center text-sm relative w-full p-2 rounded-md;
    }

    .sidebar .sidebar-menu > ul > li ul li a i {
        @apply text-sm;
    }

    .sidebar .sidebar-menu > ul > li ul li a span {
        @apply whitespace-nowrap ml-2;
    }

    .sidebar .sidebar-menu > ul > li .submenu ul {
        @apply hidden relative py-0 border-0;
    }

    .sidebar .sidebar-menu > ul > li .submenu ul li {
        @apply m-0;
    }

    .sidebar .sidebar-menu > ul li.menu-title span {
