    /* Card */
    .card {
        @apply bg-white rounded-[6px] shadow border border-border-color dark:bg-[#1e293b] dark:border-[#334155];
    }

    /* Generic sizeable buttons — shape/typography only. Colour and border
       come from utility classes on the element itself (e.g. bg-primary
       border-primary), matching how these are used across the UI kit. */
    .btn,
    .btn-sm,
    .btn-lg {
        @apply inline-flex items-center justify-center gap-1.5 font-semibold whitespace-nowrap transition-all duration-150 cursor-pointer;
    }
    .btn {
        @apply px-5 py-2.5 text-sm rounded-lg;
    }
    .btn-sm {
        @apply px-3.5 py-2 text-[13px] rounded-md;
