    }
    .ui-lightbox-nav {
        @apply absolute top-1/2 -translate-y-1/2 grid size-11 place-items-center rounded-full bg-white/10 text-white transition-colors hover:bg-white/20;
    }
    .ui-lightbox-prev {
        @apply left-4;
    }
    .ui-lightbox-next {
        @apply right-4;
    }

    .modal-panel {
        @apply bg-white rounded-xl w-full max-w-[580px] max-h-[88vh] shadow-[0_25px_80px_rgba(0,0,0,0.35)] animate-[modalIn_0.2s_ease] dark:bg-[#1e293b] dark:border dark:border-[#334155];
        display: flex;
        flex-direction: column;
        overflow-y: auto;
        overflow-x: hidden;
        padding: 0;
        /* The overlay wrapper (.hs-overlay) carries pointer-events-none so a
           closed/transparent modal never blocks clicks on the page behind
           it. Nothing re-enabled pointer events on the panel itself once
           open, so every input/button inside every modal using this class
           was inert. */
        pointer-events: auto;
    }

    .modal-panel.sm {
        @apply max-w-[420px];
    }

    /* Fixed head/foot, scrolling middle — no HTML changes needed across the
       ~140 modals that share this markup shape (title/close row, then either
       a <form> whose last child is the Cancel/Save button row, or — for
       short confirm dialogs — plain content with no <form> at all). The
       panel is now a column flexbox: the head is a non-growing flex item,
       and where a <form> is present, its own last child (the footer) is
       pinned the same way while its middle content is the only part that
       scrolls, via a nested flex column inside <form>. The panel keeps a
       fallback overflow-y so any oversized non-form content still scrolls
       instead of being clipped. */
    .modal-panel > *:not(form) {
        padding-left: 1.75rem;
        padding-right: 1.75rem;
    }
    .modal-panel > *:first-child {
        flex: 0 0 auto;
        padding-top: 1.75rem;
        padding-bottom: 1rem;
        border-bottom: 1px solid var(--color-border-color);
    }
    .dark .modal-panel > *:first-child {
        border-bottom-color: #334155;
    }
    .modal-panel.sm > *:first-child {
        border-bottom: none;
        padding-bottom: 0;
    }
    .modal-panel > *:last-child:not(form) {
        padding-bottom: 1.75rem;
    }
    .modal-panel > form {
        display: flex;
        flex-direction: column;
        flex: 1 1 auto;
        min-height: 0;
        overflow-y: auto;
    }
    .modal-panel > form > *:not(:last-child) {
        flex: 0 0 auto;
        padding: 1.5rem 1.5rem 0;
    }
    .modal-panel > form > *:nth-last-child(2) {
        padding-bottom: 1.5rem;
    }
    .modal-panel > form > *:last-child {
        flex: 0 0 auto;
        padding: 1rem 1.75rem 1.75rem;
        border-top: 1px solid var(--color-border-color);
    }
    .dark .modal-panel > form > *:last-child {
        border-top-color: #334155;
    }

    /* Form elements */
    .form-grid {
        @apply grid grid-cols-2 gap-3.5;
    }

    .form-grid.cols-1 {
        @apply grid-cols-1;
    }

    .form-group {
        @apply flex flex-col gap-1.25;
    }

    .form-group.span-2 {
        @apply col-span-2;
    }

    .form-label {
        @apply text-[12.5px] font-semibold text-[#374151] dark:text-[#d1d5db];
    }

    .form-input,
    .form-select,
    .form-textarea {
        @apply w-full py-[9px] px-3 border border-border-color! rounded-xl! text-sm! bg-white! text-gray-900! outline-none transition-[border-color,box-shadow] duration-150 disabled:bg-gray-50;
        font-family: inherit;
    }

    .form-input:focus,
    .form-select:focus,
    .form-textarea:focus {
        @apply border-[#3b82f6] shadow-none;
    }

    /* Input-group prefix/suffix (e.g. "$" + amount field): .form-input's
       forced rounded-xl! otherwise wins over the rounded-*-none! utility
       since both are !important at equal specificity. The utility's class
       token literally includes the trailing "!" (Tailwind v4 important
       modifier syntax), so it must be escaped in this selector. */
    .form-input.rounded-l-none\!,
    .form-select.rounded-l-none\!,
    .form-textarea.rounded-l-none\! {
        border-top-left-radius: 0 !important;
        border-bottom-left-radius: 0 !important;
    }

    .form-input.rounded-r-none\!,
    .form-select.rounded-r-none\!,
    .form-textarea.rounded-r-none\! {
        border-top-right-radius: 0 !important;
        border-bottom-right-radius: 0 !important;
    }

    .form-input.rounded-none\!,
    .form-select.rounded-none\!,
    .form-textarea.rounded-none\! {
        border-radius: 0 !important;
    }

    .form-textarea {
        @apply resize-y min-h-[80px];
    }

    /* Toast */
    .mc-toast {
        @apply fixed bottom-6 right-6 py-[13px] px-5 rounded-[10px] text-sm font-medium z-[9999] flex items-center gap-2 shadow-[0_8px_24px_rgba(0,0,0,0.2)] animate-[toastIn_0.25s_ease] max-w-[360px];
    }

    .mc-toast.success {
        @apply bg-[#10b981] text-white;
    }

    .mc-toast.error {
        @apply bg-[#ef4444] text-white;
    }

    .mc-toast.info {
        @apply bg-[#3b82f6] text-white;
    }

    /* Responsive Sidebar Drawer & Overlay */
    .sidebar-overlay {
        @apply hidden fixed top-0 start-0 w-full h-full bg-black/60 z-40;
    }

    .sidebar-overlay.opened {
        @apply block;
    }

    /* Single-scroll app shell — main is the only scrolling region, so the
       page (html/body) never shows a second scrollbar alongside it. */
    body:has(.sidebar) {
        @apply h-dvh overflow-hidden;
    }

    .main-wrapper {
        @apply flex flex-col h-dvh overflow-hidden;
    }

    .main-wrapper > div:not([id]) {
        @apply flex flex-1 min-h-0 flex-col;
    }

    /* Sidebar Layout Offset Compatibility for Flex Layout */
    body:has(.sidebar) > div.flex-1 {
        @apply ml-[var(--sidenav-width)] transition-[margin-left] duration-250 ease-in-out;
    }

    body.mini-sidebar:has(.sidebar) > div.flex-1 {
        @apply ml-[var(--sidebar-mini-width)];
    }

    body.mini-sidebar.expand-menu:has(.sidebar) > div.flex-1 {
        @apply ml-[var(--sidebar-mini-width)];
    }

    /* Mobile responsive layout overrides */
    @media (max-width: 991px) {
        body > div.flex-1 {
            @apply !ml-0;
        }
    }

    /* Global Interactive Elements Cursor */
    a,
    button,
    input[type="button"],
    input[type="submit"],
    input[type="reset"],
    input[type="checkbox"],
    input[type="radio"],
    select,
    [role="button"],
    [role="tab"],
    [role="menuitem"],
    [role="switch"],
    [data-hs-dropdown-trigger],
    [data-hs-overlay],
    [data-hs-collapse],
    [data-hs-tab],
    [onclick],
    .btn,
    label,
    .cursor-pointer,
    .hs-dropdown-toggle,
    .settings-nav-btn {
        @apply !cursor-pointer;
    }

    /* Ensure disabled interactive elements show appropriate cursor */
    :disabled,
    [disabled],
    .disabled {
        @apply !cursor-not-allowed;
    }

    /* Vertically center hs-overlay dialog/confirm popups site-wide. Preline's
       overlay markup only auto-centers horizontally (sm:mx-auto) by default,
       leaving modals pinned near the top of the viewport. Scoped to the
       direct-child "...mx-auto" wrapper so offcanvas/slide-in panels (which
       apply hs-overlay straight to the sliding panel, never nesting an
       mx-auto wrapper) are left untouched. */
    .hs-overlay > [class*="mx-auto"] {
        display: flex;
        align-items: center;
        min-height: calc(100% - 3.5rem);
    }
    .hs-overlay > [class*="mx-auto"] > * {
        width: 100%;
    }
}

/* =========================================================================
   APPOINTMENT MODULE
   Scoped to the Appointment pages only. Do not reuse these classes in other
   modules — they are what makes the Appointment section visually distinct.
   ========================================================================= */
@layer pages {
    /* Responsive stat grid — collapses 6 -> 3 -> 2 across breakpoints. */
    .appt-stats {
        @apply grid grid-cols-2 lg:grid-cols-3 gap-3;
    }

    .appt-stats.cols-4 {
        @apply xl:grid-cols-4;
    }

    .appt-stats.cols-6 {
        @apply xl:grid-cols-6;
    }

    /* --- Card ----------------------------------------------------------- */
    .appt-stat {
        --appt-accent: var(--color-primary);
        @apply relative overflow-hidden rounded-xl border border-border-color bg-white p-4 transition-all duration-300 dark:bg-[#1e293b];
    }

    /* Accent rail along the top edge. */
    .appt-stat::before {
        content: "";
        @apply absolute left-0 top-0 h-[3px] w-full;
        background-image: linear-gradient(
            90deg,
            var(--appt-accent) 0%,
            color-mix(in oklab, var(--appt-accent) 35%, transparent) 55%,
            transparent 100%
        );
    }

    /* Soft accent bloom in the top-right corner. */
    .appt-stat::after {
        content: "";
        @apply pointer-events-none absolute -right-10 -top-12 size-28 rounded-full blur-2xl opacity-[0.18] transition-opacity duration-300;
        background-color: var(--appt-accent);
    }

    .appt-stat:hover {
        @apply -translate-y-1;
        border-color: color-mix(in oklab, var(--appt-accent) 45%, transparent);
        box-shadow: 0 18px 38px -18px
            color-mix(in oklab, var(--appt-accent) 70%, transparent);
    }

    .appt-stat:hover::after {
        @apply opacity-30;
    }

    .appt-stat:focus-within {
        outline: 2px solid var(--appt-accent);
        outline-offset: 2px;
    }

    .appt-stat-head {
        @apply flex items-start justify-between gap-2;
    }

    .appt-stat-icon {
        @apply flex size-9 shrink-0 items-center justify-center rounded-xl text-sm transition-transform duration-300;
        color: var(--appt-accent);
        background-color: color-mix(
            in oklab,
            var(--appt-accent) 12%,
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(in oklab, var(--appt-accent) 22%, transparent);
    }

    .appt-stat:hover .appt-stat-icon {
        @apply scale-110;
    }

    /* --- Delta pill ----------------------------------------------------- */
    .appt-stat-delta {
        @apply inline-flex items-center gap-1 rounded-full px-1.5 py-0.5 text-[10px] font-bold whitespace-nowrap;
    }

    .appt-stat-delta.is-up {
        @apply bg-success/10 text-success;
    }

    .appt-stat-delta.is-down {
        @apply bg-danger/10 text-danger;
    }

    .appt-stat-delta.is-flat {
        @apply bg-gray-100 text-gray-500 dark:bg-slate-700 dark:text-gray-400;
    }

    /* --- Figures -------------------------------------------------------- */
    .appt-stat-value {
        @apply mt-3 text-2xl font-extrabold leading-none text-gray-900 tabular-nums;
    }

    .appt-stat-label {
        @apply mt-1 text-xs font-medium text-gray-500 dark:text-gray-400;
    }

    /* --- Sparkline ------------------------------------------------------ */
    .appt-stat-foot {
        @apply mt-3 flex items-end justify-between gap-2;
    }

    .appt-stat-spark {
        @apply h-6 w-20 shrink-0 overflow-visible;
        color: var(--appt-accent);
    }

    .appt-stat-meta {
        @apply text-[10px] font-medium text-gray-400 dark:text-gray-500 whitespace-nowrap;
    }

    /* --- Accent tones --------------------------------------------------- */
    .appt-stat.tone-primary {
        --appt-accent: var(--color-primary);
    }
    .appt-stat.tone-sky {
        --appt-accent: #0ea5e9;
    }
    .appt-stat.tone-emerald {
        --appt-accent: #10b981;
    }
    .appt-stat.tone-amber {
        --appt-accent: #f59e0b;
    }
    .appt-stat.tone-danger {
        --appt-accent: var(--color-danger);
    }
    .appt-stat.tone-purple {
        --appt-accent: var(--color-purple);
    }
    .appt-stat.tone-slate {
        --appt-accent: #64748b;
    }
    .appt-stat.tone-pink {
        --appt-accent: var(--color-pink);
    }

    /* Reduced motion — keep the module calm for users who ask for it. */
    @media (prefers-reduced-motion: reduce) {
        .appt-stat,
        .appt-stat-icon,
        .appt-stat::after {
            @apply transition-none;
        }
        .appt-stat:hover {
            @apply translate-y-0;
        }
        .appt-stat:hover .appt-stat-icon {
            @apply scale-100;
        }
    }

    /* =====================================================================
       Emergency KPI Card — EXCLUSIVE to the Emergency module.
       Deliberately distinct from .appt-stat: a left triage rail instead of a
       top rail, a live ECG trace instead of a sparkline, and a capacity meter
       instead of a delta pill. Do not reuse outside the Emergency module.
       ===================================================================== */
    .er-kpis {
        @apply grid grid-cols-2 lg:grid-cols-3 gap-3;
    }

    .er-kpis.cols-6 {
        @apply xl:grid-cols-6;
    }

    /* --- Card ----------------------------------------------------------- */
    .er-kpi {
        --er-accent: var(--color-danger);
        @apply relative overflow-hidden rounded-xl border border-border-color bg-white py-4 pl-5 pr-4 transition-all duration-300 dark:bg-[#1e293b];
    }

    /* Triage rail down the leading edge — the Emergency signature. */
    .er-kpi::before {
        content: "";
        @apply absolute inset-y-0 left-0 w-1;
        background-image: linear-gradient(
            180deg,
            var(--er-accent) 0%,
            color-mix(in oklab, var(--er-accent) 40%, transparent) 100%
        );
    }

    /* Monitor glow bleeding in from the leading edge. */
    .er-kpi::after {
        content: "";
        @apply pointer-events-none absolute -left-8 top-1/2 size-24 -translate-y-1/2 rounded-full blur-2xl opacity-[0.14] transition-opacity duration-300;
        background-color: var(--er-accent);
    }

    /* No lift here — Appointment cards rise, Emergency cards light up. */
    .er-kpi:hover {
        border-color: color-mix(in oklab, var(--er-accent) 45%, transparent);
        box-shadow: 0 16px 34px -20px
            color-mix(in oklab, var(--er-accent) 75%, transparent);
    }

    .er-kpi:hover::after {
        @apply opacity-25;
    }

    .er-kpi:focus-within {
        outline: 2px solid var(--er-accent);
        outline-offset: 2px;
    }

    .er-kpi-head {
        @apply flex items-center justify-between gap-2;
    }

    .er-kpi-icon {
        @apply flex size-9 shrink-0 items-center justify-center rounded-xl text-sm;
        color: var(--er-accent);
        background-color: color-mix(
            in oklab,
            var(--er-accent) 12%,
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(in oklab, var(--er-accent) 22%, transparent);
    }

    /* --- Live pulse ----------------------------------------------------- */
    .er-kpi-live {
        @apply inline-flex items-center gap-1.5 text-[10px] font-bold uppercase tracking-wide;
        color: var(--er-accent);
    }

    .er-kpi-live-dot {
        @apply size-1.5 rounded-full;
        background-color: var(--er-accent);
        animation: er-pulse 1.8s ease-in-out infinite;
    }

    /* --- Figures -------------------------------------------------------- */
    .er-kpi-value {
        @apply mt-3 text-2xl font-extrabold leading-none text-gray-900 tabular-nums;
    }

    .er-kpi-unit {
        @apply ml-1 text-xs font-semibold text-gray-400 dark:text-gray-500;
    }

    .er-kpi-label {
        @apply mt-1 text-xs font-medium text-gray-500 dark:text-gray-400;
    }

    /* --- ECG trace ------------------------------------------------------ */
    .er-kpi-ecg {
        @apply mt-3 h-5 w-full overflow-visible;
        color: var(--er-accent);
    }

    .er-kpi-ecg-line {
        stroke-dasharray: 260;
        animation: ecg-dash 3s linear infinite;
    }

    /* --- Capacity meter ------------------------------------------------- */
    .er-kpi-meter {
        @apply mt-2 h-1 w-full;
        color: var(--er-accent);
    }

    .er-kpi-meter-track {
        @apply text-gray-200 dark:text-slate-700;
    }

    .er-kpi-foot {
        @apply mt-1.5 flex items-center justify-between gap-2;
    }

    .er-kpi-meta {
        @apply text-[10px] font-medium text-gray-400 dark:text-gray-500 whitespace-nowrap;
    }

    .er-kpi-pct {
        @apply text-[10px] font-bold tabular-nums;
        color: var(--er-accent);
    }

    /* --- Triage tones --------------------------------------------------- */
    .er-kpi.tone-critical {
        --er-accent: var(--color-danger);
    }
    .er-kpi.tone-urgent {
        --er-accent: #f59e0b;
    }
    .er-kpi.tone-stable {
        --er-accent: #10b981;
    }
    .er-kpi.tone-info {
        --er-accent: var(--color-info);
    }
    .er-kpi.tone-purple {
        --er-accent: var(--color-purple);
    }
    .er-kpi.tone-slate {
        --er-accent: #64748b;
    }

    @keyframes er-pulse {
        0%,
        100% {
            opacity: 1;
            transform: scale(1);
        }
        50% {
            opacity: 0.35;
            transform: scale(1.35);
        }
    }

    /* An ER screen runs all shift — never animate at a user who opted out. */
    @media (prefers-reduced-motion: reduce) {
        .er-kpi,
        .er-kpi::after {
            @apply transition-none;
        }
        .er-kpi-live-dot,
        .er-kpi-ecg-line {
            animation: none;
        }
    }

    /* =====================================================================
       TRAUMA COMMAND CENTER — EXCLUSIVE to trauma-cases.html.
       A flagship layout: glass surfaces, layered gradients, ring gauges,
       a kanban priority board, an enterprise case grid and a slide-over
       drawer. Shares nothing with .er-kpi or .appt-stat by design.
       ===================================================================== */

    /* --- Shared tokens -------------------------------------------------- */
    .hms-scope {
        --tc-critical: #e7000b;
        --tc-high: #f97316;
        --tc-medium: #f59e0b;
        --tc-stable: #10b981;
        --tc-info: #0ea5e9;
        --tc-purple: #7c3aed;
    }

    /* Frosted surface used across the page. */
    .tc-glass {
        @apply border border-white/60 bg-white/70 backdrop-blur-xl;
        @apply dark:border-white/10 dark:bg-slate-800/60;
    }

    /* --- Hero ----------------------------------------------------------- */
    .tc-hero {
        @apply relative isolate overflow-hidden rounded-xl p-6 lg:p-8;
        background-image: linear-gradient(
            115deg,
            #0b1220 0%,
            #14243d 45%,
            #1f2f4a 100%
        );
    }

    /* Aurora bloom, top-right. */
    .tc-hero::before {
        content: "";
        @apply pointer-events-none absolute -right-24 -top-32 -z-10 size-[26rem] rounded-full blur-3xl opacity-40;
        background-image: radial-gradient(
            circle,
            var(--color-danger) 0%,
            transparent 65%
        );
    }

    /* Cool counter-bloom, bottom-left. */
    .tc-hero::after {
        content: "";
        @apply pointer-events-none absolute -bottom-40 -left-24 -z-10 size-[24rem] rounded-full blur-3xl opacity-30;
        background-image: radial-gradient(circle, #0ea5e9 0%, transparent 65%);
    }

    /* Faint clinical grid, so the hero reads as a monitor not a banner. */
    .hms-hero-grid {
        @apply pointer-events-none absolute inset-0 -z-10 opacity-[0.07];
        background-image:
            linear-gradient(#fff 1px, transparent 1px),
            linear-gradient(90deg, #fff 1px, transparent 1px);
        background-size: 44px 44px;
        mask-image: radial-gradient(
            ellipse at 50% 0%,
            #000 30%,
            transparent 75%
        );
    }

    .tc-hero-title {
        @apply text-2xl lg:text-[2rem] font-extrabold leading-tight tracking-tight text-white;
    }

    .tc-hero-sub {
        @apply mt-1.5 flex flex-wrap items-center gap-x-2 gap-y-1 text-xs font-medium text-white/60;
    }

    /* Trauma level chip — Normal / High Alert / Mass Casualty. */
    .tc-level {
        --tc-accent: var(--tc-stable);
        @apply inline-flex items-center gap-2 rounded-full px-3 py-1.5 text-xs font-bold uppercase tracking-wide backdrop-blur-md;
        color: var(--tc-accent);
        background-color: color-mix(
            in oklab,
            var(--tc-accent) 16%,
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(in oklab, var(--tc-accent) 40%, transparent);
    }
    .tc-level.is-normal {
        --tc-accent: var(--tc-stable);
    }
    .tc-level.is-high {
        --tc-accent: var(--tc-high);
    }
    .tc-level.is-mass {
        --tc-accent: var(--tc-critical);
    }

    .tc-level-dot {
        @apply size-1.5 rounded-full;
        background-color: var(--tc-accent);
        animation: tc-ping 1.8s ease-in-out infinite;
    }

    /* Hero quick actions. */
    .tc-action {
        @apply inline-flex items-center gap-2 rounded-xl px-3.5 py-2.5 text-xs font-bold transition-all duration-300;
        @apply border border-white/15 bg-white/10 text-white backdrop-blur-md;
    }
    .tc-action:hover {
        @apply -translate-y-0.5 border-white/30 bg-white/20;
    }
    .tc-action:focus-visible {
        @apply outline-2 outline-offset-2 outline-white/70;
    }
    .tc-action.is-primary {
        @apply border-transparent bg-danger text-white;
        box-shadow: 0 12px 28px -10px
            color-mix(in oklab, var(--color-danger) 85%, transparent);
    }
    .tc-action.is-primary:hover {
        @apply bg-red-700;
    }

    /* --- KPI widgets ---------------------------------------------------- */
    .tc-kpis {
        @apply grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-4;
    }

    .tc-kpi {
        --tc-accent: var(--color-primary);
        @apply relative isolate overflow-hidden rounded-xl p-4 transition-all duration-300;
        @apply border border-white/60 bg-white/70 backdrop-blur-xl;
        @apply dark:border-white/10 dark:bg-slate-800/60;
    }

    /* Accent wash — the gradient background. */
    .tc-kpi::before {
        content: "";
        @apply pointer-events-none absolute inset-0 -z-10 opacity-[0.10] transition-opacity duration-300;
        background-image: linear-gradient(
            150deg,
            var(--tc-accent) 0%,
            transparent 60%
        );
    }

    /* Specular sheen across the top — the glass highlight. */
    .tc-kpi::after {
        content: "";
        @apply pointer-events-none absolute inset-x-0 top-0 -z-10 h-px;
        background-image: linear-gradient(
            90deg,
            transparent,
            color-mix(in oklab, var(--tc-accent) 70%, white),
            transparent
        );
    }

    .tc-kpi:hover {
        @apply -translate-y-1.5;
        border-color: color-mix(in oklab, var(--tc-accent) 50%, transparent);
        box-shadow: 0 24px 48px -20px
            color-mix(in oklab, var(--tc-accent) 80%, transparent);
    }
    .tc-kpi:hover::before {
        @apply opacity-20;
    }

    .tc-kpi-head {
        @apply flex items-start justify-between gap-3;
    }

    .tc-kpi-icon {
        @apply flex size-11 shrink-0 items-center justify-center rounded-xl text-xl transition-transform duration-300;
        color: var(--tc-accent);
        background-image: linear-gradient(
            145deg,
            color-mix(in oklab, var(--tc-accent) 22%, transparent),
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(in oklab, var(--tc-accent) 28%, transparent);
    }
    .tc-kpi:hover .tc-kpi-icon {
        @apply scale-110 -rotate-6;
    }

    /* Circular progress gauge. */
    .tc-kpi-ring {
        @apply size-12 shrink-0 -rotate-90;
        color: var(--tc-accent);
    }
    .tc-kpi-ring-track {
        @apply text-gray-200 dark:text-slate-700;
    }
    .tc-kpi-ring-label {
        @apply absolute inset-0 grid place-items-center text-[10px] font-extrabold tabular-nums;
        color: var(--tc-accent);
    }

    .tc-kpi-value {
        @apply mt-3.5 text-[1.75rem] font-extrabold leading-none tracking-tight text-gray-900 tabular-nums;
    }
    .tc-kpi-label {
        @apply mt-1 text-[11px] font-semibold text-gray-500 dark:text-gray-400;
    }

    .tc-kpi-foot {
        @apply mt-3 flex items-end justify-between gap-2;
    }
    .tc-kpi-spark {
        @apply h-7 w-16 shrink-0 overflow-visible;
        color: var(--tc-accent);
    }

    /* Status chip. */
    .hms-chip {
        @apply inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-bold whitespace-nowrap;
        color: var(--tc-accent);
        background-color: color-mix(
            in oklab,
            var(--tc-accent) 14%,
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(in oklab, var(--tc-accent) 25%, transparent);
    }

    /* KPI + board tones. */
    .tone-critical {
        --tc-accent: var(--tc-critical);
    }
    .tone-high {
        --tc-accent: var(--tc-high);
    }
    .tone-medium {
        --tc-accent: var(--tc-medium);
    }
    .tone-stable {
        --tc-accent: var(--tc-stable);
    }
    .tone-info {
        --tc-accent: var(--tc-info);
    }
    .tone-purple {
        --tc-accent: var(--tc-purple);
    }

    /* Filter-chip tones: neutral default state + active/selected state. */
    .hms-chip.tone-slate {
        --tc-accent: var(--color-gray-600);
    }
    .hms-chip.ph-primary {
        --tc-accent: var(--color-primary);
    }

    /* --- Panels (overview widgets) -------------------------------------- */
    .hms-panel {
        @apply relative overflow-hidden rounded-xl border border-border-color bg-white transition-shadow duration-300;
        @apply dark:border-white/10 dark:bg-slate-800/60 dark:backdrop-blur-xl;
    }
    .hms-panel:hover {
        @apply shadow-[0_18px_44px_-24px_rgba(15,23,42,0.55)];
    }
    .hms-panel-head {
        @apply flex flex-wrap items-center gap-2 border-b border-border-color p-4 dark:border-white/10;
    }
    .hms-panel-title {
        @apply text-sm font-bold text-gray-900;
    }
    .hms-panel-icon {
        @apply flex size-8 shrink-0 items-center justify-center rounded-xl text-sm;
        color: var(--tc-accent, var(--color-primary));
        background-color: color-mix(
            in oklab,
            var(--tc-accent, var(--color-primary)) 12%,
            transparent
        );
    }

    /* Hourly admissions — column chart. */
    .tc-bar {
        @apply transition-all duration-300;
        fill: color-mix(in oklab, var(--color-primary) 35%, transparent);
    }
    .tc-bar.is-peak {
        fill: var(--color-danger);
    }
    .tc-bar:hover {
        fill: var(--color-primary);
    }

    /* Department rail. */
    .tc-dept {
        @apply flex items-center gap-3 rounded-xl p-2.5 transition-colors duration-200;
    }
    .tc-dept:hover {
        @apply bg-gray-50 dark:bg-slate-700/40;
    }

    /* --- Priority board (kanban) ---------------------------------------- */
    .tc-board {
        @apply grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-4;
    }

    .tc-col {
        --tc-accent: var(--color-primary);
        @apply flex flex-col rounded-xl border border-border-color bg-gray-50/70 p-3 dark:border-white/10 dark:bg-slate-900/40;
    }
    .tc-col-head {
        @apply mb-3 flex items-center gap-2 rounded-xl px-3 py-2;
        background-color: color-mix(
            in oklab,
            var(--tc-accent) 10%,
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(in oklab, var(--tc-accent) 20%, transparent);
    }
    .tc-col-title {
        @apply text-xs font-extrabold uppercase tracking-wide;
        color: var(--tc-accent);
    }
    .tc-col-count {
        @apply ml-auto rounded-full px-2 py-0.5 text-[10px] font-extrabold tabular-nums text-white;
        background-color: var(--tc-accent);
    }
    .tc-col-body {
        @apply flex-1 space-y-2.5 rounded-lg transition-colors duration-150;
    }
    .tc-col-body.is-drop-target {
        @apply outline-dashed outline-2 -outline-offset-2 outline-[var(--tc-accent)];
        background-color: color-mix(in oklab, var(--tc-accent) 8%, transparent);
    }
    .tc-col-empty {
        @apply rounded-xl border border-dashed border-border-color p-4 text-center text-[11px] font-semibold text-gray-400 dark:border-white/10;
    }

    /* Ticket — draggable between priority columns. */
    .tc-ticket {
        @apply relative cursor-grab overflow-hidden rounded-xl border border-border-color bg-white p-3 transition-all duration-300;
        @apply dark:border-white/10 dark:bg-slate-800;
    }
    .tc-ticket::before {
        content: "";
        @apply absolute inset-y-0 left-0 w-1;
        background-image: linear-gradient(
            180deg,
            var(--tc-accent),
            color-mix(in oklab, var(--tc-accent) 30%, transparent)
        );
    }
    .tc-ticket:hover {
        @apply -translate-y-0.5 rotate-[-0.4deg];
        border-color: color-mix(in oklab, var(--tc-accent) 45%, transparent);
        box-shadow: 0 16px 32px -18px
            color-mix(in oklab, var(--tc-accent) 85%, transparent);
    }
    .tc-ticket:active {
        @apply cursor-grabbing scale-[0.99];
    }
    .tc-ticket.is-dragging {
        @apply cursor-grabbing opacity-40;
    }
    .tc-grip {
        @apply text-gray-300 transition-colors duration-200 dark:text-slate-600;
    }
    .tc-ticket:hover .tc-grip {
        color: var(--tc-accent);
    }

    /* --- Enterprise case grid ------------------------------------------- */
    .hms-row {
        @apply border-b border-border-color transition-colors duration-200 dark:border-white/5;
    }
    .hms-row:hover {
        @apply bg-gray-50/80 dark:bg-slate-700/30;
    }
    .hms-row:last-child {
        @apply border-b-0;
    }
    .hms-cell {
        @apply px-4 py-3 align-middle;
    }
    .hms-th {
        @apply px-4 py-3 text-left text-[10px] font-extrabold uppercase tracking-wider text-gray-400 border-b border-border-color dark:border-white/5;
    }

    /* Severity meter inside the grid. */
    .tc-sev {
        @apply inline-flex items-center gap-1;
    }
    .tc-sev-pip {
        @apply h-3.5 w-1 rounded-full bg-gray-200 dark:bg-slate-600;
    }
    .tc-sev-pip.is-on {
        background-color: var(--tc-accent);
    }

    /* --- Slide-over drawer ---------------------------------------------- */
    .hms-drawer {
        @apply fixed inset-0 z-[70] hidden;
    }
    .hms-drawer.is-open {
        @apply block;
    }
    .hms-drawer-backdrop {
        @apply absolute inset-0 bg-slate-900/50 opacity-0 backdrop-blur-sm transition-opacity duration-300;
    }
    .hms-drawer.is-open .hms-drawer-backdrop {
        @apply opacity-100;
    }
    .hms-drawer-panel {
        @apply absolute inset-y-0 right-0 flex w-full max-w-xl translate-x-full flex-col bg-white shadow-2xl transition-transform duration-300 ease-out;
        @apply dark:bg-slate-900;
    }
    .hms-drawer.is-open .hms-drawer-panel {
        @apply translate-x-0;
    }
    .hms-drawer-head {
        @apply relative overflow-hidden p-5;
        background-image: linear-gradient(120deg, #0b1220 0%, #1f2f4a 100%);
    }
    .hms-drawer-body {
        @apply flex-1 overflow-y-auto p-5 space-y-5;
    }
    .hms-drawer-foot {
        @apply border-t border-border-color p-4 dark:border-white/10;
    }

    /* Vitals tile. */
    .tc-vital {
        @apply rounded-xl border border-border-color p-3 transition-colors duration-200 dark:border-white/10;
    }
    .tc-vital.is-alert {
        border-color: color-mix(in oklab, var(--color-danger) 45%, transparent);
        background-color: color-mix(
            in oklab,
            var(--color-danger) 6%,
            transparent
        );
    }

    /* Injury diagram placeholder. */
    .tc-body-map {
        @apply relative grid place-items-center rounded-xl border border-dashed border-border-color p-4 dark:border-white/15;
        background-image: radial-gradient(
            circle at 50% 30%,
            color-mix(in oklab, var(--color-danger) 8%, transparent),
            transparent 70%
        );
    }
    .tc-body-part {
        @apply transition-all duration-300;
        fill: color-mix(in oklab, var(--color-primary) 12%, transparent);
        stroke: color-mix(in oklab, var(--color-primary) 30%, transparent);
    }
    .tc-body-part.is-hit {
        fill: color-mix(in oklab, var(--color-danger) 45%, transparent);
        stroke: var(--color-danger);
    }
    .tc-body-part.is-hit:hover {
        fill: var(--color-danger);
    }

    /* --- Timelines ------------------------------------------------------ */
    .hms-tl {
        @apply relative;
    }
    .hms-tl-item {
        @apply relative flex gap-3 pb-5 last:pb-0;
    }
    /* Rail runs between nodes; the last item drops it so the list ends clean. */
    .hms-tl-item:not(:last-child)::before {
        content: "";
        @apply absolute left-[11px] top-6 bottom-0 w-px bg-border-color dark:bg-white/10;
    }
    .hms-tl-node {
        @apply relative z-10 grid size-6 shrink-0 place-items-center rounded-full text-[10px] transition-transform duration-300;
        @apply bg-gray-100 text-gray-400 dark:bg-slate-700 dark:text-slate-400;
    }
    .hms-tl-item.is-done .hms-tl-node {
        @apply bg-success/15 text-success;
        box-shadow: inset 0 0 0 1px
            color-mix(in oklab, var(--color-success) 40%, transparent);
    }
    .hms-tl-item.is-current .hms-tl-node {
        @apply bg-danger text-white;
        animation: tc-ping 1.8s ease-in-out infinite;
    }
    .hms-tl-item.is-done:not(:last-child)::before {
        @apply bg-success/30;
    }

    /* --- Trauma team ---------------------------------------------------- */
    .hms-member {
        @apply flex items-center gap-3 rounded-xl border border-border-color p-3 transition-all duration-300;
        @apply dark:border-white/10;
    }
    .hms-member:hover {
        @apply -translate-y-0.5;
        border-color: color-mix(in oklab, var(--tc-accent) 45%, transparent);
        box-shadow: 0 14px 30px -20px
            color-mix(in oklab, var(--tc-accent) 80%, transparent);
    }
    .hms-member-avatar {
        @apply relative grid size-10 shrink-0 place-items-center overflow-hidden rounded-xl text-xs font-extrabold;
        color: var(--tc-accent);
        background-color: color-mix(
            in oklab,
            var(--tc-accent) 14%,
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(in oklab, var(--tc-accent) 25%, transparent);
    }
    .hms-member-avatar img {
        @apply absolute inset-0 size-full object-cover;
    }
    .hms-member-dot {
        @apply absolute -bottom-0.5 -right-0.5 size-3 rounded-full border-2 border-white dark:border-slate-800;
        background-color: var(--tc-accent);
    }

    @keyframes tc-ping {
        0%,
        100% {
            opacity: 1;
        }
        50% {
            opacity: 0.4;
        }
    }

    /* =====================================================================
       CRITICAL CARE — EXCLUSIVE to critical-care.html.
       A bedside-monitor language: dark waveform screens, parameter-coloured
       readouts, organ-support matrix and NEWS2 rails. Deliberately distinct
       from .tc-* (trauma command centre) and .er-kpi (emergency board).
       ===================================================================== */

    /* Parameter colours follow real bedside monitor convention. */
    .cc-scope {
        --cc-hr: #22c55e;
        --cc-spo2: #06b6d4;
        --cc-bp: #ef4444;
        --cc-rr: #eab308;
        --cc-support: #a855f7;
        --cc-score: #f97316;
    }

    /* --- Hero ----------------------------------------------------------- */
    .cc-hero {
        @apply relative isolate overflow-hidden rounded-xl p-6 lg:p-8;
        background-image: linear-gradient(
            120deg,
            #042f2e 0%,
            #0b3f47 50%,
            #0e4f5c 100%
        );
    }
    .cc-hero::before {
        content: "";
        @apply pointer-events-none absolute -right-32 -top-28 -z-10 size-[28rem] rounded-full blur-3xl opacity-35;
        background-image: radial-gradient(circle, #06b6d4 0%, transparent 65%);
    }
    .cc-hero::after {
        content: "";
        @apply pointer-events-none absolute -bottom-36 left-1/3 -z-10 size-[22rem] rounded-full blur-3xl opacity-25;
        background-image: radial-gradient(circle, #22c55e 0%, transparent 65%);
    }

    /* Continuous ECG trace across the hero — the critical-care signature. */
    .cc-hero-trace {
        @apply pointer-events-none absolute inset-x-0 bottom-0 -z-10 h-24 w-full opacity-25;
        color: #22c55e;
    }
    .cc-hero-trace-line {
        stroke-dasharray: 600;
        animation: cc-sweep 6s linear infinite;
    }

    .cc-hero-title {
        @apply text-2xl lg:text-[2rem] font-extrabold leading-tight tracking-tight text-white;
    }
    .cc-hero-sub {
        @apply mt-1.5 flex flex-wrap items-center gap-x-2 gap-y-1 text-xs font-medium text-white/60;
    }

    .cc-status {
        --cc-accent: #22c55e;
        @apply inline-flex items-center gap-2 rounded-full px-3 py-1.5 text-xs font-bold uppercase tracking-wide backdrop-blur-md;
        color: var(--cc-accent);
        background-color: color-mix(
            in oklab,
            var(--cc-accent) 16%,
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(in oklab, var(--cc-accent) 40%, transparent);
    }
    .cc-status.is-stable {
        --cc-accent: #22c55e;
    }
    .cc-status.is-strained {
        --cc-accent: #eab308;
    }
    .cc-status.is-critical {
        --cc-accent: #ef4444;
    }
    .cc-status-dot {
        @apply size-1.5 rounded-full;
        background-color: var(--cc-accent);
        animation: tc-ping 1.6s ease-in-out infinite;
    }

    .cc-action {
        @apply inline-flex items-center gap-2 rounded-xl border border-white/15 bg-white/10 px-3.5 py-2.5 text-xs font-bold text-white backdrop-blur-md transition-all duration-300;
    }
    .cc-action:hover {
        @apply -translate-y-0.5 border-white/30 bg-white/20;
    }
    .cc-action:focus-visible {
        @apply outline-2 outline-offset-2 outline-white/70;
    }
    .cc-action.is-primary {
        @apply border-transparent bg-teal-500 text-white;
        box-shadow: 0 12px 28px -10px #14b8a6;
    }
    .cc-action.is-primary:hover {
        @apply bg-teal-600;
    }

    /* --- Monitor widgets ------------------------------------------------ */
    .cc-mons {
        @apply grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-4;
    }

    .cc-mon {
        --cc-accent: var(--cc-hr);
        @apply relative overflow-hidden rounded-xl border border-border-color bg-white p-3 transition-all duration-300;
        @apply dark:border-white/10 dark:bg-slate-800;
    }
    .cc-mon:hover {
        @apply -translate-y-1.5;
        border-color: color-mix(in oklab, var(--cc-accent) 55%, transparent);
        box-shadow: 0 22px 44px -20px
            color-mix(in oklab, var(--cc-accent) 80%, transparent);
    }

    /* Alarm state — a monitor that needs a nurse, not a decoration. */
    .cc-mon.is-alarm {
        border-color: color-mix(in oklab, var(--cc-bp) 60%, transparent);
        animation: cc-alarm 1.6s ease-in-out infinite;
    }

    .cc-mon-head {
        @apply flex items-center gap-2 px-1 pb-2;
    }
    .cc-mon-label {
        @apply text-[10px] font-extrabold uppercase tracking-wider;
        color: var(--cc-accent);
    }
    .cc-mon-icon {
        @apply text-sm;
        color: var(--cc-accent);
    }

    /* The dark screen stays dark in both themes — it is a monitor, not a card. */
    .cc-screen {
        @apply relative overflow-hidden rounded-xl bg-[#080f1a] p-3;
        box-shadow:
            inset 0 0 0 1px rgba(255, 255, 255, 0.06),
            inset 0 8px 24px -12px rgba(0, 0, 0, 0.9);
    }
    .cc-screen::before {
        content: "";
        @apply pointer-events-none absolute inset-0 opacity-[0.14];
        background-image:
            linear-gradient(rgba(255, 255, 255, 0.5) 1px, transparent 1px),
            linear-gradient(
                90deg,
                rgba(255, 255, 255, 0.5) 1px,
                transparent 1px
            );
        background-size: 14px 14px;
    }

    .cc-readout {
        @apply relative flex items-end gap-1 leading-none;
        color: var(--cc-accent);
    }
    .cc-readout-value {
        @apply text-[1.6rem] font-extrabold tabular-nums;
        text-shadow: 0 0 18px
            color-mix(in oklab, var(--cc-accent) 55%, transparent);
    }
    .cc-readout-unit {
        @apply pb-0.5 text-[9px] font-bold opacity-70;
    }
    .cc-readout-meta {
        @apply relative mt-0.5 text-[9px] font-semibold text-white/35;
    }

    /* Live waveform. */
    .cc-wave {
        @apply relative mt-1.5 h-8 w-full overflow-visible;
        color: var(--cc-accent);
    }
    .cc-wave-line {
        stroke-dasharray: 300;
        animation: cc-sweep 3.2s linear infinite;
    }

    /* Parameter accent selectors — applied to .cc-mon and .cc-screen so the
       readout, waveform and glow all take the monitor colour for that vital. */
    .accent-hr {
        --cc-accent: var(--cc-hr);
    }
    .accent-spo2 {
        --cc-accent: var(--cc-spo2);
    }
    .accent-bp {
        --cc-accent: var(--cc-bp);
    }
    .accent-rr {
        --cc-accent: var(--cc-rr);
    }
    .accent-support {
        --cc-accent: var(--cc-support);
    }
    .accent-score {
        --cc-accent: var(--cc-score);
    }

    /* --- Organ support matrix ------------------------------------------- */
    /* Organ support reads purple everywhere it appears — matrix, grid and
       drawer — so the colour means "support", not "acuity". */
    .cc-organ {
        --cc-accent: var(--cc-support);
        @apply grid size-7 place-items-center rounded-xl text-[11px] transition-all duration-200;
        @apply bg-gray-100 text-gray-300 dark:bg-slate-700/50 dark:text-slate-600;
    }
    .cc-organ.is-on {
        color: var(--cc-accent);
        background-color: color-mix(
            in oklab,
            var(--cc-accent) 16%,
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(in oklab, var(--cc-accent) 35%, transparent);
    }
    .cc-organ.is-on:hover {
        @apply scale-110;
    }

    /* --- NEWS2 severity rail -------------------------------------------- */
    .cc-news {
        @apply inline-flex items-center gap-1 rounded-xl px-2 py-1 text-[10px] font-extrabold tabular-nums;
        color: var(--cc-accent);
        background-color: color-mix(
            in oklab,
            var(--cc-accent) 14%,
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(in oklab, var(--cc-accent) 30%, transparent);
    }
    .cc-news.is-low {
        --cc-accent: #22c55e;
    }
    .cc-news.is-medium {
        --cc-accent: #eab308;
    }
    .cc-news.is-high {
        --cc-accent: #f97316;
    }
    .cc-news.is-critical {
        --cc-accent: #ef4444;
    }

    /* --- Bed bay tile --------------------------------------------------- */
    /* Bays are tinted by patient condition, which arrives as a .tone-* class,
       so they read --tc-accent. The fallback covers empty bays. */
    .cc-bay {
        --cc-accent: var(--tc-accent, #94a3b8);
        @apply relative overflow-hidden rounded-xl border border-border-color bg-white p-3 transition-all duration-300;
        @apply dark:border-white/10 dark:bg-slate-800;
    }
    .cc-bay::before {
        content: "";
        @apply absolute inset-x-0 top-0 h-0.5;
        background-color: var(--cc-accent);
    }
    .cc-bay:hover {
        @apply -translate-y-1;
        border-color: color-mix(in oklab, var(--cc-accent) 50%, transparent);
        box-shadow: 0 16px 32px -18px
            color-mix(in oklab, var(--cc-accent) 80%, transparent);
    }
    .cc-bay.is-empty {
        @apply border-dashed bg-gray-50/60 dark:bg-slate-900/40;
    }

    /* --- Sedation (RASS) scale ------------------------------------------ */
    .cc-rass {
        @apply flex items-center gap-0.5;
    }
    .cc-rass-step {
        @apply h-4 w-1.5 rounded-sm bg-gray-200 transition-colors duration-200 dark:bg-slate-600;
    }
    .cc-rass-step.is-on {
        background-color: var(--cc-accent, #a855f7);
    }

    /* --- Shift rounds --------------------------------------------------- */
    .cc-round {
        @apply flex items-center gap-3 rounded-xl border border-border-color p-3 transition-colors duration-200 dark:border-white/10;
    }
    .cc-round.is-now {
        border-color: color-mix(in oklab, var(--cc-spo2) 50%, transparent);
        background-color: color-mix(in oklab, var(--cc-spo2) 6%, transparent);
    }

    @keyframes cc-sweep {
        from {
            stroke-dashoffset: 600;
        }
        to {
            stroke-dashoffset: 0;
        }
    }

    @keyframes cc-alarm {
        0%,
        100% {
            box-shadow: 0 0 0 0
                color-mix(in oklab, var(--cc-bp) 45%, transparent);
        }
        50% {
            box-shadow: 0 0 0 6px transparent;
        }
    }

    /* =====================================================================
       WARDS & BEDS — module language, shared by the bed-* pages.
       A floor-plan / blueprint identity: capacity strips made of bed pips,
       architectural grid, state-coded tiles. Distinct from the Emergency
       (.er-kpi), Trauma (.tc-*) and Critical Care (.cc-*) languages.
       ===================================================================== */

    .wb-scope {
        --wb-occupied: #0371c6;
        --wb-available: #10b981;
        --wb-cleaning: #f59e0b;
        --wb-blocked: #64748b;
        --wb-maintenance: #7c3aed;
        --wb-reserved: #06b6d4;
    }

    /* --- Hero — a blueprint, not a command centre ----------------------- */
    .wb-hero {
        @apply relative isolate overflow-hidden rounded-xl border border-border-color bg-white p-6 lg:p-8;
        @apply dark:border-white/10 dark:bg-slate-800;
    }
    .wb-hero::before {
        content: "";
        @apply pointer-events-none absolute inset-0 -z-10 opacity-[0.06] dark:opacity-[0.10];
        background-image:
            linear-gradient(var(--color-primary) 1px, transparent 1px),
            linear-gradient(90deg, var(--color-primary) 1px, transparent 1px);
        background-size: 32px 32px;
        mask-image: radial-gradient(
            ellipse at 100% 0%,
            #000 10%,
            transparent 70%
        );
    }
    .wb-hero::after {
        content: "";
        @apply pointer-events-none absolute -right-20 -top-24 -z-10 size-80 rounded-full blur-3xl opacity-[0.12];
        background-color: var(--color-primary);
    }
    .wb-hero-title {
        @apply text-2xl lg:text-[1.75rem] font-extrabold leading-tight tracking-tight text-gray-900;
    }
    .wb-hero-sub {
        @apply mt-1.5 flex flex-wrap items-center gap-x-2 gap-y-1 text-xs font-medium text-gray-500 dark:text-gray-400;
    }

    .wb-action {
        @apply inline-flex items-center gap-2 rounded-xl border border-border-color bg-white px-3.5 py-2.5 text-xs font-bold text-gray-900 transition-all duration-300;
        @apply dark:border-white/10 dark:bg-slate-700;
    }
    .wb-action:hover {
        @apply -translate-y-0.5 border-primary/40 shadow-[0_10px_24px_-14px_var(--color-primary)];
    }
    .wb-action.is-primary {
        @apply border-transparent bg-primary text-white;
    }
    .wb-action.is-primary:hover {
        @apply bg-primary-hover;
    }

    /* --- Capacity KPI --------------------------------------------------- */
    .wb-kpis {
        @apply grid grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-4;
    }

    .wb-kpi {
        --wb-accent: var(--wb-occupied);
        @apply relative overflow-hidden rounded-xl border border-border-color bg-white p-4 transition-all duration-300;
        @apply dark:border-white/10 dark:bg-slate-800;
    }
    /* Blueprint grid tint — the module signature. */
    .wb-kpi::before {
        content: "";
        @apply pointer-events-none absolute inset-0 opacity-[0.05];
        background-image:
            linear-gradient(var(--wb-accent) 1px, transparent 1px),
            linear-gradient(90deg, var(--wb-accent) 1px, transparent 1px);
        background-size: 16px 16px;
    }
    .wb-kpi:hover {
        @apply -translate-y-1;
        border-color: color-mix(in oklab, var(--wb-accent) 45%, transparent);
        box-shadow: 0 20px 40px -22px
            color-mix(in oklab, var(--wb-accent) 80%, transparent);
    }

    .wb-kpi-head {
        @apply relative flex items-center gap-2;
    }
    .wb-kpi-icon {
        @apply grid size-8 shrink-0 place-items-center rounded-xl text-sm;
        color: var(--wb-accent);
        background-color: color-mix(
            in oklab,
            var(--wb-accent) 12%,
            transparent
        );
    }
    .wb-kpi-label {
        @apply text-[10px] font-extrabold uppercase tracking-wider text-gray-400;
    }
    .wb-kpi-value {
        @apply relative mt-3 text-[1.75rem] font-extrabold leading-none tracking-tight text-gray-900 tabular-nums;
    }
    .wb-kpi-share {
        @apply relative ml-1 text-xs font-bold text-gray-400;
    }

    /* Capacity strip — one pip per bed. This is the module's signature: a
       bed count you can literally see, rather than a bar chart. */
    .wb-strip {
        @apply relative mt-3 flex flex-wrap gap-[3px];
    }
    .wb-pip {
        @apply h-2 flex-1 min-w-[3px] rounded-[2px] bg-gray-200 transition-colors duration-300 dark:bg-slate-600;
    }
    .wb-pip.is-on {
        background-color: var(--wb-accent);
    }
    .wb-kpi-foot {
        @apply relative mt-2.5 flex items-center justify-between gap-2;
    }
    .wb-kpi-meta {
        @apply text-[10px] font-semibold text-gray-400;
    }

    /* --- Bed state tones ------------------------------------------------ */
    .state-occupied {
        --wb-accent: var(--wb-occupied);
    }
    .state-available {
        --wb-accent: var(--wb-available);
    }
    .state-cleaning {
        --wb-accent: var(--wb-cleaning);
    }
    .state-blocked {
        --wb-accent: var(--wb-blocked);
    }
    .state-maintenance {
        --wb-accent: var(--wb-maintenance);
    }
    .state-reserved {
        --wb-accent: var(--wb-reserved);
    }

    /* --- Floor plan ----------------------------------------------------- */
    .wb-ward {
        @apply rounded-xl border border-border-color bg-white p-4 dark:border-white/10 dark:bg-slate-800;
    }
    .wb-floor {
        @apply grid gap-2;
        grid-template-columns: repeat(auto-fill, minmax(4.25rem, 1fr));
    }

    /* A bed tile reads like a plan view: headboard bar, then the berth. */
    .wb-bed {
        --wb-accent: var(--wb-available);
        @apply relative grid aspect-square place-items-center rounded-xl border-2 text-[10px] font-extrabold transition-all duration-200;
        border-color: color-mix(in oklab, var(--wb-accent) 40%, transparent);
        background-color: color-mix(in oklab, var(--wb-accent) 8%, transparent);
        color: color-mix(in oklab, var(--wb-accent) 90%, black 10%);
    }
    .wb-bed::before {
        content: "";
        @apply absolute inset-x-2 top-1 h-1 rounded-full;
        background-color: color-mix(
            in oklab,
            var(--wb-accent) 55%,
            transparent
        );
    }
    .wb-bed:hover {
        @apply z-10 scale-110;
        border-color: var(--wb-accent);
        box-shadow: 0 12px 24px -12px var(--wb-accent);
    }
    .wb-bed:focus-visible {
        outline: 2px solid var(--wb-accent);
        outline-offset: 2px;
    }
    /* Overdue turnaround pulses — housekeeping needs to see it. */
    .wb-bed.is-overdue {
        animation: wb-flag 1.8s ease-in-out infinite;
    }

    .wb-legend {
        @apply inline-flex items-center gap-1.5 text-[10px] font-bold text-gray-500 dark:text-gray-400;
    }
    .wb-legend-dot {
        @apply size-2 rounded-full;
        background-color: var(--wb-accent);
    }

    /* --- Housekeeping queue --------------------------------------------- */
    .wb-task {
        @apply flex items-center gap-3 rounded-xl border border-border-color p-3 transition-all duration-200 dark:border-white/10;
    }
    .wb-task:hover {
        @apply -translate-y-0.5;
        border-color: color-mix(in oklab, var(--wb-accent) 45%, transparent);
    }
    .wb-task.is-overdue {
        border-color: color-mix(in oklab, var(--color-danger) 45%, transparent);
        background-color: color-mix(
            in oklab,
            var(--color-danger) 5%,
            transparent
        );
    }

    /* --- Turnaround gauge ----------------------------------------------- */
    .wb-gauge {
        @apply h-2 w-full;
        color: var(--wb-accent);
    }

    /* --- Allocation matching (bed-allocation) --------------------------- */
    /* A waiting patient reads as a queue ticket; selecting one ranks the
       open beds against their requirements. */
    .wb-wait {
        --wb-accent: var(--wb-occupied);
        @apply relative cursor-pointer overflow-hidden rounded-xl border border-border-color bg-white p-3 transition-all duration-200;
        @apply dark:border-white/10 dark:bg-slate-800;
    }
    .wb-wait::before {
        content: "";
        @apply absolute inset-y-0 left-0 w-1;
        background-color: var(--wb-accent);
    }
    .wb-wait:hover {
        @apply -translate-y-0.5;
        border-color: color-mix(in oklab, var(--wb-accent) 45%, transparent);
    }
    .wb-wait.is-active {
        border-color: var(--wb-accent);
        background-color: color-mix(in oklab, var(--wb-accent) 6%, transparent);
        box-shadow: 0 12px 26px -16px
            color-mix(in oklab, var(--wb-accent) 85%, transparent);
    }

    /* Candidate bed with a fit score. */
    .wb-cand {
        --wb-accent: var(--wb-available);
        @apply flex items-center gap-3 rounded-xl border border-border-color p-3 transition-all duration-200 dark:border-white/10;
    }
    .wb-cand:hover {
        @apply -translate-y-0.5;
        border-color: color-mix(in oklab, var(--wb-accent) 45%, transparent);
        box-shadow: 0 14px 28px -18px
            color-mix(in oklab, var(--wb-accent) 80%, transparent);
    }
    .wb-cand.is-best {
        border-color: color-mix(in oklab, var(--wb-accent) 55%, transparent);
        background-color: color-mix(in oklab, var(--wb-accent) 5%, transparent);
    }

    /* Fit-score ring — circumference 100 so dasharray reads as a percentage. */
    .wb-fit {
        @apply size-11 shrink-0 -rotate-90;
        color: var(--wb-accent);
    }
    .wb-fit-track {
        @apply text-gray-200 dark:text-slate-700;
    }
    .wb-fit-label {
        @apply absolute grid size-11 place-items-center text-[10px] font-extrabold tabular-nums;
        color: var(--wb-accent);
    }

    /* Requirement chip — met or unmet. */
    .wb-req {
        @apply inline-flex items-center gap-1 rounded-md px-1.5 py-0.5 text-[10px] font-bold;
    }
    .wb-req.is-met {
        @apply bg-success/10 text-success;
    }
    .wb-req.is-unmet {
        @apply bg-danger/10 text-danger;
    }

    /* Score tones for the fit ring / badge. */
    .fit-strong {
        --wb-accent: var(--wb-available);
    }
    .fit-fair {
        --wb-accent: var(--wb-cleaning);
    }
    .fit-poor {
        --wb-accent: var(--color-danger);
    }

    /* --- Transfer tracker (bed-transfer) -------------------------------- */
    /* Stage lanes for a live transfer board. */
    .wb-lane {
        --wb-accent: var(--wb-occupied);
        @apply flex flex-col rounded-xl border border-border-color bg-gray-50/70 p-3 dark:border-white/10 dark:bg-slate-900/40;
    }
    .wb-lane-head {
        @apply mb-3 flex items-center gap-2 rounded-xl px-3 py-2;
        background-color: color-mix(
            in oklab,
            var(--wb-accent) 10%,
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(in oklab, var(--wb-accent) 20%, transparent);
    }
    .wb-lane-title {
        @apply text-xs font-extrabold uppercase tracking-wide;
        color: var(--wb-accent);
    }
    .wb-lane-count {
        @apply ml-auto rounded-full px-2 py-0.5 text-[10px] font-extrabold tabular-nums text-white;
        background-color: var(--wb-accent);
    }

    /* A transfer card, colour-keyed to its urgency. */
    .wb-move {
        --wb-accent: var(--wb-occupied);
        @apply relative overflow-hidden rounded-xl border border-border-color bg-white p-3 transition-all duration-200;
        @apply dark:border-white/10 dark:bg-slate-800;
    }
    .wb-move::before {
        content: "";
        @apply absolute inset-y-0 left-0 w-1;
        background-color: var(--wb-accent);
    }
    .wb-move:hover {
        @apply -translate-y-0.5;
        border-color: color-mix(in oklab, var(--wb-accent) 45%, transparent);
        box-shadow: 0 14px 28px -18px
            color-mix(in oklab, var(--wb-accent) 85%, transparent);
    }
    .wb-move[draggable="true"] {
        cursor: grab;
    }
    .wb-move.is-dragging {
        @apply opacity-40;
        cursor: grabbing;
    }

    /* Lane body while a card is dragged over it as a drop target. */
    .wb-lane-body {
        @apply flex-1 space-y-2.5 rounded-lg transition-colors duration-150;
    }
    .wb-lane-body.is-drop-target {
        background-color: color-mix(
            in oklab,
            var(--wb-accent) 12%,
            transparent
        );
        outline: 2px dashed
            color-mix(in oklab, var(--wb-accent) 45%, transparent);
        outline-offset: 2px;
    }

    /* Source → destination route. */
    .wb-route {
        @apply flex items-center gap-1.5 text-[11px] font-bold;
    }
    .wb-route-node {
        @apply rounded-md px-1.5 py-0.5 font-mono text-[10px];
        @apply bg-gray-100 text-gray-700 dark:bg-slate-700 dark:text-gray-200;
    }
    .wb-route-arrow {
        @apply text-gray-300 dark:text-slate-500;
    }
    .wb-route-node.is-dest {
        color: var(--wb-accent);
        background-color: color-mix(
            in oklab,
            var(--wb-accent) 14%,
            transparent
        );
    }

    /* Direction tones for transfers. */
    .move-stepup {
        --wb-accent: var(--color-danger);
    }
    .move-stepdown {
        --wb-accent: var(--wb-available);
    }
    .move-lateral {
        --wb-accent: var(--wb-occupied);
    }
    .move-external {
        --wb-accent: var(--wb-maintenance);
    }

    /* --- Occupancy analytics (bed-occupancy) ---------------------------- */
    /* Heat cell — occupancy intensity bucketed into six discrete levels so
       the colour lives entirely in CSS (SVG <rect fill>), no inline styles.
       lvl-1 = coolest (low occupancy) … lvl-6 = hottest (at/over capacity). */
    .wb-heat {
        transition: opacity 0.15s ease;
    }
    .wb-heat.lvl-1 {
        fill: color-mix(in oklab, var(--wb-occupied) 12%, var(--color-white));
    }
    .wb-heat.lvl-2 {
        fill: color-mix(in oklab, var(--wb-occupied) 28%, var(--color-white));
    }
    .wb-heat.lvl-3 {
        fill: color-mix(in oklab, var(--wb-occupied) 46%, var(--color-white));
    }
    .wb-heat.lvl-4 {
        fill: color-mix(in oklab, var(--wb-occupied) 66%, var(--color-white));
    }
    .wb-heat.lvl-5 {
        fill: color-mix(in oklab, var(--wb-occupied) 86%, transparent);
    }
    .wb-heat.lvl-6 {
        fill: var(--color-danger);
    }
    .wb-heat:hover {
        @apply opacity-70;
    }
    .wb-heat-label {
        fill: var(--color-gray-600);
    }
    .wb-heat-val {
        @apply text-[8px] font-bold;
        fill: color-mix(in oklab, var(--color-gray-900) 70%, transparent);
    }
    .wb-heat-legend {
        @apply h-2.5 w-full rounded-full;
        background-image: linear-gradient(
            90deg,
            color-mix(in oklab, var(--wb-available) 18%, transparent),
            var(--wb-occupied)
        );
    }

    /* Metric tile — a single analytics figure with a trend hint. */
    .wb-metric {
        --wb-accent: var(--wb-occupied);
        @apply rounded-xl border border-border-color p-3 transition-colors duration-200 dark:border-white/10;
    }
    .wb-metric:hover {
        border-color: color-mix(in oklab, var(--wb-accent) 40%, transparent);
    }
    .wb-delta {
        @apply inline-flex items-center gap-0.5 rounded-full px-1.5 py-0.5 text-[10px] font-bold;
    }
    .wb-delta.is-up {
        @apply bg-danger/10 text-danger;
    }
    .wb-delta.is-down {
        @apply bg-success/10 text-success;
    }
    .wb-delta.is-flat {
        @apply bg-gray-100 text-gray-500 dark:bg-slate-700 dark:text-gray-400;
    }

    /* Chart plot line/area (occupancy trend). */
    .wb-plot-area {
        fill: color-mix(in oklab, var(--color-primary) 14%, transparent);
    }
    .wb-plot-line {
        fill: none;
        stroke: var(--color-primary);
        stroke-width: 2;
    }
    .wb-plot-cap {
        stroke: var(--color-danger);
        stroke-width: 1.5;
        stroke-dasharray: 4 3;
    }

    @keyframes wb-flag {
        0%,
        100% {
            box-shadow: 0 0 0 0
                color-mix(in oklab, var(--color-danger) 50%, transparent);
        }
        50% {
            box-shadow: 0 0 0 5px transparent;
        }
    }

    /* =====================================================================
       PHARMACY — module language for the Pharmacy section (medicines, …).
       An apothecary identity: emerald/teal, capsule-shaped icon tiles,
       dosage-form colour coding and controlled-substance schedules.
       Distinct from Emergency, Trauma, Critical Care and Wards & Beds.
       ===================================================================== */
    .ph-scope {
        --ph-primary: #0d9488;
        --ph-tablet: #0ea5e9;
        --ph-capsule: #f59e0b;
        --ph-syrup: #ec4899;
        --ph-injection: #ef4444;
        --ph-topical: #8b5cf6;
        --ph-drops: #14b8a6;
        --ph-inhaler: #6366f1;
        --ph-ophthalmic: #f97316;
    }

    /* --- Hero ----------------------------------------------------------- */
    .ph-hero {
        @apply relative isolate overflow-hidden rounded-xl p-6 lg:p-8;
        background-image: linear-gradient(
            120deg,
            #053b37 0%,
            #0b544c 50%,
            #0d6b5f 100%
        );
    }
    .ph-hero::before {
        content: "";
        @apply pointer-events-none absolute -right-24 -top-28 -z-10 size-[26rem] rounded-full blur-3xl opacity-35;
        background-image: radial-gradient(circle, #2dd4bf 0%, transparent 65%);
    }
    /* Faint pill motif drifting in the corner. */
    .ph-hero::after {
        content: "";
        @apply pointer-events-none absolute -bottom-16 right-16 -z-10 h-24 w-48 rotate-[-24deg] rounded-full opacity-[0.08];
        background-image: linear-gradient(
            90deg,
            #fff 0 50%,
            transparent 50% 100%
        );
        box-shadow: inset 0 0 0 3px rgba(255, 255, 255, 0.25);
    }
    .ph-hero-title {
        @apply text-2xl lg:text-[1.9rem] font-extrabold leading-tight tracking-tight text-white;
    }
    .ph-hero-sub {
        @apply mt-1.5 flex flex-wrap items-center gap-x-2 gap-y-1 text-xs font-medium text-white/60;
    }

    .ph-action {
        @apply inline-flex items-center gap-2 rounded-xl border border-white/15 bg-white/10 px-3.5 py-2.5 text-xs font-bold text-white backdrop-blur-md transition-all duration-300;
    }
    .ph-action:hover {
        @apply -translate-y-0.5 border-white/30 bg-white/20;
    }
    .ph-action:focus-visible {
        @apply outline-2 outline-offset-2 outline-white/70;
    }
    .ph-action.is-primary {
        @apply border-transparent bg-teal-500 text-white;
        box-shadow: 0 12px 28px -10px #14b8a6;
    }
    .ph-action.is-primary:hover {
        @apply bg-teal-600;
    }

    /* --- KPIs ----------------------------------------------------------- */
    .ph-kpis {
        @apply grid grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-4;
    }
    .ph-kpi {
        --ph-accent: var(--ph-primary);
        @apply relative overflow-hidden rounded-xl border border-border-color bg-white p-4 transition-all duration-300;
        @apply dark:border-white/10 dark:bg-slate-800;
    }
    /* Capsule sheen sweeping the card. */
    .ph-kpi::before {
        content: "";
        @apply pointer-events-none absolute -right-6 -top-6 size-20 rounded-full opacity-[0.10] transition-opacity duration-300;
        background-color: var(--ph-accent);
    }
    .ph-kpi:hover {
        @apply -translate-y-1.5;
        border-color: color-mix(in oklab, var(--ph-accent) 45%, transparent);
        box-shadow: 0 22px 44px -22px
            color-mix(in oklab, var(--ph-accent) 80%, transparent);
    }
    .ph-kpi:hover::before {
        @apply opacity-20;
    }
    .ph-kpi-head {
        @apply flex items-center justify-between gap-2;
    }
    /* Capsule-shaped icon tile — the pharmacy signature. */
    .ph-kpi-icon {
        @apply grid h-8 w-11 shrink-0 place-items-center rounded-full text-sm;
        color: var(--ph-accent);
        background-color: color-mix(
            in oklab,
            var(--ph-accent) 14%,
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(in oklab, var(--ph-accent) 26%, transparent);
    }
    .ph-kpi-value {
        @apply mt-3 text-[1.75rem] font-extrabold leading-none tracking-tight text-gray-900 tabular-nums;
    }
    .ph-kpi-label {
        @apply mt-1 text-[11px] font-semibold text-gray-500 dark:text-gray-400;
    }
    .ph-kpi-meta {
        @apply mt-2 inline-flex items-center gap-1 text-[10px] font-bold;
        color: var(--ph-accent);
    }

    /* KPI accent tones. */
    .ph-primary {
        --ph-accent: var(--ph-primary);
    }
    .ph-sky {
        --ph-accent: var(--ph-tablet);
    }
    .ph-amber {
        --ph-accent: var(--ph-capsule);
    }
    .ph-danger {
        --ph-accent: var(--ph-injection);
    }
    .ph-violet {
        --ph-accent: var(--ph-topical);
    }
    .ph-slate {
        --ph-accent: #64748b;
    }

    /* --- Dosage-form icon (table + drawer) ------------------------------ */
    .ph-form {
        --ph-accent: var(--ph-tablet);
        @apply grid size-9 shrink-0 place-items-center rounded-xl text-sm;
        color: var(--ph-accent);
        background-color: color-mix(
            in oklab,
            var(--ph-accent) 14%,
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(in oklab, var(--ph-accent) 24%, transparent);
    }
    .form-tablet {
        --ph-accent: var(--ph-tablet);
    }
    .form-capsule {
        --ph-accent: var(--ph-capsule);
    }
    .form-syrup {
        --ph-accent: var(--ph-syrup);
    }
    .form-injection {
        --ph-accent: var(--ph-injection);
    }
    .form-topical {
        --ph-accent: var(--ph-topical);
    }
    .form-drops {
        --ph-accent: var(--ph-drops);
    }
    .form-inhaler {
        --ph-accent: var(--ph-inhaler);
    }

    /* --- Controlled-substance schedule badge ---------------------------- */
    .ph-sched {
        @apply inline-flex items-center gap-1 rounded-md px-1.5 py-0.5 text-[10px] font-extrabold;
        color: var(--ph-accent, #64748b);
        background-color: color-mix(
            in oklab,
            var(--ph-accent, #64748b) 14%,
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(in oklab, var(--ph-accent, #64748b) 30%, transparent);
    }
    .sched-2 {
        --ph-accent: var(--ph-injection);
    }
    .sched-3 {
        --ph-accent: var(--ph-capsule);
    }
    .sched-4 {
        --ph-accent: var(--ph-tablet);
    }
    .sched-5 {
        --ph-accent: var(--ph-primary);
    }

    /* --- Stock level meter ---------------------------------------------- */
    .ph-stock {
        @apply h-1.5 w-full;
        color: var(--ph-accent, var(--ph-primary));
    }
    .stock-ok {
        --ph-accent: var(--ph-primary);
    }
    .stock-low {
        --ph-accent: var(--ph-capsule);
    }
    .stock-out {
        --ph-accent: var(--ph-injection);
    }

    /* --- Category card (medicine-categories) ---------------------------- */
    .ph-cats {
        @apply grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4;
    }
    .ph-cat {
        --ph-accent: var(--ph-primary);
        @apply relative flex flex-col overflow-hidden rounded-xl border border-border-color bg-white p-4 transition-all duration-300;
        @apply dark:border-white/10 dark:bg-slate-800;
    }
    /* Accent header band bleeding from the top. */
    .ph-cat::before {
        content: "";
        @apply pointer-events-none absolute inset-x-0 top-0 h-16 -z-10 opacity-[0.08];
        background-image: linear-gradient(
            180deg,
            var(--ph-accent),
            transparent
        );
    }
    .ph-cat:hover {
        @apply -translate-y-1.5;
        border-color: color-mix(in oklab, var(--ph-accent) 45%, transparent);
        box-shadow: 0 22px 46px -24px
            color-mix(in oklab, var(--ph-accent) 80%, transparent);
    }
    .ph-cat-icon {
        @apply grid size-12 shrink-0 place-items-center rounded-xl text-xl transition-transform duration-300;
        color: var(--ph-accent);
        background-color: color-mix(
            in oklab,
            var(--ph-accent) 14%,
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(in oklab, var(--ph-accent) 26%, transparent);
    }
    .ph-cat:hover .ph-cat-icon {
        @apply scale-110 -rotate-6;
    }
    /* Icon/colour swatch picker (Add/Edit Category modal) — these render as
       <button>, unlike the decorative <span>/<i> use of .ph-cat-icon elsewhere. */
    button.ph-cat-icon {
        @apply cursor-pointer;
    }
    button.ph-cat-icon:hover {
        @apply -translate-y-0.5 scale-110;
        background-color: color-mix(
            in oklab,
            var(--ph-accent) 24%,
            transparent
        );
        box-shadow:
            inset 0 0 0 1px
                color-mix(in oklab, var(--ph-accent) 45%, transparent),
            0 8px 16px -10px
                color-mix(in oklab, var(--ph-accent) 70%, transparent);
    }
    button.ph-cat-icon:active {
        @apply translate-y-0 scale-95;
    }
    /* Health ring — share of the category's drugs that are in stock. */
    .ph-cat-ring {
        @apply size-11 -rotate-90;
        color: var(--ph-accent);
    }
    .ph-cat-ring-track {
        @apply text-gray-200 dark:text-slate-700;
    }
    .ph-cat-ring-label {
        @apply absolute grid size-11 place-items-center text-[9px] font-extrabold tabular-nums;
        color: var(--ph-accent);
    }
    /* Sample-drug pill inside a category card. */
    .ph-pill {
        @apply inline-flex items-center rounded-full px-2 py-0.5 text-[10px] font-semibold;
        color: color-mix(in oklab, var(--ph-accent) 92%, black 10%);
        background-color: color-mix(
            in oklab,
            var(--ph-accent) 12%,
            transparent
        );
    }

    /* Category accent tones (cycled across the gallery). */
    .cat-teal {
        --ph-accent: var(--ph-primary);
    }
    .cat-sky {
        --ph-accent: var(--ph-tablet);
    }
    .cat-amber {
        --ph-accent: var(--ph-capsule);
    }
    .cat-pink {
        --ph-accent: var(--ph-syrup);
    }
    .cat-red {
        --ph-accent: var(--ph-injection);
    }
    .cat-violet {
        --ph-accent: var(--ph-topical);
    }
    .cat-indigo {
        --ph-accent: var(--ph-inhaler);
    }
    .cat-cyan {
        --ph-accent: var(--ph-drops);
    }
    .cat-orange {
        --ph-accent: var(--ph-ophthalmic);
    }

    @media (prefers-reduced-motion: reduce) {
        .ph-kpi,
        .ph-action,
        .ph-kpi::before,
        .ph-cat,
        .ph-cat-icon {
            @apply transition-none;
        }
        .ph-kpi:hover,
        .ph-action:hover,
        .ph-cat:hover {
            @apply translate-y-0;
        }
        .ph-cat:hover .ph-cat-icon {
            @apply scale-100 rotate-0;
        }
        button.ph-cat-icon:hover,
        button.ph-cat-icon:active {
            @apply translate-y-0 scale-100;
        }
    }

    /* =====================================================================
       DOCTOR DASHBOARD — EXCLUSIVE to doctor-dashboard.html.
       A clinician's-day command centre: indigo/violet aurora, bento grid,
       glass widgets, a schedule rail and consult analytics. Distinct from
       the admin dashboard and every module language (tc/cc/wb/ph/er).
       ===================================================================== */
    .dr-scope {
        --dr-indigo: #6366f1;
        --dr-violet: #8b5cf6;
        --dr-sky: #0ea5e9;
        --dr-rose: #f43f5e;
        --dr-emerald: #10b981;
        --dr-amber: #f59e0b;
    }

    /* --- Hero ----------------------------------------------------------- */
    .dr-hero {
        @apply relative isolate overflow-hidden rounded-xl p-6 lg:p-8;
        background-image: linear-gradient(
            118deg,
            #1e1b4b 0%,
            #312e81 45%,
            #4c1d95 100%
        );
    }
    .dr-hero::before {
        content: "";
        @apply pointer-events-none absolute -right-28 -top-32 -z-10 size-[28rem] rounded-full blur-3xl opacity-40;
        background-image: radial-gradient(
            circle,
            var(--dr-violet) 0%,
            transparent 65%
        );
    }
    .dr-hero::after {
        content: "";
        @apply pointer-events-none absolute -bottom-36 -left-20 -z-10 size-[24rem] rounded-full blur-3xl opacity-30;
        background-image: radial-gradient(
            circle,
            var(--dr-sky) 0%,
            transparent 65%
        );
    }
    /* Constellation dots — the 2026-SaaS texture. */
    .dr-hero-dots {
        @apply pointer-events-none absolute inset-0 -z-10 opacity-25;
        background-image: radial-gradient(
            rgba(255, 255, 255, 0.5) 1px,
            transparent 1px
        );
        background-size: 26px 26px;
        mask-image: radial-gradient(
            ellipse at 80% 0%,
            #000 20%,
            transparent 70%
        );
    }
    .dr-hero-title {
        @apply text-2xl lg:text-[2rem] font-extrabold leading-tight tracking-tight text-white;
    }
    .dr-hero-sub {
        @apply mt-1.5 flex flex-wrap items-center gap-x-2 gap-y-1 text-xs font-medium text-white/60;
    }
    /* Day-progress rail inside the hero. */
    .dr-day {
        @apply mt-5 max-w-md;
    }
    .dr-day-track {
        @apply relative h-2 w-full overflow-hidden rounded-full bg-white/15;
    }
    .dr-day-fill {
        @apply absolute inset-y-0 left-0 rounded-full;
        background-image: linear-gradient(
            90deg,
            var(--dr-sky),
            var(--dr-violet)
        );
    }

    .dr-action {
        @apply inline-flex items-center gap-2 rounded-xl border border-white/15 bg-white/10 px-3.5 py-2.5 text-xs font-bold text-white backdrop-blur-md transition-all duration-300;
    }
    .dr-action:hover {
        @apply -translate-y-0.5 border-white/30 bg-white/20;
    }
    .dr-action:focus-visible {
        @apply outline-2 outline-offset-2 outline-white/70;
    }
    .dr-action.is-primary {
        @apply border-transparent text-white;
        background-image: linear-gradient(
            120deg,
            var(--dr-sky),
            var(--dr-violet)
        );
        box-shadow: 0 12px 28px -10px var(--dr-violet);
    }
    .dr-action.is-primary:hover {
        @apply brightness-110;
    }

    /* --- Bento tiles ----------------------------------------------------- */
    .dr-bento {
        @apply grid grid-cols-1 md:grid-cols-2 xl:grid-cols-4 gap-5;
    }
    .dr-tile {
        --dr-accent: var(--dr-indigo);
        @apply relative flex flex-col overflow-hidden rounded-2xl border border-border-color bg-white transition-all duration-300;
        @apply dark:border-white/10 dark:bg-slate-800/70 dark:backdrop-blur-xl;
        box-shadow:
            0 1px 2px rgba(2, 12, 40, 0.04),
            0 10px 26px -20px rgba(2, 12, 40, 0.22);
    }
    .dr-tile::before {
        content: "";
        @apply absolute inset-x-0 top-0 h-[3px];
        background-image: linear-gradient(
            90deg,
            var(--dr-accent),
            color-mix(in oklab, var(--dr-accent) 30%, transparent)
        );
    }
    .dr-tile:hover {
        @apply -translate-y-1;
        border-color: color-mix(in oklab, var(--dr-accent) 40%, transparent);
        box-shadow: 0 24px 48px -26px
            color-mix(in oklab, var(--dr-accent) 75%, transparent);
    }
    .dr-tile-head {
        @apply flex items-center gap-2.5 p-4 pb-3.5 mb-0.5 border-b border-border-color/70 dark:border-white/10;
    }
    .dr-tile-icon {
        @apply grid size-9 shrink-0 place-items-center rounded-xl text-base;
        color: var(--dr-accent);
        background-image: linear-gradient(
            145deg,
            color-mix(in oklab, var(--dr-accent) 20%, transparent),
            color-mix(in oklab, var(--dr-accent) 4%, transparent)
        );
        box-shadow: inset 0 0 0 1px
            color-mix(in oklab, var(--dr-accent) 28%, transparent);
    }
    .dr-tile-title {
        @apply text-sm font-bold text-gray-900 tracking-tight dark:text-white;
    }
    /* dark:text-white here is baked into this custom class via @apply, so it
       never shows up as a literal .dark\:text-white to be caught by the
       general override further down — same trap as the -hero titles, just
       not covered by that name-based selector. Fix it directly. */
    .dark .dr-tile-title {
        color: #fff;
    }
    .dr-tile-body {
        @apply flex-1 p-4 pt-3.5;
    }

    /* Accent tones for tiles. */
    .dr-indigo {
        --dr-accent: var(--dr-indigo);
    }
    .dr-violet {
        --dr-accent: var(--dr-violet);
    }
    .dr-sky {
        --dr-accent: var(--dr-sky);
    }
    .dr-rose {
        --dr-accent: var(--dr-rose);
    }
    .dr-emerald {
        --dr-accent: var(--dr-emerald);
    }
    .dr-amber {
        --dr-accent: var(--dr-amber);
    }

    /* --- Schedule rail --------------------------------------------------- */
    .dr-slot {
        @apply relative flex gap-3 pb-4 last:pb-0;
    }
    .dr-slot:not(:last-child)::before {
        content: "";
        @apply absolute left-[7px] top-5 bottom-0 w-px bg-border-color dark:bg-white/10;
    }
    .dr-slot-dot {
        @apply relative z-10 mt-1 size-3.5 shrink-0 rounded-full border-2 border-white dark:border-slate-800;
        background-color: var(--dr-accent, var(--dr-indigo));
    }
    .dr-slot.is-now .dr-slot-dot {
        animation: tc-ping 1.8s ease-in-out infinite;
    }
    .dr-slot-card {
        @apply min-w-0 flex-1 rounded-xl border border-border-color p-2.5 transition-all duration-200 dark:border-white/10;
    }
    .dr-slot-card:hover {
        border-color: color-mix(
            in oklab,
            var(--dr-accent, var(--dr-indigo)) 35%,
            transparent
        );
        box-shadow: 0 6px 16px -10px
            color-mix(
                in oklab,
                var(--dr-accent, var(--dr-indigo)) 60%,
                transparent
            );
    }
    .dr-slot.is-now .dr-slot-card {
        border-color: color-mix(
            in oklab,
            var(--dr-accent, var(--dr-indigo)) 45%,
            transparent
        );
        background-color: color-mix(
            in oklab,
            var(--dr-accent, var(--dr-indigo)) 6%,
            transparent
        );
    }

    /* Shared list row for waiting-room / results-to-sign style tiles. */
    .dr-row {
        @apply flex items-center gap-2.5 rounded-xl border border-border-color p-2.5 transition-all duration-200 dark:border-white/10;
    }
    .dr-row:hover {
        border-color: color-mix(
            in oklab,
            var(--dr-accent, var(--dr-indigo)) 35%,
            transparent
        );
        background-color: color-mix(
            in oklab,
            var(--dr-accent, var(--dr-indigo)) 4%,
            transparent
        );
    }
    .dr-row.is-flagged {
        border-color: color-mix(in oklab, var(--color-danger) 30%, transparent);
        background-color: color-mix(
            in oklab,
            var(--color-danger) 5%,
            transparent
        );
    }

    /* --- Vitals ring cluster --------------------------------------------- */
    .dr-ring {
        @apply size-15 -rotate-90;
        color: var(--dr-accent);
        filter: drop-shadow(
            0 2px 6px color-mix(in oklab, var(--dr-accent) 35%, transparent)
        );
    }
    .dr-ring-track {
        @apply text-gray-200 dark:text-slate-700;
    }
    .dr-ring-label {
        @apply absolute grid size-15 place-items-center text-xs font-extrabold tabular-nums;
        color: var(--dr-accent);
    }

    /* --- AI insight card -------------------------------------------------- */
    .dr-ai {
        @apply relative overflow-hidden rounded-xl p-3.5;
        background-image: linear-gradient(
            130deg,
            color-mix(in oklab, var(--dr-violet) 10%, transparent),
            color-mix(in oklab, var(--dr-sky) 8%, transparent)
        );
        box-shadow: inset 0 0 0 1px
            color-mix(in oklab, var(--dr-violet) 22%, transparent);
    }
    .dr-ai-tag {
        @apply inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[9px] font-extrabold uppercase tracking-wider text-white;
        background-image: linear-gradient(
            120deg,
            var(--dr-sky),
            var(--dr-violet)
        );
    }

    /* --- Load heat strip (appointments by hour) --------------------------- */
    .dr-heat {
        transition: opacity 0.15s ease;
    }
    .dr-heat:hover {
        @apply opacity-70;
    }
    .dr-heat.lv-0 {
        fill: color-mix(in oklab, var(--dr-indigo) 8%, var(--color-white));
    }
    .dr-heat.lv-1 {
        fill: color-mix(in oklab, var(--dr-indigo) 25%, var(--color-white));
    }
    .dr-heat.lv-2 {
        fill: color-mix(in oklab, var(--dr-indigo) 45%, var(--color-white));
    }
    .dr-heat.lv-3 {
        fill: color-mix(in oklab, var(--dr-indigo) 70%, transparent);
    }
    .dr-heat.lv-4 {
        fill: var(--dr-violet);
    }

    /* --- Spark bars / plot ------------------------------------------------ */
    .dr-bar {
        fill: color-mix(
            in oklab,
            var(--dr-accent, var(--dr-indigo)) 30%,
            transparent
        );
        transition: fill 0.2s ease;
    }
    .dr-bar.is-peak,
    .dr-bar:hover {
        fill: var(--dr-accent, var(--dr-indigo));
    }

    /* --- Status chip ------------------------------------------------------ */
    .dr-chip {
        @apply inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-bold whitespace-nowrap;
        color: var(--dr-accent, var(--dr-indigo));
        background-color: color-mix(
            in oklab,
            var(--dr-accent, var(--dr-indigo)) 13%,
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(
                in oklab,
                var(--dr-accent, var(--dr-indigo)) 24%,
                transparent
            );
    }
    .dr-delta {
        @apply inline-flex items-center gap-0.5 rounded-full px-1.5 py-0.5 text-[10px] font-bold;
    }
    .dr-delta.is-up {
        @apply bg-success/10 text-success;
    }
    .dr-delta.is-down {
        @apply bg-danger/10 text-danger;
    }

    @media (prefers-reduced-motion: reduce) {
        .dr-tile,
        .dr-action {
            @apply transition-none;
        }
        .dr-tile:hover,
        .dr-action:hover {
            @apply translate-y-0;
        }
        .dr-slot.is-now .dr-slot-dot {
            animation: none;
        }
    }

    /* =====================================================================
       NURSE COMMAND CENTER — EXCLUSIVE to nurse-dashboard.html.
       A working head-nurse station for a live shift: deep teal ward
       gradient, bento panels, med rail, vitals tiles, ward map, kanban
       and a floating action dock. Distinct from dr/tc/cc/wb/ph/er.
       ===================================================================== */
    .ns-scope {
        --ns-teal: #0d9488;
        --ns-cyan: #06b6d4;
        --ns-rose: #f43f5e;
        --ns-amber: #f59e0b;
        --ns-violet: #8b5cf6;
        --ns-emerald: #10b981;
        --ns-slate: #64748b;
    }

    /* --- Hero: the nurse station board ----------------------------------- */
    .ns-hero {
        @apply relative isolate overflow-hidden rounded-xl p-6 lg:p-8;
        background-image: linear-gradient(
            115deg,
            #042f2e 0%,
            #115e59 48%,
            #164e63 100%
        );
    }
    .ns-hero::before {
        content: "";
        @apply pointer-events-none absolute -right-24 -top-28 -z-10 size-[26rem] rounded-full blur-3xl opacity-40;
        background-image: radial-gradient(
            circle,
            var(--ns-cyan) 0%,
            transparent 65%
        );
    }
    .ns-hero::after {
        content: "";
        @apply pointer-events-none absolute -bottom-32 -left-16 -z-10 size-[22rem] rounded-full blur-3xl opacity-25;
        background-image: radial-gradient(
            circle,
            var(--ns-teal) 0%,
            transparent 65%
        );
    }
    /* ECG grid texture — a ward monitor, not constellation dots. */
    .ns-hero-grid {
        @apply pointer-events-none absolute inset-0 -z-10 opacity-[0.08];
        background-image:
            linear-gradient(rgba(255, 255, 255, 0.8) 1px, transparent 1px),
            linear-gradient(
                90deg,
                rgba(255, 255, 255, 0.8) 1px,
                transparent 1px
            );
        background-size: 34px 34px;
        mask-image: radial-gradient(
            ellipse at 70% 20%,
            #000 15%,
            transparent 75%
        );
    }
    .ns-hero-title {
        @apply text-2xl lg:text-[2rem] font-extrabold leading-tight tracking-tight text-white;
    }
    .ns-hero-sub {
        @apply mt-1.5 flex flex-wrap items-center gap-x-2 gap-y-1 text-xs font-medium text-white/60;
    }
    /* Duty status pill with a live pulse dot. */
    .ns-duty {
        @apply inline-flex items-center gap-1.5 rounded-full border border-emerald-300/30 bg-emerald-400/15 px-2.5 py-1 text-[10px] font-extrabold uppercase tracking-wider text-emerald-200;
    }
    .ns-duty-dot {
        @apply size-1.5 rounded-full bg-emerald-300;
        animation: tc-ping 1.6s ease-in-out infinite;
    }
    /* Hero fact chips (beds, patients, acuity...). */
    .ns-fact {
        @apply rounded-xl border border-white/10 bg-white/[0.07] px-3.5 py-2.5 backdrop-blur-md;
    }
    .ns-fact dt {
        @apply text-[9px] font-extrabold uppercase tracking-[0.14em] text-white/45;
    }
    .ns-fact dd {
        @apply mt-0.5 text-sm font-extrabold text-white tabular-nums;
    }
    /* Shift countdown ring in the hero. */
    .ns-count {
        @apply relative grid place-items-center;
    }
    .ns-count-ring {
        @apply size-[7.5rem] -rotate-90;
    }
    .ns-count-track {
        stroke: rgba(255, 255, 255, 0.12);
    }
    .ns-count-fill {
        stroke: url(#ns-count-grad);
        transition: stroke-dashoffset 0.8s ease;
    }
    .ns-count-label {
        @apply absolute inset-0 grid place-items-center text-center;
    }
    .ns-action {
        @apply inline-flex items-center gap-2 rounded-xl border border-white/15 bg-white/10 px-3.5 py-2.5 text-xs font-bold text-white backdrop-blur-md transition-all duration-300;
    }
    .ns-action:hover {
        @apply -translate-y-0.5 border-white/30 bg-white/20;
    }
    .ns-action:focus-visible {
        @apply outline-2 outline-offset-2 outline-white/70;
    }
    .ns-action.is-primary {
        @apply border-transparent;
        background-image: linear-gradient(
            120deg,
            var(--ns-teal),
            var(--ns-cyan)
        );
        box-shadow: 0 12px 28px -10px var(--ns-cyan);
    }
    .ns-action.is-primary:hover {
        @apply brightness-110;
    }
    /* Emergency banner state on the hero. */
    .ns-code {
        @apply mt-5 flex flex-wrap items-center gap-3 rounded-xl border border-white/10 bg-white/[0.06] px-4 py-3 backdrop-blur-md;
    }
    .ns-code.is-alert {
        @apply border-rose-400/40;
        background-image: linear-gradient(
            100deg,
            color-mix(in oklab, var(--ns-rose) 26%, transparent),
            transparent 70%
        );
    }

    /* --- Shift timeline stepper ------------------------------------------ */
    .ns-steps {
        @apply flex min-w-max items-stretch gap-0;
    }
    .ns-step {
        @apply relative flex min-w-32 flex-1 flex-col items-center gap-2 px-3 pt-1 text-center;
    }
    .ns-step:not(:last-child)::after {
        content: "";
        @apply absolute left-1/2 right-[-50%] top-[1.35rem] h-0.5 bg-border-color dark:bg-white/10;
    }
    .ns-step.is-done:not(:last-child)::after {
        background-image: linear-gradient(
            90deg,
            var(--ns-teal),
            var(--ns-cyan)
        );
    }
    .ns-step-node {
        @apply relative z-10 grid size-9 place-items-center rounded-full border-2 border-border-color bg-white text-sm text-gray-400 transition-all duration-300 dark:border-white/15 dark:bg-slate-800;
    }
    .ns-step.is-done .ns-step-node {
        @apply border-transparent text-white;
        background-image: linear-gradient(
            135deg,
            var(--ns-teal),
            var(--ns-cyan)
        );
    }
    .ns-step.is-now .ns-step-node {
        @apply border-transparent text-white;
        background-image: linear-gradient(
            135deg,
            var(--ns-cyan),
            var(--ns-violet)
        );
        box-shadow: 0 0 0 5px
            color-mix(in oklab, var(--ns-cyan) 18%, transparent);
        animation: tc-ping 2s ease-in-out infinite;
    }
    .ns-step-name {
        @apply text-[11px] font-bold text-gray-500;
    }
    .ns-step.is-now .ns-step-name {
        @apply text-gray-900;
    }
    .ns-step-time {
        @apply text-[10px] font-semibold text-gray-400 tabular-nums;
    }

    /* --- Panels (bento tiles) -------------------------------------------- */
    .ns-panel {
        --ns-accent: var(--ns-teal);
        @apply relative flex flex-col overflow-hidden rounded-xl border border-border-color bg-white transition-all duration-300;
        @apply dark:border-white/10 dark:bg-slate-800/70 dark:backdrop-blur-xl;
    }
    .ns-panel:hover {
        @apply -translate-y-1;
        border-color: color-mix(in oklab, var(--ns-accent) 40%, transparent);
        box-shadow: 0 24px 48px -26px
            color-mix(in oklab, var(--ns-accent) 70%, transparent);
    }
    .ns-panel-head {
        @apply flex items-center gap-2.5 p-4 pb-0;
    }
    .ns-panel-icon {
        @apply grid size-9 shrink-0 place-items-center rounded-xl text-sm;
        color: var(--ns-accent);
        background-image: linear-gradient(
            145deg,
            color-mix(in oklab, var(--ns-accent) 18%, transparent),
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(in oklab, var(--ns-accent) 26%, transparent);
    }
    .ns-panel-title {
        @apply text-sm font-bold text-gray-900;
    }
    .ns-panel-body {
        @apply flex-1 p-4;
    }
    .ns-teal {
        --ns-accent: var(--ns-teal);
    }
    .ns-cyan {
        --ns-accent: var(--ns-cyan);
    }
    .ns-rose {
        --ns-accent: var(--ns-rose);
    }
    .ns-amber {
        --ns-accent: var(--ns-amber);
    }
    .ns-violet {
        --ns-accent: var(--ns-violet);
    }
    .ns-emerald {
        --ns-accent: var(--ns-emerald);
    }
    .ns-chip {
        @apply inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-bold whitespace-nowrap;
        color: var(--ns-accent, var(--ns-teal));
        background-color: color-mix(
            in oklab,
            var(--ns-accent, var(--ns-teal)) 13%,
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(
                in oklab,
                var(--ns-accent, var(--ns-teal)) 24%,
                transparent
            );
    }

    /* --- Patient workspace cards ----------------------------------------- */
    .ns-pt {
        @apply relative overflow-hidden rounded-xl border border-border-color p-3.5 transition-all duration-300 dark:border-white/10;
        border-left-width: 3px;
        border-left-color: var(--ns-risk, var(--ns-emerald));
    }
    .ns-pt:hover {
        @apply -translate-y-0.5 bg-gray-50 dark:bg-white/5;
        box-shadow: 0 14px 30px -20px
            color-mix(
                in oklab,
                var(--ns-risk, var(--ns-emerald)) 80%,
                transparent
            );
    }
    .ns-pt.risk-high {
        --ns-risk: var(--ns-rose);
    }
    .ns-pt.risk-medium {
        --ns-risk: var(--ns-amber);
    }
    .ns-pt.risk-low {
        --ns-risk: var(--ns-emerald);
    }
    .ns-pt-avatar {
        @apply grid size-11 shrink-0 place-items-center overflow-hidden rounded-xl text-[13px] font-extrabold text-white;
        background-image: linear-gradient(
            135deg,
            var(--ns-risk, var(--ns-teal)),
            color-mix(in oklab, var(--ns-risk, var(--ns-teal)) 55%, #0f172a)
        );
    }
    .ns-pt-avatar img {
        @apply size-full object-cover;
    }
    .ns-pt-bed {
        @apply inline-flex items-center gap-1 rounded-xl bg-gray-100 px-1.5 py-0.5 text-[10px] font-extrabold text-gray-600 tabular-nums dark:bg-white/10 dark:text-gray-300;
    }
    .ns-pt-tag {
        @apply inline-flex items-center gap-1 rounded-full px-1.5 py-0.5 text-[9px] font-extrabold uppercase tracking-wide;
    }
    .ns-pt-actions {
        @apply mt-3 flex items-center gap-1 border-t border-dashed border-border-color pt-2.5 dark:border-white/10;
    }
    .ns-pt-btn {
        @apply grid size-7 place-items-center rounded-xl text-xs text-gray-400 transition-all duration-200;
    }
    .ns-pt-btn:hover {
        color: var(--ns-risk, var(--ns-teal));
        background-color: color-mix(
            in oklab,
            var(--ns-risk, var(--ns-teal)) 12%,
            transparent
        );
    }

    /* --- Medication rail -------------------------------------------------- */
    .ns-med {
        @apply relative flex gap-3 pb-4 last:pb-0;
    }
    .ns-med:not(:last-child)::before {
        content: "";
        @apply absolute left-[9px] top-6 bottom-0 w-px bg-border-color dark:bg-white/10;
    }
    .ns-med-dot {
        @apply relative z-10 mt-1.5 grid size-[19px] shrink-0 place-items-center rounded-full border-2 border-white text-[9px] text-white dark:border-slate-800;
        background-color: var(--ns-accent, var(--ns-teal));
    }
    .ns-med.is-due .ns-med-dot {
        animation: tc-ping 1.8s ease-in-out infinite;
    }
    .ns-med-card {
        @apply min-w-0 flex-1 rounded-xl border border-border-color p-2.5 transition-colors duration-200 dark:border-white/10;
    }
    .ns-med.is-due .ns-med-card {
        border-color: color-mix(
            in oklab,
            var(--ns-accent, var(--ns-teal)) 45%,
            transparent
        );
        background-color: color-mix(
            in oklab,
            var(--ns-accent, var(--ns-teal)) 6%,
            transparent
        );
    }
    /* Controlled-drug badge — double-signature look. */
    .ns-cd {
        @apply inline-flex items-center gap-1 rounded-md border border-dashed px-1.5 py-0.5 text-[9px] font-extrabold uppercase tracking-wide;
        color: var(--ns-violet);
        border-color: color-mix(in oklab, var(--ns-violet) 45%, transparent);
        background-color: color-mix(in oklab, var(--ns-violet) 8%, transparent);
    }

    /* --- Vitals tiles ------------------------------------------------------ */
    .ns-vital {
        @apply relative overflow-hidden rounded-xl border border-border-color p-3 transition-all duration-300 dark:border-white/10;
    }
    .ns-vital:hover {
        @apply -translate-y-0.5;
        border-color: color-mix(
            in oklab,
            var(--ns-v, var(--ns-teal)) 45%,
            transparent
        );
    }
    .ns-vital.is-abnormal {
        border-color: color-mix(in oklab, var(--ns-rose) 45%, transparent);
        background-image: linear-gradient(
            160deg,
            color-mix(in oklab, var(--ns-rose) 8%, transparent),
            transparent 60%
        );
    }
    .ns-vital-icon {
        @apply grid size-7 place-items-center rounded-xl text-[13px];
        color: var(--ns-v, var(--ns-teal));
        background-color: color-mix(
            in oklab,
            var(--ns-v, var(--ns-teal)) 13%,
            transparent
        );
    }
    .ns-vital-val {
        @apply text-lg font-extrabold leading-none text-gray-900 tabular-nums;
    }
    .ns-vital.is-abnormal .ns-vital-val {
        color: var(--ns-rose);
    }
    .ns-spark {
        stroke: var(--ns-v, var(--ns-teal));
        fill: none;
        stroke-width: 2;
        stroke-linecap: round;
        stroke-linejoin: round;
    }

    /* --- Ward map ---------------------------------------------------------- */
    .ns-bed {
        @apply relative grid aspect-square place-items-center rounded-xl border text-[10px] font-extrabold transition-all duration-200 cursor-default tabular-nums;
        color: var(--ns-bed-c, var(--ns-slate));
        border-color: color-mix(
            in oklab,
            var(--ns-bed-c, var(--ns-slate)) 35%,
            transparent
        );
        background-color: color-mix(
            in oklab,
            var(--ns-bed-c, var(--ns-slate)) 10%,
            transparent
        );
    }
    .ns-bed:hover {
        @apply scale-110 z-10;
        box-shadow: 0 8px 18px -8px
            color-mix(
                in oklab,
                var(--ns-bed-c, var(--ns-slate)) 80%,
                transparent
            );
    }
    .ns-bed.is-available {
        --ns-bed-c: var(--ns-emerald);
    }
    .ns-bed.is-occupied {
        --ns-bed-c: var(--ns-cyan);
    }
    .ns-bed.is-cleaning {
        --ns-bed-c: var(--ns-amber);
    }
    .ns-bed.is-isolation {
        --ns-bed-c: var(--ns-violet);
    }
    .ns-bed.is-emergency {
        --ns-bed-c: var(--ns-rose);
    }
    .ns-bed.is-discharge {
        --ns-bed-c: var(--ns-slate);
    }
    .ns-bed.is-emergency {
        animation: skeleton-pulse 1.6s ease-in-out infinite;
    }
    .ns-bed-flag {
        @apply absolute -right-1 -top-1 grid size-4 place-items-center rounded-full text-[8px] text-white;
        background-color: var(--ns-bed-c, var(--ns-slate));
    }

    /* --- Kanban ------------------------------------------------------------ */
    .ns-lane {
        @apply flex min-w-56 flex-1 flex-col rounded-xl border border-border-color bg-gray-50/70 p-2.5 dark:border-white/10 dark:bg-white/[0.03];
        border-top-width: 3px;
        border-top-color: var(--ns-accent, var(--ns-teal));
    }
    .ns-lane-items {
        @apply flex-1 rounded-lg transition-colors duration-150;
    }
    .ns-lane-items.is-over {
        @apply bg-primary/5 outline-2 outline-dashed outline-primary/40 outline-offset-2;
    }
    .ns-task {
        @apply rounded-xl border border-border-color bg-white p-2.5 transition-all duration-200 dark:border-white/10 dark:bg-slate-800;
        cursor: grab;
    }
    .ns-task:hover {
        @apply -translate-y-0.5 shadow-md;
    }
    .ns-task.is-dragging {
        @apply opacity-40 shadow-none;
        cursor: grabbing;
    }
    .ns-task + .ns-task {
        @apply mt-2;
    }

    /* --- Alert center ------------------------------------------------------ */
    .ns-alert {
        @apply relative flex items-start gap-3 overflow-hidden rounded-xl border p-3 transition-colors duration-200;
        border-color: color-mix(
            in oklab,
            var(--ns-accent, var(--ns-rose)) 30%,
            transparent
        );
        background-image: linear-gradient(
            120deg,
            color-mix(
                in oklab,
                var(--ns-accent, var(--ns-rose)) 8%,
                transparent
            ),
            transparent 65%
        );
    }
    .ns-alert.is-code {
        border-color: color-mix(in oklab, var(--ns-rose) 55%, transparent);
        animation: skeleton-pulse 1.8s ease-in-out infinite;
    }

    /* --- Care timeline / activity ------------------------------------------ */
    .ns-tl {
        @apply relative flex gap-3 pb-4 last:pb-0;
    }
    .ns-tl:not(:last-child)::before {
        content: "";
        @apply absolute left-[13px] top-8 bottom-0 w-px bg-border-color dark:bg-white/10;
    }
    .ns-tl-icon {
        @apply relative z-10 grid size-7 shrink-0 place-items-center rounded-full text-[11px];
        color: var(--ns-accent, var(--ns-teal));
        background-color: color-mix(
            in oklab,
            var(--ns-accent, var(--ns-teal)) 14%,
            transparent
        );
        box-shadow:
            inset 0 0 0 1px
                color-mix(
                    in oklab,
                    var(--ns-accent, var(--ns-teal)) 28%,
                    transparent
                ),
            0 0 0 3px var(--color-white);
    }

    /* --- Shift performance gauges ------------------------------------------ */
    .ns-gauge {
        @apply relative grid place-items-center;
    }
    .ns-gauge-ring {
        @apply size-16 -rotate-90;
    }
    .ns-gauge-track {
        @apply text-gray-200 dark:text-slate-700;
    }
    .ns-gauge-fill {
        stroke: var(--ns-accent, var(--ns-teal));
        transition: stroke-dashoffset 0.8s ease;
    }
    .ns-gauge-label {
        @apply absolute inset-0 grid place-items-center text-xs font-extrabold tabular-nums text-gray-900;
    }

    /* --- Handover panel ----------------------------------------------------- */
    .ns-hand {
        @apply rounded-xl border border-border-color p-3.5 dark:border-white/10;
        border-left-width: 3px;
        border-left-color: var(--ns-accent, var(--ns-teal));
        background-image: linear-gradient(
            120deg,
            color-mix(
                in oklab,
                var(--ns-accent, var(--ns-teal)) 5%,
                transparent
            ),
            transparent 55%
        );
    }

    /* --- Floating action dock ----------------------------------------------- */
    .ns-dock {
        @apply fixed bottom-6 right-6 z-40 flex flex-col items-end gap-2.5;
    }
    .ns-dock-menu {
        @apply flex flex-col items-end gap-2 transition-all duration-300;
    }
    .ns-dock-menu.is-closed {
        @apply pointer-events-none translate-y-3 opacity-0;
    }
    .ns-dock-item {
        @apply flex items-center gap-2.5 rounded-full border border-border-color bg-white py-2 pl-4 pr-2 text-xs font-bold text-gray-700 shadow-lg transition-all duration-200 dark:border-white/10 dark:bg-slate-800 dark:text-gray-200;
    }
    .ns-dock-item:hover {
        @apply -translate-x-1;
        border-color: color-mix(
            in oklab,
            var(--ns-accent, var(--ns-teal)) 45%,
            transparent
        );
    }
    .ns-dock-item i {
        @apply grid size-8 place-items-center rounded-full text-[13px] text-white;
        background-image: linear-gradient(
            135deg,
            var(--ns-accent, var(--ns-teal)),
            color-mix(in oklab, var(--ns-accent, var(--ns-teal)) 60%, #0f172a)
        );
    }
    .ns-dock-fab {
        @apply grid size-14 place-items-center rounded-xl text-xl text-white transition-all duration-300;
        background-image: linear-gradient(
            135deg,
            var(--ns-teal),
            var(--ns-cyan)
        );
        box-shadow: 0 18px 36px -12px var(--ns-cyan);
    }
    .ns-dock-fab:hover {
        @apply -translate-y-1 brightness-110;
    }
    .ns-dock-fab.is-open {
        @apply rotate-45;
    }

    /* The station board runs a full shift — honour reduced-motion. */
    @media (prefers-reduced-motion: reduce) {
        .ns-panel,
        .ns-action,
        .ns-pt,
        .ns-vital,
        .ns-task,
        .ns-bed,
        .ns-dock-item,
        .ns-dock-fab,
        .ns-dock-menu {
            @apply transition-none;
        }
        .ns-panel:hover,
        .ns-action:hover,
        .ns-pt:hover,
        .ns-vital:hover,
        .ns-task:hover,
        .ns-dock-fab:hover {
            @apply translate-y-0;
        }
        .ns-bed:hover {
            @apply scale-100;
        }
        .ns-duty-dot,
        .ns-step.is-now .ns-step-node,
        .ns-med.is-due .ns-med-dot,
        .ns-bed.is-emergency,
        .ns-alert.is-code {
            animation: none;
        }
    }

    /* =====================================================================
       RECEPTION COMMAND CENTER — EXCLUSIVE to reception-dashboard.html.
       The hospital front desk at full flow: warm amber/indigo dusk hero,
       token queue board, registration desk, doctor status wall, waiting
       area seat map and a billing drawer. Distinct from dr/ns/tc/cc/wb.
       ===================================================================== */
    .rc-scope {
        --rc-amber: #f59e0b;
        --rc-orange: #f97316;
        --rc-indigo: #6366f1;
        --rc-sky: #0ea5e9;
        --rc-rose: #f43f5e;
        --rc-emerald: #10b981;
        --rc-violet: #8b5cf6;
        --rc-slate: #64748b;
    }

    /* --- Hero: the front desk ------------------------------------------- */
    .rc-hero {
        @apply relative isolate overflow-hidden rounded-xl p-6 lg:p-8;
        background-image: linear-gradient(
            112deg,
            #1e1b4b 0%,
            #3b2f63 42%,
            #7c2d12 100%
        );
    }
    .rc-hero::before {
        content: "";
        @apply pointer-events-none absolute -right-24 -top-32 -z-10 size-[28rem] rounded-full blur-3xl opacity-40;
        background-image: radial-gradient(
            circle,
            var(--rc-orange) 0%,
            transparent 65%
        );
    }
    .rc-hero::after {
        content: "";
        @apply pointer-events-none absolute -bottom-32 -left-16 -z-10 size-[22rem] rounded-full blur-3xl opacity-30;
        background-image: radial-gradient(
            circle,
            var(--rc-indigo) 0%,
            transparent 65%
        );
    }
    /* Ticket-perforation texture — a token counter, not a monitor grid. */
    .rc-hero-ticks {
        @apply pointer-events-none absolute inset-x-0 top-0 -z-10 h-full opacity-[0.12];
        background-image: repeating-linear-gradient(
            90deg,
            transparent 0 30px,
            rgba(255, 255, 255, 0.7) 30px 31px
        );
        mask-image: linear-gradient(to bottom, #000 0%, transparent 34%);
    }
    .rc-hero-title {
        @apply text-2xl lg:text-[2rem] font-extrabold leading-tight tracking-tight text-white;
    }
    .rc-hero-sub {
        @apply mt-1.5 flex flex-wrap items-center gap-x-2 gap-y-1 text-xs font-medium text-white/60;
    }
    .rc-onair {
        @apply inline-flex items-center gap-1.5 rounded-full border border-amber-300/30 bg-amber-400/15 px-2.5 py-1 text-[10px] font-extrabold uppercase tracking-wider text-amber-200;
    }
    .rc-onair-dot {
        @apply size-1.5 rounded-full bg-amber-300;
        animation: tc-ping 1.6s ease-in-out infinite;
    }
    /* Flip-clock style time block. */
    .rc-clock {
        @apply flex items-center gap-1;
    }
    .rc-clock-cell {
        @apply grid min-w-11 place-items-center rounded-xl border border-white/10 bg-white/10 px-2 py-1.5 text-xl font-extrabold text-white tabular-nums backdrop-blur-md;
    }
    .rc-clock-sep {
        @apply text-lg font-extrabold text-white/40;
    }
    .rc-fact {
        @apply rounded-xl border border-white/10 bg-white/[0.07] px-3.5 py-2.5 backdrop-blur-md;
    }
    .rc-fact dt {
        @apply text-[9px] font-extrabold uppercase tracking-[0.14em] text-white/45;
    }
    .rc-fact dd {
        @apply mt-0.5 text-sm font-extrabold text-white tabular-nums;
    }
    /* Now-serving token marquee chip. */
    .rc-serving {
        @apply relative flex items-center gap-3 overflow-hidden rounded-xl border border-amber-300/25 px-4 py-3 backdrop-blur-md;
        background-image: linear-gradient(
            100deg,
            color-mix(in oklab, var(--rc-amber) 22%, transparent),
            transparent 70%
        );
    }
    .rc-serving-token {
        @apply rounded-xl px-3 py-1.5 text-lg font-extrabold text-amber-950 tabular-nums;
        background-image: linear-gradient(120deg, #fcd34d, var(--rc-amber));
        box-shadow: 0 10px 24px -10px var(--rc-amber);
    }
    .rc-action {
        @apply inline-flex items-center gap-2 rounded-xl border border-white/15 bg-white/10 px-3.5 py-2.5 text-xs font-bold text-white backdrop-blur-md transition-all duration-300;
    }
    .rc-action:hover {
        @apply -translate-y-0.5 border-white/30 bg-white/20;
    }
    .rc-action:focus-visible {
        @apply outline-2 outline-offset-2 outline-white/70;
    }
    .rc-action.is-primary {
        @apply border-transparent;
        background-image: linear-gradient(
            120deg,
            var(--rc-orange),
            var(--rc-amber)
        );
        box-shadow: 0 12px 28px -10px var(--rc-orange);
    }
    .rc-action.is-primary:hover {
        @apply brightness-110;
    }

    /* --- Workflow stepper ------------------------------------------------- */
    .rc-steps {
        @apply flex min-w-max items-stretch;
    }
    .rc-step {
        @apply relative flex min-w-32 flex-1 flex-col items-center gap-2 px-3 pt-1 text-center;
    }
    .rc-step:not(:last-child)::after {
        content: "";
        @apply absolute left-1/2 right-[-50%] top-[1.35rem] h-0.5 bg-border-color dark:bg-white/10;
    }
    .rc-step.is-done:not(:last-child)::after {
        background-image: linear-gradient(
            90deg,
            var(--rc-orange),
            var(--rc-amber)
        );
    }
    .rc-step-node {
        @apply relative z-10 grid size-9 place-items-center rounded-full border-2 border-border-color bg-white text-sm text-gray-400 transition-all duration-300 dark:border-white/15 dark:bg-slate-800;
    }
    .rc-step.is-done .rc-step-node {
        @apply border-transparent text-white;
        background-image: linear-gradient(
            135deg,
            var(--rc-orange),
            var(--rc-amber)
        );
    }
    .rc-step.is-now .rc-step-node {
        @apply border-transparent text-white;
        background-image: linear-gradient(
            135deg,
            var(--rc-amber),
            var(--rc-indigo)
        );
        box-shadow: 0 0 0 5px
            color-mix(in oklab, var(--rc-amber) 20%, transparent);
        animation: tc-ping 2s ease-in-out infinite;
    }
    .rc-step-name {
        @apply text-[11px] font-bold text-gray-500;
    }
    .rc-step.is-now .rc-step-name {
        @apply text-gray-900;
    }
    .rc-step-time {
        @apply text-[10px] font-semibold text-gray-400 tabular-nums;
    }

    /* --- Panels ------------------------------------------------------------ */
    .rc-panel {
        --rc-accent: var(--rc-amber);
        @apply relative flex flex-col overflow-hidden rounded-xl border border-border-color bg-white transition-all duration-300;
        @apply dark:border-white/10 dark:bg-slate-800/70 dark:backdrop-blur-xl;
    }
    .rc-panel:hover {
        @apply -translate-y-1;
        border-color: color-mix(in oklab, var(--rc-accent) 40%, transparent);
        box-shadow: 0 24px 48px -26px
            color-mix(in oklab, var(--rc-accent) 70%, transparent);
    }
    .rc-panel-head {
        @apply flex items-center gap-2.5 p-4 pb-0;
    }
    .rc-panel-icon {
        @apply grid size-9 shrink-0 place-items-center rounded-xl text-sm;
        color: var(--rc-accent);
        background-image: linear-gradient(
            145deg,
            color-mix(in oklab, var(--rc-accent) 18%, transparent),
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(in oklab, var(--rc-accent) 26%, transparent);
    }
    .rc-panel-title {
        @apply text-sm font-bold text-gray-900;
    }
    .rc-panel-body {
        @apply flex-1 p-4;
    }
    .rc-amber {
        --rc-accent: var(--rc-amber);
    }
    .rc-orange {
        --rc-accent: var(--rc-orange);
    }
    .rc-indigo {
        --rc-accent: var(--rc-indigo);
    }
    .rc-sky {
        --rc-accent: var(--rc-sky);
    }
    .rc-rose {
        --rc-accent: var(--rc-rose);
    }
    .rc-emerald {
        --rc-accent: var(--rc-emerald);
    }
    .rc-violet {
        --rc-accent: var(--rc-violet);
    }
    .rc-chip {
        @apply inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-bold whitespace-nowrap;
        color: var(--rc-accent, var(--rc-amber));
        background-color: color-mix(
            in oklab,
            var(--rc-accent, var(--rc-amber)) 13%,
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(
                in oklab,
                var(--rc-accent, var(--rc-amber)) 24%,
                transparent
            );
    }

    /* --- Token queue board -------------------------------------------------- */
    .rc-lane {
        @apply flex min-w-60 flex-1 flex-col rounded-xl border border-border-color bg-gray-50/70 p-2.5 dark:border-white/10 dark:bg-white/[0.03];
        border-top-width: 3px;
        border-top-color: var(--rc-accent, var(--rc-amber));
    }
    .rc-lane-items {
        @apply flex-1 rounded-lg transition-colors duration-150;
    }
    .rc-lane-items.is-over {
        @apply bg-primary/5 outline-2 outline-dashed outline-primary/40 outline-offset-2;
    }
    .rc-token {
        @apply relative overflow-hidden rounded-xl border border-border-color bg-white p-2.5 transition-all duration-200 dark:border-white/10 dark:bg-slate-800;
        cursor: grab;
    }
    .rc-token:hover {
        @apply -translate-y-0.5 shadow-md;
    }
    .rc-token.is-dragging {
        @apply opacity-40 shadow-none;
        cursor: grabbing;
    }
    .rc-token + .rc-token {
        @apply mt-2;
    }
    .rc-token.is-called {
        border-color: color-mix(
            in oklab,
            var(--rc-accent, var(--rc-amber)) 55%,
            transparent
        );
        animation: skeleton-pulse 2s ease-in-out infinite;
    }
    /* Perforated ticket number stub. */
    .rc-token-no {
        @apply relative grid size-10 shrink-0 place-items-center rounded-xl text-xs font-extrabold text-white tabular-nums;
        background-image: linear-gradient(
            135deg,
            var(--rc-accent, var(--rc-amber)),
            color-mix(in oklab, var(--rc-accent, var(--rc-amber)) 55%, #1e1b4b)
        );
    }
    .rc-token-no::after {
        content: "";
        @apply absolute -bottom-1 left-1/2 size-2 -translate-x-1/2 rounded-full bg-white dark:bg-slate-800;
    }
    .rc-token-btn {
        @apply grid size-6.5 place-items-center rounded-xl text-[11px] text-gray-400 transition-all duration-200;
    }
    .rc-token-btn:hover {
        color: var(--rc-accent, var(--rc-amber));
        background-color: color-mix(
            in oklab,
            var(--rc-accent, var(--rc-amber)) 12%,
            transparent
        );
    }

    /* --- Appointment timeline ----------------------------------------------- */
    .rc-appt {
        @apply relative flex gap-3 pb-4 last:pb-0;
    }
    .rc-appt:not(:last-child)::before {
        content: "";
        @apply absolute left-[9px] top-6 bottom-0 w-px bg-border-color dark:bg-white/10;
    }
    .rc-appt-dot {
        @apply relative z-10 mt-1.5 grid size-[19px] shrink-0 place-items-center rounded-full border-2 border-white text-[9px] text-white dark:border-slate-800;
        background-color: var(--rc-accent, var(--rc-amber));
    }
    .rc-appt.is-now .rc-appt-dot {
        animation: tc-ping 1.8s ease-in-out infinite;
    }
    .rc-appt-card {
        @apply min-w-0 flex-1 rounded-xl border border-border-color p-2.5 transition-colors duration-200 dark:border-white/10;
    }
    .rc-appt.is-now .rc-appt-card {
        border-color: color-mix(
            in oklab,
            var(--rc-accent, var(--rc-amber)) 45%,
            transparent
        );
        background-color: color-mix(
            in oklab,
            var(--rc-accent, var(--rc-amber)) 6%,
            transparent
        );
    }

    /* --- Registration desk --------------------------------------------------- */
    .rc-reg {
        @apply relative overflow-hidden rounded-xl border border-border-color p-3 transition-all duration-200 dark:border-white/10;
        border-left-width: 3px;
        border-left-color: var(--rc-accent, var(--rc-amber));
    }
    .rc-reg:hover {
        @apply -translate-y-0.5 bg-gray-50 dark:bg-white/5;
    }
    .rc-reg-btn {
        @apply flex w-full items-center gap-2.5 rounded-xl border border-dashed border-border-color p-2.5 text-xs font-bold text-gray-600 transition-all duration-200 dark:border-white/15 dark:text-gray-300;
    }
    .rc-reg-btn:hover {
        @apply -translate-y-0.5;
        color: var(--rc-accent, var(--rc-amber));
        border-color: color-mix(
            in oklab,
            var(--rc-accent, var(--rc-amber)) 50%,
            transparent
        );
        background-color: color-mix(
            in oklab,
            var(--rc-accent, var(--rc-amber)) 7%,
            transparent
        );
    }
    .rc-reg-btn i {
        @apply grid size-8 place-items-center rounded-xl text-[13px];
        color: var(--rc-accent, var(--rc-amber));
        background-color: color-mix(
            in oklab,
            var(--rc-accent, var(--rc-amber)) 12%,
            transparent
        );
    }

    /* --- Waiting area seat map ----------------------------------------------- */
    .rc-seat {
        @apply grid aspect-square place-items-center rounded-xl border text-[9px] transition-all duration-200 cursor-default;
        color: var(--rc-seat-c, var(--rc-slate));
        border-color: color-mix(
            in oklab,
            var(--rc-seat-c, var(--rc-slate)) 35%,
            transparent
        );
        background-color: color-mix(
            in oklab,
            var(--rc-seat-c, var(--rc-slate)) 10%,
            transparent
        );
    }
    .rc-seat:hover {
        @apply scale-110;
    }
    .rc-seat.is-free {
        --rc-seat-c: var(--rc-emerald);
    }
    .rc-seat.is-patient {
        --rc-seat-c: var(--rc-sky);
    }
    .rc-seat.is-family {
        --rc-seat-c: var(--rc-violet);
    }
    .rc-seat.is-emergency {
        --rc-seat-c: var(--rc-rose);
        animation: skeleton-pulse 1.8s ease-in-out infinite;
    }

    /* --- Doctor status wall ---------------------------------------------------- */
    .rc-doc {
        @apply relative overflow-hidden rounded-xl border border-border-color p-3 transition-all duration-200 dark:border-white/10;
    }
    .rc-doc:hover {
        @apply -translate-y-0.5;
        border-color: color-mix(
            in oklab,
            var(--rc-doc-c, var(--rc-emerald)) 45%,
            transparent
        );
        box-shadow: 0 14px 30px -20px
            color-mix(
                in oklab,
                var(--rc-doc-c, var(--rc-emerald)) 80%,
                transparent
            );
    }
    .rc-doc.is-available {
        --rc-doc-c: var(--rc-emerald);
    }
    .rc-doc.is-consult {
        --rc-doc-c: var(--rc-sky);
    }
    .rc-doc.is-surgery {
        --rc-doc-c: var(--rc-violet);
    }
    .rc-doc.is-break {
        --rc-doc-c: var(--rc-amber);
    }
    .rc-doc.is-offline {
        --rc-doc-c: var(--rc-slate);
    }
    .rc-doc-avatar {
        @apply relative grid size-10 shrink-0 place-items-center rounded-xl text-xs font-extrabold text-white;
        background-image: linear-gradient(
            135deg,
            var(--rc-doc-c, var(--rc-slate)),
            color-mix(in oklab, var(--rc-doc-c, var(--rc-slate)) 55%, #1e1b4b)
        );
    }
    .rc-doc-dot {
        @apply absolute -bottom-0.5 -right-0.5 size-3 rounded-full border-2 border-white dark:border-slate-800;
        background-color: var(--rc-doc-c, var(--rc-slate));
    }
    .rc-doc.is-available .rc-doc-dot {
        animation: tc-ping 1.8s ease-in-out infinite;
    }
    .rc-doc-status {
        @apply inline-flex items-center gap-1 rounded-full px-1.5 py-0.5 text-[9px] font-extrabold uppercase tracking-wide;
        color: var(--rc-doc-c, var(--rc-slate));
        background-color: color-mix(
            in oklab,
            var(--rc-doc-c, var(--rc-slate)) 13%,
            transparent
        );
    }

    /* --- Visitor pass cards ------------------------------------------------------ */
    .rc-pass {
        @apply relative flex items-center gap-3 overflow-hidden rounded-xl border border-border-color p-3 transition-all duration-200 dark:border-white/10;
    }
    .rc-pass:hover {
        @apply -translate-y-0.5;
        border-color: color-mix(
            in oklab,
            var(--rc-accent, var(--rc-amber)) 45%,
            transparent
        );
    }
    /* Lanyard hole punch. */
    .rc-pass::before {
        content: "";
        @apply absolute left-1/2 top-1.5 h-1.5 w-8 -translate-x-1/2 rounded-full bg-gray-100 dark:bg-white/10;
    }
    .rc-pass-badge {
        @apply grid size-10 shrink-0 place-items-center rounded-xl text-[11px] font-extrabold text-white;
        background-image: linear-gradient(
            135deg,
            var(--rc-accent, var(--rc-amber)),
            color-mix(in oklab, var(--rc-accent, var(--rc-amber)) 55%, #1e1b4b)
        );
    }

    /* --- Billing drawer ----------------------------------------------------------- */
    .rc-bill {
        @apply relative overflow-hidden rounded-xl border border-border-color p-3.5 transition-all duration-200 dark:border-white/10;
        background-image: linear-gradient(
            140deg,
            color-mix(
                in oklab,
                var(--rc-accent, var(--rc-amber)) 7%,
                transparent
            ),
            transparent 60%
        );
    }
    .rc-bill:hover {
        @apply -translate-y-0.5;
        border-color: color-mix(
            in oklab,
            var(--rc-accent, var(--rc-amber)) 45%,
            transparent
        );
    }
    .rc-bill-val {
        @apply text-xl font-extrabold text-gray-900 tabular-nums;
    }

    /* --- Announcements board -------------------------------------------------------- */
    .rc-note {
        @apply relative overflow-hidden rounded-xl border p-3 transition-colors duration-200;
        border-color: color-mix(
            in oklab,
            var(--rc-accent, var(--rc-amber)) 30%,
            transparent
        );
        background-image: linear-gradient(
            120deg,
            color-mix(
                in oklab,
                var(--rc-accent, var(--rc-amber)) 8%,
                transparent
            ),
            transparent 65%
        );
    }
    .rc-note.is-broadcast {
        border-color: color-mix(in oklab, var(--rc-rose) 55%, transparent);
        animation: skeleton-pulse 1.8s ease-in-out infinite;
    }

    /* --- Performance meters ----------------------------------------------------------- */
    .rc-meter {
        @apply rounded-xl border border-border-color p-3 dark:border-white/10;
    }
    .rc-meter-track {
        @apply mt-2 h-1.5 w-full overflow-hidden rounded-full bg-gray-100 dark:bg-slate-700;
    }
    .rc-meter-fill {
        @apply h-full rounded-full transition-all duration-700;
        background-image: linear-gradient(
            90deg,
            color-mix(
                in oklab,
                var(--rc-accent, var(--rc-amber)) 65%,
                transparent
            ),
            var(--rc-accent, var(--rc-amber))
        );
    }

    /* --- Activity feed ------------------------------------------------------------------ */
    .rc-tl {
        @apply relative flex gap-3 pb-4 last:pb-0;
    }
    .rc-tl:not(:last-child)::before {
        content: "";
        @apply absolute left-[13px] top-8 bottom-0 w-px bg-border-color dark:bg-white/10;
    }
    .rc-tl-icon {
        @apply relative z-10 grid size-7 shrink-0 place-items-center rounded-full text-[11px];
        color: var(--rc-accent, var(--rc-amber));
        background-color: color-mix(
            in oklab,
            var(--rc-accent, var(--rc-amber)) 14%,
            transparent
        );
        box-shadow:
            inset 0 0 0 1px
                color-mix(
                    in oklab,
                    var(--rc-accent, var(--rc-amber)) 28%,
                    transparent
                ),
            0 0 0 3px var(--color-white);
    }

    /* --- Floating action dock ------------------------------------------------------------ */
    .rc-dock {
        @apply fixed bottom-6 right-6 z-40 flex flex-col items-end gap-2.5;
    }
    .rc-dock-menu {
        @apply flex flex-col items-end gap-2 transition-all duration-300;
    }
    .rc-dock-menu.is-closed {
        @apply pointer-events-none translate-y-3 opacity-0;
    }
    .rc-dock-item {
        @apply flex items-center gap-2.5 rounded-full border border-border-color bg-white py-2 pl-4 pr-2 text-xs font-bold text-gray-700 shadow-lg transition-all duration-200 dark:border-white/10 dark:bg-slate-800 dark:text-gray-200;
    }
    .rc-dock-item:hover {
        @apply -translate-x-1;
        border-color: color-mix(
            in oklab,
            var(--rc-accent, var(--rc-amber)) 45%,
            transparent
        );
    }
    .rc-dock-item i {
        @apply grid size-8 place-items-center rounded-full text-[13px] text-white;
        background-image: linear-gradient(
            135deg,
            var(--rc-accent, var(--rc-amber)),
            color-mix(in oklab, var(--rc-accent, var(--rc-amber)) 60%, #1e1b4b)
        );
    }
    .rc-dock-fab {
        @apply grid size-14 place-items-center rounded-xl text-xl text-white transition-all duration-300;
        background-image: linear-gradient(
            135deg,
            var(--rc-orange),
            var(--rc-amber)
        );
        box-shadow: 0 18px 36px -12px var(--rc-orange);
    }
    .rc-dock-fab:hover {
        @apply -translate-y-1 brightness-110;
    }
    .rc-dock-fab.is-open {
        @apply rotate-45;
    }

    /* The front desk runs all day — honour reduced-motion. */
    @media (prefers-reduced-motion: reduce) {
        .rc-panel,
        .rc-action,
        .rc-token,
        .rc-doc,
        .rc-seat,
        .rc-pass,
        .rc-bill,
        .rc-reg,
        .rc-reg-btn,
        .rc-dock-item,
        .rc-dock-fab,
        .rc-dock-menu {
            @apply transition-none;
        }
        .rc-panel:hover,
        .rc-action:hover,
        .rc-token:hover,
        .rc-doc:hover,
        .rc-pass:hover,
        .rc-bill:hover,
        .rc-reg:hover,
        .rc-reg-btn:hover,
        .rc-dock-fab:hover {
            @apply translate-y-0;
        }
        .rc-seat:hover {
            @apply scale-100;
        }
        .rc-onair-dot,
        .rc-step.is-now .rc-step-node,
        .rc-appt.is-now .rc-appt-dot,
        .rc-doc.is-available .rc-doc-dot,
        .rc-token.is-called,
        .rc-seat.is-emergency,
        .rc-note.is-broadcast {
            animation: none;
        }
    }

    /* =====================================================================
       PHARMACY COMMAND CENTER — EXCLUSIVE to pharmacy-dashboard.html.
       A hospital dispensary at full flow: deep emerald apothecary hero
       with a capsule texture, Rx kanban, expiry conveyor, controlled-drug
       vault, supplier dock and category shelves. Distinct from dr/ns/rc
       and the ph- pharmacy module pages.
       ===================================================================== */
    .rx-scope {
        --rx-emerald: #10b981;
        --rx-green: #22c55e;
        --rx-lime: #84cc16;
        --rx-violet: #8b5cf6;
        --rx-amber: #f59e0b;
        --rx-rose: #f43f5e;
        --rx-sky: #0ea5e9;
        --rx-slate: #64748b;
    }

    /* --- Hero: the dispensary counter ------------------------------------ */
    .rx-hero {
        @apply relative isolate overflow-hidden rounded-xl p-6 lg:p-8;
        background-image: linear-gradient(
            114deg,
            #022c22 0%,
            #065f46 46%,
            #1a2e05 100%
        );
    }
    .rx-hero::before {
        content: "";
        @apply pointer-events-none absolute -right-24 -top-28 -z-10 size-[26rem] rounded-full blur-3xl opacity-40;
        background-image: radial-gradient(
            circle,
            var(--rx-green) 0%,
            transparent 65%
        );
    }
    .rx-hero::after {
        content: "";
        @apply pointer-events-none absolute -bottom-32 -left-16 -z-10 size-[22rem] rounded-full blur-3xl opacity-25;
        background-image: radial-gradient(
            circle,
            var(--rx-lime) 0%,
            transparent 65%
        );
    }
    /* Capsule texture — staggered pill shapes, not dots or grids. */
    .rx-hero-pills {
        @apply pointer-events-none absolute inset-0 -z-10 opacity-[0.09];
        background-image: radial-gradient(
            ellipse 9px 4px at 12px 10px,
            rgba(255, 255, 255, 0.9) 60%,
            transparent 61%
        );
        background-size: 44px 30px;
        mask-image: radial-gradient(
            ellipse at 75% 10%,
            #000 15%,
            transparent 70%
        );
    }
    .rx-hero-title {
        @apply text-2xl lg:text-[2rem] font-extrabold leading-tight tracking-tight text-white;
    }
    .rx-hero-sub {
        @apply mt-1.5 flex flex-wrap items-center gap-x-2 gap-y-1 text-xs font-medium text-white/60;
    }
    .rx-open {
        @apply inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[10px] font-extrabold uppercase tracking-wider;
    }
    .rx-open.is-open {
        @apply border-emerald-300/30 bg-emerald-400/15 text-emerald-200;
    }
    .rx-open.is-busy {
        @apply border-amber-300/30 bg-amber-400/15 text-amber-200;
    }
    .rx-open.is-emergency {
        @apply border-rose-300/40 bg-rose-400/15 text-rose-200;
    }
    .rx-open-dot {
        @apply size-1.5 rounded-full bg-current;
        animation: tc-ping 1.6s ease-in-out infinite;
    }
    .rx-fact {
        @apply rounded-xl border border-white/10 bg-white/[0.07] px-3.5 py-2.5 backdrop-blur-md;
    }
    .rx-fact dt {
        @apply text-[9px] font-extrabold uppercase tracking-[0.14em] text-white/45;
    }
    .rx-fact dd {
        @apply mt-0.5 text-sm font-extrabold text-white tabular-nums;
    }
    /* Counter status pips inside the hero. */
    .rx-counter {
        @apply flex items-center gap-2 rounded-xl border border-white/10 bg-white/[0.07] px-3 py-2 backdrop-blur-md;
    }
    .rx-counter-dot {
        @apply size-2 rounded-full;
    }
    .rx-action {
        @apply inline-flex items-center gap-2 rounded-xl border border-white/15 bg-white/10 px-3.5 py-2.5 text-xs font-bold text-white backdrop-blur-md transition-all duration-300;
    }
    .rx-action:hover {
        @apply -translate-y-0.5 border-white/30 bg-white/20;
    }
    .rx-action:focus-visible {
        @apply outline-2 outline-offset-2 outline-white/70;
    }
    .rx-action.is-primary {
        @apply border-transparent;
        background-image: linear-gradient(
            120deg,
            var(--rx-emerald),
            var(--rx-lime)
        );
        box-shadow: 0 12px 28px -10px var(--rx-emerald);
    }
    .rx-action.is-primary:hover {
        @apply brightness-110;
    }
    /* Emergency order ribbon on the hero. */
    .rx-urgent {
        @apply mt-6 flex flex-wrap items-center gap-3 rounded-xl border border-white/10 bg-white/[0.06] px-4 py-3 backdrop-blur-md;
    }
    .rx-urgent.is-alert {
        @apply border-rose-400/40;
        background-image: linear-gradient(
            100deg,
            color-mix(in oklab, var(--rx-rose) 26%, transparent),
            transparent 70%
        );
    }

    /* --- Workflow stepper -------------------------------------------------- */
    .rx-steps {
        @apply flex min-w-max items-stretch;
    }
    .rx-step {
        @apply relative flex min-w-32 flex-1 flex-col items-center gap-2 px-3 pt-1 text-center;
    }
    .rx-step:not(:last-child)::after {
        content: "";
        @apply absolute left-1/2 right-[-50%] top-[1.35rem] h-0.5 bg-border-color dark:bg-white/10;
    }
    .rx-step.is-done:not(:last-child)::after {
        background-image: linear-gradient(
            90deg,
            var(--rx-emerald),
            var(--rx-lime)
        );
    }
    .rx-step-node {
        @apply relative z-10 grid size-9 place-items-center rounded-full border-2 border-border-color bg-white text-sm text-gray-400 transition-all duration-300 dark:border-white/15 dark:bg-slate-800;
    }
    .rx-step.is-done .rx-step-node {
        @apply border-transparent text-white;
        background-image: linear-gradient(
            135deg,
            var(--rx-emerald),
            var(--rx-lime)
        );
    }
    .rx-step.is-now .rx-step-node {
        @apply border-transparent text-white;
        background-image: linear-gradient(
            135deg,
            var(--rx-emerald),
            var(--rx-sky)
        );
        box-shadow: 0 0 0 5px
            color-mix(in oklab, var(--rx-emerald) 18%, transparent);
        animation: tc-ping 2s ease-in-out infinite;
    }
    .rx-step-name {
        @apply text-[11px] font-bold text-gray-500;
    }
    .rx-step.is-now .rx-step-name {
        @apply text-gray-900;
    }
    .rx-step-time {
        @apply text-[10px] font-semibold text-gray-400 tabular-nums;
    }

    /* --- Panels -------------------------------------------------------------- */
    .rx-panel {
        --rx-accent: var(--rx-emerald);
        @apply relative flex flex-col overflow-hidden rounded-xl border border-border-color bg-white transition-all duration-300;
        @apply dark:border-white/10 dark:bg-slate-800/70 dark:backdrop-blur-xl;
    }
    .rx-panel:hover {
        @apply -translate-y-1;
        border-color: color-mix(in oklab, var(--rx-accent) 40%, transparent);
        box-shadow: 0 24px 48px -26px
            color-mix(in oklab, var(--rx-accent) 70%, transparent);
    }
    .rx-panel-head {
        @apply flex items-center gap-2.5 p-4 pb-0;
    }
    .rx-panel-icon {
        @apply grid size-9 shrink-0 place-items-center rounded-xl text-sm;
        color: var(--rx-accent);
        background-image: linear-gradient(
            145deg,
            color-mix(in oklab, var(--rx-accent) 18%, transparent),
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(in oklab, var(--rx-accent) 26%, transparent);
    }
    .rx-panel-title {
        @apply text-sm font-bold text-gray-900;
    }
    .rx-panel-body {
        @apply flex-1 p-4;
    }
    .rx-emerald {
        --rx-accent: var(--rx-emerald);
    }
    .rx-green {
        --rx-accent: var(--rx-green);
    }
    .rx-lime {
        --rx-accent: var(--rx-lime);
    }
    .rx-violet {
        --rx-accent: var(--rx-violet);
    }
    .rx-amber {
        --rx-accent: var(--rx-amber);
    }
    .rx-rose {
        --rx-accent: var(--rx-rose);
    }
    .rx-sky {
        --rx-accent: var(--rx-sky);
    }
    .rx-chip {
        @apply inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-bold whitespace-nowrap;
        color: var(--rx-accent, var(--rx-emerald));
        background-color: color-mix(
            in oklab,
            var(--rx-accent, var(--rx-emerald)) 13%,
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(
                in oklab,
                var(--rx-accent, var(--rx-emerald)) 24%,
                transparent
            );
    }

    /* --- Dispensing kanban ----------------------------------------------------- */
    .rx-lane {
        @apply flex min-w-56 flex-1 flex-col rounded-xl border border-border-color bg-gray-50/70 p-2.5 dark:border-white/10 dark:bg-white/[0.03];
        border-top-width: 3px;
        border-top-color: var(--rx-accent, var(--rx-emerald));
    }
    .rx-card {
        @apply relative overflow-hidden rounded-xl border border-border-color bg-white p-2.5 transition-all duration-200 dark:border-white/10 dark:bg-slate-800;
    }
    .rx-card:hover {
        @apply -translate-y-0.5 shadow-md;
    }
    .rx-card + .rx-card {
        @apply mt-2;
    }
    .rx-card.is-stat {
        animation: skeleton-pulse 2s ease-in-out infinite;
        border-color: color-mix(in oklab, var(--rx-rose) 55%, transparent);
    }
    /* Rx ID plate — prescription pad corner. */
    .rx-id {
        @apply inline-flex items-center gap-1 rounded-xl px-1.5 py-0.5 text-[10px] font-extrabold tabular-nums text-white;
        background-image: linear-gradient(
            135deg,
            var(--rx-accent, var(--rx-emerald)),
            color-mix(
                in oklab,
                var(--rx-accent, var(--rx-emerald)) 55%,
                #022c22
            )
        );
    }
    .rx-card-btn {
        @apply grid size-6.5 place-items-center rounded-xl text-[11px] text-gray-400 transition-all duration-200;
    }
    .rx-card-btn:hover {
        color: var(--rx-accent, var(--rx-emerald));
        background-color: color-mix(
            in oklab,
            var(--rx-accent, var(--rx-emerald)) 12%,
            transparent
        );
    }

    /* --- Inventory monitor rings ------------------------------------------------- */
    .rx-inv {
        @apply flex items-center gap-3 rounded-xl border border-border-color p-3 transition-all duration-200 dark:border-white/10;
    }
    .rx-inv:hover {
        @apply -translate-y-0.5;
        border-color: color-mix(
            in oklab,
            var(--rx-accent, var(--rx-emerald)) 45%,
            transparent
        );
    }
    .rx-ring {
        @apply relative grid shrink-0 place-items-center;
    }
    .rx-ring svg {
        @apply size-12 -rotate-90;
    }
    .rx-ring-track {
        @apply text-gray-200 dark:text-slate-700;
    }
    .rx-ring-fill {
        stroke: var(--rx-accent, var(--rx-emerald));
        transition: stroke-dashoffset 0.8s ease;
    }
    .rx-ring-label {
        @apply absolute inset-0 grid place-items-center text-[10px] font-extrabold tabular-nums;
        color: var(--rx-accent, var(--rx-emerald));
    }

    /* --- Low stock shelf cards ----------------------------------------------------- */
    .rx-med {
        @apply relative overflow-hidden rounded-xl border border-border-color p-3 transition-all duration-200 dark:border-white/10;
        border-left-width: 3px;
        border-left-color: var(--rx-accent, var(--rx-amber));
    }
    .rx-med:hover {
        @apply -translate-y-0.5 bg-gray-50 dark:bg-white/5;
        box-shadow: 0 14px 30px -20px
            color-mix(
                in oklab,
                var(--rx-accent, var(--rx-amber)) 80%,
                transparent
            );
    }
    .rx-med-track {
        @apply mt-2 h-1.5 w-full overflow-hidden rounded-full bg-gray-100 dark:bg-slate-700;
    }
    .rx-med-fill {
        @apply h-full rounded-full transition-all duration-700;
        background-image: linear-gradient(
            90deg,
            var(--rx-accent, var(--rx-amber)),
            color-mix(in oklab, var(--rx-accent, var(--rx-amber)) 60%, #fff)
        );
    }

    /* --- Expiry conveyor -------------------------------------------------------------- */
    .rx-exp {
        @apply relative flex min-w-52 flex-1 flex-col rounded-xl border border-border-color p-3 dark:border-white/10;
        border-top-width: 3px;
        border-top-color: var(--rx-accent, var(--rx-amber));
        background-image: linear-gradient(
            170deg,
            color-mix(
                in oklab,
                var(--rx-accent, var(--rx-amber)) 6%,
                transparent
            ),
            transparent 45%
        );
    }
    .rx-exp.is-critical {
        animation: skeleton-pulse 1.8s ease-in-out infinite;
        border-color: color-mix(in oklab, var(--rx-rose) 50%, transparent);
    }
    .rx-exp-item {
        @apply flex items-center justify-between gap-2 rounded-xl px-2 py-1.5 text-[11px] font-semibold text-gray-600 transition-colors duration-150 dark:text-gray-300;
    }
    .rx-exp-item:hover {
        background-color: color-mix(
            in oklab,
            var(--rx-accent, var(--rx-amber)) 9%,
            transparent
        );
    }

    /* --- Controlled drug vault ---------------------------------------------------------- */
    .rx-vault {
        @apply relative overflow-hidden rounded-xl p-3.5;
        background-image: linear-gradient(
            130deg,
            color-mix(in oklab, var(--rx-violet) 12%, transparent),
            color-mix(in oklab, var(--rx-violet) 4%, transparent)
        );
        box-shadow: inset 0 0 0 1px
            color-mix(in oklab, var(--rx-violet) 26%, transparent);
    }
    .rx-vault-row {
        @apply flex items-center justify-between gap-2 border-b border-dashed py-2 text-[11px] font-semibold text-gray-600 last:border-0 last:pb-0 dark:text-gray-300;
        border-color: color-mix(in oklab, var(--rx-violet) 20%, transparent);
    }
    .rx-lock {
        @apply inline-flex items-center gap-1.5 rounded-full px-2 py-1 text-[9px] font-extrabold uppercase tracking-wider;
        color: var(--rx-violet);
        background-color: color-mix(
            in oklab,
            var(--rx-violet) 13%,
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(in oklab, var(--rx-violet) 30%, transparent);
    }

    /* --- Supplier dock ------------------------------------------------------------------- */
    .rx-sup {
        @apply relative flex items-center gap-3 overflow-hidden rounded-xl border border-border-color p-3 transition-all duration-200 dark:border-white/10;
    }
    .rx-sup:hover {
        @apply -translate-y-0.5;
        border-color: color-mix(
            in oklab,
            var(--rx-accent, var(--rx-sky)) 45%,
            transparent
        );
    }
    .rx-sup-logo {
        @apply grid size-10 shrink-0 place-items-center rounded-xl text-[11px] font-extrabold text-white;
        background-image: linear-gradient(
            135deg,
            var(--rx-accent, var(--rx-sky)),
            color-mix(in oklab, var(--rx-accent, var(--rx-sky)) 55%, #022c22)
        );
    }

    /* --- Category shelves ------------------------------------------------------------------ */
    .rx-shelf {
        @apply relative overflow-hidden rounded-xl border border-border-color p-3 text-center transition-all duration-200 dark:border-white/10;
    }
    .rx-shelf:hover {
        @apply -translate-y-0.5;
        border-color: color-mix(
            in oklab,
            var(--rx-accent, var(--rx-emerald)) 45%,
            transparent
        );
        box-shadow: 0 14px 30px -20px
            color-mix(
                in oklab,
                var(--rx-accent, var(--rx-emerald)) 80%,
                transparent
            );
    }
    .rx-shelf-icon {
        @apply mx-auto grid size-10 place-items-center rounded-xl text-base;
        color: var(--rx-accent, var(--rx-emerald));
        background-image: linear-gradient(
            145deg,
            color-mix(
                in oklab,
                var(--rx-accent, var(--rx-emerald)) 16%,
                transparent
            ),
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(
                in oklab,
                var(--rx-accent, var(--rx-emerald)) 26%,
                transparent
            );
    }

    /* --- Finance ledger ---------------------------------------------------------------------- */
    .rx-fin {
        @apply relative overflow-hidden rounded-xl border border-border-color p-3.5 transition-all duration-200 dark:border-white/10;
        background-image: linear-gradient(
            140deg,
            color-mix(
                in oklab,
                var(--rx-accent, var(--rx-emerald)) 7%,
                transparent
            ),
            transparent 60%
        );
    }
    .rx-fin:hover {
        @apply -translate-y-0.5;
        border-color: color-mix(
            in oklab,
            var(--rx-accent, var(--rx-emerald)) 45%,
            transparent
        );
    }

    /* --- Activity feed -------------------------------------------------------------------------- */
    .rx-tl {
        @apply relative flex gap-3 pb-4 last:pb-0;
    }
    .rx-tl:not(:last-child)::before {
        content: "";
        @apply absolute left-[13px] top-8 bottom-0 w-px bg-border-color dark:bg-white/10;
    }
    .rx-tl-icon {
        @apply relative z-10 grid size-7 shrink-0 place-items-center rounded-full text-[11px];
        color: var(--rx-accent, var(--rx-emerald));
        background-color: color-mix(
            in oklab,
            var(--rx-accent, var(--rx-emerald)) 14%,
            transparent
        );
        box-shadow:
            inset 0 0 0 1px
                color-mix(
                    in oklab,
                    var(--rx-accent, var(--rx-emerald)) 28%,
                    transparent
                ),
            0 0 0 3px var(--color-white);
    }

    /* --- Floating action dock --------------------------------------------------------------------- */
    .rx-dock {
        @apply fixed bottom-6 right-6 z-40 flex flex-col items-end gap-2.5;
    }
    .rx-dock-menu {
        @apply flex flex-col items-end gap-2 transition-all duration-300;
    }
    .rx-dock-menu.is-closed {
        @apply pointer-events-none translate-y-3 opacity-0;
    }
    .rx-dock-item {
        @apply flex items-center gap-2.5 rounded-full border border-border-color bg-white py-2 pl-4 pr-2 text-xs font-bold text-gray-700 shadow-lg transition-all duration-200 dark:border-white/10 dark:bg-slate-800 dark:text-gray-200;
    }
    .rx-dock-item:hover {
        @apply -translate-x-1;
        border-color: color-mix(
            in oklab,
            var(--rx-accent, var(--rx-emerald)) 45%,
            transparent
        );
    }
    .rx-dock-item i {
        @apply grid size-8 place-items-center rounded-full text-[13px] text-white;
        background-image: linear-gradient(
            135deg,
            var(--rx-accent, var(--rx-emerald)),
            color-mix(
                in oklab,
                var(--rx-accent, var(--rx-emerald)) 60%,
                #022c22
            )
        );
    }
    .rx-dock-fab {
        @apply grid size-14 place-items-center rounded-xl text-xl text-white transition-all duration-300;
        background-image: linear-gradient(
            135deg,
            var(--rx-emerald),
            var(--rx-lime)
        );
        box-shadow: 0 18px 36px -12px var(--rx-emerald);
    }
    .rx-dock-fab:hover {
        @apply -translate-y-1 brightness-110;
    }
    .rx-dock-fab.is-open {
        @apply rotate-45;
    }

    /* The dispensary runs all day — honour reduced-motion. */
    @media (prefers-reduced-motion: reduce) {
        .rx-panel,
        .rx-action,
        .rx-card,
        .rx-inv,
        .rx-med,
        .rx-sup,
        .rx-shelf,
        .rx-fin,
        .rx-dock-item,
        .rx-dock-fab,
        .rx-dock-menu {
            @apply transition-none;
        }
        .rx-panel:hover,
        .rx-action:hover,
        .rx-card:hover,
        .rx-inv:hover,
        .rx-med:hover,
        .rx-sup:hover,
        .rx-shelf:hover,
        .rx-fin:hover,
        .rx-dock-fab:hover {
            @apply translate-y-0;
        }
        .rx-open-dot,
        .rx-step.is-now .rx-step-node,
        .rx-card.is-stat,
        .rx-exp.is-critical {
            animation: none;
        }
    }

    /* =====================================================================
       LABORATORY COMMAND CENTER — EXCLUSIVE to laboratory-dashboard.html.
       A LIMS floor at full throughput: cold navy/blue diagnostics hero
       with a microplate-well texture, sample pipeline, tracking kanban,
       equipment bay, technician bench, QC console and report approvals.
       Distinct from dr/ns/rc/rx and the laboratory module pages.
       ===================================================================== */
    .lb-scope {
        --lb-blue: #3b82f6;
        --lb-cyan: #06b6d4;
        --lb-indigo: #6366f1;
        --lb-violet: #8b5cf6;
        --lb-amber: #f59e0b;
        --lb-rose: #f43f5e;
        --lb-emerald: #10b981;
        --lb-slate: #64748b;
    }

    /* --- Hero: the lab floor --------------------------------------------- */
    .lb-hero {
        @apply relative isolate overflow-hidden rounded-xl p-6 lg:p-8;
        background-image: linear-gradient(
            116deg,
            #0b1533 0%,
            #1e3a8a 48%,
            #155e75 100%
        );
    }
    .lb-hero::before {
        content: "";
        @apply pointer-events-none absolute -right-24 -top-28 -z-10 size-[26rem] rounded-full blur-3xl opacity-40;
        background-image: radial-gradient(
            circle,
            var(--lb-cyan) 0%,
            transparent 65%
        );
    }
    .lb-hero::after {
        content: "";
        @apply pointer-events-none absolute -bottom-32 -left-16 -z-10 size-[22rem] rounded-full blur-3xl opacity-30;
        background-image: radial-gradient(
            circle,
            var(--lb-indigo) 0%,
            transparent 65%
        );
    }
    /* Microplate-well texture — rings in a tight grid, pure lab bench. */
    .lb-hero-wells {
        @apply pointer-events-none absolute inset-0 -z-10 opacity-[0.11];
        background-image: radial-gradient(
            circle 5px at center,
            transparent 3px,
            rgba(255, 255, 255, 0.85) 3.5px,
            rgba(255, 255, 255, 0.85) 4.5px,
            transparent 5px
        );
        background-size: 28px 28px;
        mask-image: radial-gradient(
            ellipse at 78% 12%,
            #000 12%,
            transparent 66%
        );
    }
    .lb-hero-title {
        @apply text-2xl lg:text-[2rem] font-extrabold leading-tight tracking-tight text-white;
    }
    .lb-hero-sub {
        @apply mt-1.5 flex flex-wrap items-center gap-x-2 gap-y-1 text-xs font-medium text-white/60;
    }
    .lb-live {
        @apply inline-flex items-center gap-1.5 rounded-full border border-cyan-300/30 bg-cyan-400/15 px-2.5 py-1 text-[10px] font-extrabold uppercase tracking-wider text-cyan-200;
    }
    .lb-live-dot {
        @apply size-1.5 rounded-full bg-cyan-300;
        animation: tc-ping 1.6s ease-in-out infinite;
    }
    .lb-fact {
        @apply rounded-xl border border-white/10 bg-white/[0.07] px-3.5 py-2.5 backdrop-blur-md;
    }
    .lb-fact dt {
        @apply text-[9px] font-extrabold uppercase tracking-[0.14em] text-white/45;
    }
    .lb-fact dd {
        @apply mt-0.5 text-sm font-extrabold text-white tabular-nums;
    }
    /* Equipment-health meter in the hero. */
    .lb-health {
        @apply rounded-xl border border-white/10 bg-white/[0.07] px-4 py-3 backdrop-blur-md;
    }
    .lb-health-track {
        @apply mt-2 h-1.5 w-40 overflow-hidden rounded-full bg-white/15;
    }
    .lb-health-fill {
        @apply h-full rounded-full transition-all duration-700;
        background-image: linear-gradient(
            90deg,
            var(--lb-cyan),
            var(--lb-emerald)
        );
    }
    .lb-action {
        @apply inline-flex items-center gap-2 rounded-xl border border-white/15 bg-white/10 px-3.5 py-2.5 text-xs font-bold text-white backdrop-blur-md transition-all duration-300;
    }
    .lb-action:hover {
        @apply -translate-y-0.5 border-white/30 bg-white/20;
    }
    .lb-action:focus-visible {
        @apply outline-2 outline-offset-2 outline-white/70;
    }
    .lb-action.is-primary {
        @apply border-transparent;
        background-image: linear-gradient(
            120deg,
            var(--lb-blue),
            var(--lb-cyan)
        );
        box-shadow: 0 12px 28px -10px var(--lb-cyan);
    }
    .lb-action.is-primary:hover {
        @apply brightness-110;
    }
    /* STAT ribbon on the hero. */
    .lb-stat {
        @apply mt-6 flex flex-wrap items-center gap-3 rounded-xl border border-white/10 bg-white/[0.06] px-4 py-3 backdrop-blur-md;
    }
    .lb-stat.is-alert {
        @apply border-rose-400/40;
        background-image: linear-gradient(
            100deg,
            color-mix(in oklab, var(--lb-rose) 26%, transparent),
            transparent 70%
        );
    }

    /* --- Sample pipeline --------------------------------------------------- */
    .lb-pipe {
        @apply flex min-w-max items-stretch;
    }
    .lb-stage {
        @apply relative flex min-w-40 flex-1 flex-col gap-2 px-3 pt-1 text-center;
    }
    .lb-stage:not(:last-child)::after {
        content: "";
        @apply absolute left-1/2 right-[-50%] top-[1.35rem] h-0.5 bg-border-color dark:bg-white/10;
    }
    .lb-stage.is-done:not(:last-child)::after {
        background-image: linear-gradient(
            90deg,
            var(--lb-blue),
            var(--lb-cyan)
        );
    }
    .lb-stage-node {
        @apply relative z-10 mx-auto grid size-9 place-items-center rounded-full border-2 border-border-color bg-white text-sm text-gray-400 transition-all duration-300 dark:border-white/15 dark:bg-slate-800;
    }
    .lb-stage.is-done .lb-stage-node {
        @apply border-transparent text-white;
        background-image: linear-gradient(
            135deg,
            var(--lb-blue),
            var(--lb-cyan)
        );
    }
    .lb-stage.is-now .lb-stage-node {
        @apply border-transparent text-white;
        background-image: linear-gradient(
            135deg,
            var(--lb-cyan),
            var(--lb-violet)
        );
        box-shadow: 0 0 0 5px
            color-mix(in oklab, var(--lb-cyan) 18%, transparent);
        animation: tc-ping 2s ease-in-out infinite;
    }
    /* Per-stage stat plate under each node. */
    .lb-stage-plate {
        @apply mx-auto w-full max-w-36 rounded-xl border border-border-color p-2 dark:border-white/10;
    }
    .lb-stage.is-now .lb-stage-plate {
        border-color: color-mix(in oklab, var(--lb-cyan) 45%, transparent);
        background-color: color-mix(in oklab, var(--lb-cyan) 6%, transparent);
    }
    .lb-stage-bar {
        @apply mt-1.5 h-1 w-full overflow-hidden rounded-full bg-gray-100 dark:bg-slate-700;
    }
    .lb-stage-bar span {
        @apply block h-full rounded-full transition-all duration-700;
        background-image: linear-gradient(
            90deg,
            var(--lb-blue),
            var(--lb-cyan)
        );
    }

    /* --- Panels -------------------------------------------------------------- */
    .lb-panel {
        --lb-accent: var(--lb-blue);
        @apply relative flex flex-col overflow-hidden rounded-xl border border-border-color bg-white transition-all duration-300;
        @apply dark:border-white/10 dark:bg-slate-800/70 dark:backdrop-blur-xl;
    }
    .lb-panel:hover {
        @apply -translate-y-1;
        border-color: color-mix(in oklab, var(--lb-accent) 40%, transparent);
        box-shadow: 0 24px 48px -26px
            color-mix(in oklab, var(--lb-accent) 70%, transparent);
    }
    .lb-panel-head {
        @apply flex items-center gap-2.5 p-4 pb-0;
    }
    .lb-panel-icon {
        @apply grid size-9 shrink-0 place-items-center rounded-xl text-sm;
        color: var(--lb-accent);
        background-image: linear-gradient(
            145deg,
            color-mix(in oklab, var(--lb-accent) 18%, transparent),
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(in oklab, var(--lb-accent) 26%, transparent);
    }
    .lb-panel-title {
        @apply text-sm font-bold text-gray-900;
    }
    .lb-panel-body {
        @apply flex-1 p-4;
    }
    .lb-blue {
        --lb-accent: var(--lb-blue);
    }
    .lb-cyan {
        --lb-accent: var(--lb-cyan);
    }
    .lb-indigo {
        --lb-accent: var(--lb-indigo);
    }
    .lb-violet {
        --lb-accent: var(--lb-violet);
    }
    .lb-amber {
        --lb-accent: var(--lb-amber);
    }
    .lb-rose {
        --lb-accent: var(--lb-rose);
    }
    .lb-emerald {
        --lb-accent: var(--lb-emerald);
    }
    .lb-chip {
        @apply inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-bold whitespace-nowrap;
        color: var(--lb-accent, var(--lb-blue));
        background-color: color-mix(
            in oklab,
            var(--lb-accent, var(--lb-blue)) 13%,
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(
                in oklab,
                var(--lb-accent, var(--lb-blue)) 24%,
                transparent
            );
    }

    /* --- Sample tracking kanban ----------------------------------------------- */
    .lb-lane {
        @apply flex min-w-56 flex-1 flex-col rounded-xl border border-border-color bg-gray-50/70 p-2.5 dark:border-white/10 dark:bg-white/[0.03];
        border-top-width: 3px;
        border-top-color: var(--lb-accent, var(--lb-blue));
    }
    .lb-card {
        @apply relative overflow-hidden rounded-xl border border-border-color bg-white p-2.5 transition-all duration-200 dark:border-white/10 dark:bg-slate-800;
    }
    .lb-card:hover {
        @apply -translate-y-0.5 shadow-md;
    }
    .lb-card + .lb-card {
        @apply mt-2;
    }
    .lb-card.is-stat {
        animation: skeleton-pulse 2s ease-in-out infinite;
        border-color: color-mix(in oklab, var(--lb-rose) 55%, transparent);
    }
    /* Barcode-styled sample ID. */
    .lb-id {
        @apply relative inline-flex items-center gap-1.5 rounded-xl py-0.5 pl-1.5 pr-2 text-[10px] font-extrabold tabular-nums text-white;
        background-image: linear-gradient(
            135deg,
            var(--lb-accent, var(--lb-blue)),
            color-mix(in oklab, var(--lb-accent, var(--lb-blue)) 55%, #0b1533)
        );
    }
    .lb-id::before {
        content: "";
        @apply h-3 w-2;
        background-image: repeating-linear-gradient(
            90deg,
            rgba(255, 255, 255, 0.9) 0 1px,
            transparent 1px 2.5px
        );
    }
    .lb-card-btn {
        @apply grid size-6.5 place-items-center rounded-xl text-[11px] text-gray-400 transition-all duration-200;
    }
    .lb-card-btn:hover {
        color: var(--lb-accent, var(--lb-blue));
        background-color: color-mix(
            in oklab,
            var(--lb-accent, var(--lb-blue)) 12%,
            transparent
        );
    }

    /* --- Critical results center ------------------------------------------------- */
    .lb-crit {
        @apply relative flex items-start gap-3 overflow-hidden rounded-xl border p-3 transition-colors duration-200;
        border-color: color-mix(
            in oklab,
            var(--lb-accent, var(--lb-rose)) 30%,
            transparent
        );
        background-image: linear-gradient(
            120deg,
            color-mix(
                in oklab,
                var(--lb-accent, var(--lb-rose)) 8%,
                transparent
            ),
            transparent 65%
        );
    }
    .lb-crit.is-stat {
        border-color: color-mix(in oklab, var(--lb-rose) 55%, transparent);
        animation: skeleton-pulse 1.8s ease-in-out infinite;
    }

    /* --- Equipment bay ------------------------------------------------------------ */
    .lb-eq {
        @apply relative overflow-hidden rounded-xl border border-border-color p-3 transition-all duration-200 dark:border-white/10;
    }
    .lb-eq:hover {
        @apply -translate-y-0.5;
        border-color: color-mix(
            in oklab,
            var(--lb-eq-c, var(--lb-emerald)) 45%,
            transparent
        );
        box-shadow: 0 14px 30px -20px
            color-mix(
                in oklab,
                var(--lb-eq-c, var(--lb-emerald)) 80%,
                transparent
            );
    }
    .lb-eq.is-running {
        --lb-eq-c: var(--lb-emerald);
    }
    .lb-eq.is-idle {
        --lb-eq-c: var(--lb-slate);
    }
    .lb-eq.is-maintenance {
        --lb-eq-c: var(--lb-amber);
    }
    .lb-eq.is-error {
        --lb-eq-c: var(--lb-rose);
    }
    .lb-eq.is-error {
        animation: skeleton-pulse 1.6s ease-in-out infinite;
    }
    .lb-eq-icon {
        @apply grid size-9 shrink-0 place-items-center rounded-xl text-sm;
        color: var(--lb-eq-c, var(--lb-emerald));
        background-color: color-mix(
            in oklab,
            var(--lb-eq-c, var(--lb-emerald)) 13%,
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(
                in oklab,
                var(--lb-eq-c, var(--lb-emerald)) 26%,
                transparent
            );
    }
    .lb-eq-status {
        @apply inline-flex items-center gap-1 rounded-full px-1.5 py-0.5 text-[9px] font-extrabold uppercase tracking-wide;
        color: var(--lb-eq-c, var(--lb-emerald));
        background-color: color-mix(
            in oklab,
            var(--lb-eq-c, var(--lb-emerald)) 13%,
            transparent
        );
    }
    .lb-eq-status::before {
        content: "";
        @apply size-1 rounded-full bg-current;
    }
    .lb-eq.is-running .lb-eq-status::before {
        animation: tc-ping 1.8s ease-in-out infinite;
    }
    .lb-eq-track {
        @apply mt-2 h-1 w-full overflow-hidden rounded-full bg-gray-100 dark:bg-slate-700;
    }
    .lb-eq-fill {
        @apply block h-full rounded-full transition-all duration-700;
        background-color: var(--lb-eq-c, var(--lb-emerald));
    }

    /* --- Technician bench ------------------------------------------------------------ */
    .lb-tech {
        @apply relative overflow-hidden rounded-xl border border-border-color p-3 transition-all duration-200 dark:border-white/10;
    }
    .lb-tech:hover {
        @apply -translate-y-0.5;
        border-color: color-mix(
            in oklab,
            var(--lb-accent, var(--lb-indigo)) 45%,
            transparent
        );
        box-shadow: 0 14px 30px -20px
            color-mix(
                in oklab,
                var(--lb-accent, var(--lb-indigo)) 80%,
                transparent
            );
    }
    .lb-tech-avatar {
        @apply grid size-11 shrink-0 place-items-center rounded-xl text-[13px] font-extrabold text-white;
        background-image: linear-gradient(
            135deg,
            var(--lb-accent, var(--lb-indigo)),
            color-mix(in oklab, var(--lb-accent, var(--lb-indigo)) 55%, #0b1533)
        );
    }
    .lb-tech-load {
        @apply mt-2 h-1.5 w-full overflow-hidden rounded-full bg-gray-100 dark:bg-slate-700;
    }
    .lb-tech-load span {
        @apply block h-full rounded-full transition-all duration-700;
        background-image: linear-gradient(
            90deg,
            var(--lb-accent, var(--lb-indigo)),
            color-mix(in oklab, var(--lb-accent, var(--lb-indigo)) 55%, #fff)
        );
    }

    /* --- Performance dials -------------------------------------------------------------- */
    .lb-dial {
        @apply relative grid place-items-center;
    }
    .lb-dial svg {
        @apply size-16 -rotate-90;
    }
    .lb-dial-track {
        @apply text-gray-200 dark:text-slate-700;
    }
    .lb-dial-fill {
        stroke: var(--lb-accent, var(--lb-blue));
        transition: stroke-dashoffset 0.8s ease;
    }
    .lb-dial-label {
        @apply absolute inset-0 grid place-items-center text-xs font-extrabold tabular-nums text-gray-900;
    }

    /* --- QC console ----------------------------------------------------------------------- */
    .lb-qc {
        @apply relative overflow-hidden rounded-xl p-3.5;
        background-image: linear-gradient(
            130deg,
            color-mix(
                in oklab,
                var(--lb-accent, var(--lb-emerald)) 10%,
                transparent
            ),
            color-mix(
                in oklab,
                var(--lb-accent, var(--lb-emerald)) 3%,
                transparent
            )
        );
        box-shadow: inset 0 0 0 1px
            color-mix(
                in oklab,
                var(--lb-accent, var(--lb-emerald)) 24%,
                transparent
            );
    }
    .lb-qc-row {
        @apply flex items-center justify-between gap-2 border-b border-dashed py-2 text-[11px] font-semibold text-gray-600 last:border-0 last:pb-0 first:pt-0 dark:text-gray-300;
        border-color: color-mix(
            in oklab,
            var(--lb-accent, var(--lb-emerald)) 20%,
            transparent
        );
    }

    /* --- Category benches ------------------------------------------------------------------- */
    .lb-cat {
        @apply relative overflow-hidden rounded-xl border border-border-color p-3 transition-all duration-200 dark:border-white/10;
        border-left-width: 3px;
        border-left-color: var(--lb-accent, var(--lb-blue));
    }
    .lb-cat:hover {
        @apply -translate-y-0.5 bg-gray-50 dark:bg-white/5;
        box-shadow: 0 14px 30px -20px
            color-mix(
                in oklab,
                var(--lb-accent, var(--lb-blue)) 80%,
                transparent
            );
    }
    .lb-cat-pill {
        @apply grid flex-1 place-items-center rounded-xl py-1.5 text-center;
        background-color: color-mix(
            in oklab,
            var(--lb-accent, var(--lb-blue)) 8%,
            transparent
        );
    }

    /* --- Report approval rail ------------------------------------------------------------------ */
    .lb-rep {
        @apply relative flex gap-3 pb-4 last:pb-0;
    }
    .lb-rep:not(:last-child)::before {
        content: "";
        @apply absolute left-[9px] top-6 bottom-0 w-px bg-border-color dark:bg-white/10;
    }
    .lb-rep-dot {
        @apply relative z-10 mt-1.5 grid size-[19px] shrink-0 place-items-center rounded-full border-2 border-white text-[9px] text-white dark:border-slate-800;
        background-color: var(--lb-accent, var(--lb-blue));
    }
    .lb-rep-card {
        @apply min-w-0 flex-1 rounded-xl border border-border-color p-2.5 transition-colors duration-200 dark:border-white/10;
    }
    .lb-rep:hover .lb-rep-card {
        border-color: color-mix(
            in oklab,
            var(--lb-accent, var(--lb-blue)) 45%,
            transparent
        );
        background-color: color-mix(
            in oklab,
            var(--lb-accent, var(--lb-blue)) 5%,
            transparent
        );
    }

    /* --- Activity feed --------------------------------------------------------------------------- */
    .lb-tl {
        @apply relative flex gap-3 pb-4 last:pb-0;
    }
    .lb-tl:not(:last-child)::before {
        content: "";
        @apply absolute left-[13px] top-8 bottom-0 w-px bg-border-color dark:bg-white/10;
    }
    .lb-tl-icon {
        @apply relative z-10 grid size-7 shrink-0 place-items-center rounded-full text-[11px];
        color: var(--lb-accent, var(--lb-blue));
        background-color: color-mix(
            in oklab,
            var(--lb-accent, var(--lb-blue)) 14%,
            transparent
        );
        box-shadow:
            inset 0 0 0 1px
                color-mix(
                    in oklab,
                    var(--lb-accent, var(--lb-blue)) 28%,
                    transparent
                ),
            0 0 0 3px var(--color-white);
    }

    /* --- Floating action dock ---------------------------------------------------------------------- */
    .lb-dock {
        @apply fixed bottom-6 right-6 z-40 flex flex-col items-end gap-2.5;
    }
    .lb-dock-menu {
        @apply flex flex-col items-end gap-2 transition-all duration-300;
    }
    .lb-dock-menu.is-closed {
        @apply pointer-events-none translate-y-3 opacity-0;
    }
    .lb-dock-item {
        @apply flex items-center gap-2.5 rounded-full border border-border-color bg-white py-2 pl-4 pr-2 text-xs font-bold text-gray-700 shadow-lg transition-all duration-200 dark:border-white/10 dark:bg-slate-800 dark:text-gray-200;
    }
    .lb-dock-item:hover {
        @apply -translate-x-1;
        border-color: color-mix(
            in oklab,
            var(--lb-accent, var(--lb-blue)) 45%,
            transparent
        );
    }
    .lb-dock-item i {
        @apply grid size-8 place-items-center rounded-full text-[13px] text-white;
        background-image: linear-gradient(
            135deg,
            var(--lb-accent, var(--lb-blue)),
            color-mix(in oklab, var(--lb-accent, var(--lb-blue)) 60%, #0b1533)
        );
    }
    .lb-dock-fab {
        @apply grid size-14 place-items-center rounded-xl text-xl text-white transition-all duration-300;
        background-image: linear-gradient(
            135deg,
            var(--lb-blue),
            var(--lb-cyan)
        );
        box-shadow: 0 18px 36px -12px var(--lb-cyan);
    }
    .lb-dock-fab:hover {
        @apply -translate-y-1 brightness-110;
    }
    .lb-dock-fab.is-open {
        @apply rotate-45;
    }

    /* The lab runs around the clock — honour reduced-motion. */
    @media (prefers-reduced-motion: reduce) {
        .lb-panel,
        .lb-action,
        .lb-card,
        .lb-eq,
        .lb-tech,
        .lb-cat,
        .lb-dock-item,
        .lb-dock-fab,
        .lb-dock-menu {
            @apply transition-none;
        }
        .lb-panel:hover,
        .lb-action:hover,
        .lb-card:hover,
        .lb-eq:hover,
        .lb-tech:hover,
        .lb-cat:hover,
        .lb-dock-fab:hover {
            @apply translate-y-0;
        }
        .lb-live-dot,
        .lb-stage.is-now .lb-stage-node,
        .lb-card.is-stat,
        .lb-crit.is-stat,
        .lb-eq.is-error,
        .lb-eq.is-running .lb-eq-status::before {
            animation: none;
        }
    }

    /* =====================================================================
       BILLING & REVENUE COMMAND CENTER — EXCLUSIVE to billing-dashboard.html.
       A hospital finance floor: graphite-and-gold ledger hero with ruled
       lines, revenue pipeline, invoice kanban, payment mix, claims desk,
       collections ledger, department revenue and refund workflow.
       Distinct from dr/ns/rc/rx/lb and the billing module pages.
       ===================================================================== */
    .bl-scope {
        --bl-gold: #eab308;
        --bl-amber: #f59e0b;
        --bl-emerald: #10b981;
        --bl-sky: #0ea5e9;
        --bl-violet: #8b5cf6;
        --bl-rose: #f43f5e;
        --bl-indigo: #6366f1;
        --bl-slate: #64748b;
    }

    /* --- Hero: the revenue desk ------------------------------------------ */
    .bl-hero {
        @apply relative isolate overflow-hidden rounded-xl p-6 lg:p-8;
        background-image: linear-gradient(
            113deg,
            #171310 0%,
            #3b2f14 52%,
            #713f12 100%
        );
    }
    .bl-hero::before {
        content: "";
        @apply pointer-events-none absolute -right-24 -top-28 -z-10 size-[26rem] rounded-full blur-3xl opacity-35;
        background-image: radial-gradient(
            circle,
            var(--bl-gold) 0%,
            transparent 65%
        );
    }
    .bl-hero::after {
        content: "";
        @apply pointer-events-none absolute -bottom-32 -left-16 -z-10 size-[22rem] rounded-full blur-3xl opacity-20;
        background-image: radial-gradient(
            circle,
            var(--bl-emerald) 0%,
            transparent 65%
        );
    }
    /* Ledger-rule texture — fine horizontal book lines with a margin rule. */
    .bl-hero-rules {
        @apply pointer-events-none absolute inset-0 -z-10 opacity-[0.08];
        background-image:
            repeating-linear-gradient(
                180deg,
                transparent 0 26px,
                rgba(255, 255, 255, 0.85) 26px 27px
            ),
            linear-gradient(
                90deg,
                transparent 0 calc(100% - 88px),
                rgba(244, 63, 94, 0.9) calc(100% - 88px) calc(100% - 87px),
                transparent calc(100% - 87px)
            );
        mask-image: linear-gradient(to right, transparent 30%, #000 75%);
    }
    .bl-hero-title {
        @apply text-2xl lg:text-[2rem] font-extrabold leading-tight tracking-tight text-white;
    }
    .bl-hero-sub {
        @apply mt-1.5 flex flex-wrap items-center gap-x-2 gap-y-1 text-xs font-medium text-white/60;
    }
    .bl-open {
        @apply inline-flex items-center gap-1.5 rounded-full border border-yellow-300/30 bg-yellow-400/15 px-2.5 py-1 text-[10px] font-extrabold uppercase tracking-wider text-yellow-200;
    }
    .bl-open-dot {
        @apply size-1.5 rounded-full bg-yellow-300;
        animation: tc-ping 1.6s ease-in-out infinite;
    }
    .bl-fact {
        @apply rounded-xl border border-white/10 bg-white/[0.07] px-3.5 py-2.5 backdrop-blur-md;
    }
    .bl-fact dt {
        @apply text-[9px] font-extrabold uppercase tracking-[0.14em] text-white/45;
    }
    .bl-fact dd {
        @apply mt-0.5 text-sm font-extrabold text-white tabular-nums;
    }
    /* Revenue ticker plate — the hero's centrepiece number. */
    .bl-ticker {
        @apply rounded-xl border border-yellow-300/25 px-4 py-3 backdrop-blur-md;
        background-image: linear-gradient(
            120deg,
            color-mix(in oklab, var(--bl-gold) 20%, transparent),
            transparent 70%
        );
    }
    .bl-action {
        @apply inline-flex items-center gap-2 rounded-xl border border-white/15 bg-white/10 px-3.5 py-2.5 text-xs font-bold text-white backdrop-blur-md transition-all duration-300;
    }
    .bl-action:hover {
        @apply -translate-y-0.5 border-white/30 bg-white/20;
    }
    .bl-action:focus-visible {
        @apply outline-2 outline-offset-2 outline-white/70;
    }
    .bl-action.is-primary {
        @apply border-transparent text-yellow-950;
        background-image: linear-gradient(120deg, #fde047, var(--bl-gold));
        box-shadow: 0 12px 28px -10px var(--bl-gold);
    }
    .bl-action.is-primary:hover {
        @apply brightness-110;
    }
    /* Day-closing strip on the hero. */
    .bl-close {
        @apply mt-6 flex flex-wrap items-center gap-3 rounded-xl border border-white/10 bg-white/[0.06] px-4 py-3 backdrop-blur-md;
    }
    .bl-close.is-alert {
        @apply border-rose-400/40;
        background-image: linear-gradient(
            100deg,
            color-mix(in oklab, var(--bl-rose) 24%, transparent),
            transparent 70%
        );
    }

    /* --- Revenue pipeline --------------------------------------------------- */
    .bl-pipe {
        @apply flex min-w-max items-stretch;
    }
    .bl-stage {
        @apply relative flex min-w-44 flex-1 flex-col gap-2 px-3 pt-1 text-center;
    }
    .bl-stage:not(:last-child)::after {
        content: "";
        @apply absolute left-1/2 right-[-50%] top-[1.35rem] h-0.5 bg-border-color dark:bg-white/10;
    }
    .bl-stage.is-done:not(:last-child)::after {
        background-image: linear-gradient(
            90deg,
            var(--bl-gold),
            var(--bl-emerald)
        );
    }
    .bl-stage-node {
        @apply relative z-10 mx-auto grid size-9 place-items-center rounded-full border-2 border-border-color bg-white text-sm text-gray-400 transition-all duration-300 dark:border-white/15 dark:bg-slate-800;
    }
    .bl-stage.is-done .bl-stage-node {
        @apply border-transparent text-white;
        background-image: linear-gradient(
            135deg,
            var(--bl-amber),
            var(--bl-gold)
        );
    }
    .bl-stage.is-now .bl-stage-node {
        @apply border-transparent text-white;
        background-image: linear-gradient(
            135deg,
            var(--bl-gold),
            var(--bl-emerald)
        );
        box-shadow: 0 0 0 5px
            color-mix(in oklab, var(--bl-gold) 22%, transparent);
        animation: tc-ping 2s ease-in-out infinite;
    }
    .bl-stage-plate {
        @apply mx-auto w-full max-w-40 rounded-xl border border-border-color p-2 dark:border-white/10;
    }
    .bl-stage.is-now .bl-stage-plate {
        border-color: color-mix(in oklab, var(--bl-gold) 50%, transparent);
        background-color: color-mix(in oklab, var(--bl-gold) 7%, transparent);
    }
    .bl-stage-bar {
        @apply mt-1.5 h-1 w-full overflow-hidden rounded-full bg-gray-100 dark:bg-slate-700;
    }
    .bl-stage-bar span {
        @apply block h-full rounded-full transition-all duration-700;
        background-image: linear-gradient(
            90deg,
            var(--bl-amber),
            var(--bl-gold)
        );
    }

    /* --- Panels ---------------------------------------------------------------- */
    .bl-panel {
        --bl-accent: var(--bl-gold);
        @apply relative flex flex-col overflow-hidden rounded-xl border border-border-color bg-white transition-all duration-300;
        @apply dark:border-white/10 dark:bg-slate-800/70 dark:backdrop-blur-xl;
    }
    .bl-panel:hover {
        @apply -translate-y-1;
        border-color: color-mix(in oklab, var(--bl-accent) 40%, transparent);
        box-shadow: 0 24px 48px -26px
            color-mix(in oklab, var(--bl-accent) 70%, transparent);
    }
    .bl-panel-head {
        @apply flex items-center gap-2.5 p-4 pb-0;
    }
    .bl-panel-icon {
        @apply grid size-9 shrink-0 place-items-center rounded-xl text-sm;
        color: var(--bl-accent);
        background-image: linear-gradient(
            145deg,
            color-mix(in oklab, var(--bl-accent) 18%, transparent),
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(in oklab, var(--bl-accent) 26%, transparent);
    }
    .bl-panel-title {
        @apply text-sm font-bold text-gray-900;
    }
    .bl-panel-body {
        @apply flex-1 p-4;
    }
    .bl-gold {
        --bl-accent: var(--bl-gold);
    }
    .bl-amber {
        --bl-accent: var(--bl-amber);
    }
    .bl-emerald {
        --bl-accent: var(--bl-emerald);
    }
    .bl-sky {
        --bl-accent: var(--bl-sky);
    }
    .bl-violet {
        --bl-accent: var(--bl-violet);
    }
    .bl-rose {
        --bl-accent: var(--bl-rose);
    }
    .bl-indigo {
        --bl-accent: var(--bl-indigo);
    }
    .bl-chip {
        @apply inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-bold whitespace-nowrap;
        color: var(--bl-accent, var(--bl-gold));
        background-color: color-mix(
            in oklab,
            var(--bl-accent, var(--bl-gold)) 13%,
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(
                in oklab,
                var(--bl-accent, var(--bl-gold)) 24%,
                transparent
            );
    }

    /* --- Billing kanban ----------------------------------------------------------- */
    .bl-lane {
        @apply flex min-w-60 flex-1 flex-col rounded-xl border border-border-color bg-gray-50/70 p-2.5 dark:border-white/10 dark:bg-white/[0.03];
        border-top-width: 3px;
        border-top-color: var(--bl-accent, var(--bl-gold));
    }
    .bl-inv {
        @apply relative overflow-hidden rounded-xl border border-border-color bg-white p-2.5 transition-all duration-200 dark:border-white/10 dark:bg-slate-800;
    }
    .bl-inv:hover {
        @apply -translate-y-0.5 shadow-md;
    }
    .bl-inv + .bl-inv {
        @apply mt-2;
    }
    .bl-inv.is-overdue {
        animation: skeleton-pulse 2s ease-in-out infinite;
        border-color: color-mix(in oklab, var(--bl-rose) 55%, transparent);
    }
    /* Invoice number plate — a receipt corner with serrated edge. */
    .bl-inv-no {
        @apply relative inline-flex items-center rounded-md px-1.5 py-0.5 pr-2 text-[10px] font-extrabold tabular-nums text-white;
        background-image: linear-gradient(
            135deg,
            var(--bl-accent, var(--bl-gold)),
            color-mix(in oklab, var(--bl-accent, var(--bl-gold)) 55%, #171310)
        );
        mask-image:
            radial-gradient(
                circle 2px at right 1px top 3px,
                transparent 2px,
                #000 2.5px
            ),
            radial-gradient(
                circle 2px at right 1px top 11px,
                transparent 2px,
                #000 2.5px
            );
        mask-composite: intersect;
    }
    .bl-inv-btn {
        @apply grid size-6.5 place-items-center rounded-xl text-[11px] text-gray-400 transition-all duration-200;
    }
    .bl-inv-btn:hover {
        color: var(--bl-accent, var(--bl-gold));
        background-color: color-mix(
            in oklab,
            var(--bl-accent, var(--bl-gold)) 12%,
            transparent
        );
    }

    /* --- Revenue analytics tiles ----------------------------------------------------- */
    .bl-rev {
        @apply relative overflow-hidden rounded-xl border border-border-color p-3.5 transition-all duration-200 dark:border-white/10;
        background-image: linear-gradient(
            150deg,
            color-mix(
                in oklab,
                var(--bl-accent, var(--bl-gold)) 7%,
                transparent
            ),
            transparent 55%
        );
    }
    .bl-rev:hover {
        @apply -translate-y-0.5;
        border-color: color-mix(
            in oklab,
            var(--bl-accent, var(--bl-gold)) 45%,
            transparent
        );
    }
    .bl-spark {
        stroke: var(--bl-accent, var(--bl-gold));
        fill: none;
        stroke-width: 2;
        stroke-linecap: round;
        stroke-linejoin: round;
    }
    .bl-spark-fill {
        fill: color-mix(
            in oklab,
            var(--bl-accent, var(--bl-gold)) 14%,
            transparent
        );
        stroke: none;
    }

    /* --- Payment mix bars --------------------------------------------------------------- */
    .bl-pay {
        @apply flex items-center gap-3 rounded-xl border border-border-color p-3 transition-all duration-200 dark:border-white/10;
    }
    .bl-pay:hover {
        @apply -translate-y-0.5;
        border-color: color-mix(
            in oklab,
            var(--bl-accent, var(--bl-sky)) 45%,
            transparent
        );
    }
    .bl-pay-icon {
        @apply grid size-9 shrink-0 place-items-center rounded-xl text-sm;
        color: var(--bl-accent, var(--bl-sky));
        background-color: color-mix(
            in oklab,
            var(--bl-accent, var(--bl-sky)) 13%,
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(
                in oklab,
                var(--bl-accent, var(--bl-sky)) 26%,
                transparent
            );
    }
    .bl-pay-track {
        @apply mt-1.5 h-1.5 w-full overflow-hidden rounded-full bg-gray-100 dark:bg-slate-700;
    }
    .bl-pay-fill {
        @apply block h-full rounded-full transition-all duration-700;
        background-image: linear-gradient(
            90deg,
            var(--bl-accent, var(--bl-sky)),
            color-mix(in oklab, var(--bl-accent, var(--bl-sky)) 55%, #fff)
        );
    }

    /* --- Claims desk ------------------------------------------------------------------------ */
    .bl-claim {
        @apply relative overflow-hidden rounded-xl border border-border-color p-3 transition-all duration-200 dark:border-white/10;
        border-left-width: 3px;
        border-left-color: var(--bl-accent, var(--bl-sky));
    }
    .bl-claim:hover {
        @apply -translate-y-0.5 bg-gray-50 dark:bg-white/5;
    }
    .bl-claim.is-expiring {
        animation: skeleton-pulse 1.8s ease-in-out infinite;
    }

    /* --- Collections ledger -------------------------------------------------------------------- */
    .bl-col {
        @apply relative flex items-center gap-3 overflow-hidden rounded-xl border border-border-color p-3 transition-all duration-200 dark:border-white/10;
    }
    .bl-col:hover {
        @apply -translate-y-0.5;
        border-color: color-mix(
            in oklab,
            var(--bl-accent, var(--bl-rose)) 45%,
            transparent
        );
    }
    .bl-col-avatar {
        @apply grid size-10 shrink-0 place-items-center rounded-xl text-[11px] font-extrabold text-white;
        background-image: linear-gradient(
            135deg,
            var(--bl-accent, var(--bl-rose)),
            color-mix(in oklab, var(--bl-accent, var(--bl-rose)) 55%, #171310)
        );
    }
    .bl-col-days {
        @apply grid size-9 shrink-0 place-items-center rounded-xl text-center;
        background-color: color-mix(
            in oklab,
            var(--bl-accent, var(--bl-rose)) 11%,
            transparent
        );
    }

    /* --- Department revenue meters ---------------------------------------------------------------- */
    .bl-dept {
        @apply relative overflow-hidden rounded-xl border border-border-color p-3 transition-all duration-200 dark:border-white/10;
        border-left-width: 3px;
        border-left-color: var(--bl-accent, var(--bl-gold));
    }
    .bl-dept:hover {
        @apply -translate-y-0.5 bg-gray-50 dark:bg-white/5;
        box-shadow: 0 14px 30px -20px
            color-mix(
                in oklab,
                var(--bl-accent, var(--bl-gold)) 80%,
                transparent
            );
    }
    .bl-dept-track {
        @apply mt-2 h-1 w-full overflow-hidden rounded-full bg-gray-100 dark:bg-slate-700;
    }
    .bl-dept-fill {
        @apply block h-full rounded-full transition-all duration-700;
        background-color: var(--bl-accent, var(--bl-gold));
    }

    /* --- Refund workflow rail ----------------------------------------------------------------------- */
    .bl-ref {
        @apply relative flex gap-3 pb-4 last:pb-0;
    }
    .bl-ref:not(:last-child)::before {
        content: "";
        @apply absolute left-[9px] top-6 bottom-0 w-px bg-border-color dark:bg-white/10;
    }
    .bl-ref-dot {
        @apply relative z-10 mt-1.5 grid size-[19px] shrink-0 place-items-center rounded-full border-2 border-white text-[9px] text-white dark:border-slate-800;
        background-color: var(--bl-accent, var(--bl-gold));
    }
    .bl-ref-card {
        @apply min-w-0 flex-1 rounded-xl border border-border-color p-2.5 transition-colors duration-200 dark:border-white/10;
    }
    .bl-ref:hover .bl-ref-card {
        border-color: color-mix(
            in oklab,
            var(--bl-accent, var(--bl-gold)) 45%,
            transparent
        );
        background-color: color-mix(
            in oklab,
            var(--bl-accent, var(--bl-gold)) 5%,
            transparent
        );
    }

    /* --- Performance dials ---------------------------------------------------------------------------- */
    .bl-dial {
        @apply relative grid place-items-center;
    }
    .bl-dial svg {
        @apply size-16 -rotate-90;
    }
    .bl-dial-track {
        @apply text-gray-200 dark:text-slate-700;
    }
    .bl-dial-fill {
        stroke: var(--bl-accent, var(--bl-gold));
        transition: stroke-dashoffset 0.8s ease;
    }
    .bl-dial-label {
        @apply absolute inset-0 grid place-items-center text-xs font-extrabold tabular-nums text-gray-900;
    }

    /* --- Transaction feed -------------------------------------------------------------------------------- */
    .bl-tl {
        @apply relative flex gap-3 pb-4 last:pb-0;
    }
    .bl-tl:not(:last-child)::before {
        content: "";
        @apply absolute left-[13px] top-8 bottom-0 w-px bg-border-color dark:bg-white/10;
    }
    .bl-tl-icon {
        @apply relative z-10 grid size-7 shrink-0 place-items-center rounded-full text-[11px];
        color: var(--bl-accent, var(--bl-gold));
        background-color: color-mix(
            in oklab,
            var(--bl-accent, var(--bl-gold)) 14%,
            transparent
        );
        box-shadow:
            inset 0 0 0 1px
                color-mix(
                    in oklab,
                    var(--bl-accent, var(--bl-gold)) 28%,
                    transparent
                ),
            0 0 0 3px var(--color-white);
    }

    /* --- Floating action dock ------------------------------------------------------------------------------ */
    .bl-dock {
        @apply fixed bottom-6 right-6 z-40 flex flex-col items-end gap-2.5;
    }
    .bl-dock-menu {
        @apply flex flex-col items-end gap-2 transition-all duration-300;
    }
    .bl-dock-menu.is-closed {
        @apply pointer-events-none translate-y-3 opacity-0;
    }
    .bl-dock-item {
        @apply flex items-center gap-2.5 rounded-full border border-border-color bg-white py-2 pl-4 pr-2 text-xs font-bold text-gray-700 shadow-lg transition-all duration-200 dark:border-white/10 dark:bg-slate-800 dark:text-gray-200;
    }
    .bl-dock-item:hover {
        @apply -translate-x-1;
        border-color: color-mix(
            in oklab,
            var(--bl-accent, var(--bl-gold)) 45%,
            transparent
        );
    }
    .bl-dock-item i {
        @apply grid size-8 place-items-center rounded-full text-[13px] text-white;
        background-image: linear-gradient(
            135deg,
            var(--bl-accent, var(--bl-gold)),
            color-mix(in oklab, var(--bl-accent, var(--bl-gold)) 60%, #171310)
        );
    }
    .bl-dock-fab {
        @apply grid size-14 place-items-center rounded-xl text-xl text-yellow-950 transition-all duration-300;
        background-image: linear-gradient(135deg, #fde047, var(--bl-gold));
        box-shadow: 0 18px 36px -12px var(--bl-gold);
    }
    .bl-dock-fab:hover {
        @apply -translate-y-1 brightness-110;
    }
    .bl-dock-fab.is-open {
        @apply rotate-45;
    }

    /* The revenue desk runs all day — honour reduced-motion. */
    @media (prefers-reduced-motion: reduce) {
        .bl-panel,
        .bl-action,
        .bl-inv,
        .bl-rev,
        .bl-pay,
        .bl-claim,
        .bl-col,
        .bl-dept,
        .bl-dock-item,
        .bl-dock-fab,
        .bl-dock-menu {
            @apply transition-none;
        }
        .bl-panel:hover,
        .bl-action:hover,
        .bl-inv:hover,
        .bl-rev:hover,
        .bl-pay:hover,
        .bl-claim:hover,
        .bl-col:hover,
        .bl-dept:hover,
        .bl-dock-fab:hover {
            @apply translate-y-0;
        }
        .bl-open-dot,
        .bl-stage.is-now .bl-stage-node,
        .bl-inv.is-overdue,
        .bl-claim.is-expiring {
            animation: none;
        }
    }

    /* =====================================================================
       EXECUTIVE COMMAND CENTER — EXCLUSIVE to executive-dashboard.html.
       The boardroom view of the whole hospital: midnight-plum pinstripe
       hero, digital-twin department wall, operations pipeline, decision
       intelligence, capacity radials, finance flow, workforce, projects,
       compliance and the executive calendar. Distinct from all modules.
       ===================================================================== */
    .ex-scope {
        --ex-fuchsia: #d946ef;
        --ex-violet: #8b5cf6;
        --ex-indigo: #6366f1;
        --ex-sky: #0ea5e9;
        --ex-emerald: #10b981;
        --ex-amber: #f59e0b;
        --ex-rose: #f43f5e;
        --ex-gold: #eab308;
        --ex-slate: #64748b;
    }

    /* --- Hero: the boardroom -------------------------------------------- */
    .ex-hero {
        @apply relative isolate overflow-hidden rounded-xl p-6 lg:p-8;
        background-image: linear-gradient(
            117deg,
            #14101f 0%,
            #3b1d5e 50%,
            #701a4b 100%
        );
    }
    .ex-hero::before {
        content: "";
        @apply pointer-events-none absolute -right-24 -top-28 -z-10 size-[28rem] rounded-full blur-3xl opacity-35;
        background-image: radial-gradient(
            circle,
            var(--ex-fuchsia) 0%,
            transparent 65%
        );
    }
    .ex-hero::after {
        content: "";
        @apply pointer-events-none absolute -bottom-32 -left-16 -z-10 size-[24rem] rounded-full blur-3xl opacity-25;
        background-image: radial-gradient(
            circle,
            var(--ex-indigo) 0%,
            transparent 65%
        );
    }
    /* Pinstripe texture — fine diagonals, boardroom tailoring. */
    .ex-hero-stripes {
        @apply pointer-events-none absolute inset-0 -z-10 opacity-[0.07];
        background-image: repeating-linear-gradient(
            125deg,
            transparent 0 14px,
            rgba(255, 255, 255, 0.9) 14px 15px
        );
        mask-image: radial-gradient(
            ellipse at 80% 0%,
            #000 20%,
            transparent 72%
        );
    }
    .ex-hero-title {
        @apply text-2xl lg:text-[2rem] font-extrabold leading-tight tracking-tight text-white;
    }
    .ex-hero-sub {
        @apply mt-1.5 flex flex-wrap items-center gap-x-2 gap-y-1 text-xs font-medium text-white/60;
    }
    .ex-net {
        @apply inline-flex items-center gap-1.5 rounded-full border border-fuchsia-300/30 bg-fuchsia-400/15 px-2.5 py-1 text-[10px] font-extrabold uppercase tracking-wider text-fuchsia-200;
    }
    .ex-net-dot {
        @apply size-1.5 rounded-full bg-fuchsia-300;
        animation: tc-ping 1.6s ease-in-out infinite;
    }
    .ex-fact {
        @apply rounded-xl border border-white/10 bg-white/[0.07] px-3.5 py-2.5 backdrop-blur-md;
    }
    .ex-fact dt {
        @apply text-[9px] font-extrabold uppercase tracking-[0.14em] text-white/45;
    }
    .ex-fact dd {
        @apply mt-0.5 text-sm font-extrabold text-white tabular-nums;
    }
    /* Operational-health gauge in the hero. */
    .ex-health {
        @apply relative grid place-items-center;
    }
    .ex-health-ring {
        @apply size-[7.5rem] -rotate-90;
    }
    .ex-health-track {
        stroke: rgba(255, 255, 255, 0.12);
    }
    .ex-health-fill {
        stroke: url(#ex-health-grad);
        transition: stroke-dashoffset 0.8s ease;
    }
    .ex-health-label {
        @apply absolute inset-0 grid place-items-center text-center;
    }
    .ex-action {
        @apply inline-flex items-center gap-2 rounded-xl border border-white/15 bg-white/10 px-3.5 py-2.5 text-xs font-bold text-white backdrop-blur-md transition-all duration-300;
    }
    .ex-action:hover {
        @apply -translate-y-0.5 border-white/30 bg-white/20;
    }
    .ex-action:focus-visible {
        @apply outline-2 outline-offset-2 outline-white/70;
    }
    .ex-action.is-primary {
        @apply border-transparent;
        background-image: linear-gradient(
            120deg,
            var(--ex-violet),
            var(--ex-fuchsia)
        );
        box-shadow: 0 12px 28px -10px var(--ex-fuchsia);
    }
    .ex-action.is-primary:hover {
        @apply brightness-110;
    }
    /* Emergency network strip on the hero. */
    .ex-alert {
        @apply mt-6 flex flex-wrap items-center gap-3 rounded-xl border border-white/10 bg-white/[0.06] px-4 py-3 backdrop-blur-md;
    }
    .ex-alert.is-alert {
        @apply border-rose-400/40;
        background-image: linear-gradient(
            100deg,
            color-mix(in oklab, var(--ex-rose) 26%, transparent),
            transparent 70%
        );
    }

    /* --- Panels ------------------------------------------------------------ */
    .ex-panel {
        --ex-accent: var(--ex-violet);
        @apply relative flex flex-col overflow-hidden rounded-xl border border-border-color bg-white transition-all duration-300;
        @apply dark:border-white/10 dark:bg-slate-800/70 dark:backdrop-blur-xl;
    }
    .ex-panel:hover {
        @apply -translate-y-1;
        border-color: color-mix(in oklab, var(--ex-accent) 40%, transparent);
        box-shadow: 0 24px 48px -26px
            color-mix(in oklab, var(--ex-accent) 70%, transparent);
    }
    .ex-panel-head {
        @apply flex items-center gap-2.5 p-4 pb-0;
    }
    .ex-panel-icon {
        @apply grid size-9 shrink-0 place-items-center rounded-xl text-sm;
        color: var(--ex-accent);
        background-image: linear-gradient(
            145deg,
            color-mix(in oklab, var(--ex-accent) 18%, transparent),
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(in oklab, var(--ex-accent) 26%, transparent);
    }
    .ex-panel-title {
        @apply text-sm font-bold text-gray-900;
    }
    .ex-panel-body {
        @apply flex-1 p-4;
    }
    .ex-fuchsia {
        --ex-accent: var(--ex-fuchsia);
    }
    .ex-violet {
        --ex-accent: var(--ex-violet);
    }
    .ex-indigo {
        --ex-accent: var(--ex-indigo);
    }
    .ex-sky {
        --ex-accent: var(--ex-sky);
    }
    .ex-emerald {
        --ex-accent: var(--ex-emerald);
    }
    .ex-amber {
        --ex-accent: var(--ex-amber);
    }
    .ex-rose {
        --ex-accent: var(--ex-rose);
    }
    .ex-gold {
        --ex-accent: var(--ex-gold);
    }
    .ex-chip {
        @apply inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[10px] font-bold whitespace-nowrap;
        color: var(--ex-accent, var(--ex-violet));
        background-color: color-mix(
            in oklab,
            var(--ex-accent, var(--ex-violet)) 13%,
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(
                in oklab,
                var(--ex-accent, var(--ex-violet)) 24%,
                transparent
            );
    }

    /* --- Digital twin department wall ---------------------------------------- */
    .ex-dept {
        @apply relative overflow-hidden rounded-xl border border-border-color p-3 transition-all duration-200 dark:border-white/10;
        border-top-width: 3px;
        border-top-color: var(--ex-dept-c, var(--ex-emerald));
    }
    .ex-dept:hover {
        @apply -translate-y-0.5;
        border-color: color-mix(
            in oklab,
            var(--ex-dept-c, var(--ex-emerald)) 45%,
            transparent
        );
        border-top-color: var(--ex-dept-c, var(--ex-emerald));
        box-shadow: 0 14px 30px -20px
            color-mix(
                in oklab,
                var(--ex-dept-c, var(--ex-emerald)) 80%,
                transparent
            );
    }
    .ex-dept.is-optimal {
        --ex-dept-c: var(--ex-emerald);
    }
    .ex-dept.is-busy {
        --ex-dept-c: var(--ex-amber);
    }
    .ex-dept.is-critical {
        --ex-dept-c: var(--ex-rose);
    }
    .ex-dept.is-critical {
        animation: skeleton-pulse 2s ease-in-out infinite;
    }
    .ex-dept-status {
        @apply inline-flex items-center gap-1 rounded-full px-1.5 py-0.5 text-[9px] font-extrabold uppercase tracking-wide;
        color: var(--ex-dept-c, var(--ex-emerald));
        background-color: color-mix(
            in oklab,
            var(--ex-dept-c, var(--ex-emerald)) 13%,
            transparent
        );
    }
    .ex-dept-status::before {
        content: "";
        @apply size-1 rounded-full bg-current;
    }
    .ex-dept-track {
        @apply mt-1.5 h-1 w-full overflow-hidden rounded-full bg-gray-100 dark:bg-slate-700;
    }
    .ex-dept-fill {
        @apply block h-full rounded-full transition-all duration-700;
        background-color: var(--ex-dept-c, var(--ex-emerald));
    }

    /* --- Operations pipeline --------------------------------------------------- */
    .ex-pipe {
        @apply flex min-w-max items-stretch;
    }
    .ex-stage {
        @apply relative flex min-w-36 flex-1 flex-col gap-2 px-2.5 pt-1 text-center;
    }
    .ex-stage:not(:last-child)::after {
        content: "";
        @apply absolute left-1/2 right-[-50%] top-[1.35rem] h-0.5 bg-border-color dark:bg-white/10;
    }
    .ex-stage.is-done:not(:last-child)::after {
        background-image: linear-gradient(
            90deg,
            var(--ex-violet),
            var(--ex-fuchsia)
        );
    }
    .ex-stage-node {
        @apply relative z-10 mx-auto grid size-9 place-items-center rounded-full border-2 border-border-color bg-white text-sm text-gray-400 transition-all duration-300 dark:border-white/15 dark:bg-slate-800;
    }
    .ex-stage.is-done .ex-stage-node {
        @apply border-transparent text-white;
        background-image: linear-gradient(
            135deg,
            var(--ex-indigo),
            var(--ex-violet)
        );
    }
    .ex-stage.is-now .ex-stage-node {
        @apply border-transparent text-white;
        background-image: linear-gradient(
            135deg,
            var(--ex-violet),
            var(--ex-fuchsia)
        );
        box-shadow: 0 0 0 5px
            color-mix(in oklab, var(--ex-fuchsia) 20%, transparent);
        animation: tc-ping 2s ease-in-out infinite;
    }
    .ex-stage-plate {
        @apply mx-auto w-full rounded-xl border border-border-color p-2 dark:border-white/10;
    }
    .ex-stage.is-now .ex-stage-plate {
        border-color: color-mix(in oklab, var(--ex-fuchsia) 45%, transparent);
        background-color: color-mix(
            in oklab,
            var(--ex-fuchsia) 6%,
            transparent
        );
    }
    .ex-stage-bar {
        @apply mt-1.5 h-1 w-full overflow-hidden rounded-full bg-gray-100 dark:bg-slate-700;
    }
    .ex-stage-bar span {
        @apply block h-full rounded-full transition-all duration-700;
        background-image: linear-gradient(
            90deg,
            var(--ex-indigo),
            var(--ex-fuchsia)
        );
    }

    /* --- Decision intelligence cards --------------------------------------------- */
    .ex-brief {
        @apply relative overflow-hidden rounded-xl p-3.5;
        background-image: linear-gradient(
            130deg,
            color-mix(
                in oklab,
                var(--ex-accent, var(--ex-violet)) 10%,
                transparent
            ),
            color-mix(
                in oklab,
                var(--ex-accent, var(--ex-violet)) 3%,
                transparent
            )
        );
        box-shadow: inset 0 0 0 1px
            color-mix(
                in oklab,
                var(--ex-accent, var(--ex-violet)) 24%,
                transparent
            );
    }
    .ex-brief-tag {
        @apply inline-flex items-center gap-1 rounded-full px-2 py-0.5 text-[9px] font-extrabold uppercase tracking-wider text-white;
        background-image: linear-gradient(
            120deg,
            var(--ex-accent, var(--ex-violet)),
            color-mix(in oklab, var(--ex-accent, var(--ex-violet)) 60%, #14101f)
        );
    }

    /* --- Capacity radials + occupancy strips ---------------------------------------- */
    .ex-cap {
        @apply flex items-center gap-3 rounded-xl border border-border-color p-3 transition-all duration-200 dark:border-white/10;
    }
    .ex-cap:hover {
        @apply -translate-y-0.5;
        border-color: color-mix(
            in oklab,
            var(--ex-accent, var(--ex-sky)) 45%,
            transparent
        );
    }
    .ex-ring {
        @apply relative grid shrink-0 place-items-center;
    }
    .ex-ring svg {
        @apply size-12 -rotate-90;
    }
    .ex-ring-track {
        @apply text-gray-200 dark:text-slate-700;
    }
    .ex-ring-fill {
        stroke: var(--ex-accent, var(--ex-sky));
        transition: stroke-dashoffset 0.8s ease;
    }
    .ex-ring-label {
        @apply absolute inset-0 grid place-items-center text-[10px] font-extrabold tabular-nums;
        color: var(--ex-accent, var(--ex-sky));
    }

    /* --- Finance flow rows ------------------------------------------------------------ */
    .ex-fin {
        @apply relative overflow-hidden rounded-xl border border-border-color p-3.5 transition-all duration-200 dark:border-white/10;
        background-image: linear-gradient(
            140deg,
            color-mix(
                in oklab,
                var(--ex-accent, var(--ex-gold)) 7%,
                transparent
            ),
            transparent 60%
        );
    }
    .ex-fin:hover {
        @apply -translate-y-0.5;
        border-color: color-mix(
            in oklab,
            var(--ex-accent, var(--ex-gold)) 45%,
            transparent
        );
    }
    .ex-flow-track {
        @apply mt-2 flex h-2.5 w-full overflow-hidden rounded-full bg-gray-100 dark:bg-slate-700;
    }
    .ex-flow-seg {
        @apply h-full transition-all duration-700;
    }

    /* --- Clinical quality rows ----------------------------------------------------------- */
    .ex-clin {
        @apply relative flex items-center gap-3 rounded-xl border border-border-color p-3 transition-all duration-200 dark:border-white/10;
        border-left-width: 3px;
        border-left-color: var(--ex-accent, var(--ex-sky));
    }
    .ex-clin:hover {
        @apply -translate-y-0.5 bg-gray-50 dark:bg-white/5;
    }

    /* --- Workforce meters -------------------------------------------------------------------- */
    .ex-staff {
        @apply rounded-xl border border-border-color p-3 dark:border-white/10;
    }
    .ex-staff-track {
        @apply mt-1.5 h-1.5 w-full overflow-hidden rounded-full bg-gray-100 dark:bg-slate-700;
    }
    .ex-staff-fill {
        @apply block h-full rounded-full transition-all duration-700;
        background-image: linear-gradient(
            90deg,
            var(--ex-accent, var(--ex-indigo)),
            color-mix(in oklab, var(--ex-accent, var(--ex-indigo)) 55%, #fff)
        );
    }

    /* --- Intelligence feed --------------------------------------------------------------------- */
    .ex-intel {
        @apply relative flex items-start gap-3 overflow-hidden rounded-xl border p-3 transition-colors duration-200;
        border-color: color-mix(
            in oklab,
            var(--ex-accent, var(--ex-violet)) 30%,
            transparent
        );
        background-image: linear-gradient(
            120deg,
            color-mix(
                in oklab,
                var(--ex-accent, var(--ex-violet)) 8%,
                transparent
            ),
            transparent 65%
        );
    }
    .ex-intel.is-urgent {
        border-color: color-mix(in oklab, var(--ex-rose) 55%, transparent);
        animation: skeleton-pulse 1.8s ease-in-out infinite;
    }

    /* --- Strategic project tracker ---------------------------------------------------------------- */
    .ex-proj {
        @apply relative flex gap-3 pb-4 last:pb-0;
    }
    .ex-proj:not(:last-child)::before {
        content: "";
        @apply absolute left-[9px] top-6 bottom-0 w-px bg-border-color dark:bg-white/10;
    }
    .ex-proj-dot {
        @apply relative z-10 mt-1.5 grid size-[19px] shrink-0 place-items-center rounded-full border-2 border-white text-[9px] text-white dark:border-slate-800;
        background-color: var(--ex-accent, var(--ex-violet));
    }
    .ex-proj-card {
        @apply min-w-0 flex-1 rounded-xl border border-border-color p-2.5 transition-colors duration-200 dark:border-white/10;
    }
    .ex-proj:hover .ex-proj-card {
        border-color: color-mix(
            in oklab,
            var(--ex-accent, var(--ex-violet)) 45%,
            transparent
        );
        background-color: color-mix(
            in oklab,
            var(--ex-accent, var(--ex-violet)) 5%,
            transparent
        );
    }
    .ex-proj-track {
        @apply mt-2 h-1.5 w-full overflow-hidden rounded-full bg-gray-100 dark:bg-slate-700;
    }
    .ex-proj-fill {
        @apply block h-full rounded-full transition-all duration-700;
        background-image: linear-gradient(
            90deg,
            var(--ex-accent, var(--ex-violet)),
            color-mix(in oklab, var(--ex-accent, var(--ex-violet)) 55%, #fff)
        );
    }

    /* --- Compliance & risk console ------------------------------------------------------------------ */
    .ex-risk {
        @apply relative overflow-hidden rounded-xl p-3.5;
        background-image: linear-gradient(
            130deg,
            color-mix(
                in oklab,
                var(--ex-accent, var(--ex-emerald)) 10%,
                transparent
            ),
            color-mix(
                in oklab,
                var(--ex-accent, var(--ex-emerald)) 3%,
                transparent
            )
        );
        box-shadow: inset 0 0 0 1px
            color-mix(
                in oklab,
                var(--ex-accent, var(--ex-emerald)) 24%,
                transparent
            );
    }
    .ex-risk-row {
        @apply flex items-center justify-between gap-2 border-b border-dashed py-2 text-[11px] font-semibold text-gray-600 first:pt-0 last:border-0 last:pb-0 dark:text-gray-300;
        border-color: color-mix(
            in oklab,
            var(--ex-accent, var(--ex-emerald)) 20%,
            transparent
        );
    }

    /* --- Executive calendar --------------------------------------------------------------------------- */
    .ex-cal {
        @apply relative flex items-center gap-3 overflow-hidden rounded-xl border border-border-color p-3 transition-all duration-200 dark:border-white/10;
    }
    .ex-cal:hover {
        @apply -translate-y-0.5;
        border-color: color-mix(
            in oklab,
            var(--ex-accent, var(--ex-indigo)) 45%,
            transparent
        );
    }
    .ex-cal-date {
        @apply grid size-11 shrink-0 place-items-center rounded-xl text-center;
        background-color: color-mix(
            in oklab,
            var(--ex-accent, var(--ex-indigo)) 12%,
            transparent
        );
    }

    /* --- Executive activity timeline -------------------------------------------------------------------- */
    .ex-tl {
        @apply relative flex gap-3 pb-4 last:pb-0;
    }
    .ex-tl:not(:last-child)::before {
        content: "";
        @apply absolute left-[13px] top-8 bottom-0 w-px bg-border-color dark:bg-white/10;
    }
    .ex-tl-icon {
        @apply relative z-10 grid size-7 shrink-0 place-items-center rounded-full text-[11px];
        color: var(--ex-accent, var(--ex-violet));
        background-color: color-mix(
            in oklab,
            var(--ex-accent, var(--ex-violet)) 14%,
            transparent
        );
        box-shadow:
            inset 0 0 0 1px
                color-mix(
                    in oklab,
                    var(--ex-accent, var(--ex-violet)) 28%,
                    transparent
                ),
            0 0 0 3px var(--color-white);
    }

    /* --- Floating action dock ----------------------------------------------------------------------------- */
    .ex-dock {
        @apply fixed bottom-6 right-6 z-40 flex flex-col items-end gap-2.5;
    }
    .ex-dock-menu {
        @apply flex flex-col items-end gap-2 transition-all duration-300;
    }
    .ex-dock-menu.is-closed {
        @apply pointer-events-none translate-y-3 opacity-0;
    }
    .ex-dock-item {
        @apply flex items-center gap-2.5 rounded-full border border-border-color bg-white py-2 pl-4 pr-2 text-xs font-bold text-gray-700 shadow-lg transition-all duration-200 dark:border-white/10 dark:bg-slate-800 dark:text-gray-200;
    }
    .ex-dock-item:hover {
        @apply -translate-x-1;
        border-color: color-mix(
            in oklab,
            var(--ex-accent, var(--ex-violet)) 45%,
            transparent
        );
    }
    .ex-dock-item i {
        @apply grid size-8 place-items-center rounded-full text-[13px] text-white;
        background-image: linear-gradient(
            135deg,
            var(--ex-accent, var(--ex-violet)),
            color-mix(in oklab, var(--ex-accent, var(--ex-violet)) 60%, #14101f)
        );
    }
    .ex-dock-fab {
        @apply grid size-14 place-items-center rounded-xl text-xl text-white transition-all duration-300;
        background-image: linear-gradient(
            135deg,
            var(--ex-violet),
            var(--ex-fuchsia)
        );
        box-shadow: 0 18px 36px -12px var(--ex-fuchsia);
    }
    .ex-dock-fab:hover {
        @apply -translate-y-1 brightness-110;
    }
    .ex-dock-fab.is-open {
        @apply rotate-45;
    }

    /* The command center runs 24/7 — honour reduced-motion. */
    @media (prefers-reduced-motion: reduce) {
        .ex-panel,
        .ex-action,
        .ex-dept,
        .ex-cap,
        .ex-fin,
        .ex-clin,
        .ex-cal,
        .ex-dock-item,
        .ex-dock-fab,
        .ex-dock-menu {
            @apply transition-none;
        }
        .ex-panel:hover,
        .ex-action:hover,
        .ex-dept:hover,
        .ex-cap:hover,
        .ex-fin:hover,
        .ex-clin:hover,
        .ex-cal:hover,
        .ex-dock-fab:hover {
            @apply translate-y-0;
        }
        .ex-net-dot,
        .ex-stage.is-now .ex-stage-node,
        .ex-dept.is-critical,
        .ex-intel.is-urgent {
            animation: none;
        }
    }

    /* =====================================================================
       ENTERPRISE COMMAND BAR — the redesigned header (partials/topbar.html).
       Floating glassmorphism command bar with a workspace switcher, AI
       command palette, live hospital status pills, a quick-action dock,
       a tabbed notification center, appearance switcher and an activity
       drawer. Namespaced hc- so it never collides with page modules.
       ===================================================================== */
    .hc-bar {
        @apply relative flex h-16 shrink-0 items-center gap-3 px-4 lg:px-6 z-30;
        background-color: color-mix(
            in oklab,
            var(--color-white) 82%,
            transparent
        );
        border-bottom: 1px solid var(--color-border-color);
        backdrop-filter: blur(18px) saturate(1.4);
        -webkit-backdrop-filter: blur(18px) saturate(1.4);
        transition:
            box-shadow 0.3s ease,
            background-color 0.3s ease;
    }
    .hc-bar.hc-scrolled {
        background-color: color-mix(
            in oklab,
            var(--color-white) 92%,
            transparent
        );
        box-shadow: 0 10px 30px -18px rgba(2, 12, 40, 0.35);
    }
    /* Aurora hairline along the top edge — the enterprise sheen. */
    .hc-bar::before {
        content: "";
        @apply pointer-events-none absolute inset-x-0 top-0 h-px opacity-70;
        background-image: linear-gradient(
            90deg,
            transparent,
            color-mix(in oklab, var(--color-primary) 55%, transparent),
            #8b5cf6,
            transparent
        );
    }

    /* --- Generic round icon buttons -------------------------------------- */
    .hc-icon-btn {
        @apply relative grid size-9 shrink-0 place-items-center rounded-full border border-transparent text-gray-500 transition-all duration-200 cursor-pointer;
    }
    .hc-icon-btn:hover {
        @apply -translate-y-0.5 border-border-color text-primary-text;
        background-color: color-mix(
            in oklab,
            var(--color-primary) 8%,
            transparent
        );
    }
    .hc-icon-btn i {
        @apply text-lg;
    }
    .hc-icon-btn .hc-dot {
        @apply absolute right-1.5 top-1.5 size-2 rounded-full ring-2;
        --tw-ring-color: var(--color-white);
    }
    .hc-badge {
        @apply absolute -right-1 -top-1 grid min-w-4 place-items-center rounded-full px-1 text-[9px] font-extrabold text-white;
        background-image: linear-gradient(135deg, #f43f5e, #e11d48);
    }

    /* --- Workspace switcher --------------------------------------------- */
    .hc-ws-btn {
        @apply flex shrink-0 items-center gap-2 rounded-xl border border-border-color bg-white px-2.5 py-2 text-xs font-bold text-gray-900 transition-all duration-200 cursor-pointer dark:bg-slate-800;
    }
    .hc-ws-btn:hover {
        border-color: color-mix(
            in oklab,
            var(--color-primary) 45%,
            transparent
        );
    }
    .hc-ws-swatch {
        @apply grid size-6 place-items-center rounded-xl text-white text-[13px];
        background-image: linear-gradient(
            135deg,
            var(--color-primary),
            #8b5cf6
        );
    }
    .hc-ws-item {
        @apply flex items-center gap-2.5 rounded-xl p-2 transition-colors duration-150 cursor-pointer;
    }
    .hc-ws-item:hover {
        background-color: color-mix(
            in oklab,
            var(--hc-c, var(--color-primary)) 10%,
            transparent
        );
    }
    .hc-ws-item.is-active {
        background-color: color-mix(
            in oklab,
            var(--hc-c, var(--color-primary)) 12%,
            transparent
        );
    }
    .hc-ws-ico {
        @apply grid size-8 shrink-0 place-items-center rounded-xl text-sm text-white;
        background-image: linear-gradient(
            135deg,
            var(--hc-c, var(--color-primary)),
            color-mix(in oklab, var(--hc-c, var(--color-primary)) 55%, #1e1b4b)
        );
    }

    /* --- Global search / command trigger -------------------------------- */
    .hc-search {
        @apply relative hidden lg:flex min-w-0 flex-1 max-w-xl items-center;
    }
    .hc-search-field {
        @apply flex w-full items-center gap-2.5 rounded-xl border border-border-color bg-white px-3 py-2 text-sm transition-all duration-200 dark:bg-slate-800/70;
    }
    .hc-search.is-open .hc-search-field,
    .hc-search-field:focus-within {
        border-color: color-mix(
            in oklab,
            var(--color-primary) 55%,
            transparent
        );
        box-shadow: 0 0 0 4px
            color-mix(in oklab, var(--color-primary) 12%, transparent);
    }
    .hc-search-input {
        @apply w-full border-0 bg-transparent p-0 text-sm text-gray-900 placeholder:text-gray-400 focus:outline-none focus:ring-0;
    }
    .hc-kbd {
        @apply inline-flex shrink-0 items-center gap-0.5 rounded-md border border-border-color bg-gray-50 px-1.5 py-0.5 text-[10px] font-bold text-gray-400 dark:bg-slate-700/60;
    }

    /* --- Floating glass panel (custom dropdowns + search) --------------- */
    .hc-pop {
        @apply absolute z-50 rounded-xl border border-border-color bg-white p-2 shadow-2xl transition-all duration-200 dark:bg-slate-800;
        box-shadow: 0 30px 60px -24px rgba(2, 12, 40, 0.45);
    }
    .hc-pop.hc-glass {
        background-color: color-mix(
            in oklab,
            var(--color-white) 92%,
            transparent
        );
        backdrop-filter: blur(20px) saturate(1.4);
        -webkit-backdrop-filter: blur(20px) saturate(1.4);
    }
    .hc-pop[hidden] {
        @apply pointer-events-none translate-y-1 scale-[0.98] opacity-0;
        display: block !important;
    }
    .hc-pop-head {
        @apply flex items-center justify-between px-2 pb-1.5 pt-1;
    }
    .hc-pop-title {
        @apply text-[10px] font-extrabold uppercase tracking-[0.14em] text-gray-400;
    }

    /* --- Header dropdown enter/exit animation ---------------------------
       Preline positions these menus with Floating UI, which writes an inline
       `transform: translate3d(...)`. We animate the INDEPENDENT `translate`
       and `scale` properties instead — they compose on top of that transform,
       so the menu slides/scales smoothly without ever disturbing its computed
       position (no flicker, no jump). Scoped to header (.hc-bar) menus only;
       Preline holds the element visible until this transition ends before it
       re-applies `hidden`, so the exit animation plays too. */
    .hc-bar .hs-dropdown-menu.hc-pop {
        opacity: 0;
        translate: 0 6px;
        scale: 0.97;
        transform-origin: top center;
        transition:
            opacity 0.16s ease,
            translate 0.22s cubic-bezier(0.16, 1, 0.3, 1),
            scale 0.22s cubic-bezier(0.16, 1, 0.3, 1);
        will-change: opacity, translate, scale;
    }
    .hc-bar .hs-dropdown.open > .hs-dropdown-menu.hc-pop {
        opacity: 1;
        translate: 0 0;
        scale: 1;
    }
    /* Solid, fully opaque panel — no see-through glass over page content.
       Overrides both the light (.hc-pop.hc-glass) and dark
       (.dark .hc-pop.hc-glass) translucent backgrounds with a higher-
       specificity selector, and drops the backdrop blur. `--color-white`
       resolves to solid white in light and solid slate in dark, so a single
       token keeps both themes opaque. z-index stays in the header band
       (above page content, below the z-60 command palette / drawer). */
    .hc-bar .hs-dropdown-menu.hc-pop.hc-glass,
    .dark .hc-bar .hs-dropdown-menu.hc-pop.hc-glass,
    .hc-bar #hc-search-panel.hc-glass,
    .dark .hc-bar #hc-search-panel.hc-glass {
        z-index: 55;
        background-color: var(--color-white);
        backdrop-filter: none;
        -webkit-backdrop-filter: none;
    }

    /* --- Right utility cluster (glass card) ----------------------------- */
    .hc-cluster {
        @apply flex items-center gap-1 rounded-xl border border-border-color bg-white p-1 dark:bg-slate-800/70;
    }
    .hc-divider {
        @apply mx-0.5 h-6 w-px shrink-0 bg-border-color;
    }

    /* --- Live clock block ----------------------------------------------- */
    .hc-clock {
        @apply hidden xl:flex flex-col items-end px-2 leading-tight;
    }
    .hc-clock-time {
        @apply text-sm font-extrabold text-gray-900 tabular-nums;
    }
    .hc-clock-meta {
        @apply text-[10px] font-semibold text-gray-400;
    }

    /* --- Emergency button ------------------------------------------------ */
    .hc-emg {
        @apply flex shrink-0 items-center gap-1.5 rounded-xl px-2.5 py-2 text-xs font-extrabold text-white transition-all duration-200 cursor-pointer;
        background-image: linear-gradient(135deg, #f43f5e, #e11d48);
        box-shadow: 0 10px 22px -12px #f43f5e;
        /* Fixed red surface: .dark{} repoints --color-white to slate, which
           would turn the label, icon and dot dark-on-red. Keep it real white. */
        --color-white: #ffffff;
    }
    .hc-emg:hover {
        @apply -translate-y-0.5 brightness-110;
    }
    .hc-emg-dot {
        @apply size-1.5 rounded-full bg-white;
        animation: tc-ping 1.4s ease-in-out infinite;
    }

    /* --- Quick action dock ---------------------------------------------- */
    .hc-dock-fab {
        background-image: linear-gradient(
            135deg,
            var(--color-primary),
            #8b5cf6
        );
        @apply text-white border-transparent;
    }
    .hc-dock-fab:hover {
        @apply text-white brightness-110;
        background-image: linear-gradient(
            135deg,
            var(--color-primary),
            #8b5cf6
        );
    }
    .hc-dock-item {
        @apply flex items-center gap-2.5 rounded-xl p-2 transition-colors duration-150 cursor-pointer;
    }
    .hc-dock-item:hover {
        background-color: color-mix(
            in oklab,
            var(--hc-c, var(--color-primary)) 10%,
            transparent
        );
    }
    .hc-dock-ico {
        @apply grid size-8 shrink-0 place-items-center rounded-xl text-white text-sm;
        background-image: linear-gradient(
            135deg,
            var(--hc-c, var(--color-primary)),
            color-mix(in oklab, var(--hc-c, var(--color-primary)) 55%, #1e1b4b)
        );
    }

    /* --- Appearance switcher (segmented) -------------------------------- */
    .hc-seg {
        @apply flex items-center gap-1 rounded-xl bg-gray-100 p-1 dark:bg-slate-700/60;
    }
    .hc-seg-btn {
        @apply flex flex-1 items-center justify-center gap-1.5 rounded-xl px-2.5 py-1.5 text-[11px] font-bold text-gray-500 transition-all duration-200 cursor-pointer;
    }
    .hc-seg-btn:hover {
        @apply text-gray-900;
    }
    .hc-seg-btn.is-active {
        @apply bg-white text-primary-text shadow-sm dark:bg-slate-900;
    }

    /* --- AI assistant panel --------------------------------------------- */
    .hc-ai-hero {
        @apply relative overflow-hidden rounded-xl p-3 text-white;
        background-image: linear-gradient(
            130deg,
            var(--color-primary),
            #8b5cf6 55%,
            #d946ef
        );
        /* Same fixed-dark-surface issue as .sidebar/.hc-prof-card: pin
           --color-white back to real white for this gradient's own
           white/N utilities regardless of the theme toggle. */
        --color-white: #ffffff;
    }
    .hc-ai-chip {
        @apply flex items-center gap-2 rounded-xl border border-border-color p-2 text-[11px] font-semibold text-gray-600 transition-all duration-150 cursor-pointer dark:text-gray-300;
    }
    .hc-ai-chip:hover {
        @apply -translate-y-0.5 text-primary-text;
        border-color: color-mix(
            in oklab,
            var(--color-primary) 45%,
            transparent
        );
        background-color: color-mix(
            in oklab,
            var(--color-primary) 7%,
            transparent
        );
    }

    /* --- Notification center (redesign, keeps Preline shell) ------------ */
    .hc-noti-tab {
        @apply relative rounded-xl px-2.5 py-1 text-[11px] font-bold text-gray-500 transition-colors duration-150 cursor-pointer;
    }
    .hc-noti-tab:hover {
        @apply text-gray-900;
    }
    .hc-noti-tab.is-active {
        @apply text-primary-text;
        background-color: color-mix(
            in oklab,
            var(--color-primary) 12%,
            transparent
        );
    }
    .hc-noti {
        @apply relative flex gap-3 rounded-xl p-2.5 transition-colors duration-150 cursor-pointer;
        border-left: 3px solid var(--hc-c, var(--color-primary));
    }
    .hc-noti:hover {
        background-color: color-mix(
            in oklab,
            var(--hc-c, var(--color-primary)) 8%,
            transparent
        );
    }
    .hc-noti[hidden] {
        display: none !important;
    }
    .hc-noti-ico {
        @apply grid size-9 shrink-0 place-items-center rounded-xl text-sm;
        color: var(--hc-c, var(--color-primary));
        background-color: color-mix(
            in oklab,
            var(--hc-c, var(--color-primary)) 13%,
            transparent
        );
    }
    .hc-noti-prio {
        @apply inline-flex items-center gap-1 rounded-full px-1.5 py-0.5 text-[8px] font-extrabold uppercase tracking-wide;
        color: var(--hc-c, var(--color-primary));
        background-color: color-mix(
            in oklab,
            var(--hc-c, var(--color-primary)) 14%,
            transparent
        );
    }
    .hc-noti-act {
        @apply rounded-xl px-2 py-1 text-[10px] font-bold text-gray-500 transition-colors duration-150 cursor-pointer hover:text-primary;
        background-color: color-mix(
            in oklab,
            var(--color-primary) 8%,
            transparent
        );
    }

    /* --- Profile card ---------------------------------------------------- */
    .hc-prof-card {
        @apply relative overflow-hidden rounded-xl p-4 text-white;
        background-image: linear-gradient(
            130deg,
            #1e1b4b,
            #4c1d95 55%,
            #6d28d9
        );
        /* Same fixed-dark-surface issue as .sidebar: this gradient never
           changes with the theme toggle, but its white/N utilities (badge,
           stat chips, "Shift"/"Dept" labels) are built on the shared
           --color-white token, which .dark{} redefines to a dark slate for
           surfaces that do invert. Pin it back to real white in here. */
        --color-white: #ffffff;
    }
    .hc-prof-badge {
        @apply inline-flex items-center gap-1 rounded-full border border-white/20 bg-white/15 px-2 py-0.5 text-[9px] font-extrabold uppercase tracking-wider text-white backdrop-blur-md;
    }
    .hc-prof-stat {
        @apply rounded-xl border border-white/10 bg-white/10 px-2.5 py-1.5 backdrop-blur-md;
    }
    .hc-prof-link {
        @apply flex items-center gap-2.5 rounded-xl p-2 text-sm font-medium text-gray-700 transition-colors duration-150 dark:text-gray-200;
    }
    .hc-prof-link:hover {
        @apply text-primary-text;
        background-color: color-mix(
            in oklab,
            var(--color-primary) 9%,
            transparent
        );
    }
    .hc-prof-link i {
        @apply grid size-8 place-items-center rounded-xl text-base;
        color: var(--color-primary-text);
        background-color: color-mix(
            in oklab,
            var(--color-primary) 12%,
            transparent
        );
    }

    /* --- Command palette (Ctrl+K) --------------------------------------- */
    .hc-cmd {
        @apply fixed inset-0 z-[60] flex items-start justify-center px-4 pt-[12vh] transition-opacity duration-200;
        background-color: rgba(8, 12, 30, 0.5);
        backdrop-filter: blur(6px);
        -webkit-backdrop-filter: blur(6px);
    }
    .hc-cmd[hidden] {
        @apply pointer-events-none opacity-0;
        display: flex !important;
    }
    .hc-cmd-box {
        @apply w-full max-w-2xl overflow-hidden rounded-xl border border-border-color bg-white shadow-2xl transition-all duration-200 dark:bg-slate-800;
        box-shadow: 0 40px 80px -30px rgba(2, 12, 40, 0.6);
    }
    .hc-cmd[hidden] .hc-cmd-box {
        @apply -translate-y-3 scale-[0.97];
    }
    .hc-cmd-search {
        @apply flex items-center gap-3 border-b border-border-color px-5 py-4;
    }
    .hc-cmd-input {
        @apply w-full border-0 bg-transparent p-0 text-base font-medium text-gray-900 placeholder:text-gray-400 focus:outline-none focus:ring-0;
    }
    .hc-cmd-list {
        @apply max-h-[52vh] overflow-y-auto p-3;
    }
    .hc-cmd-group {
        @apply px-2 pb-1 pt-3 text-[10px] font-extrabold uppercase tracking-[0.14em] text-gray-400 first:pt-1;
    }
    .hc-cmd-item {
        @apply flex items-center gap-3 rounded-xl px-3 py-2.5 transition-colors duration-100 cursor-pointer;
    }
    .hc-cmd-item.is-active,
    .hc-cmd-item:hover {
        background-color: color-mix(
            in oklab,
            var(--color-primary) 10%,
            transparent
        );
    }
    .hc-cmd-item[hidden] {
        display: none !important;
    }
    .hc-cmd-ico {
        @apply grid size-9 shrink-0 place-items-center rounded-xl text-sm;
        color: var(--hc-c, var(--color-primary));
        background-color: color-mix(
            in oklab,
            var(--hc-c, var(--color-primary)) 13%,
            transparent
        );
    }

    /* --- Activity drawer ------------------------------------------------- */
    .hc-drawer {
        @apply fixed inset-0 z-[60];
    }
    .hc-drawer[hidden] {
        @apply pointer-events-none;
        display: block !important;
    }
    .hc-drawer-backdrop {
        @apply absolute inset-0 transition-opacity duration-300;
        background-color: rgba(8, 12, 30, 0.45);
        backdrop-filter: blur(4px);
        -webkit-backdrop-filter: blur(4px);
    }
    .hc-drawer[hidden] .hc-drawer-backdrop {
        @apply opacity-0;
    }
    .hc-drawer-panel {
        @apply absolute right-0 top-0 flex h-full w-[92%] max-w-md flex-col border-l border-border-color bg-white transition-transform duration-300 dark:bg-slate-900;
    }
    .hc-drawer[hidden] .hc-drawer-panel {
        @apply translate-x-full;
    }
    .hc-drawer-item {
        @apply relative flex gap-3 pb-4 last:pb-0;
    }
    .hc-drawer-item:not(:last-child)::before {
        content: "";
        @apply absolute left-[13px] top-8 bottom-0 w-px bg-border-color dark:bg-white/10;
    }
    .hc-drawer-ico {
        @apply relative z-10 grid size-7 shrink-0 place-items-center rounded-full text-[11px];
        color: var(--hc-c, var(--color-primary));
        background-color: color-mix(
            in oklab,
            var(--hc-c, var(--color-primary)) 14%,
            transparent
        );
        box-shadow:
            inset 0 0 0 1px
                color-mix(
                    in oklab,
                    var(--hc-c, var(--color-primary)) 28%,
                    transparent
                ),
            0 0 0 3px var(--color-white);
    }

    /* Accent helpers shared across command-bar pieces. */
    .hc-c-primary {
        --hc-c: var(--color-primary);
    }
    .hc-c-emerald {
        --hc-c: #10b981;
    }
    .hc-c-sky {
        --hc-c: #0ea5e9;
    }
    .hc-c-violet {
        --hc-c: #8b5cf6;
    }
    .hc-c-amber {
        --hc-c: #f59e0b;
    }
    .hc-c-rose {
        --hc-c: #f43f5e;
    }
    .hc-c-indigo {
        --hc-c: #6366f1;
    }
    .hc-c-fuchsia {
        --hc-c: #d946ef;
    }
    .hc-c-teal {
        --hc-c: #0d9488;
    }
    .hc-c-gold {
        --hc-c: #eab308;
    }

    /* The command bar is always on screen — honour reduced-motion. */
    @media (prefers-reduced-motion: reduce) {
        .hc-bar,
        .hc-icon-btn,
        .hc-ws-btn,
        .hc-emg,
        .hc-pop,
        .hc-cmd,
        .hc-cmd-box,
        .hc-drawer-panel,
        .hc-drawer-backdrop,
        .hc-ai-chip {
            @apply transition-none;
        }
        .hc-icon-btn:hover,
        .hc-emg:hover,
        .hc-ai-chip:hover {
            @apply translate-y-0;
        }
        .hc-bar .hs-dropdown-menu.hc-pop {
            transition: none;
            translate: 0;
            scale: 1;
        }
        .hc-emg-dot {
            animation: none;
        }
    }

    /* Dark-mode ring/glass corrections for the command bar. */
    .dark .hc-bar {
        background-color: color-mix(in oklab, #0f172a 78%, transparent);
        border-color: rgba(255, 255, 255, 0.08);
    }
    .dark .hc-bar.hc-scrolled {
        background-color: color-mix(in oklab, #0f172a 90%, transparent);
    }
    .dark .hc-icon-btn .hc-dot {
        --tw-ring-color: #0f172a;
    }
    .dark .hc-pop.hc-glass,
    .dark .hc-cmd-box {
        background-color: color-mix(in oklab, #0f172a 92%, transparent);
    }
    .dark .hc-noti-ico,
    .dark .hc-cmd-ico,
    .dark .hc-drawer-ico {
        box-shadow: none;
    }
    .dark .hc-drawer-ico {
        box-shadow:
            inset 0 0 0 1px
                color-mix(
                    in oklab,
                    var(--hc-c, var(--color-primary)) 30%,
                    transparent
                ),
            0 0 0 3px #0f172a;
    }

    /* =====================================================================
       ENTERPRISE SIDEBAR WORKSPACE — visual redesign layer for the existing
       navigation (partials/sidebar.html). Adds premium level-1 cards,
       distinct level-2/level-3 styling, tree connectors, glowing active
       states, accordion motion, category accents, a workspace switcher,
       sidebar search, favorites/recent and an enhanced footer. Placed after
       the base sidebar rules so it layers on top; never alters the menu tree.
       ===================================================================== */

    /* Category accent map — driven by data-accent on existing anchors. */
    .sidebar [data-accent="primary"] {
        --sb-accent: var(--color-primary);
    }
    .sidebar [data-accent="rose"] {
        --sb-accent: #fb7185;
    }
    .sidebar [data-accent="amber"] {
        --sb-accent: #fbbf24;
    }
    .sidebar [data-accent="emerald"] {
        --sb-accent: #34d399;
    }
    .sidebar [data-accent="sky"] {
        --sb-accent: #38bdf8;
    }
    .sidebar [data-accent="violet"] {
        --sb-accent: #a78bfa;
    }
    .sidebar [data-accent="indigo"] {
        --sb-accent: #818cf8;
    }
    .sidebar [data-accent="teal"] {
        --sb-accent: #2dd4bf;
    }
    .sidebar [data-accent="fuchsia"] {
        --sb-accent: #e879f9;
    }
    .sidebar [data-accent="gold"] {
        --sb-accent: #fcd34d;
    }
    .sidebar [data-accent="cyan"] {
        --sb-accent: #22d3ee;
    }

    /* --- Level 1: premium module cards ---------------------------------- */
    /* Media-object layout: icon column + stacked title/description rows,
       so all three share one left edge and the spacing stays even. The
       menu-arrow span is absolutely positioned (base rule) and stays out
       of the grid flow. */
    .sidebar .sidebar-menu > ul > li.submenu > a {
        @apply relative rounded-xl pl-3 pr-9 py-2 normal-case tracking-normal transition-all duration-200;
        display: grid;
        grid-template-columns: auto minmax(0, 1fr);
        grid-template-areas: "icon title" "icon desc";
        align-items: center;
        column-gap: 0.75rem;
        row-gap: 0.1rem;
        --sb-accent: var(--color-primary);
    }
    .sidebar .sidebar-menu > ul > li.submenu > a::after {
        content: attr(data-desc);
        grid-area: desc;
        @apply pointer-events-none min-w-0 truncate text-[10px] font-medium normal-case text-gray-500 opacity-70;
    }
    /* Icon becomes an accent chip. */
    .sidebar .sidebar-menu > ul > li.submenu > a > i {
        grid-area: icon;
        @apply grid size-9 shrink-0 place-items-center self-center rounded-xl text-base! transition-all duration-200;
        color: var(--sb-accent) !important;
        background-color: color-mix(
            in oklab,
            var(--sb-accent) 15%,
            transparent
        );
        box-shadow: inset 0 0 0 1px
            color-mix(in oklab, var(--sb-accent) 26%, transparent);
    }
    .sidebar .sidebar-menu > ul > li.submenu > a > span:not(.menu-arrow) {
        grid-area: title;
        @apply min-w-0 truncate text-[13px] font-bold uppercase tracking-wide text-white/90 ml-0;
    }
    .sidebar .sidebar-menu > ul > li.submenu > a:hover {
        background-color: color-mix(
            in oklab,
            var(--sb-accent) 12%,
            transparent
        );
        box-shadow: inset 3px 0 0
