        }
    }
}

select {
    @apply [appearance:base-select]! pe-3!;
    background-image: none !important;
}

/* appearance:base-select is the popup-picker customization API — it only
   targets a plain single-value <select>. A listbox-mode select (multiple,
   or size > 1) isn't a popup at all, and forcing base-select onto it left
   only the :checked rows getting the custom padding/color while the rest
   fell back to cramped native styling. Give listbox selects their normal
   appearance back so every option renders through the one plain rule below. */
select[multiple],
select[size] {
    appearance: auto !important;
}

option {
    @apply py-2 px-3.5 rounded-sm cursor-pointer! text-gray-500!;
}

option:checked {
    @apply bg-primary! text-white! dark:text-dark-white!;
}

::picker(select) {
    @apply [appearance:base-select]! border border-border-color! rounded-md bg-white!;
}

option::checkmark {
    @apply hidden! [content:'']!;
}

select::picker-icon {
    @apply block! text-gray-900! not-italic font-normal  ml-auto! text-sm!;
    font-family: "lucide", "font-icons", sans-serif !important;
    content: "\e06d" !important;
}
