    border-radius: 0.9rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 30px 60px -24px rgba(2, 12, 40, 0.5);
    animation: pp-pop 0.16s ease;
}
@keyframes pp-pop {
    from {
        opacity: 0;
        transform: translateY(-6px) scale(0.97);
    }
}
.pp-menu button,
.pp-menu a {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    width: 100%;
    padding: 0.45rem 0.55rem;
    border-radius: 0.55rem;
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--color-gray-900);
    text-align: left;
    transition:
        background 0.14s ease,
        color 0.14s ease;
}
.pp-menu button:hover,
.pp-menu a:hover {
    background: color-mix(in oklab, var(--color-primary) 8%, transparent);
    color: var(--color-primary-text);
}
.pp-menu .danger {
    color: #e11d48;
}
.pp-menu .danger:hover {
    background: rgba(244, 63, 94, 0.1);
}

.pp-modal {
    position: fixed;
    inset: 0;
    z-index: 1200;
    display: none;
    align-items: center;
    justify-content: center;
    padding: 1rem;
}
.pp-modal.open {
    display: flex;
}
.pp-modal-back {
    position: absolute;
    inset: 0;
    background: rgba(8, 12, 30, 0.5);
    -webkit-backdrop-filter: blur(3px);
    backdrop-filter: blur(3px);
    animation: pp-fadein 0.2s ease;
}
@keyframes pp-fadein {
    from {
        opacity: 0;
    }
}
.pp-modal-panel {
    position: relative;
    width: 100%;
    max-width: 34rem;
    max-height: 90vh;
    overflow-y: auto;
    border-radius: 1.25rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 40px 80px -30px rgba(2, 12, 40, 0.6);
    animation: pp-modin 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes pp-modin {
    from {
        opacity: 0;
        transform: translateY(16px) scale(0.97);
    }
}

.pp-drawer {
    position: fixed;
    inset: 0;
    z-index: 1200;
    visibility: hidden;
}
.pp-drawer.open {
    visibility: visible;
}
.pp-drawer-back {
    position: absolute;
    inset: 0;
    background: rgba(8, 12, 30, 0.5);
    opacity: 0;
    transition: opacity 0.3s ease;
}
.pp-drawer.open .pp-drawer-back {
    opacity: 1;
}
.pp-drawer-panel {
    position: absolute;
    top: 0;
    right: 0;
    height: 100%;
    width: min(420px, 92vw);
    background: var(--color-white);
    box-shadow: -30px 0 60px -30px rgba(2, 12, 40, 0.55);
    transform: translateX(100%);
    transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1);
    display: flex;
    flex-direction: column;
}
.pp-drawer.open .pp-drawer-panel {
    transform: translateX(0);
}

.pp-in {
    width: 100%;
    padding: 0.65rem 0.8rem;
    border-radius: 0.7rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.85rem;
    font-weight: 600;
    outline: none;
    transition:
        border-color 0.16s ease,
        box-shadow 0.16s ease;
}
.pp-in:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 4px
        color-mix(in oklab, var(--color-primary) 14%, transparent);
}
.pp-lbl {
    display: block;
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--color-gray-500);
    margin-bottom: 0.3rem;
}

.pp-c-indigo {
    --pp-c: #6366f1;
}
.pp-c-sky {
    --pp-c: #0ea5e9;
}
.pp-c-rose {
    --pp-c: #f43f5e;
}
.pp-c-amber {
    --pp-c: #f59e0b;
}
.pp-c-emerald {
    --pp-c: #10b981;
}
.pp-c-violet {
    --pp-c: #8b5cf6;
}
.pp-c-teal {
    --pp-c: #14b8a6;
}
.pp-c-primary {
    --pp-c: var(--color-primary);
}

.pp-sk {
    position: relative;
    overflow: hidden;
    background: color-mix(in oklab, var(--color-gray-500) 12%, transparent);
    border-radius: 0.6rem;
}
.pp-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in oklab, var(--color-white) 55%, transparent),
        transparent
    );
    animation: pp-shimmer 1.4s infinite;
}
.dark .pp-sk::after {
    background: linear-gradient(
        90deg,
        transparent,
        rgba(255, 255, 255, 0.06),
        transparent
    );
}
@keyframes pp-shimmer {
    100% {
        transform: translateX(100%);
    }
}

.pp-toast {
    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    z-index: 2000;
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.8rem 1.1rem;
    border-radius: 0.9rem;
    font-size: 0.85rem;
    font-weight: 700;
    color: #fff;
    box-shadow: 0 20px 45px -18px rgba(0, 0, 0, 0.5);
    animation: pp-toastin 0.25s ease;
}
@keyframes pp-toastin {
    from {
        opacity: 0;
        transform: translateY(12px);
    }
}
.pp-toast.success {
    background: linear-gradient(135deg, #10b981, #059669);
}
.pp-toast.info {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
}
.pp-toast.error {
    background: linear-gradient(135deg, #f43f5e, #e11d48);
}

@media (prefers-reduced-motion: reduce) {
    .pp-btn,
    .pp-vital,
    .pp-doc,
    .pp-ring .bar,
    .pp-dot,
    .pp-sk::after,
    .pp-icobtn,
    .pp-drawer-panel {
        transition: none;
        animation: none;
    }
    .pp-btn:hover,
    .pp-vital:hover,
    .pp-doc:hover,
    .pp-icobtn:hover {
        transform: none;
    }
}
@media print {
    .sidebar,
    header.navbar-header,
    .pp-tabs,
    .pp-actions-print-hide {
        display: none !important;
    }
    .pp-panel {
        display: block !important;
    }
}

/* ================================================================
   SPECIALIZATIONS CENTER · specializations.html (page-exclusive)
   Do not reuse these classes in other modules.
   Design-system CSS variables → automatic light / dark.
   ================================================================ */
#sp-page {
    --sp-c: var(--color-primary);
}
.sp-surface {
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    border-radius: 1.25rem;
    box-shadow: 0 20px 45px -35px rgba(15, 23, 42, 0.4);
}
.sp-muted {
    color: var(--color-gray-500);
}

.sp-layout {
    display: grid;
    grid-template-columns: 1fr;
    gap: 1.25rem;
    align-items: start;
}
@media (min-width: 1280px) {
    .sp-layout {
        grid-template-columns: minmax(0, 1fr) 330px;
    }
}
.sp-grid {
    display: grid;
    gap: 0.9rem;
}
.sp-g6 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
}
@media (min-width: 700px) {
    .sp-g6 {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}
@media (min-width: 1200px) {
    .sp-g6 {
        grid-template-columns: repeat(6, minmax(0, 1fr));
    }
}
.sp-cards {
    display: grid;
    gap: 1rem;
    grid-template-columns: 1fr;
}
.sp-cards.hidden {
    display: none;
}
@media (min-width: 640px) {
    .sp-cards {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

/* ---------- HERO ---------- */
.sp-hero {
