    color: #fff;
    background:
        radial-gradient(
            120% 140% at 0% 0%,
            rgba(139, 92, 246, 0.5),
            transparent 55%
        ),
        radial-gradient(
            120% 160% at 100% 0%,
            rgba(236, 72, 153, 0.5),
            transparent 50%
        ),
        linear-gradient(135deg, #0f172a, #171233 55%, #0b1220);
    box-shadow: 0 30px 60px -30px rgba(15, 23, 42, 0.7);
}
.sp-hero::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image: radial-gradient(
        rgba(255, 255, 255, 0.08) 1px,
        transparent 1px
    );
    background-size: 22px 22px;
    -webkit-mask-image: linear-gradient(180deg, #000, transparent 75%);
    mask-image: linear-gradient(180deg, #000, transparent 75%);
}
.sp-hero > * {
    position: relative;
    z-index: 1;
}
@media (min-width: 1024px) {
    .sp-hero {
        padding: 2rem 2.25rem;
    }
}
.sp-hbadge {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.25rem 0.7rem;
    border-radius: 9999px;
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    background: rgba(255, 255, 255, 0.14);
    border: 1px solid rgba(255, 255, 255, 0.22);
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
}
.sp-hmeta {
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
    padding: 0.45rem 0.8rem;
    border-radius: 0.8rem;
    background: rgba(255, 255, 255, 0.1);
    border: 1px solid rgba(255, 255, 255, 0.16);
    font-size: 0.72rem;
    font-weight: 700;
}
.sp-dot {
    width: 0.5rem;
    height: 0.5rem;
    border-radius: 9999px;
    background: #c084fc;
    box-shadow: 0 0 0 4px rgba(192, 132, 252, 0.25);
    animation: sp-pulse 2s ease-in-out infinite;
}
@keyframes sp-pulse {
    0%,
    100% {
        opacity: 1;
    }
    50% {
        opacity: 0.4;
    }
}

