}
.sp-segb {
    padding: 0.4rem 0.7rem;
    border-radius: 0.5rem;
    font-size: 0.76rem;
    font-weight: 700;
    color: var(--color-gray-600);
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
}
.sp-segb.active {
    background: var(--color-white);
    color: var(--color-primary-text);
    box-shadow: 0 6px 14px -10px rgba(15, 23, 42, 0.5);
}

/* ---------- SKELETON ---------- */
.sp-sk {
    position: relative;
    overflow: hidden;
    background: var(--color-gray-100);
    border-radius: 1rem;
}
.sp-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in srgb, var(--color-gray-300) 55%, transparent),
        transparent
    );
    animation: sp-sh 1.4s infinite;
}
@keyframes sp-sh {
    100% {
        transform: translateX(100%);
    }
}

/* ---------- DRAWER ---------- */
.sp-drawer {
    position: fixed;
    inset: 0;
    z-index: 70;
    display: none;
}
.sp-drawer.open {
    display: block;
}
.sp-mask {
    position: absolute;
    inset: 0;
    background: rgba(15, 23, 42, 0.55);
    -webkit-backdrop-filter: blur(3px);
    backdrop-filter: blur(3px);
    animation: sp-fade 0.25s ease;
}
@keyframes sp-fade {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}
.sp-panel {
    position: absolute;
    top: 0;
    right: 0;
    height: 100%;
    width: min(470px, 100vw);
    background: var(--color-white);
    border-left: 1px solid var(--color-border-color);
    box-shadow: -30px 0 60px -30px rgba(15, 23, 42, 0.6);
    overflow-y: auto;
    animation: sp-slide 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
@keyframes sp-slide {
    from {
        transform: translateX(100%);
    }
    to {
        transform: none;
    }
}

/* ---------- MODAL ---------- */
.sp-modal {
    position: fixed;
    inset: 0;
    z-index: 75;
    display: none;
}
.sp-modal.open {
    display: block;
}
.sp-dialog {
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
    width: min(520px, 94vw);
    max-height: 90vh;
    overflow: auto;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    border-radius: 1.25rem;
    box-shadow: 0 40px 80px -30px rgba(15, 23, 42, 0.7);
    animation: sp-pop 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}
@keyframes sp-pop {
    from {
        opacity: 0;
        transform: translate(-50%, -46%) scale(0.96);
    }
    to {
        opacity: 1;
        transform: translate(-50%, -50%) scale(1);
    }
}

/* ---------- TOAST ---------- */
#sp-toast {
    position: fixed;
    right: 1rem;
    bottom: 1rem;
    z-index: 90;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}
.sp-toast {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    padding: 0.7rem 0.95rem;
    border-radius: 0.8rem;
    background: var(--color-gray-900);
    color: #fff;
    font-size: 0.8rem;
    font-weight: 700;
    box-shadow: 0 18px 40px -18px rgba(0, 0, 0, 0.6);
    animation: sp-tin 0.3s ease;
}
@keyframes sp-tin {
    from {
        opacity: 0;
        transform: translateY(12px);
    }
    to {
        opacity: 1;
        transform: none;
    }
}

/* ================================================================
   BLOOD INVENTORY MANAGEMENT CENTER · blood-bank.html (page-exclusive)
   Namespace: bb-  ·  Theme-aware · Lucide icons (icon-*).
   Blood-group inventory / expiry / donation focused.
   Do not reuse these classes in other modules.
   ================================================================ */
#bb-page {
