    --bb-panel: var(--color-gray-50);
    --bb-border: var(--color-border-color);
    --bb-text: var(--color-gray-900);
    --bb-mut: var(--color-gray-500);
    --bb-soft: var(--color-gray-400);
    --bb-elev: var(--color-white);
    --bb-hover: var(--color-gray-100);
    --bb-track: color-mix(in srgb, var(--color-gray-500) 16%, transparent);
    --bb-neutral: color-mix(in srgb, var(--color-gray-500) 12%, transparent);
}
.dark #bb-page {
    --bb-accent: #f87171;
