/* ---------- BLOOD GROUP CARD ---------- */
.bb-bg {
    position: relative;
    border-radius: 0.9rem;
    overflow: hidden;
    background: var(--bb-surface);
    border: 1px solid color-mix(in srgb, var(--kv) 32%, var(--bb-border));
    transition:
        box-shadow 0.2s,
        transform 0.2s;
    cursor: pointer;
}
.bb-bg:hover {
    box-shadow: 0 18px 40px -28px rgba(15, 23, 42, 0.4);
    transform: translateY(-3px);
}
.bb-bg::before {
    content: "";
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    width: 3px;
    background: var(--kv);
}
.bb-drop {
    position: relative;
    width: 52px;
    height: 52px;
    flex: none;
}
.bb-drop svg {
    width: 100%;
    height: 100%;
    filter: drop-shadow(
        0 4px 8px color-mix(in srgb, var(--kv) 40%, transparent)
    );
}
.bb-drop .lbl {
    position: absolute;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.82rem;
    font-weight: 800;
    color: #fff;
    letter-spacing: -0.02em;
    padding-top: 6px;
}
.bb-vial {
    height: 36px;
    width: 14px;
    border-radius: 4px 4px 6px 6px;
    border: 1.5px solid var(--bb-border);
    position: relative;
    overflow: hidden;
    background: var(--bb-panel);
}
.bb-vial > span {
    position: absolute;
    left: 0;
    right: 0;
    bottom: 0;
    border-radius: 0 0 4px 4px;
}
.bb-stab {
    height: 7px;
    border-radius: 999px;
    background: var(--bb-track);
    overflow: hidden;
}
.bb-stab > span {
    display: block;
    height: 100%;
    border-radius: 999px;
    transition: width 0.6s;
}

/* list */
.bb-row {
    display: grid;
    grid-template-columns: auto 90px 1fr 1fr 1fr auto;
    gap: 0.75rem;
    align-items: center;
    padding: 0.65rem 0.85rem;
    border-bottom: 1px solid var(--bb-border);
}
.bb-row:hover {
    background: color-mix(in srgb, var(--bb-c) 4%, transparent);
}

/* ---------- MENU / MODAL / DRAWER ---------- */
.bb-menu {
    position: fixed;
    z-index: 120;
    width: 210px;
    max-height: 72vh;
    overflow-y: auto;
    background: var(--bb-elev);
    border: 1px solid var(--bb-border);
    border-radius: 0.75rem;
    box-shadow: 0 24px 50px -18px rgba(15, 23, 42, 0.45);
    padding: 0.35rem;
    color: var(--bb-text);
}
.bb-menu button {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    width: 100%;
    text-align: left;
    font-size: 0.8rem;
    padding: 0.5rem 0.55rem;
    border-radius: 0.45rem;
    color: var(--bb-text);
}
.bb-menu button i {
    color: var(--bb-mut);
    font-size: 0.95rem;
}
.bb-menu button:hover {
    background: var(--bb-hover);
}
.bb-menu button.danger {
    color: #dc2626;
}
.bb-menu button.danger i {
    color: #dc2626;
}
.bb-menu button.danger:hover {
    background: color-mix(in srgb, #ef4444 10%, transparent);
}
.bb-menu-sep {
    height: 1px;
    background: var(--bb-border);
    margin: 0.3rem 0.2rem;
}

.bb-modal-wrap {
    position: fixed;
    inset: 0;
    z-index: 130;
    display: none;
}
.bb-modal-wrap.open {
    display: block;
}
.bb-modal-bg {
    position: absolute;
    inset: 0;
    background: rgba(8, 15, 26, 0.6);
    backdrop-filter: blur(5px);
    animation: bb-fade 0.2s;
}
@keyframes bb-fade {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}
.bb-modal {
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
    width: min(600px, 94vw);
    max-height: 90vh;
    display: flex;
    flex-direction: column;
    background: var(--bb-elev);
    color: var(--bb-text);
    border: 1px solid var(--bb-border);
    border-radius: 1rem;
    box-shadow: 0 40px 90px -24px rgba(2, 6, 15, 0.55);
    animation: bb-pop 0.22s cubic-bezier(0.4, 0, 0.2, 1);
    overflow: hidden;
}
@keyframes bb-pop {
    from {
        opacity: 0;
        transform: translate(-50%, -47%) scale(0.98);
    }
    to {
        opacity: 1;
        transform: translate(-50%, -50%) scale(1);
    }
}
.bb-modal-head {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 1rem 1.15rem;
    border-bottom: 1px solid var(--bb-border);
}
.bb-modal-badge {
    width: 38px;
    height: 38px;
    border-radius: 0.6rem;
    display: flex;
    align-items: center;
    justify-content: center;
    background: color-mix(in srgb, #dc2626 15%, transparent);
    color: #dc2626;
    font-size: 1.05rem;
    flex: none;
}
.bb-modal-body {
    padding: 1.15rem;
    overflow-y: auto;
}
.bb-modal-foot {
    display: flex;
    justify-content: flex-end;
    gap: 0.5rem;
    padding: 0.9rem 1.15rem;
    border-top: 1px solid var(--bb-border);
    background: var(--bb-panel);
}
.bb-formlabel {
    font-size: 0.72rem;
    font-weight: 600;
    color: var(--bb-mut);
    text-transform: uppercase;
    letter-spacing: 0.03em;
}
.bb-in {
    width: 100%;
    padding: 0.55rem 0.7rem;
    font-size: 0.82rem;
    border: 1px solid var(--bb-border);
    border-radius: 0.55rem;
    background: var(--bb-surface);
    color: var(--bb-text);
    transition:
        border-color 0.15s,
        box-shadow 0.15s;
}
.bb-in:focus {
    outline: none;
    border-color: #dc2626;
    box-shadow: 0 0 0 3px color-mix(in srgb, #dc2626 18%, transparent);
}
.bb-in::placeholder {
    color: var(--bb-soft);
}
.bb-drawer {
    position: fixed;
    top: 0;
    right: 0;
    height: 100%;
    width: min(460px, 96vw);
    background: var(--bb-elev);
    color: var(--bb-text);
    z-index: 125;
    transform: translateX(100%);
    transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    box-shadow: -30px 0 70px -30px rgba(2, 6, 15, 0.5);
    overflow-y: auto;
    border-left: 1px solid var(--bb-border);
}
.bb-drawer.open {
    transform: none;
}

.bb-toast {
    position: fixed;
    bottom: 1.25rem;
    left: 50%;
    transform: translateX(-50%) translateY(120%);
    z-index: 140;
    background: #0f1b2d;
    color: #e5edf5;
    border: 1px solid rgba(148, 163, 184, 0.2);
    padding: 0.7rem 1.05rem;
    border-radius: 0.65rem;
    font-size: 0.82rem;
    font-weight: 500;
    box-shadow: 0 18px 40px -18px rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    gap: 0.5rem;
    transition: transform 0.32s cubic-bezier(0.4, 0, 0.2, 1);
}
.bb-toast.show {
    transform: translateX(-50%) translateY(0);
}
.bb-bulk {
    position: sticky;
    bottom: 0.75rem;
    z-index: 40;
    background: #0f1b2d;
    color: #e5edf5;
    border-radius: 0.85rem;
    box-shadow: 0 18px 40px -18px rgba(0, 0, 0, 0.55);
    display: none;
    border: 1px solid rgba(148, 163, 184, 0.18);
}
.bb-bulk.show {
    display: flex;
}

.bb-sk {
    position: relative;
    overflow: hidden;
    background: var(--bb-panel);
    border-radius: 0.85rem;
}
.bb-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in srgb, var(--color-white) 45%, transparent),
        transparent
    );
    animation: bb-shim 1.4s infinite;
}
@keyframes bb-shim {
    100% {
        transform: translateX(100%);
    }
}
.bb-dropz {
    background-image: repeating-linear-gradient(
        0deg,
        var(--bb-border) 0,
        var(--bb-border) 6px,
        transparent 6px,
        transparent 12px
    );
}
.bb-seg {
    display: inline-flex;
    background: var(--bb-panel);
    border: 1px solid var(--bb-border);
    border-radius: 0.6rem;
    padding: 0.18rem;
    gap: 0.12rem;
}
.bb-seg button {
    padding: 0.35rem 0.7rem;
    font-size: 0.74rem;
    font-weight: 600;
    border-radius: 0.42rem;
    color: var(--bb-mut);
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
}
