    background: var(--bb-surface);
    color: var(--bb-text);
    box-shadow: 0 1px 3px rgba(15, 23, 42, 0.15);
}

/* =====================================================================
   DASHBOARD REFINEMENT LAYER  ·  dashboard.html (page-exclusive)
   Premium depth, hover and motion. Uses semantic tokens so light/dark
   both stay correct.
   ===================================================================== */
.dash-card {
    transition:
        transform 0.25s cubic-bezier(0.4, 0, 0.2, 1),
        box-shadow 0.25s ease,
        border-color 0.25s ease;
}
.dash-soft {
    box-shadow:
        0 1px 2px rgba(2, 12, 40, 0.04),
        0 10px 26px -20px rgba(2, 12, 40, 0.22);
}
.dark .dash-soft {
    box-shadow:
        0 1px 2px rgba(0, 0, 0, 0.35),
        0 12px 28px -20px rgba(0, 0, 0, 0.6);
}
.dash-card:hover {
    transform: translateY(-2px);
    border-color: color-mix(
        in oklab,
        var(--color-primary) 24%,
        var(--border-color)
    );
    box-shadow:
        0 1px 2px rgba(2, 12, 40, 0.05),
        0 22px 44px -26px rgba(2, 12, 40, 0.3);
}
.dark .dash-card:hover {
    box-shadow:
        0 1px 2px rgba(0, 0, 0, 0.4),
        0 24px 48px -26px rgba(0, 0, 0, 0.7);
}
.dash-ico {
    transition: transform 0.25s ease;
}
.dash-card:hover .dash-ico {
    transform: scale(1.08);
}
.dash-act {
    transition:
        background-color 0.2s ease,
        color 0.2s ease,
        transform 0.2s ease,
        border-color 0.2s ease;
}
.dash-act:hover {
    background-color: var(--color-primary);
    border-color: var(--color-primary);
    color: #fff;
    transform: translateY(-1px);
}
.dash-row td {
    transition:
        background-color 0.18s ease,
        box-shadow 0.18s ease;
}
.dash-row:hover td {
    background-color: color-mix(
        in oklab,
        var(--color-primary) 5%,
        var(--color-white)
    );
}
.dash-row:hover td:first-child {
    box-shadow: inset 3px 0 0 var(--color-primary);
}
.dash-noti {
    transition: background-color 0.2s ease;
}
.dash-noti:hover {
    background-color: color-mix(in oklab, var(--color-primary) 6%, transparent);
}
.dash-btn {
    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease,
        filter 0.2s ease;
}
.dash-btn:hover {
    transform: translateY(-1px);
}
.dash-bar {
    transition: width 0.7s cubic-bezier(0.22, 1, 0.36, 1);
}
@media (prefers-reduced-motion: reduce) {
    .dash-card,
    .dash-card:hover,
    .dash-ico,
    .dash-card:hover .dash-ico,
    .dash-act,
    .dash-act:hover,
    .dash-btn,
    .dash-btn:hover {
        transition: none;
        transform: none;
    }
}

