    color: var(--ca-text);
    box-shadow: 0 1px 3px rgba(15, 23, 42, 0.15);
}

/* =====================================================================
   HIDDEN MENU LAYOUT DEMO  ·  layout-hidden.html (page-exclusive)
   Keeps the sidebar off-canvas by default on every breakpoint, reusing
   the existing .slide-nav / .sidebar-overlay toggle mechanism.
   ===================================================================== */
@media (min-width: 1024px) {
    body[data-page="layout-hidden"] #sidebar {
        transform: translateX(-100%);
        transition: transform 0.3s ease-in-out;
    }
    body[data-page="layout-hidden"] .main-wrapper.slide-nav #sidebar {
        transform: translateX(0);
    }
    body[data-page="layout-hidden"] main,
    body[data-page="layout-hidden"] header {
        margin-left: 0 !important;
    }
}

/* =====================================================================
   FULL WIDTH LAYOUT DEMO  ·  layout-fullwidth.html (page-exclusive)
   Sidebar hidden off-canvas by default so content spans the full browser
   width; the #menu_btn next to the header search reuses the same
   .slide-nav / .sidebar-overlay toggle mechanism as Hidden Menu to bring
   it back on demand, overlaying the content rather than pushing it over.
   ===================================================================== */
@media (min-width: 1024px) {
    body[data-page="layout-fullwidth"] #sidebar {
        transform: translateX(-100%);
        transition: transform 0.3s ease-in-out;
    }
    body[data-page="layout-fullwidth"] .main-wrapper.slide-nav #sidebar {
        transform: translateX(0);
    }
    body[data-page="layout-fullwidth"] main,
    body[data-page="layout-fullwidth"] header {
        margin-left: 0 !important;
    }
}

/* =====================================================================
   RTL LAYOUT DEMO  ·  layout-rtl.html (page-exclusive)
   Mirrors the sidebar to the right edge and offsets the header/main from
   the right instead of the left, to match this page's dir="rtl" preview.
   ===================================================================== */
@media (min-width: 1024px) {
    body[data-page="layout-rtl"] .sidebar {
        left: auto;
        right: 0;
    }
    body[data-page="layout-rtl"] header,
    body[data-page="layout-rtl"] main {
        margin-left: 0;
        margin-right: var(--sidenav-width);
    }
    body[data-page="layout-rtl"] .sidebar .sidebar-menu > ul > li.submenu > a{
        padding: 8px 8px 8px 34px;
    }
    body[data-page="layout-rtl"] .sidebar .sidebar-logo #toggle_btn.sb-toggle.active {
        right: auto;
        left: -18px;
    }
}
body[data-page="layout-rtl"] .sidebar .sidebar-menu .menu-arrow {
    right: auto;
    left: 0.625rem;
}

