    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--color-gray-400, #94a3b8);
    padding: 0.75rem 1rem;
    border-bottom: 1px solid var(--color-border-color);
    white-space: nowrap;
    background: color-mix(in oklab, var(--color-gray-500) 5%, transparent);
}
.apt-table tbody td {
    padding: 0.7rem 1rem;
    border-bottom: 1px solid var(--color-border-color);
    font-size: 0.82rem;
    color: var(--color-gray-900);
    vertical-align: middle;
    white-space: nowrap;
}
.apt-table tbody tr {
    transition: background 0.15s ease;
}
.apt-table tbody tr:hover {
    background: color-mix(in oklab, var(--color-primary) 5%, transparent);
}
.apt-table tbody tr.is-selected {
    background: color-mix(in oklab, var(--color-primary) 9%, transparent);
}
.apt-check {
    width: 1.05rem;
    height: 1.05rem;
    border-radius: 0.35rem;
    accent-color: var(--color-primary);
    cursor: pointer;
}

.apt-menu {
    position: absolute;
    z-index: 1100;
    min-width: 14rem;
    max-height: 26rem;
    overflow-y: auto;
    padding: 0.4rem;
    border-radius: 1rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 30px 60px -24px rgba(2, 12, 40, 0.5);
    animation: apt-pop 0.16s ease;
}
@keyframes apt-pop {
    from {
        opacity: 0;
        transform: translateY(-6px) scale(0.97);
    }
}
.apt-menu button,
.apt-menu a {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    width: 100%;
    padding: 0.45rem 0.55rem;
    border-radius: 0.55rem;
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--color-gray-900);
    text-align: left;
    transition:
        background 0.14s ease,
        color 0.14s ease;
}
.apt-menu button:hover,
.apt-menu a:hover {
    background: color-mix(in oklab, var(--color-primary) 8%, transparent);
    color: var(--color-primary-text);
}
.apt-menu .danger {
    color: #e11d48;
}
.apt-menu .danger:hover {
    background: rgba(244, 63, 94, 0.1);
}
.apt-menu-sep {
    height: 1px;
    margin: 0.3rem 0.2rem;
    background: var(--color-border-color);
}
.apt-menu-lbl {
    padding: 0.4rem 0.55rem 0.15rem;
    font-size: 0.58rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--color-gray-400, #94a3b8);
}

.apt-drawer {
    position: fixed;
    inset: 0;
    z-index: 1200;
    visibility: hidden;
}
.apt-drawer.open {
    visibility: visible;
}
.apt-drawer-back {
    position: absolute;
    inset: 0;
    background: rgba(8, 12, 30, 0.5);
    opacity: 0;
    transition: opacity 0.3s ease;
}
.apt-drawer.open .apt-drawer-back {
    opacity: 1;
}
.apt-drawer-panel {
    position: absolute;
    top: 0;
    right: 0;
    height: 100%;
    width: min(480px, 94vw);
    background: var(--color-white);
    box-shadow: -30px 0 60px -30px rgba(2, 12, 40, 0.55);
    transform: translateX(100%);
    transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1);
    display: flex;
    flex-direction: column;
}
.apt-drawer.open .apt-drawer-panel {
    transform: translateX(0);
}
.apt-drawer-panel.left {
    right: auto;
    left: 0;
    transform: translateX(-100%);
    box-shadow: 30px 0 60px -30px rgba(2, 12, 40, 0.55);
}
.apt-drawer.open .apt-drawer-panel.left {
    transform: translateX(0);
}
.apt-drawer-hero {
    position: relative;
    padding: 1.5rem;
    color: #fff;
    background:
        radial-gradient(
            120% 130% at 100% 0%,
            rgba(6, 182, 212, 0.55),
            transparent 55%
        ),
        linear-gradient(135deg, #4f46e5, #0f172a);
}

.apt-modal {
    position: fixed;
    inset: 0;
    z-index: 1300;
    display: none;
    align-items: center;
    justify-content: center;
    padding: 1rem;
}
.apt-modal.open {
    display: flex;
}
.apt-modal-back {
    position: absolute;
    inset: 0;
    background: rgba(8, 12, 30, 0.5);
    -webkit-backdrop-filter: blur(3px);
    backdrop-filter: blur(3px);
    animation: apt-fadein 0.2s ease;
}
@keyframes apt-fadein {
    from {
        opacity: 0;
    }
}
.apt-modal-panel {
    position: relative;
    width: 100%;
    max-width: 37rem;
    max-height: 90vh;
    overflow-y: auto;
    border-radius: 1.25rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 40px 80px -30px rgba(2, 12, 40, 0.6);
    animation: apt-modin 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes apt-modin {
    from {
        opacity: 0;
        transform: translateY(16px) scale(0.97);
    }
}
.apt-doc-ico {
    display: grid;
    place-items: center;
    width: 2.75rem;
    height: 2.75rem;
    border-radius: 0.8rem;
    color: var(--apt-c);
    font-size: 1.15rem;
    background: color-mix(in oklab, var(--apt-c) 14%, transparent);
}

.apt-bulk {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.55rem;
    padding: 0.7rem 0.9rem;
    border-radius: 1.25rem;
    background: color-mix(in oklab, var(--color-white) 85%, transparent);
    -webkit-backdrop-filter: blur(16px);
    backdrop-filter: blur(16px);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 12px 28px -18px rgba(15, 23, 42, 0.45);
    animation: apt-bulk-in 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes apt-bulk-in {
    from {
        opacity: 0;
        transform: translateY(-8px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}
.apt-bulk-btn {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.4rem 0.7rem;
    border-radius: 0.7rem;
    font-size: 0.76rem;
    font-weight: 700;
    color: var(--color-gray-700, #374151);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.15s ease;
    white-space: nowrap;
}
.dark .apt-bulk-btn {
    color: var(--color-gray-900);
}
.apt-bulk-btn:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.apt-bulk-btn.danger {
    color: #e11d48;
}
.apt-bulk-btn.danger:hover {
    border-color: #e11d48;
    background: rgba(244, 63, 94, 0.08);
}

.apt-pg {
    display: grid;
    place-items: center;
    min-width: 2.1rem;
    height: 2.1rem;
    padding: 0 0.5rem;
    border-radius: 0.6rem;
    font-size: 0.8rem;
    font-weight: 700;
    color: var(--color-gray-600, #475569);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.15s ease;
    cursor: pointer;
}
.apt-pg:hover:not(:disabled) {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.apt-pg.is-active {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    border-color: transparent;
}
.apt-pg:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

.apt-bar {
    height: 0.5rem;
    border-radius: 9999px;
    background: color-mix(in oklab, var(--apt-c) 14%, transparent);
    overflow: hidden;
}
.apt-bar > i {
    display: block;
    height: 100%;
    border-radius: 9999px;
    background: linear-gradient(
        90deg,
        var(--apt-c),
        color-mix(in oklab, var(--apt-c) 55%, #6366f1)
    );
}
.apt-recent {
    display: flex;
    align-items: center;
    gap: 0.7rem;
    padding: 0.6rem;
    border-radius: 0.8rem;
    transition: background 0.15s ease;
}
.apt-recent:hover {
    background: color-mix(in oklab, var(--color-primary) 6%, transparent);
}

/* calendar */
.apt-cal {
    display: grid;
    grid-template-columns: repeat(7, minmax(0, 1fr));
    gap: 0.4rem;
}
.apt-cal-dow {
    text-align: center;
    font-size: 0.64rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--color-gray-400, #94a3b8);
    padding-bottom: 0.25rem;
}
.apt-day {
    position: relative;
    min-height: 5rem;
    border-radius: 0.8rem;
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    padding: 0.4rem;
    cursor: pointer;
    transition:
        transform 0.15s ease,
        border-color 0.15s ease,
        box-shadow 0.15s ease;
    overflow: hidden;
}
.apt-day:hover {
    transform: translateY(-2px);
    border-color: color-mix(
        in oklab,
        var(--color-primary) 40%,
        var(--color-border-color)
    );
    box-shadow: 0 10px 22px -16px rgba(15, 23, 42, 0.5);
}
.apt-day.muted {
    opacity: 0.45;
}
.apt-day.today {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 1px var(--color-primary) inset;
}
.apt-day.is-active {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 2px
        color-mix(in oklab, var(--color-primary) 35%, transparent);
}
.apt-day .num {
    font-size: 0.72rem;
    font-weight: 800;
    color: var(--color-gray-900);
}
.apt-pill {
    display: block;
    margin-top: 0.2rem;
    padding: 0.08rem 0.3rem;
    border-radius: 0.35rem;
    font-size: 0.58rem;
    font-weight: 700;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.apt-in {
    width: 100%;
    padding: 0.65rem 0.8rem;
    border-radius: 0.7rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.85rem;
    font-weight: 600;
    outline: none;
    transition:
        border-color 0.16s ease,
        box-shadow 0.16s ease;
}
.apt-in:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 4px
        color-mix(in oklab, var(--color-primary) 14%, transparent);
}
.apt-lbl {
    display: block;
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--color-gray-500);
    margin-bottom: 0.3rem;
}
.apt-avail {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.12rem 0.5rem;
    border-radius: 9999px;
    font-size: 0.6rem;
    font-weight: 800;
    text-transform: uppercase;
}
.apt-avail.on {
    color: #059669;
    background: rgba(16, 185, 129, 0.15);
}
.apt-avail.busy {
    color: #d97706;
    background: rgba(245, 158, 11, 0.15);
}
.apt-avail.off {
    color: #64748b;
    background: rgba(100, 116, 139, 0.15);
}
.apt-slot {
    padding: 0.4rem;
    border-radius: 0.55rem;
    border: 1px solid var(--color-border-color);
    font-size: 0.72rem;
    font-weight: 700;
    text-align: center;
    cursor: pointer;
    transition: all 0.14s ease;
}
.apt-slot:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.apt-slot.taken {
    opacity: 0.4;
    text-decoration: line-through;
    cursor: not-allowed;
}
.apt-slot.sel {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    border-color: transparent;
}

.apt-c-indigo {
    --apt-c: #6366f1;
}
.apt-c-sky {
    --apt-c: #0ea5e9;
}
.apt-c-rose {
    --apt-c: #f43f5e;
}
.apt-c-amber {
    --apt-c: #f59e0b;
}
.apt-c-emerald {
    --apt-c: #10b981;
}
.apt-c-violet {
    --apt-c: #8b5cf6;
}
.apt-c-teal {
    --apt-c: #14b8a6;
}
.apt-c-primary {
    --apt-c: var(--color-primary);
}
.apt-c-cyan {
    --apt-c: #06b6d4;
}

.apt-sk {
    position: relative;
    overflow: hidden;
    background: color-mix(in oklab, var(--color-gray-500) 12%, transparent);
    border-radius: 0.75rem;
}
.apt-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in oklab, var(--color-white) 55%, transparent),
        transparent
    );
    animation: apt-shimmer 1.4s infinite;
}
.dark .apt-sk::after {
    background: linear-gradient(
        90deg,
        transparent,
        rgba(255, 255, 255, 0.06),
        transparent
    );
}
@keyframes apt-shimmer {
    100% {
        transform: translateX(100%);
    }
}

.apt-toast {
    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    z-index: 2000;
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.8rem 1.1rem;
    border-radius: 0.9rem;
    font-size: 0.85rem;
    font-weight: 700;
    color: #fff;
    box-shadow: 0 20px 45px -18px rgba(0, 0, 0, 0.5);
    animation: apt-toastin 0.25s ease;
}
@keyframes apt-toastin {
    from {
        opacity: 0;
        transform: translateY(12px);
    }
}
.apt-toast.success {
    background: linear-gradient(135deg, #6366f1, #4f46e5);
}
.apt-toast.info {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
}
.apt-toast.error {
    background: linear-gradient(135deg, #f43f5e, #e11d48);
}

/* cascade-safe per-instance modifiers (unlayered — see CASCADE-SAFE OVERRIDE UTILITIES note) */
.apt-hbadge-cyan {
    background: rgba(6, 182, 212, 0.18);
    border-color: rgba(6, 182, 212, 0.4);
}
.apt-hbadge-rose {
    background: rgba(244, 63, 94, 0.18);
    border-color: rgba(244, 63, 94, 0.4);
}
.apt-ring-lg {
    width: 4.5rem;
    height: 4.5rem;
}
.apt-btn-sm {
    padding: 0.45rem 0.8rem;
}
.apt-tool-compact {
    padding: 0.35rem 0.6rem;
}
.apt-tool-compact-sm {
    padding: 0.35rem 0.5rem;
}

@media (prefers-reduced-motion: reduce) {
    .apt-btn,
    .apt-stat,
    .apt-card,
    .apt-day,
    .apt-ring .bar,
    .apt-dot,
    .apt-sk::after,
    .apt-icobtn,
    .apt-mini,
    .apt-drawer-panel,
    .apt-bulk {
        transition: none;
        animation: none;
    }
    .apt-btn:hover,
    .apt-stat:hover,
    .apt-card:hover,
    .apt-day:hover,
    .apt-icobtn:hover,
    .apt-mini:hover {
        transform: none;
    }
}
@media print {
    .sidebar,
    header.navbar-header,
    .apt-print-hide {
        display: none !important;
    }
}

/* ============================================================
   PATIENT VISIT MANAGEMENT CENTER · patient-visits.html (page-exclusive)
   Do not reuse these classes in other modules.
   ============================================================ */
/* ================================================================
   PATIENT VISIT MANAGEMENT CENTER — self-contained (inline).
   Design-system CSS variables → automatic light / dark.
   ================================================================ */
#pv-page {
    --pv-c: var(--color-primary);
}
.pv-surface {
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    border-radius: 1.25rem;
    box-shadow: 0 20px 45px -35px rgba(15, 23, 42, 0.4);
}

.pv-layout {
    display: grid;
    grid-template-columns: 1fr;
    gap: 1.25rem;
    align-items: start;
}
@media (min-width: 1280px) {
    .pv-layout {
        grid-template-columns: minmax(0, 1fr) 340px;
    }
}
.pv-grid {
    display: grid;
    gap: 0.9rem;
}
.pv-g3 {
    grid-template-columns: repeat(1, minmax(0, 1fr));
}
.pv-g6 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
}
@media (min-width: 640px) {
    .pv-g3 {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}
@media (min-width: 900px) {
    .pv-g3 {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
    .pv-g6 {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}
@media (min-width: 1200px) {
    .pv-g6 {
        grid-template-columns: repeat(6, minmax(0, 1fr));
    }
}
.pv-cards {
    display: grid;
    gap: 1rem;
    grid-template-columns: 1fr;
}
.pv-cards.hidden {
    display: none;
}
@media (min-width: 700px) {
    .pv-cards {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}
@media (min-width: 1500px) {
    .pv-cards {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}

.pv-hero {
    position: relative;
    overflow: hidden;
    border-radius: 1.5rem;
    padding: 1.75rem;
    color: #fff;
    background:
        radial-gradient(
            120% 140% at 0% 0%,
            rgba(20, 184, 166, 0.5),
            transparent 55%
        ),
        radial-gradient(
            120% 160% at 100% 0%,
            rgba(59, 130, 246, 0.55),
            transparent 50%
        ),
        linear-gradient(135deg, #0f172a, #0c2a3a 55%, #0b1220);
    box-shadow: 0 30px 60px -30px rgba(15, 23, 42, 0.7);
}
.pv-hero::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image: radial-gradient(
        rgba(255, 255, 255, 0.08) 1px,
        transparent 1px
    );
    background-size: 22px 22px;
    -webkit-mask-image: linear-gradient(180deg, #000, transparent 75%);
    mask-image: linear-gradient(180deg, #000, transparent 75%);
}
.pv-hero > * {
    position: relative;
    z-index: 1;
}
@media (min-width: 1024px) {
    .pv-hero {
        padding: 2rem 2.25rem;
    }
}
.pv-hbadge {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.25rem 0.7rem;
    border-radius: 9999px;
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    background: rgba(255, 255, 255, 0.14);
    border: 1px solid rgba(255, 255, 255, 0.22);
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
}
.pv-hmeta {
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
    padding: 0.45rem 0.8rem;
    border-radius: 0.8rem;
    background: rgba(255, 255, 255, 0.1);
    border: 1px solid rgba(255, 255, 255, 0.16);
    font-size: 0.72rem;
    font-weight: 700;
}
.pv-dot {
    width: 0.5rem;
    height: 0.5rem;
    border-radius: 9999px;
    background: #2dd4bf;
    box-shadow: 0 0 0 4px rgba(45, 212, 191, 0.25);
    animation: pv-pulse 2s ease-in-out infinite;
}
@keyframes pv-pulse {
    0%,
    100% {
        opacity: 1;
    }
    50% {
        opacity: 0.4;
    }
}

.pv-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    padding: 0.55rem 0.9rem;
    border-radius: 0.8rem;
    font-size: 0.8rem;
    font-weight: 700;
    cursor: pointer;
    border: 1px solid transparent;
    white-space: nowrap;
    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease,
        background 0.2s ease,
        color 0.2s ease,
        border-color 0.2s ease;
}
.pv-btn:hover {
    transform: translateY(-2px);
}
.pv-btn-primary {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    box-shadow: 0 12px 24px -12px var(--color-primary);
}
.pv-btn-success {
    background: linear-gradient(135deg, #14b8a6, #0d9488);
    color: #fff;
    box-shadow: 0 12px 24px -12px #14b8a6;
}
.pv-btn-glass {
    background: rgba(255, 255, 255, 0.12);
    color: #fff;
    border-color: rgba(255, 255, 255, 0.24);
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
}
.pv-btn-glass:hover {
    background: rgba(255, 255, 255, 0.2);
}
.pv-btn-solid {
    background: var(--color-white);
    color: var(--color-gray-900);
    border-color: var(--color-border-color);
}
.pv-btn-solid:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.pv-btn-danger {
    background: #e11d48;
    color: #fff;
}
.pv-icobtn {
    display: grid;
    place-items: center;
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 0.75rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-500);
    cursor: pointer;
    transition: all 0.16s ease;
    flex-shrink: 0;
}
.pv-icobtn:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
    transform: translateY(-1px);
}

.pv-stat {
    position: relative;
    overflow: hidden;
    border-radius: 1.25rem;
    padding: 1.1rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 18px 40px -30px rgba(15, 23, 42, 0.45);
    transition:
        transform 0.25s ease,
        box-shadow 0.25s ease,
        border-color 0.25s ease;
}
.pv-stat::after {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(
        135deg,
        color-mix(in oklab, var(--pv-c) 12%, transparent),
        transparent 60%
    );
    pointer-events: none;
}
.pv-stat:hover {
    transform: translateY(-4px);
    box-shadow: 0 26px 50px -26px
        color-mix(in oklab, var(--pv-c) 55%, rgba(15, 23, 42, 0.5));
    border-color: color-mix(
        in oklab,
        var(--pv-c) 40%,
        var(--color-border-color)
    );
}
.pv-stat > * {
    position: relative;
    z-index: 1;
}
.pv-stat-ico {
    display: grid;
    place-items: center;
    width: 2.9rem;
    height: 2.9rem;
    border-radius: 0.9rem;
    color: #fff;
    font-size: 1.15rem;
    background: linear-gradient(
        135deg,
        var(--pv-c),
        color-mix(in oklab, var(--pv-c) 55%, #6366f1)
    );
    box-shadow: 0 10px 20px -10px var(--pv-c);
}
.pv-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.15rem 0.5rem;
    border-radius: 9999px;
    font-size: 0.62rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    color: color-mix(in oklab, var(--pv-c) 70%, #1e293b);
    background: color-mix(in oklab, var(--pv-c) 16%, transparent);
}
.dark .pv-chip {
    color: color-mix(in oklab, var(--pv-c) 55%, #fff);
}
.pv-ring {
    --p: 0;
    width: 3rem;
    height: 3rem;
    transform: rotate(-90deg);
}
.pv-ring circle {
    fill: none;
    stroke-width: 4;
}
.pv-ring .trk {
    stroke: color-mix(in oklab, var(--pv-c) 16%, transparent);
}
.pv-ring .bar {
    stroke: var(--pv-c);
    stroke-linecap: round;
    stroke-dasharray: 100 100;
    stroke-dashoffset: calc(100 - var(--p));
    transition: stroke-dashoffset 0.9s cubic-bezier(0.16, 1, 0.3, 1);
}

.pv-head {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 1rem 1.15rem;
    border-bottom: 1px solid var(--color-border-color);
}
.pv-head .ico {
    display: grid;
    place-items: center;
    width: 2.3rem;
    height: 2.3rem;
    border-radius: 0.75rem;
    color: #fff;
    font-size: 0.95rem;
    background: linear-gradient(
        135deg,
        color-mix(in oklab, var(--pv-c) 90%, #000),
        color-mix(in oklab, var(--pv-c) 55%, #6366f1)
    );
    box-shadow: 0 10px 18px -12px var(--pv-c);
    flex-shrink: 0;
}
.pv-title {
    font-weight: 800;
    color: var(--color-gray-900);
    font-size: 0.9rem;
}

.pv-search {
    position: relative;
    flex: 1 1 220px;
    min-width: 180px;
}
.pv-search input {
    width: 100%;
    padding: 0.6rem 0.9rem 0.6rem 2.5rem;
    border-radius: 0.85rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.85rem;
    font-weight: 600;
    outline: none;
    transition:
        border-color 0.18s ease,
        box-shadow 0.18s ease;
}
.pv-search input:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 4px
        color-mix(in oklab, var(--color-primary) 14%, transparent);
}
.pv-search .ico {
    position: absolute;
    left: 0.85rem;
    top: 50%;
    transform: translateY(-50%);
    color: var(--color-gray-400, #94a3b8);
    pointer-events: none;
}
.pv-tool {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.55rem 0.8rem;
    border-radius: 0.8rem;
    font-size: 0.8rem;
    font-weight: 700;
    cursor: pointer;
    white-space: nowrap;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-600, #475569);
    transition:
        border-color 0.18s ease,
        color 0.18s ease,
        transform 0.18s ease;
}
.pv-tool:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
    transform: translateY(-1px);
}
.pv-seg {
    display: inline-flex;
    padding: 0.25rem;
    border-radius: 0.85rem;
    background: color-mix(in oklab, var(--color-gray-500) 14%, transparent);
}
.pv-seg button {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.4rem 0.7rem;
    border-radius: 0.65rem;
    font-size: 0.78rem;
    font-weight: 700;
    color: var(--color-gray-500);
    transition: all 0.18s ease;
}
.pv-seg button.is-active {
    background: var(--color-white);
    color: var(--color-primary-text);
    box-shadow: 0 4px 10px -6px rgba(15, 23, 42, 0.4);
}

.pv-card {
    position: relative;
    overflow: hidden;
    border-radius: 1.25rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 18px 40px -32px rgba(15, 23, 42, 0.5);
    transition:
        transform 0.25s ease,
        box-shadow 0.25s ease,
        border-color 0.25s ease;
}
.pv-card::before {
    content: "";
    position: absolute;
    inset: 0 0 auto 0;
    height: 3px;
    background: linear-gradient(
        90deg,
        var(--pv-c),
        color-mix(in oklab, var(--pv-c) 40%, #6366f1)
    );
}
.pv-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 26px 48px -26px
        color-mix(in oklab, var(--pv-c) 45%, rgba(15, 23, 42, 0.5));
    border-color: color-mix(
        in oklab,
        var(--pv-c) 35%,
        var(--color-border-color)
    );
}
.pv-card.is-selected {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 2px
        color-mix(in oklab, var(--color-primary) 40%, transparent);
}
.pv-ava {
    width: 3rem;
    height: 3rem;
    border-radius: 0.85rem;
    display: grid;
    place-items: center;
    color: #fff;
    font-weight: 800;
    font-size: 0.95rem;
    background: linear-gradient(
        135deg,
        var(--pv-c),
        color-mix(in oklab, var(--pv-c) 55%, #6366f1)
    );
}
.pv-ava-ring {
    padding: 2px;
    border-radius: 1rem;
    background: linear-gradient(
        135deg,
        var(--pv-c),
        color-mix(in oklab, var(--pv-c) 40%, #6366f1)
    );
    flex-shrink: 0;
}

.pv-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.15rem 0.55rem;
    border-radius: 9999px;
    font-size: 0.64rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    white-space: nowrap;
}
.pv-badge.completed {
    color: #059669;
    background: rgba(16, 185, 129, 0.15);
}
.pv-badge.ongoing {
    color: var(--color-primary-text);
    background: color-mix(in oklab, var(--color-primary) 15%, transparent);
}
.pv-badge.waiting {
    color: #d97706;
    background: rgba(245, 158, 11, 0.15);
}
.pv-badge.scheduled {
    color: #0284c7;
    background: rgba(14, 165, 233, 0.15);
}
.pv-badge.cancelled {
    color: #e11d48;
    background: rgba(244, 63, 94, 0.15);
}
.pv-tag {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.1rem 0.45rem;
    border-radius: 0.5rem;
    font-size: 0.62rem;
    font-weight: 700;
    background: color-mix(in oklab, var(--pv-c) 14%, transparent);
    color: var(--pv-c);
}
.pv-prio {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.1rem 0.5rem;
    border-radius: 9999px;
    font-size: 0.6rem;
    font-weight: 800;
    text-transform: uppercase;
}
.pv-prio.high {
    color: #e11d48;
    background: rgba(244, 63, 94, 0.14);
}
.pv-prio.medium {
    color: #d97706;
    background: rgba(245, 158, 11, 0.14);
}
.pv-prio.low {
    color: #059669;
    background: rgba(16, 185, 129, 0.14);
}
.pv-mini {
    display: grid;
    place-items: center;
    width: 2rem;
    height: 2rem;
    border-radius: 0.6rem;
    color: var(--color-gray-500);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.16s ease;
}
.pv-mini:hover {
    border-color: var(--pv-c);
    color: var(--pv-c);
    transform: translateY(-1px);
}
.pv-kv {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    font-size: 0.72rem;
    color: var(--color-gray-500);
    min-width: 0;
}
.pv-kv b {
    color: var(--color-gray-900);
    font-weight: 700;
}

.pv-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0;
}
.pv-table thead th {
    text-align: left;
    font-size: 0.66rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--color-gray-400, #94a3b8);
    padding: 0.75rem 1rem;
    border-bottom: 1px solid var(--color-border-color);
    white-space: nowrap;
    background: color-mix(in oklab, var(--color-gray-500) 5%, transparent);
}
.pv-table tbody td {
    padding: 0.7rem 1rem;
    border-bottom: 1px solid var(--color-border-color);
    font-size: 0.82rem;
    color: var(--color-gray-900);
    vertical-align: middle;
    white-space: nowrap;
}
.pv-table tbody tr {
    transition: background 0.15s ease;
}
.pv-table tbody tr:hover {
    background: color-mix(in oklab, var(--color-primary) 5%, transparent);
}
.pv-table tbody tr.is-selected {
    background: color-mix(in oklab, var(--color-primary) 9%, transparent);
}
.pv-check {
    width: 1.05rem;
    height: 1.05rem;
    border-radius: 0.35rem;
    accent-color: var(--color-primary);
    cursor: pointer;
}

.pv-menu {
    position: absolute;
    z-index: 1100;
    min-width: 15rem;
    max-height: 26rem;
    overflow-y: auto;
    padding: 0.4rem;
    border-radius: 1rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 30px 60px -24px rgba(2, 12, 40, 0.5);
    animation: pv-pop 0.16s ease;
}
@keyframes pv-pop {
    from {
        opacity: 0;
        transform: translateY(-6px) scale(0.97);
    }
}
.pv-menu button,
.pv-menu a {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    width: 100%;
    padding: 0.45rem 0.55rem;
    border-radius: 0.55rem;
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--color-gray-900);
    text-align: left;
    transition:
        background 0.14s ease,
        color 0.14s ease;
}
.pv-menu button:hover,
.pv-menu a:hover {
    background: color-mix(in oklab, var(--color-primary) 8%, transparent);
    color: var(--color-primary-text);
}
.pv-menu .danger {
    color: #e11d48;
}
.pv-menu .danger:hover {
    background: rgba(244, 63, 94, 0.1);
}
.pv-menu-sep {
    height: 1px;
    margin: 0.3rem 0.2rem;
    background: var(--color-border-color);
}
.pv-menu-lbl {
    padding: 0.4rem 0.55rem 0.15rem;
    font-size: 0.58rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--color-gray-400, #94a3b8);
}

.pv-drawer {
    position: fixed;
    inset: 0;
    z-index: 1200;
    visibility: hidden;
}
.pv-drawer.open {
    visibility: visible;
}
.pv-drawer-back {
    position: absolute;
    inset: 0;
    background: rgba(8, 12, 30, 0.5);
    opacity: 0;
    transition: opacity 0.3s ease;
}
.pv-drawer.open .pv-drawer-back {
    opacity: 1;
}
.pv-drawer-panel {
    position: absolute;
    top: 0;
    right: 0;
    height: 100%;
    width: min(490px, 94vw);
    background: var(--color-white);
    box-shadow: -30px 0 60px -30px rgba(2, 12, 40, 0.55);
    transform: translateX(100%);
    transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1);
    display: flex;
    flex-direction: column;
}
.pv-drawer.open .pv-drawer-panel {
    transform: translateX(0);
}
.pv-drawer-panel.left {
    right: auto;
    left: 0;
    transform: translateX(-100%);
    box-shadow: 30px 0 60px -30px rgba(2, 12, 40, 0.55);
}
.pv-drawer.open .pv-drawer-panel.left {
    transform: translateX(0);
}
.pv-drawer-hero {
    position: relative;
    padding: 1.5rem;
    color: #fff;
    background:
        radial-gradient(
            120% 130% at 100% 0%,
            rgba(20, 184, 166, 0.6),
            transparent 55%
        ),
        linear-gradient(135deg, #4f46e5, #0f172a);
}

.pv-modal {
    position: fixed;
    inset: 0;
    z-index: 1300;
    display: none;
    align-items: center;
    justify-content: center;
    padding: 1rem;
}
.pv-modal.open {
    display: flex;
}
.pv-modal-back {
    position: absolute;
    inset: 0;
    background: rgba(8, 12, 30, 0.5);
    -webkit-backdrop-filter: blur(3px);
    backdrop-filter: blur(3px);
    animation: pv-fadein 0.2s ease;
}
@keyframes pv-fadein {
    from {
        opacity: 0;
    }
}
.pv-modal-panel {
    position: relative;
    width: 100%;
    max-width: 36rem;
    max-height: 90vh;
    overflow-y: auto;
    border-radius: 1.25rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 40px 80px -30px rgba(2, 12, 40, 0.6);
    animation: pv-modin 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes pv-modin {
    from {
        opacity: 0;
        transform: translateY(16px) scale(0.97);
    }
}
.pv-doc-ico {
    display: grid;
    place-items: center;
    width: 2.75rem;
    height: 2.75rem;
    border-radius: 0.8rem;
    color: var(--pv-c);
    font-size: 1.15rem;
    background: color-mix(in oklab, var(--pv-c) 14%, transparent);
}

.pv-bulk {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.55rem;
    padding: 0.7rem 0.9rem;
    border-radius: 1.25rem;
    background: color-mix(in oklab, var(--color-white) 85%, transparent);
    -webkit-backdrop-filter: blur(16px);
    backdrop-filter: blur(16px);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 12px 28px -18px rgba(15, 23, 42, 0.45);
    animation: pv-bulk-in 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes pv-bulk-in {
    from {
        opacity: 0;
        transform: translateY(-8px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}
.pv-bulk-btn {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.4rem 0.7rem;
    border-radius: 0.7rem;
    font-size: 0.76rem;
    font-weight: 700;
    color: var(--color-gray-700, #374151);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.15s ease;
    white-space: nowrap;
}
.dark .pv-bulk-btn {
    color: var(--color-gray-900);
}
.pv-bulk-btn:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.pv-bulk-btn.danger {
    color: #e11d48;
}
.pv-bulk-btn.danger:hover {
    border-color: #e11d48;
    background: rgba(244, 63, 94, 0.08);
}

.pv-pg {
    display: grid;
    place-items: center;
    min-width: 2.1rem;
    height: 2.1rem;
    padding: 0 0.5rem;
    border-radius: 0.6rem;
    font-size: 0.8rem;
    font-weight: 700;
    color: var(--color-gray-600, #475569);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.15s ease;
    cursor: pointer;
}
.pv-pg:hover:not(:disabled) {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.pv-pg.is-active {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    border-color: transparent;
}
.pv-pg:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

/* horizontal visit stage strip */
.pv-stage {
    display: flex;
    align-items: center;
    gap: 0.25rem;
    overflow-x: auto;
    scrollbar-width: none;
}
.pv-stage::-webkit-scrollbar {
    display: none;
}
.pv-stage-step {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.4rem;
    min-width: 4.75rem;
    text-align: center;
}
.pv-stage-node {
    display: grid;
    place-items: center;
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 9999px;
    font-size: 0.85rem;
    color: var(--color-gray-500);
    background: color-mix(in oklab, var(--color-gray-500) 14%, transparent);
}
.pv-stage-step.done .pv-stage-node {
    background: linear-gradient(135deg, #14b8a6, #0d9488);
    color: #fff;
}
.pv-stage-step.active .pv-stage-node {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    box-shadow: 0 10px 20px -8px var(--color-primary);
}
.pv-stage-line {
    flex: 1 1 0.6rem;
    min-width: 0.6rem;
    height: 2px;
    border-radius: 2px;
    background: var(--color-border-color);
}
.pv-stage-line.done {
    background: linear-gradient(90deg, #14b8a6, #0d9488);
}

.pv-tl {
    position: relative;
    padding-left: 1.75rem;
}
.pv-tl::before {
    content: "";
    position: absolute;
    left: 0.72rem;
    top: 0.35rem;
    bottom: 0.35rem;
    width: 2px;
    background: linear-gradient(
        180deg,
        var(--pv-c, var(--color-primary)),
        color-mix(in oklab, var(--pv-c, var(--color-primary)) 20%, transparent)
    );
}
.pv-tl-item {
    position: relative;
    padding-bottom: 1.1rem;
}
.pv-tl-item:last-child {
    padding-bottom: 0;
}
.pv-tl-node {
    position: absolute;
    left: -1.75rem;
    top: 0.05rem;
    display: grid;
    place-items: center;
    width: 1.5rem;
    height: 1.5rem;
    border-radius: 9999px;
    color: #fff;
    font-size: 0.62rem;
    background: linear-gradient(
        135deg,
        var(--pv-c, var(--color-primary)),
        color-mix(in oklab, var(--pv-c, var(--color-primary)) 55%, #6366f1)
    );
    box-shadow: 0 0 0 3px
        color-mix(in oklab, var(--pv-c, var(--color-primary)) 16%, transparent);
}
.pv-tl-node.pending {
    background: var(--color-border-color);
    color: var(--color-gray-500);
    box-shadow: none;
}

.pv-bar {
    height: 0.5rem;
    border-radius: 9999px;
    background: color-mix(in oklab, var(--pv-c) 14%, transparent);
    overflow: hidden;
}
.pv-bar > i {
    display: block;
    height: 100%;
    border-radius: 9999px;
    background: linear-gradient(
        90deg,
        var(--pv-c),
        color-mix(in oklab, var(--pv-c) 55%, #6366f1)
    );
}

.pv-sum {
    position: relative;
    overflow: hidden;
    border-radius: 1rem;
    padding: 0.9rem;
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition:
        transform 0.2s ease,
        border-color 0.2s ease;
}
.pv-sum:hover {
    transform: translateY(-3px);
    border-color: color-mix(
        in oklab,
        var(--pv-c) 35%,
        var(--color-border-color)
    );
}
.pv-sum-ico {
    display: grid;
    place-items: center;
    width: 2.3rem;
    height: 2.3rem;
    border-radius: 0.7rem;
    font-size: 1rem;
    color: var(--pv-c);
    background: color-mix(in oklab, var(--pv-c) 14%, transparent);
}
.pv-avail {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.12rem 0.5rem;
    border-radius: 9999px;
    font-size: 0.6rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.03em;
}
.pv-avail.on {
    color: #059669;
    background: rgba(16, 185, 129, 0.15);
}
.pv-avail.busy {
    color: #d97706;
    background: rgba(245, 158, 11, 0.15);
}
.pv-avail.off {
    color: #64748b;
    background: rgba(100, 116, 139, 0.15);
}

.pv-in {
    width: 100%;
    padding: 0.65rem 0.8rem;
    border-radius: 0.7rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.85rem;
    font-weight: 600;
    outline: none;
    transition:
        border-color 0.16s ease,
        box-shadow 0.16s ease;
}
.pv-in:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 4px
        color-mix(in oklab, var(--color-primary) 14%, transparent);
}
.pv-lbl {
    display: block;
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--color-gray-500);
    margin-bottom: 0.3rem;
}
.pv-recent {
    display: flex;
    align-items: center;
    gap: 0.7rem;
    padding: 0.6rem;
    border-radius: 0.8rem;
    transition: background 0.15s ease;
}
.pv-recent:hover {
    background: color-mix(in oklab, var(--color-primary) 6%, transparent);
}

.pv-c-indigo {
    --pv-c: #6366f1;
}
.pv-c-sky {
    --pv-c: #0ea5e9;
}
.pv-c-rose {
    --pv-c: #f43f5e;
}
.pv-c-amber {
    --pv-c: #f59e0b;
}
.pv-c-emerald {
    --pv-c: #10b981;
}
.pv-c-violet {
    --pv-c: #8b5cf6;
}
.pv-c-teal {
    --pv-c: #14b8a6;
}
.pv-c-primary {
    --pv-c: var(--color-primary);
}

.pv-sk {
    position: relative;
    overflow: hidden;
    background: color-mix(in oklab, var(--color-gray-500) 12%, transparent);
    border-radius: 0.75rem;
}
.pv-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in oklab, var(--color-white) 55%, transparent),
        transparent
    );
    animation: pv-shimmer 1.4s infinite;
}
.dark .pv-sk::after {
    background: linear-gradient(
        90deg,
        transparent,
        rgba(255, 255, 255, 0.06),
        transparent
    );
}
@keyframes pv-shimmer {
    100% {
        transform: translateX(100%);
    }
}

.pv-toast {
    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    z-index: 2000;
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.8rem 1.1rem;
    border-radius: 0.9rem;
    font-size: 0.85rem;
    font-weight: 700;
    color: #fff;
    box-shadow: 0 20px 45px -18px rgba(0, 0, 0, 0.5);
    animation: pv-toastin 0.25s ease;
}
@keyframes pv-toastin {
    from {
        opacity: 0;
        transform: translateY(12px);
    }
}
.pv-toast.success {
    background: linear-gradient(135deg, #14b8a6, #0d9488);
}
.pv-toast.info {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
}
.pv-toast.error {
    background: linear-gradient(135deg, #f43f5e, #e11d48);
}

/* Per-instance modifiers (unlayered so they win over the shared .pv-hbadge/.pv-ring/.pv-tool defaults above) */
.pv-hbadge-indigo {
    background: rgba(99, 102, 241, 0.18);
    border-color: rgba(99, 102, 241, 0.4);
}
.pv-hbadge-amber {
    background: rgba(245, 158, 11, 0.18);
    border-color: rgba(245, 158, 11, 0.4);
}
.pv-ring-lg {
    width: 4.5rem;
    height: 4.5rem;
}
.pv-tool-sm {
    padding: 0.35rem 0.6rem;
}
.pv-tool-xs {
    padding: 0.35rem 0.5rem;
}

@media (prefers-reduced-motion: reduce) {
    .pv-btn,
    .pv-stat,
    .pv-card,
    .pv-sum,
    .pv-ring .bar,
    .pv-dot,
    .pv-sk::after,
    .pv-icobtn,
    .pv-mini,
    .pv-drawer-panel,
    .pv-bulk {
        transition: none;
        animation: none;
    }
    .pv-btn:hover,
    .pv-stat:hover,
    .pv-card:hover,
    .pv-sum:hover,
    .pv-icobtn:hover,
    .pv-mini:hover {
        transform: none;
    }
}
@media print {
    .sidebar,
    header.navbar-header,
    .pv-print-hide {
        display: none !important;
    }
}

/* ================================================================
   ICU BED MANAGEMENT & ALLOCATION COMMAND CENTER · icu-beds.html (page-exclusive)
   Namespace: ib-  ·  FULLY theme-aware (light widgets in light mode).
   Focus: bed operations / capacity — distinct from icu & icu-patients.
   Do not reuse these classes in other modules.
   ================================================================ */
body:has(#ib-page) {
    --ib-c: var(--color-primary);
    --ib-surface: var(--color-white);
    --ib-panel: var(--color-gray-50);
    --ib-border: var(--color-border-color);
    --ib-text: var(--color-gray-900);
    --ib-mut: var(--color-gray-500);
    --ib-elev: var(--color-white);
    --ib-hover: var(--color-gray-100);
    --ib-screen: #0a1120;
    --ib-track: color-mix(in srgb, var(--color-gray-500) 20%, transparent);
}
.dark body:has(#ib-page) {
    --ib-surface: #0b1120;
    --ib-panel: rgba(148, 163, 184, 0.06);
    --ib-border: rgba(148, 163, 184, 0.16);
    --ib-text: #e2e8f0;
    --ib-mut: #94a3b8;
    --ib-elev: #0d1526;
    --ib-hover: rgba(148, 163, 184, 0.12);
    --ib-track: rgba(148, 163, 184, 0.2);
}
.ib-card {
    background: var(--ib-surface);
    border: 1px solid var(--ib-border);
    border-radius: 1.25rem;
    color: var(--ib-text);
    box-shadow: 0 20px 45px -38px rgba(15, 23, 42, 0.35);
}
.ib-panel {
    background: var(--ib-panel);
    border: 1px solid var(--ib-border);
    border-radius: 1rem;
}
.ib-mut {
    color: var(--ib-mut);
}
.ib-head {
    color: var(--ib-text);
}

/* ---------- HERO ---------- */
.ib-hero {
    position: relative;
    overflow: hidden;
    border-radius: 1.25rem;
    color: #fff;
    background:
        radial-gradient(
            120% 90% at 0% 0%,
            rgba(99, 102, 241, 0.22),
            transparent 55%
        ),
        radial-gradient(
            120% 90% at 100% 0%,
            rgba(14, 165, 233, 0.2),
            transparent 50%
        ),
        linear-gradient(160deg, #0a0f1e, #111a33 60%, #0a0f1e);
    border: 1px solid rgba(148, 163, 184, 0.2);
    box-shadow: 0 30px 60px -30px rgba(2, 6, 15, 0.7);
}
.ib-hgrid {
    position: absolute;
    inset: 0;
    background-image:
        linear-gradient(rgba(148, 163, 184, 0.06) 1px, transparent 1px),
        linear-gradient(90deg, rgba(148, 163, 184, 0.06) 1px, transparent 1px);
    background-size: 26px 26px;
    pointer-events: none;
}
.ib-hstat {
    background: rgba(148, 163, 184, 0.08);
    border: 1px solid rgba(148, 163, 184, 0.18);
    border-radius: 0.9rem;
    padding: 0.6rem 0.8rem;
}

.ib-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.68rem;
    font-weight: 700;
    padding: 0.22rem 0.55rem;
    border-radius: 999px;
}
.ib-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    display: inline-block;
}
@keyframes ib-pulse {
    0%,
    100% {
        opacity: 1;
        transform: scale(1);
    }
    50% {
        opacity: 0.35;
        transform: scale(0.82);
    }
}
.ib-live {
    animation: ib-pulse 1.4s infinite;
}

/* bed status palette */
.bs-green {
    --bc: #16a34a;
}
.bs-blue {
    --bc: #2563eb;
}
.bs-yellow {
    --bc: #ca8a04;
}
.bs-orange {
    --bc: #ea580c;
}
.bs-red {
    --bc: #dc2626;
}
.bs-gray {
    --bc: #64748b;
}
.dark .bs-green {
    --bc: #22c55e;
}
.dark .bs-blue {
    --bc: #3b82f6;
}
.dark .bs-yellow {
    --bc: #eab308;
}
.dark .bs-orange {
    --bc: #f97316;
}
.dark .bs-red {
    --bc: #ef4444;
}
.dark .bs-gray {
    --bc: #94a3b8;
}

/* ---------- CAPACITY RIBBON ---------- */
.ib-ribbon {
    overflow: hidden;
    position: relative;
}
.ib-ribbon-track {
    display: flex;
    gap: 0.6rem;
    width: max-content;
    animation: ib-marquee 30s linear infinite;
}
.ib-ribbon:hover .ib-ribbon-track {
    animation-play-state: paused;
}
@keyframes ib-marquee {
    from {
        transform: translateX(0);
    }
    to {
        transform: translateX(-50%);
    }
}
.ib-alert {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    font-size: 0.76rem;
    font-weight: 700;
    padding: 0.4rem 0.8rem;
    border-radius: 0.6rem;
    white-space: nowrap;
    border: 1px solid;
}

/* ---------- FLOOR MAP BED CARD ---------- */
.ib-bed {
    position: relative;
    border-radius: 0.9rem;
    padding: 0.7rem;
    cursor: pointer;
    overflow: hidden;
    background: var(--ib-panel);
    border: 1px solid color-mix(in srgb, var(--bc) 40%, var(--ib-border));
    transition:
        transform 0.18s,
        box-shadow 0.18s;
}
.ib-bed:hover {
    transform: translateY(-3px);
    box-shadow:
        0 18px 34px -22px rgba(15, 23, 42, 0.45),
        0 0 0 1px var(--bc);
}
.ib-bed::before {
    content: "";
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    width: 4px;
    background: var(--bc);
    box-shadow: 0 0 10px var(--bc);
}
.ib-bed.sel {
    outline: 2px solid var(--ib-c);
    outline-offset: 1px;
}
.ib-bed .stat {
    background: color-mix(in srgb, var(--bc) 18%, transparent);
    color: var(--bc);
}
.ib-bed .prev {
    max-height: 0;
    opacity: 0;
    overflow: hidden;
    transition: 0.25s;
}
.ib-bed:hover .prev {
    max-height: 70px;
    opacity: 1;
}
.ib-monidot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
}

.ib-ring {
    transform: rotate(-90deg);
}
.ib-ring .bar {
    stroke-dasharray: 100 100;
    stroke-dashoffset: calc(100 - var(--p, 0));
    transition: stroke-dashoffset 1.1s cubic-bezier(0.4, 0, 0.2, 1);
}
.ib-stab {
    height: 8px;
    border-radius: 999px;
    background: var(--ib-track);
    overflow: hidden;
}
.ib-stab > span {
    display: block;
    height: 100%;
    border-radius: 999px;
    transition: width 0.6s;
}

/* ---------- KANBAN ---------- */
.ib-kcol {
    background: var(--ib-panel);
    border: 1px solid var(--ib-border);
    border-radius: 1rem;
}
.ib-ktask {
    background: var(--ib-surface);
    border: 1px solid var(--ib-border);
    border-radius: 0.7rem;
    padding: 0.6rem;
    cursor: grab;
    transition: box-shadow 0.15s;
}
.ib-ktask:hover {
    box-shadow: 0 10px 24px -16px rgba(15, 23, 42, 0.5);
}
.ib-ktask.drag {
    opacity: 0.5;
}
.ib-kcol.over {
    outline: 2px dashed color-mix(in srgb, var(--ib-c) 50%, transparent);
    outline-offset: -4px;
}

/* ---------- TIMELINE ---------- */
.ib-tl {
    position: relative;
    padding-left: 1.6rem;
}
.ib-tl::before {
    content: "";
    position: absolute;
    left: 0.45rem;
    top: 0.3rem;
    bottom: 0.3rem;
    width: 2px;
    background: var(--ib-border);
}
.ib-tl-item {
    position: relative;
    padding-bottom: 1rem;
}
.ib-tl-item::before {
    content: "";
    position: absolute;
    left: -1.3rem;
    top: 0.1rem;
    width: 14px;
    height: 14px;
    border-radius: 50%;
    background: var(--ib-surface);
    border: 3px solid var(--tc, var(--ib-c));
}

/* ---------- MENU / MODAL ---------- */
.ib-menu {
    position: fixed;
    z-index: 120;
    width: 222px;
    max-height: 72vh;
    overflow-y: auto;
    background: var(--ib-elev);
    border: 1px solid var(--ib-border);
    border-radius: 0.9rem;
    box-shadow: 0 30px 60px -20px rgba(15, 23, 42, 0.5);
    padding: 0.35rem;
    color: var(--ib-text);
}
.ib-menu button {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    width: 100%;
    text-align: left;
    font-size: 0.8rem;
    padding: 0.5rem 0.6rem;
    border-radius: 0.5rem;
    color: var(--ib-text);
}
.ib-menu button:hover {
    background: var(--ib-hover);
}
.ib-menu button.danger {
    color: #dc2626;
}
.ib-menu button.danger:hover {
    background: color-mix(in srgb, #ef4444 12%, transparent);
}

.ib-modal-wrap {
    position: fixed;
    inset: 0;
    z-index: 130;
    display: none;
}
.ib-modal-wrap.open {
    display: block;
}
.ib-modal-bg {
    position: absolute;
    inset: 0;
    background: rgba(2, 6, 15, 0.55);
    backdrop-filter: blur(4px);
}
.ib-modal {
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
    width: min(600px, 94vw);
    max-height: 90vh;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    background: var(--ib-elev);
    color: var(--ib-text);
    border: 1px solid var(--ib-border);
    border-radius: 1rem;
    box-shadow: 0 40px 90px -24px rgba(2, 6, 15, 0.55);
    animation: ib-pop 0.22s cubic-bezier(0.4, 0, 0.2, 1);
}
.ib-modal-head {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 1rem 1.15rem;
    border-bottom: 1px solid var(--ib-border);
}
.ib-modal-badge {
    width: 38px;
    height: 38px;
    border-radius: 0.6rem;
    display: flex;
    align-items: center;
    justify-content: center;
    background: color-mix(in srgb, var(--ib-c) 15%, transparent);
    color: var(--ib-c);
    font-size: 1.05rem;
    flex: none;
}
.ib-modal-body {
    padding: 1.15rem;
    overflow-y: auto;
}
.ib-modal-foot {
    display: flex;
    justify-content: flex-end;
    gap: 0.5rem;
    padding: 0.9rem 1.15rem;
    border-top: 1px solid var(--ib-border);
    background: var(--ib-panel);
}
.ib-formlabel {
    font-size: 0.72rem;
    font-weight: 600;
    color: var(--ib-mut);
    text-transform: uppercase;
    letter-spacing: 0.03em;
}
.ib-btn {
    font-size: 0.82rem;
    font-weight: 600;
    padding: 0.55rem 0.95rem;
    border-radius: 0.55rem;
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    transition: 0.15s;
}
.ib-btn-primary {
    background: var(--ib-c);
    color: #fff;
}
.ib-btn-primary:hover {
    opacity: 0.92;
}
.ib-btn-ghost {
    background: transparent;
    border: 1px solid var(--ib-border);
    color: var(--ib-text);
}
.ib-btn-ghost:hover {
    background: var(--ib-hover);
}
.ib-btn-danger {
    background: #dc2626;
    color: #fff;
}
.ib-btn-danger:hover {
    background: #b91c1c;
}
@keyframes ib-pop {
    from {
        opacity: 0;
        transform: translate(-50%, -46%) scale(0.97);
    }
    to {
        opacity: 1;
        transform: translate(-50%, -50%) scale(1);
    }
}
.ib-in {
    width: 100%;
    padding: 0.5rem 0.7rem;
    font-size: 0.82rem;
    border: 1px solid var(--ib-border);
    border-radius: 0.6rem;
    background: var(--ib-panel);
    color: var(--ib-text);
}
.ib-in:focus {
    outline: none;
    border-color: var(--ib-c);
    box-shadow: 0 0 0 3px color-mix(in srgb, var(--ib-c) 20%, transparent);
}
.ib-in::placeholder {
    color: var(--ib-mut);
}

.ib-toast {
    position: fixed;
    bottom: 1.25rem;
    left: 50%;
    transform: translateX(-50%) translateY(120%);
    z-index: 140;
    background: #0d1526;
    color: #fff;
    border: 1px solid rgba(148, 163, 184, 0.25);
    padding: 0.7rem 1.1rem;
    border-radius: 0.8rem;
    font-size: 0.82rem;
    font-weight: 500;
    box-shadow: 0 20px 40px -18px rgba(0, 0, 0, 0.55);
    display: flex;
    align-items: center;
    gap: 0.5rem;
    transition: transform 0.35s cubic-bezier(0.4, 0, 0.2, 1);
}
.ib-toast.show {
    transform: translateX(-50%) translateY(0);
}
.ib-bulk {
    position: sticky;
    bottom: 0.75rem;
    z-index: 40;
    background: #0f172a;
    color: #fff;
    border-radius: 1rem;
    box-shadow: 0 20px 45px -20px rgba(0, 0, 0, 0.6);
    display: none;
}
.ib-bulk.show {
    display: flex;
}

.ib-sk {
    position: relative;
    overflow: hidden;
    background: var(--color-gray-200);
    border-radius: 1rem;
}
.ib-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in srgb, var(--color-white) 55%, transparent),
        transparent
    );
    animation: ib-shim 1.4s infinite;
}
@keyframes ib-shim {
    100% {
        transform: translateX(100%);
    }
}
.ib-drop {
    background-image: repeating-linear-gradient(
        0deg,
        var(--ib-border) 0,
        var(--ib-border) 6px,
        transparent 6px,
        transparent 12px
    );
}
.ib-seg {
    display: inline-flex;
    background: var(--ib-panel);
    border: 1px solid var(--ib-border);
    border-radius: 0.7rem;
    padding: 0.2rem;
    gap: 0.15rem;
    flex-wrap: wrap;
}
.ib-seg button {
    padding: 0.35rem 0.7rem;
    font-size: 0.74rem;
    font-weight: 600;
    border-radius: 0.5rem;
    color: var(--ib-mut);
}
.ib-seg button.on {
    background: var(--ib-surface);
    color: var(--ib-c);
    box-shadow: 0 2px 8px -3px rgba(15, 23, 42, 0.4);
}

/* ================================================================
   ICU PATIENT OPERATIONS WORKSPACE · icu-patients.html (page-exclusive)
   Namespace: ip-  ·  Theme-aware.  Lucide icons (icon-*).
   Professional clinical palette: color reserved for medical
   acuity / status; decorative chrome kept neutral & restrained.
   Do not reuse these classes in other modules.
   ================================================================ */
body:has(#ip-page) {
    --ip-c: var(--color-primary);
    --ip-accent: #0d9488; /* clinical teal — single decorative accent */
    --ip-surface: var(--color-white);
    --ip-panel: var(--color-gray-50);
    --ip-border: var(--color-border-color);
    --ip-text: var(--color-gray-900);
    --ip-mut: var(--color-gray-500);
    --ip-soft: var(--color-gray-400);
    --ip-elev: var(--color-white);
    --ip-hover: var(--color-gray-100);
    --ip-screen: #0a1120;
    --ip-track: color-mix(in srgb, var(--color-gray-500) 18%, transparent);
    --ip-neutral: color-mix(in srgb, var(--color-gray-500) 12%, transparent);
}
.dark body:has(#ip-page) {
    --ip-accent: #2dd4bf;
    --ip-surface: #0e1626;
    --ip-panel: #131c2e;
    --ip-border: rgba(148, 163, 184, 0.16);
    --ip-text: #e2e8f0;
    --ip-mut: #94a3b8;
    --ip-soft: #64748b;
    --ip-elev: #131c2e;
    --ip-hover: rgba(148, 163, 184, 0.1);
    --ip-track: rgba(148, 163, 184, 0.18);
    --ip-neutral: rgba(148, 163, 184, 0.1);
}
.ip-card {
    background: var(--ip-surface);
    border: 1px solid var(--ip-border);
    border-radius: 1rem;
    color: var(--ip-text);
    box-shadow:
        0 1px 2px rgba(15, 23, 42, 0.04),
        0 14px 40px -34px rgba(15, 23, 42, 0.3);
}
.ip-panel {
    background: var(--ip-panel);
    border: 1px solid var(--ip-border);
    border-radius: 0.75rem;
}
.ip-mut {
    color: var(--ip-mut);
}
.ip-head {
    color: var(--ip-text);
}
.ip-hicon {
    color: var(--ip-accent);
}
/* neutral pill — for non-clinical metadata */
.ip-npill {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    font-size: 0.68rem;
    font-weight: 600;
    padding: 0.2rem 0.5rem;
    border-radius: 0.4rem;
    background: var(--ip-neutral);
    color: var(--ip-mut);
}

/* ---------- HERO ---------- */
.ip-hero {
    position: relative;
    overflow: hidden;
    border-radius: 1rem;
    color: #e5edf5;
    background: linear-gradient(135deg, #0b1a2b 0%, #102437 55%, #0c1b2a 100%);
    border: 1px solid rgba(148, 163, 184, 0.16);
    box-shadow: 0 20px 50px -34px rgba(2, 6, 15, 0.7);
}
.ip-hgrid {
    position: absolute;
    inset: 0;
    background-image:
        linear-gradient(rgba(148, 163, 184, 0.05) 1px, transparent 1px),
        linear-gradient(90deg, rgba(148, 163, 184, 0.05) 1px, transparent 1px);
    background-size: 28px 28px;
    pointer-events: none;
}
.ip-hbadge {
    background: rgba(148, 163, 184, 0.1);
    border: 1px solid rgba(148, 163, 184, 0.16);
    border-radius: 0.6rem;
    padding: 0.6rem 0.8rem;
}

.ip-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.68rem;
    font-weight: 700;
    padding: 0.2rem 0.55rem;
    border-radius: 0.4rem;
}
.ip-dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    display: inline-block;
}
@keyframes ip-pulse {
    0%,
    100% {
        opacity: 1;
    }
    50% {
        opacity: 0.4;
    }
}
.ip-live {
    animation: ip-pulse 1.6s infinite;
}

/* severity (clinical) */
.sev-red {
    --sv: #dc2626;
}
.sev-orange {
    --sv: #e06c1f;
}
.sev-yellow {
    --sv: #b7791f;
}
.sev-green {
    --sv: #15803d;
}
.sev-blue {
    --sv: #1d4ed8;
}
.sev-gray {
    --sv: #64748b;
}
.dark .sev-red {
    --sv: #f87171;
}
.dark .sev-orange {
    --sv: #fb923c;
}
.dark .sev-yellow {
    --sv: #eab308;
}
.dark .sev-green {
    --sv: #4ade80;
}
.dark .sev-blue {
    --sv: #60a5fa;
}
.dark .sev-gray {
    --sv: #94a3b8;
}

/* ---------- ALERT RIBBON ---------- */
.ip-ribbon {
    overflow: hidden;
    position: relative;
}
.ip-ribbon-track {
    display: flex;
    gap: 0.5rem;
    width: max-content;
    animation: ip-marquee 34s linear infinite;
}
.ip-ribbon:hover .ip-ribbon-track {
    animation-play-state: paused;
}
@keyframes ip-marquee {
    from {
        transform: translateX(0);
    }
    to {
        transform: translateX(-50%);
    }
}
.ip-alert {
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
    font-size: 0.75rem;
    font-weight: 600;
    padding: 0.35rem 0.7rem;
    border-radius: 0.5rem;
    white-space: nowrap;
    border: 1px solid;
}

/* ---------- ACUITY BOARD ---------- */
.ip-acuity {
    position: relative;
    border-radius: 0.85rem;
    padding: 0.9rem;
    overflow: hidden;
    border: 1px solid var(--ip-border);
    background: var(--ip-surface);
    transition:
        border-color 0.18s,
        box-shadow 0.18s;
    cursor: pointer;
}
.ip-acuity:hover {
    border-color: color-mix(in srgb, var(--sv) 45%, var(--ip-border));
    box-shadow: 0 12px 30px -22px rgba(15, 23, 42, 0.4);
}
.ip-acuity::before {
    content: "";
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    width: 3px;
    background: var(--sv);
}

/* ---------- BED TILE ---------- */
.ip-bed {
    position: relative;
    border-radius: 0.75rem;
    padding: 0.7rem;
    cursor: pointer;
    overflow: hidden;
    background: var(--ip-surface);
    border: 1px solid var(--ip-border);
    transition:
        border-color 0.18s,
        box-shadow 0.18s;
}
.ip-bed:hover {
    border-color: color-mix(in srgb, var(--sv) 40%, var(--ip-border));
    box-shadow: 0 14px 30px -24px rgba(15, 23, 42, 0.4);
}
.ip-bed::before {
    content: "";
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    width: 3px;
    background: var(--sv);
}
.ip-bed.sel {
    border-color: var(--sv);
    box-shadow: 0 0 0 1px var(--sv);
}
.ip-bed .risk {
    background: color-mix(in srgb, var(--sv) 14%, transparent);
    color: var(--sv);
}
.ip-bed-empty {
    border-style: dashed;
    background: var(--ip-panel);
}
.ip-bed .prev {
    max-height: 0;
    opacity: 0;
    overflow: hidden;
    transition: 0.25s;
}
.ip-bed:hover .prev {
    max-height: 60px;
    opacity: 1;
}
.ip-screen {
    background: var(--ip-screen);
    border-radius: 0.4rem;
}
.ip-ecg polyline {
    filter: drop-shadow(0 0 2px currentColor);
}

.ip-stab {
    height: 6px;
    border-radius: 999px;
    background: var(--ip-track);
    overflow: hidden;
}
.ip-stab > span {
    display: block;
    height: 100%;
    border-radius: 999px;
    transition: width 0.6s;
}
.ip-avatar {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    color: #fff;
    border-radius: 0.55rem;
    letter-spacing: 0.02em;
}

/* ---------- KANBAN ---------- */
.ip-kcol {
    background: var(--ip-panel);
    border: 1px solid var(--ip-border);
    border-radius: 0.85rem;
}
.ip-ktask {
    background: var(--ip-surface);
    border: 1px solid var(--ip-border);
    border-radius: 0.6rem;
    padding: 0.6rem;
    cursor: grab;
    transition: box-shadow 0.15s;
}
.ip-ktask:hover {
    box-shadow: 0 8px 20px -16px rgba(15, 23, 42, 0.5);
}
.ip-ktask.drag {
    opacity: 0.5;
}
.ip-kcol.over {
    outline: 2px dashed color-mix(in srgb, var(--ip-accent) 50%, transparent);
    outline-offset: -4px;
}

/* ---------- TIMELINE ---------- */
.ip-tl {
    position: relative;
    padding-left: 1.5rem;
}
.ip-tl::before {
    content: "";
    position: absolute;
    left: 0.42rem;
    top: 0.3rem;
    bottom: 0.3rem;
    width: 2px;
    background: var(--ip-border);
}
.ip-tl-item {
    position: relative;
    padding-bottom: 0.95rem;
}
.ip-tl-item::before {
    content: "";
    position: absolute;
    left: -1.28rem;
    top: 0.15rem;
    width: 12px;
    height: 12px;
    border-radius: 50%;
    background: var(--ip-surface);
    border: 2.5px solid var(--tc, var(--ip-accent));
}

/* ---------- MENU ---------- */
.ip-menu {
    position: fixed;
    z-index: 120;
    width: 224px;
    max-height: 72vh;
    overflow-y: auto;
    background: var(--ip-elev);
    border: 1px solid var(--ip-border);
    border-radius: 0.75rem;
    box-shadow: 0 24px 50px -18px rgba(15, 23, 42, 0.45);
    padding: 0.35rem;
    color: var(--ip-text);
}
.ip-menu button {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    width: 100%;
    text-align: left;
    font-size: 0.8rem;
    padding: 0.5rem 0.55rem;
    border-radius: 0.45rem;
    color: var(--ip-text);
}
.ip-menu button i {
    color: var(--ip-mut);
    font-size: 0.95rem;
}
.ip-menu button:hover {
    background: var(--ip-hover);
}
.ip-menu button.danger {
    color: #dc2626;
}
.ip-menu button.danger i {
    color: #dc2626;
}
.ip-menu button.danger:hover {
    background: color-mix(in srgb, #ef4444 10%, transparent);
}
.ip-menu-sep {
    height: 1px;
    background: var(--ip-border);
    margin: 0.3rem 0.2rem;
}

/* ---------- MODAL (premium) ---------- */
.ip-modal-wrap {
    position: fixed;
    inset: 0;
    z-index: 130;
    display: none;
}
.ip-modal-wrap.open {
    display: block;
}
.ip-modal-bg {
    position: absolute;
    inset: 0;
    background: rgba(8, 15, 26, 0.6);
    backdrop-filter: blur(5px);
    animation: ip-fade 0.2s;
}
@keyframes ip-fade {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}
.ip-modal {
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
    width: min(600px, 94vw);
    max-height: 90vh;
    display: flex;
    flex-direction: column;
    background: var(--ip-elev);
    color: var(--ip-text);
    border: 1px solid var(--ip-border);
    border-radius: 1rem;
    box-shadow: 0 40px 90px -24px rgba(2, 6, 15, 0.55);
    animation: ip-pop 0.22s cubic-bezier(0.4, 0, 0.2, 1);
    overflow: hidden;
}
@keyframes ip-pop {
    from {
        opacity: 0;
        transform: translate(-50%, -47%) scale(0.98);
    }
    to {
        opacity: 1;
        transform: translate(-50%, -50%) scale(1);
    }
}
.ip-modal-head {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 1rem 1.15rem;
    border-bottom: 1px solid var(--ip-border);
}
.ip-modal-badge {
    width: 38px;
    height: 38px;
    border-radius: 0.6rem;
    display: flex;
    align-items: center;
    justify-content: center;
    background: color-mix(in srgb, var(--ip-accent) 15%, transparent);
    color: var(--ip-accent);
    font-size: 1.05rem;
    flex: none;
}
.ip-modal-body {
    padding: 1.15rem;
    overflow-y: auto;
}
.ip-modal-foot {
    display: flex;
    justify-content: flex-end;
    gap: 0.5rem;
    padding: 0.9rem 1.15rem;
    border-top: 1px solid var(--ip-border);
    background: var(--ip-panel);
}
.ip-formlabel {
    font-size: 0.72rem;
    font-weight: 600;
    color: var(--ip-mut);
    text-transform: uppercase;
    letter-spacing: 0.03em;
}
.ip-in {
    width: 100%;
    padding: 0.55rem 0.7rem;
    font-size: 0.82rem;
    border: 1px solid var(--ip-border);
    border-radius: 0.55rem;
    background: var(--ip-surface);
    color: var(--ip-text);
    transition:
        border-color 0.15s,
        box-shadow 0.15s;
}
.ip-in:focus {
    outline: none;
    border-color: var(--ip-accent);
    box-shadow: 0 0 0 3px color-mix(in srgb, var(--ip-accent) 18%, transparent);
}
.ip-in::placeholder {
    color: var(--ip-soft);
}
.ip-btn {
    font-size: 0.82rem;
    font-weight: 600;
    padding: 0.55rem 0.95rem;
    border-radius: 0.55rem;
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    transition: 0.15s;
}
.ip-btn-primary {
    background: var(--ip-c);
    color: #fff;
}
.ip-btn-primary:hover {
    opacity: 0.92;
}
.ip-btn-ghost {
    background: transparent;
    border: 1px solid var(--ip-border);
    color: var(--ip-text);
}
.ip-btn-ghost:hover {
    background: var(--ip-hover);
}
.ip-btn-danger {
    background: #dc2626;
    color: #fff;
}
.ip-btn-danger:hover {
    background: #b91c1c;
}

.ip-toast {
    position: fixed;
    bottom: 1.25rem;
    left: 50%;
    transform: translateX(-50%) translateY(120%);
    z-index: 140;
    background: #0f1b2d;
    color: #e5edf5;
    border: 1px solid rgba(148, 163, 184, 0.2);
    padding: 0.7rem 1.05rem;
    border-radius: 0.65rem;
    font-size: 0.82rem;
    font-weight: 500;
    box-shadow: 0 18px 40px -18px rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    gap: 0.5rem;
    transition: transform 0.32s cubic-bezier(0.4, 0, 0.2, 1);
}
.ip-toast.show {
    transform: translateX(-50%) translateY(0);
}
.ip-bulk {
    position: sticky;
    bottom: 0.75rem;
    z-index: 40;
    background: #0f1b2d;
    color: #e5edf5;
    border-radius: 0.85rem;
    box-shadow: 0 18px 40px -18px rgba(0, 0, 0, 0.55);
    display: none;
    border: 1px solid rgba(148, 163, 184, 0.18);
}
.ip-bulk.show {
    display: flex;
}

.ip-sk {
    position: relative;
    overflow: hidden;
    background: var(--ip-panel);
    border-radius: 0.85rem;
}
.ip-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in srgb, var(--color-white) 45%, transparent),
        transparent
    );
    animation: ip-shim 1.4s infinite;
}
@keyframes ip-shim {
    100% {
        transform: translateX(100%);
    }
}
.ip-drop {
    background-image: repeating-linear-gradient(
        0deg,
        var(--ip-border) 0,
        var(--ip-border) 6px,
        transparent 6px,
        transparent 12px
    );
}
.ip-seg {
    display: inline-flex;
    background: var(--ip-panel);
    border: 1px solid var(--ip-border);
    border-radius: 0.6rem;
    padding: 0.18rem;
    gap: 0.12rem;
}
.ip-seg button {
    padding: 0.35rem 0.7rem;
    font-size: 0.74rem;
    font-weight: 600;
    border-radius: 0.42rem;
    color: var(--ip-mut);
}
.ip-seg button.on {
    background: var(--ip-surface);
    color: var(--ip-text);
    box-shadow: 0 1px 3px rgba(15, 23, 42, 0.15);
}
.ip-iconbadge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 0.5rem;
    background: var(--ip-neutral);
    color: var(--ip-mut);
}
h2 .ip-hicon {
    font-size: 1.05rem;
}

