    gap: 0.25rem;
    padding: 0.15rem 0.5rem;
    border-radius: 9999px;
    font-size: 0.62rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    color: color-mix(in oklab, var(--fb-c) 70%, #1e293b);
    background: color-mix(in oklab, var(--fb-c) 16%, transparent);
}
.dark .fb-chip {
    color: color-mix(in oklab, var(--fb-c) 55%, #fff);
}
.fb-ring {
    --p: 0;
    width: 3rem;
    height: 3rem;
    transform: rotate(-90deg);
}
.fb-ring circle {
    fill: none;
    stroke-width: 4;
}
.fb-ring .trk {
    stroke: color-mix(in oklab, var(--fb-c) 16%, transparent);
}
.fb-ring .bar {
    stroke: var(--fb-c);
    stroke-linecap: round;
    stroke-dasharray: 100 100;
    stroke-dashoffset: calc(100 - var(--p));
    transition: stroke-dashoffset 0.9s cubic-bezier(0.16, 1, 0.3, 1);
}

.fb-head {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 1rem 1.15rem;
    border-bottom: 1px solid var(--color-border-color);
}
.fb-head .ico {
    display: grid;
    place-items: center;
    width: 2.3rem;
    height: 2.3rem;
    border-radius: 0.75rem;
    color: #fff;
    font-size: 0.95rem;
    background: linear-gradient(
        135deg,
        color-mix(in oklab, var(--fb-c) 90%, #000),
        color-mix(in oklab, var(--fb-c) 55%, #6366f1)
    );
    box-shadow: 0 10px 18px -12px var(--fb-c);
    flex-shrink: 0;
}
.fb-t {
    font-weight: 800;
    color: var(--color-gray-900);
    font-size: 0.9rem;
}

.fb-search {
    position: relative;
    flex: 1 1 220px;
    min-width: 180px;
}
.fb-search input {
    width: 100%;
    padding: 0.6rem 0.9rem 0.6rem 2.5rem;
    border-radius: 0.85rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.85rem;
    font-weight: 600;
    outline: none;
    transition:
        border-color 0.18s ease,
        box-shadow 0.18s ease;
}
.fb-search input:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 4px
        color-mix(in oklab, var(--color-primary) 14%, transparent);
}
.fb-search .ico {
    position: absolute;
    left: 0.85rem;
    top: 50%;
    transform: translateY(-50%);
    color: var(--color-gray-400, #94a3b8);
    pointer-events: none;
}
.fb-tool {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.55rem 0.8rem;
    border-radius: 0.8rem;
    font-size: 0.8rem;
    font-weight: 700;
    cursor: pointer;
    white-space: nowrap;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-600, #475569);
    transition:
        border-color 0.18s ease,
        color 0.18s ease,
        transform 0.18s ease;
}
.fb-tool:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
    transform: translateY(-1px);
}
.fb-seg {
    display: inline-flex;
    padding: 0.25rem;
    border-radius: 0.85rem;
    background: color-mix(in oklab, var(--color-gray-500) 14%, transparent);
}
.fb-seg button {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.4rem 0.7rem;
    border-radius: 0.65rem;
    font-size: 0.78rem;
    font-weight: 700;
    color: var(--color-gray-500);
    transition: all 0.18s ease;
}
.fb-seg button.is-active {
    background: var(--color-white);
    color: var(--color-primary-text);
    box-shadow: 0 4px 10px -6px rgba(15, 23, 42, 0.4);
}

.fb-card {
    position: relative;
    overflow: hidden;
    border-radius: 1.25rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 18px 40px -32px rgba(15, 23, 42, 0.5);
    transition:
        transform 0.25s ease,
        box-shadow 0.25s ease,
        border-color 0.25s ease;
}
.fb-card::before {
    content: "";
    position: absolute;
    inset: 0 0 auto 0;
    height: 3px;
    background: linear-gradient(
        90deg,
        var(--fb-c),
        color-mix(in oklab, var(--fb-c) 40%, #6366f1)
    );
}
.fb-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 26px 48px -26px
        color-mix(in oklab, var(--fb-c) 45%, rgba(15, 23, 42, 0.5));
    border-color: color-mix(
        in oklab,
        var(--fb-c) 35%,
        var(--color-border-color)
    );
}
.fb-card.is-selected {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 2px
        color-mix(in oklab, var(--color-primary) 40%, transparent);
}
.fb-ava {
    width: 2.8rem;
    height: 2.8rem;
    border-radius: 0.85rem;
    display: grid;
    place-items: center;
    color: #fff;
    font-weight: 800;
    font-size: 0.9rem;
    background: linear-gradient(
        135deg,
        var(--fb-c),
        color-mix(in oklab, var(--fb-c) 55%, #6366f1)
    );
    flex-shrink: 0;
}
.fb-stars {
    display: inline-flex;
    gap: 0.1rem;
    color: #f59e0b;
    font-size: 0.85rem;
}
.fb-stars .off {
    color: color-mix(in oklab, var(--color-gray-500) 30%, transparent);
}
.fb-stars-in i {
    cursor: pointer;
    font-size: 1.4rem;
    transition: transform 0.1s ease;
}
.fb-stars-in i:hover {
    transform: scale(1.15);
}

.fb-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.15rem 0.55rem;
    border-radius: 9999px;
    font-size: 0.62rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    white-space: nowrap;
}
.fb-badge.new {
    color: #0284c7;
    background: rgba(14, 165, 233, 0.15);
}
.fb-badge.responded {
    color: var(--color-primary-text);
    background: color-mix(in oklab, var(--color-primary) 15%, transparent);
}
.fb-badge.resolved {
    color: #059669;
    background: rgba(16, 185, 129, 0.15);
}
.fb-badge.escalated {
    color: #e11d48;
    background: rgba(244, 63, 94, 0.15);
}
.fb-sent {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.1rem 0.5rem;
    border-radius: 9999px;
    font-size: 0.6rem;
    font-weight: 800;
    text-transform: uppercase;
}
.fb-sent.positive {
    color: #059669;
    background: rgba(16, 185, 129, 0.14);
}
.fb-sent.neutral {
    color: #64748b;
    background: rgba(100, 116, 139, 0.14);
}
.fb-sent.negative {
    color: #e11d48;
    background: rgba(244, 63, 94, 0.14);
}
.fb-tag {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.1rem 0.45rem;
    border-radius: 0.5rem;
    font-size: 0.62rem;
    font-weight: 700;
    background: color-mix(in oklab, var(--fb-c) 14%, transparent);
    color: var(--fb-c);
}
.fb-mini {
    display: grid;
    place-items: center;
    width: 2rem;
    height: 2rem;
    border-radius: 0.6rem;
    color: var(--color-gray-500);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.16s ease;
}
.fb-mini:hover {
    border-color: var(--fb-c);
    color: var(--fb-c);
    transform: translateY(-1px);
}
.fb-kv {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    font-size: 0.72rem;
    color: var(--color-gray-500);
    min-width: 0;
}
.fb-kv b {
    color: var(--color-gray-900);
    font-weight: 700;
}

.fb-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0;
}
.fb-table thead th {
    text-align: left;
    font-size: 0.66rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--color-gray-400, #94a3b8);
    padding: 0.75rem 1rem;
    border-bottom: 1px solid var(--color-border-color);
    white-space: nowrap;
    background: color-mix(in oklab, var(--color-gray-500) 5%, transparent);
}
.fb-table tbody td {
    padding: 0.7rem 1rem;
    border-bottom: 1px solid var(--color-border-color);
    font-size: 0.82rem;
    color: var(--color-gray-900);
    vertical-align: middle;
}
.fb-table tbody tr {
    transition: background 0.15s ease;
}
.fb-table tbody tr:hover {
    background: color-mix(in oklab, var(--color-primary) 5%, transparent);
}
.fb-table tbody tr.is-selected {
    background: color-mix(in oklab, var(--color-primary) 9%, transparent);
}
.fb-check {
    width: 1.05rem;
    height: 1.05rem;
    border-radius: 0.35rem;
    accent-color: var(--color-primary);
    cursor: pointer;
}

.fb-menu {
    position: absolute;
    z-index: 1100;
    min-width: 14rem;
    max-height: 26rem;
    overflow-y: auto;
    padding: 0.4rem;
    border-radius: 1rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 30px 60px -24px rgba(2, 12, 40, 0.5);
    animation: fb-pop 0.16s ease;
}
@keyframes fb-pop {
    from {
        opacity: 0;
        transform: translateY(-6px) scale(0.97);
    }
}
.fb-menu button,
.fb-menu a {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    width: 100%;
    padding: 0.45rem 0.55rem;
    border-radius: 0.55rem;
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--color-gray-900);
    text-align: left;
    transition:
        background 0.14s ease,
        color 0.14s ease;
}
.fb-menu button:hover,
.fb-menu a:hover {
    background: color-mix(in oklab, var(--color-primary) 8%, transparent);
    color: var(--color-primary-text);
}
.fb-menu .danger {
    color: #e11d48;
}
.fb-menu .danger:hover {
    background: rgba(244, 63, 94, 0.1);
}
.fb-menu-sep {
    height: 1px;
    margin: 0.3rem 0.2rem;
    background: var(--color-border-color);
}
.fb-menu-lbl {
    padding: 0.4rem 0.55rem 0.15rem;
    font-size: 0.58rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--color-gray-400, #94a3b8);
}

.fb-drawer {
    position: fixed;
    inset: 0;
    z-index: 1200;
    visibility: hidden;
}
.fb-drawer.open {
    visibility: visible;
}
.fb-drawer-back {
    position: absolute;
    inset: 0;
    background: rgba(8, 12, 30, 0.5);
    opacity: 0;
    transition: opacity 0.3s ease;
}
.fb-drawer.open .fb-drawer-back {
    opacity: 1;
}
.fb-drawer-panel {
    position: absolute;
    top: 0;
    right: 0;
    height: 100%;
    width: min(490px, 94vw);
    background: var(--color-white);
    box-shadow: -30px 0 60px -30px rgba(2, 12, 40, 0.55);
    transform: translateX(100%);
    transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1);
    display: flex;
    flex-direction: column;
}
.fb-drawer.open .fb-drawer-panel {
    transform: translateX(0);
}
.fb-drawer-panel.left {
    right: auto;
    left: 0;
    transform: translateX(-100%);
    box-shadow: 30px 0 60px -30px rgba(2, 12, 40, 0.55);
}
.fb-drawer.open .fb-drawer-panel.left {
    transform: translateX(0);
}
.fb-drawer-hero {
    position: relative;
    padding: 1.5rem;
    color: #fff;
    background:
        radial-gradient(
            120% 130% at 100% 0%,
            rgba(236, 72, 153, 0.55),
            transparent 55%
        ),
        linear-gradient(135deg, #d97706, #0f172a);
}

.fb-modal {
    position: fixed;
    inset: 0;
    z-index: 1300;
    display: none;
    align-items: center;
    justify-content: center;
    padding: 1rem;
}
.fb-modal.open {
    display: flex;
}
.fb-modal-back {
    position: absolute;
    inset: 0;
    background: rgba(8, 12, 30, 0.5);
    -webkit-backdrop-filter: blur(3px);
    backdrop-filter: blur(3px);
    animation: fb-fadein 0.2s ease;
}
@keyframes fb-fadein {
    from {
        opacity: 0;
    }
}
.fb-modal-panel {
    position: relative;
    width: 100%;
    max-width: 37rem;
    max-height: 90vh;
    overflow-y: auto;
    border-radius: 1.25rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 40px 80px -30px rgba(2, 12, 40, 0.6);
    animation: fb-modin 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes fb-modin {
    from {
        opacity: 0;
        transform: translateY(16px) scale(0.97);
    }
}
.fb-doc-ico {
    display: grid;
    place-items: center;
    width: 2.75rem;
    height: 2.75rem;
    border-radius: 0.8rem;
    color: var(--fb-c);
    font-size: 1.15rem;
    background: color-mix(in oklab, var(--fb-c) 14%, transparent);
}

.fb-bulk {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.55rem;
    padding: 0.7rem 0.9rem;
    border-radius: 1.25rem;
    background: color-mix(in oklab, var(--color-white) 85%, transparent);
    -webkit-backdrop-filter: blur(16px);
    backdrop-filter: blur(16px);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 12px 28px -18px rgba(15, 23, 42, 0.45);
    animation: fb-bulk-in 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes fb-bulk-in {
    from {
        opacity: 0;
        transform: translateY(-8px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}
.fb-bulk-btn {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.4rem 0.7rem;
    border-radius: 0.7rem;
    font-size: 0.76rem;
    font-weight: 700;
    color: var(--color-gray-700, #374151);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.15s ease;
    white-space: nowrap;
}
.dark .fb-bulk-btn {
    color: var(--color-gray-900);
}
.fb-bulk-btn:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.fb-bulk-btn.danger {
    color: #e11d48;
}
.fb-bulk-btn.danger:hover {
    border-color: #e11d48;
    background: rgba(244, 63, 94, 0.08);
}

.fb-pg {
    display: grid;
    place-items: center;
    min-width: 2.1rem;
    height: 2.1rem;
    padding: 0 0.5rem;
    border-radius: 0.6rem;
    font-size: 0.8rem;
    font-weight: 700;
    color: var(--color-gray-600, #475569);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.15s ease;
    cursor: pointer;
}
.fb-pg:hover:not(:disabled) {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.fb-pg.is-active {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    border-color: transparent;
}
.fb-pg:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

.fb-bar {
    height: 0.5rem;
    border-radius: 9999px;
    background: color-mix(in oklab, var(--fb-c) 14%, transparent);
    overflow: hidden;
}
.fb-bar > i {
    display: block;
    height: 100%;
    border-radius: 9999px;
    background: linear-gradient(
        90deg,
        var(--fb-c),
        color-mix(in oklab, var(--fb-c) 55%, #6366f1)
    );
}
.fb-recent {
    display: flex;
    align-items: center;
    gap: 0.7rem;
    padding: 0.6rem;
    border-radius: 0.8rem;
    transition: background 0.15s ease;
}
.fb-recent:hover {
    background: color-mix(in oklab, var(--color-primary) 6%, transparent);
}

.fb-in {
    width: 100%;
    padding: 0.65rem 0.8rem;
    border-radius: 0.7rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.85rem;
    font-weight: 600;
    outline: none;
    transition:
        border-color 0.16s ease,
        box-shadow 0.16s ease;
}
.fb-in:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 4px
        color-mix(in oklab, var(--color-primary) 14%, transparent);
}
.fb-lbl {
    display: block;
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--color-gray-500);
    margin-bottom: 0.3rem;
}

.fb-c-indigo {
    --fb-c: #6366f1;
}
.fb-c-sky {
    --fb-c: #0ea5e9;
}
.fb-c-rose {
    --fb-c: #f43f5e;
}
.fb-c-amber {
    --fb-c: #f59e0b;
}
.fb-c-emerald {
    --fb-c: #10b981;
}
.fb-c-violet {
    --fb-c: #8b5cf6;
}
.fb-c-teal {
    --fb-c: #14b8a6;
}
.fb-c-primary {
    --fb-c: var(--color-primary);
}
.fb-c-pink {
    --fb-c: #ec4899;
}
.fb-c-slate {
    --fb-c: #64748b;
}

.fb-sk {
    position: relative;
    overflow: hidden;
    background: color-mix(in oklab, var(--color-gray-500) 12%, transparent);
    border-radius: 0.75rem;
}
.fb-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in oklab, var(--color-white) 55%, transparent),
        transparent
    );
    animation: fb-shimmer 1.4s infinite;
}
.dark .fb-sk::after {
    background: linear-gradient(
        90deg,
        transparent,
        rgba(255, 255, 255, 0.06),
        transparent
    );
}
@keyframes fb-shimmer {
    100% {
        transform: translateX(100%);
    }
}

.fb-toast {
    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    z-index: 2000;
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.8rem 1.1rem;
    border-radius: 0.9rem;
    font-size: 0.85rem;
    font-weight: 700;
    color: #fff;
    box-shadow: 0 20px 45px -18px rgba(0, 0, 0, 0.5);
    animation: fb-toastin 0.25s ease;
}
@keyframes fb-toastin {
    from {
        opacity: 0;
        transform: translateY(12px);
    }
}
.fb-toast.success {
    background: linear-gradient(135deg, #f59e0b, #d97706);
}
.fb-toast.info {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
}
.fb-toast.error {
    background: linear-gradient(135deg, #f43f5e, #e11d48);
}

/* Per-instance modifiers (unlayered so they win over the shared .fb-hbadge/.fb-ring/.fb-tool defaults above) */
.fb-hbadge-emerald {
    background: rgba(16, 185, 129, 0.18);
    border-color: rgba(16, 185, 129, 0.4);
}
.fb-hbadge-rose {
    background: rgba(244, 63, 94, 0.18);
    border-color: rgba(244, 63, 94, 0.4);
}
.fb-ring-lg {
    width: 4.5rem;
    height: 4.5rem;
}
.fb-tool-sm {
    padding: 0.35rem 0.6rem;
}
.fb-tool-xs {
    padding: 0.35rem 0.5rem;
}

@media (prefers-reduced-motion: reduce) {
    .fb-btn,
    .fb-stat,
    .fb-card,
    .fb-ring .bar,
    .fb-dot,
    .fb-sk::after,
    .fb-icobtn,
    .fb-mini,
    .fb-drawer-panel,
    .fb-bulk {
        transition: none;
        animation: none;
    }
    .fb-btn:hover,
    .fb-stat:hover,
    .fb-card:hover,
    .fb-icobtn:hover,
    .fb-mini:hover {
        transform: none;
    }
}
@media print {
    .sidebar,
    header.navbar-header,
    .fb-print-hide {
        display: none !important;
    }
}

/* ============================================================
   CONSULTATION HISTORY CENTER · consultation-history.html (page-exclusive)
   Do not reuse these classes in other modules.
