    border-color: color-mix(in srgb, var(--cc) 45%, var(--color-border-color));
}
.ch-tl-card::before {
    content: "";
    position: absolute;
    left: -1.83rem;
    top: 1.3rem;
    width: 0.6rem;
    height: 0.6rem;
    border-radius: 9999px;
    background: var(--cc, #94a3b8);
    border: 2px solid var(--color-white);
    box-shadow: 0 0 0 3px color-mix(in srgb, var(--cc) 18%, transparent);
}

