}
.ch-mi.danger:hover {
    background: color-mix(in srgb, #ef4444 12%, transparent);
}
.ch-sep {
    height: 1px;
    background: var(--color-border-color);
    margin: 0.3rem 0.2rem;
}

/* ---------- SKELETON ---------- */
.ch-sk {
    position: relative;
    overflow: hidden;
    background: var(--color-gray-100);
    border-radius: 1rem;
}
.ch-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in srgb, var(--color-gray-300) 55%, transparent),
        transparent
    );
    animation: ch-sh 1.4s infinite;
}
@keyframes ch-sh {
    100% {
        transform: translateX(100%);
    }
}

/* ---------- DRAWER ---------- */
.ch-drawer {
    position: fixed;
    inset: 0;
    z-index: 70;
    display: none;
}
.ch-drawer.open {
    display: block;
}
.ch-mask {
    position: absolute;
    inset: 0;
    background: rgba(15, 23, 42, 0.55);
    -webkit-backdrop-filter: blur(3px);
    backdrop-filter: blur(3px);
    animation: ch-fade 0.25s ease;
}
@keyframes ch-fade {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}
.ch-panel {
    position: absolute;
    top: 0;
    right: 0;
    height: 100%;
    width: min(500px, 100vw);
    background: var(--color-white);
    border-left: 1px solid var(--color-border-color);
    box-shadow: -30px 0 60px -30px rgba(15, 23, 42, 0.6);
    overflow-y: auto;
    animation: ch-slide 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
@keyframes ch-slide {
    from {
        transform: translateX(100%);
    }
    to {
        transform: none;
    }
}

/* ---------- MODAL ---------- */
.ch-modal {
    position: fixed;
    inset: 0;
    z-index: 75;
    display: none;
}
.ch-modal.open {
    display: block;
}
.ch-dialog {
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
    width: min(580px, 94vw);
    max-height: 90vh;
    overflow: auto;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    border-radius: 1.25rem;
    box-shadow: 0 40px 80px -30px rgba(15, 23, 42, 0.7);
    animation: ch-pop 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}
@keyframes ch-pop {
    from {
        opacity: 0;
        transform: translate(-50%, -46%) scale(0.96);
    }
    to {
        opacity: 1;
        transform: translate(-50%, -50%) scale(1);
    }
}
.ch-drop {
    border: 2px dashed var(--color-border-color);
    border-radius: 1rem;
    padding: 1.6rem;
    text-align: center;
    transition: all 0.2s ease;
    cursor: pointer;
}
.ch-drop:hover,
.ch-drop.drag {
    border-color: var(--color-primary);
    background: color-mix(in srgb, var(--color-primary) 6%, transparent);
}

/* ---------- BULK BAR ---------- */
.ch-bulk {
    position: fixed;
    left: 50%;
    bottom: 1.25rem;
    transform: translateX(-50%) translateY(160%);
    z-index: 60;
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.6rem 0.6rem 0.6rem 1rem;
    border-radius: 1rem;
    background: var(--color-gray-900);
    color: #fff;
    box-shadow: 0 30px 60px -20px rgba(0, 0, 0, 0.6);
    transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
    flex-wrap: wrap;
    max-width: 94vw;
}
.ch-bulk.show {
    transform: translateX(-50%) translateY(0);
}

/* ---------- TOAST ---------- */
#ch-toast {
    position: fixed;
    right: 1rem;
    bottom: 1rem;
    z-index: 90;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
