.vit-dot {
    width: 0.5rem;
    height: 0.5rem;
    border-radius: 9999px;
    background: #fb7185;
    box-shadow: 0 0 0 4px rgba(251, 113, 133, 0.25);
    animation: vit-pulse 1.4s ease-in-out infinite;
}
@keyframes vit-pulse {
    0%,
    100% {
        opacity: 1;
        transform: scale(1);
    }
    50% {
        opacity: 0.35;
        transform: scale(1.35);
    }
}
.vit-hava {
    width: 3.5rem;
    height: 3.5rem;
    border-radius: 1rem;
    display: grid;
    place-items: center;
    font-weight: 800;
    font-size: 1.1rem;
    color: #fff;
    background: rgba(255, 255, 255, 0.16);
    border: 1px solid rgba(255, 255, 255, 0.28);
}

.vit-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    padding: 0.55rem 0.9rem;
    border-radius: 0.8rem;
    font-size: 0.8rem;
    font-weight: 700;
    cursor: pointer;
    border: 1px solid transparent;
    white-space: nowrap;
    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease,
        background 0.2s ease,
        color 0.2s ease,
        border-color 0.2s ease;
}
.vit-btn:hover {
    transform: translateY(-2px);
}
.vit-btn-primary {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    box-shadow: 0 12px 24px -12px var(--color-primary);
}
.vit-btn-success {
    background: linear-gradient(135deg, #f43f5e, #e11d48);
    color: #fff;
    box-shadow: 0 12px 24px -12px #f43f5e;
}
.vit-btn-glass {
    background: rgba(255, 255, 255, 0.12);
    color: #fff;
    border-color: rgba(255, 255, 255, 0.24);
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
}
.vit-btn-glass:hover {
    background: rgba(255, 255, 255, 0.2);
}
.vit-btn-solid {
    background: var(--color-white);
    color: var(--color-gray-900);
    border-color: var(--color-border-color);
}
.vit-btn-solid:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.vit-btn-danger {
    background: #e11d48;
    color: #fff;
}
.vit-icobtn {
    display: grid;
    place-items: center;
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 0.75rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-500);
    cursor: pointer;
    transition: all 0.16s ease;
    flex-shrink: 0;
}
.vit-icobtn:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
    transform: translateY(-1px);
}

.vit-stat {
    position: relative;
    overflow: hidden;
    border-radius: 1.25rem;
    padding: 1.1rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 18px 40px -30px rgba(15, 23, 42, 0.45);
    transition:
        transform 0.25s ease,
        box-shadow 0.25s ease,
        border-color 0.25s ease;
}
.vit-stat::after {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(
        135deg,
        color-mix(in oklab, var(--vit-c) 12%, transparent),
        transparent 60%
    );
    pointer-events: none;
}
.vit-stat:hover {
    transform: translateY(-4px);
    box-shadow: 0 26px 50px -26px
        color-mix(in oklab, var(--vit-c) 55%, rgba(15, 23, 42, 0.5));
    border-color: color-mix(
        in oklab,
        var(--vit-c) 40%,
        var(--color-border-color)
    );
}
.vit-stat > * {
    position: relative;
    z-index: 1;
}
.vit-stat-ico {
    display: grid;
    place-items: center;
    width: 2.9rem;
    height: 2.9rem;
    border-radius: 0.9rem;
    color: #fff;
    font-size: 1.15rem;
    background: linear-gradient(
        135deg,
        var(--vit-c),
        color-mix(in oklab, var(--vit-c) 55%, #6366f1)
    );
    box-shadow: 0 10px 20px -10px var(--vit-c);
}
.vit-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.15rem 0.5rem;
    border-radius: 9999px;
    font-size: 0.62rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    color: color-mix(in oklab, var(--vit-c) 70%, #1e293b);
    background: color-mix(in oklab, var(--vit-c) 16%, transparent);
}
.dark .vit-chip {
    color: color-mix(in oklab, var(--vit-c) 55%, #fff);
}
.vit-ring {
    --p: 0;
    width: 3rem;
    height: 3rem;
    transform: rotate(-90deg);
}
.vit-ring circle {
    fill: none;
    stroke-width: 4;
}
.vit-ring .trk {
    stroke: color-mix(in oklab, var(--vit-c) 16%, transparent);
}
.vit-ring .bar {
    stroke: var(--vit-c);
    stroke-linecap: round;
    stroke-dasharray: 100 100;
    stroke-dashoffset: calc(100 - var(--p));
    transition: stroke-dashoffset 0.9s cubic-bezier(0.16, 1, 0.3, 1);
}

.vit-head {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 1rem 1.15rem;
    border-bottom: 1px solid var(--color-border-color);
}
.vit-head .ico {
    display: grid;
    place-items: center;
    width: 2.3rem;
    height: 2.3rem;
    border-radius: 0.75rem;
    color: #fff;
    font-size: 0.95rem;
    background: linear-gradient(
        135deg,
        color-mix(in oklab, var(--vit-c) 90%, #000),
        color-mix(in oklab, var(--vit-c) 55%, #6366f1)
    );
    box-shadow: 0 10px 18px -12px var(--vit-c);
    flex-shrink: 0;
}
.vit-t {
    font-weight: 800;
    color: var(--color-gray-900);
    font-size: 0.9rem;
}

.vit-search {
    position: relative;
    flex: 1 1 220px;
    min-width: 180px;
}
.vit-search input {
    width: 100%;
    padding: 0.6rem 0.9rem 0.6rem 2.5rem;
    border-radius: 0.85rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.85rem;
    font-weight: 600;
    outline: none;
    transition:
        border-color 0.18s ease,
        box-shadow 0.18s ease;
}
.vit-search input:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 4px
        color-mix(in oklab, var(--color-primary) 14%, transparent);
}
.vit-search .ico {
    position: absolute;
    left: 0.85rem;
    top: 50%;
    transform: translateY(-50%);
    color: var(--color-gray-400, #94a3b8);
    pointer-events: none;
}
.vit-tool {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.55rem 0.8rem;
    border-radius: 0.8rem;
    font-size: 0.8rem;
    font-weight: 700;
    cursor: pointer;
    white-space: nowrap;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-600, #475569);
    transition:
        border-color 0.18s ease,
        color 0.18s ease,
        transform 0.18s ease;
}
.vit-tool:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
    transform: translateY(-1px);
}
.vit-seg {
    display: inline-flex;
    padding: 0.25rem;
    border-radius: 0.85rem;
    background: color-mix(in oklab, var(--color-gray-500) 14%, transparent);
}
.vit-seg button {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.4rem 0.7rem;
    border-radius: 0.65rem;
    font-size: 0.78rem;
    font-weight: 700;
    color: var(--color-gray-500);
    transition: all 0.18s ease;
}
.vit-seg button.is-active {
    background: var(--color-white);
    color: var(--color-primary-text);
    box-shadow: 0 4px 10px -6px rgba(15, 23, 42, 0.4);
}

/* vital cards */
.vit-card {
    position: relative;
    overflow: hidden;
    border-radius: 1.25rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 18px 40px -32px rgba(15, 23, 42, 0.5);
    transition:
        transform 0.25s ease,
        box-shadow 0.25s ease,
        border-color 0.25s ease;
}
.vit-card::before {
    content: "";
    position: absolute;
    inset: 0 0 auto 0;
    height: 3px;
    background: linear-gradient(
        90deg,
        var(--vit-c),
        color-mix(in oklab, var(--vit-c) 40%, #6366f1)
    );
}
.vit-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 26px 48px -26px
        color-mix(in oklab, var(--vit-c) 45%, rgba(15, 23, 42, 0.5));
    border-color: color-mix(
        in oklab,
        var(--vit-c) 35%,
        var(--color-border-color)
    );
}
.vit-cico {
    display: grid;
    place-items: center;
    width: 2.8rem;
    height: 2.8rem;
    border-radius: 0.9rem;
    font-size: 1.2rem;
    color: #fff;
    background: linear-gradient(
        135deg,
        var(--vit-c),
        color-mix(in oklab, var(--vit-c) 55%, #6366f1)
    );
    box-shadow: 0 10px 20px -10px var(--vit-c);
}
.vit-big {
    font-size: 2rem;
    font-weight: 900;
    letter-spacing: -0.02em;
    line-height: 1;
    color: var(--color-gray-900);
}

.vit-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.15rem 0.55rem;
    border-radius: 9999px;
    font-size: 0.62rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    white-space: nowrap;
}
.vit-badge.normal {
    color: #059669;
    background: rgba(16, 185, 129, 0.15);
}
.vit-badge.high {
    color: #d97706;
    background: rgba(245, 158, 11, 0.15);
}
.vit-badge.low {
    color: #0284c7;
    background: rgba(14, 165, 233, 0.15);
}
.vit-badge.critical {
    color: #e11d48;
    background: rgba(244, 63, 94, 0.15);
}
.vit-tag {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.1rem 0.45rem;
    border-radius: 0.5rem;
    font-size: 0.62rem;
    font-weight: 700;
    background: color-mix(in oklab, var(--vit-c) 14%, transparent);
    color: var(--vit-c);
}
.vit-mini {
    display: grid;
    place-items: center;
    width: 2rem;
    height: 2rem;
    border-radius: 0.6rem;
    color: var(--color-gray-500);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.16s ease;
}
.vit-mini:hover {
    border-color: var(--vit-c);
    color: var(--vit-c);
    transform: translateY(-1px);
}
.vit-kv {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    font-size: 0.72rem;
    color: var(--color-gray-500);
    min-width: 0;
}
.vit-kv b {
    color: var(--color-gray-900);
    font-weight: 700;
}

.vit-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0;
}
.vit-table thead th {
    text-align: left;
    font-size: 0.66rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--color-gray-400, #94a3b8);
    padding: 0.75rem 1rem;
    border-bottom: 1px solid var(--color-border-color);
    white-space: nowrap;
    background: color-mix(in oklab, var(--color-gray-500) 5%, transparent);
}
.vit-table tbody td {
    padding: 0.7rem 1rem;
    border-bottom: 1px solid var(--color-border-color);
    font-size: 0.82rem;
    color: var(--color-gray-900);
    vertical-align: middle;
    white-space: nowrap;
}
.vit-table tbody tr {
    transition: background 0.15s ease;
}
.vit-table tbody tr:hover {
    background: color-mix(in oklab, var(--color-primary) 5%, transparent);
}
.vit-table tbody tr.is-selected {
    background: color-mix(in oklab, var(--color-primary) 9%, transparent);
}
.vit-check {
    width: 1.05rem;
    height: 1.05rem;
    border-radius: 0.35rem;
    accent-color: var(--color-primary);
    cursor: pointer;
}
.vit-fileico {
    display: grid;
    place-items: center;
    width: 2rem;
    height: 2rem;
    border-radius: 0.55rem;
    font-size: 0.9rem;
    color: var(--vit-c);
    background: color-mix(in oklab, var(--vit-c) 14%, transparent);
    flex-shrink: 0;
}

.vit-menu {
    position: absolute;
    z-index: 1100;
    min-width: 13rem;
    max-height: 26rem;
    overflow-y: auto;
    padding: 0.4rem;
    border-radius: 1rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 30px 60px -24px rgba(2, 12, 40, 0.5);
    animation: vit-pop 0.16s ease;
}
@keyframes vit-pop {
    from {
        opacity: 0;
        transform: translateY(-6px) scale(0.97);
    }
}
.vit-menu button,
.vit-menu a {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    width: 100%;
    padding: 0.45rem 0.55rem;
    border-radius: 0.55rem;
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--color-gray-900);
    text-align: left;
    transition:
        background 0.14s ease,
        color 0.14s ease;
}
.vit-menu button:hover,
.vit-menu a:hover {
    background: color-mix(in oklab, var(--color-primary) 8%, transparent);
    color: var(--color-primary-text);
}
.vit-menu .danger {
    color: #e11d48;
}
.vit-menu .danger:hover {
    background: rgba(244, 63, 94, 0.1);
}
.vit-menu-sep {
    height: 1px;
    margin: 0.3rem 0.2rem;
    background: var(--color-border-color);
}
.vit-menu-lbl {
    padding: 0.4rem 0.55rem 0.15rem;
    font-size: 0.58rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--color-gray-400, #94a3b8);
}

.vit-drawer {
    position: fixed;
    inset: 0;
    z-index: 1200;
    visibility: hidden;
}
.vit-drawer.open {
    visibility: visible;
}
.vit-drawer-back {
    position: absolute;
    inset: 0;
    background: rgba(8, 12, 30, 0.5);
    opacity: 0;
    transition: opacity 0.3s ease;
}
.vit-drawer.open .vit-drawer-back {
    opacity: 1;
}
.vit-drawer-panel {
    position: absolute;
    top: 0;
    right: 0;
    height: 100%;
    width: min(500px, 94vw);
    background: var(--color-white);
    box-shadow: -30px 0 60px -30px rgba(2, 12, 40, 0.55);
    transform: translateX(100%);
    transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1);
    display: flex;
    flex-direction: column;
}
.vit-drawer.open .vit-drawer-panel {
    transform: translateX(0);
}
.vit-drawer-panel.left {
    right: auto;
    left: 0;
    transform: translateX(-100%);
    box-shadow: 30px 0 60px -30px rgba(2, 12, 40, 0.55);
}
.vit-drawer.open .vit-drawer-panel.left {
    transform: translateX(0);
}
.vit-drawer-hero {
    position: relative;
    padding: 1.5rem;
    color: #fff;
    background:
        radial-gradient(
            120% 130% at 100% 0%,
            rgba(249, 115, 22, 0.55),
            transparent 55%
        ),
        linear-gradient(135deg, #e11d48, #0f172a);
}

.vit-modal {
    position: fixed;
    inset: 0;
    z-index: 1300;
    display: none;
    align-items: center;
    justify-content: center;
    padding: 1rem;
}
.vit-modal.open {
    display: flex;
}
.vit-modal-back {
    position: absolute;
    inset: 0;
    background: rgba(8, 12, 30, 0.5);
    -webkit-backdrop-filter: blur(3px);
    backdrop-filter: blur(3px);
    animation: vit-fadein 0.2s ease;
}
@keyframes vit-fadein {
    from {
        opacity: 0;
    }
}
.vit-modal-panel {
    position: relative;
    width: 100%;
    max-width: 38rem;
    max-height: 90vh;
    overflow-y: auto;
    border-radius: 1.25rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 40px 80px -30px rgba(2, 12, 40, 0.6);
    animation: vit-modin 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes vit-modin {
    from {
        opacity: 0;
        transform: translateY(16px) scale(0.97);
    }
}
.vit-doc-ico {
    display: grid;
    place-items: center;
    width: 2.75rem;
    height: 2.75rem;
    border-radius: 0.8rem;
    color: var(--vit-c);
    font-size: 1.15rem;
    background: color-mix(in oklab, var(--vit-c) 14%, transparent);
}

.vit-bulk {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.55rem;
    padding: 0.7rem 0.9rem;
    border-radius: 1.25rem;
    background: color-mix(in oklab, var(--color-white) 85%, transparent);
    -webkit-backdrop-filter: blur(16px);
    backdrop-filter: blur(16px);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 12px 28px -18px rgba(15, 23, 42, 0.45);
    animation: vit-bulk-in 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes vit-bulk-in {
    from {
        opacity: 0;
        transform: translateY(-8px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}
.vit-bulk-btn {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.4rem 0.7rem;
    border-radius: 0.7rem;
    font-size: 0.76rem;
    font-weight: 700;
    color: var(--color-gray-700, #374151);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.15s ease;
    white-space: nowrap;
}
.dark .vit-bulk-btn {
    color: var(--color-gray-900);
}
.vit-bulk-btn:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.vit-bulk-btn.danger {
    color: #e11d48;
}
.vit-bulk-btn.danger:hover {
    border-color: #e11d48;
    background: rgba(244, 63, 94, 0.08);
}

.vit-pg {
    display: grid;
    place-items: center;
    min-width: 2.1rem;
    height: 2.1rem;
    padding: 0 0.5rem;
    border-radius: 0.6rem;
    font-size: 0.8rem;
    font-weight: 700;
    color: var(--color-gray-600, #475569);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.15s ease;
    cursor: pointer;
}
.vit-pg:hover:not(:disabled) {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.vit-pg.is-active {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    border-color: transparent;
}
.vit-pg:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

.vit-bar {
    height: 0.5rem;
    border-radius: 9999px;
    background: color-mix(in oklab, var(--vit-c) 14%, transparent);
    overflow: hidden;
}
.vit-bar > i {
    display: block;
    height: 100%;
    border-radius: 9999px;
    background: linear-gradient(
        90deg,
        var(--vit-c),
        color-mix(in oklab, var(--vit-c) 55%, #6366f1)
    );
}
.vit-recent {
    display: flex;
    align-items: center;
    gap: 0.7rem;
    padding: 0.6rem;
    border-radius: 0.8rem;
    transition: background 0.15s ease;
}
.vit-recent:hover {
    background: color-mix(in oklab, var(--color-primary) 6%, transparent);
}
.vit-spark {
    width: 100%;
    height: 44px;
    display: block;
    overflow: visible;
}
.vit-gauge {
    position: relative;
    height: 0.65rem;
    border-radius: 9999px;
    background: linear-gradient(
        90deg,
        #0ea5e9,
        #10b981 35%,
        #f59e0b 75%,
        #f43f5e
    );
    overflow: visible;
}
.vit-gauge .pin {
    position: absolute;
    top: -3px;
    width: 0.4rem;
    height: calc(0.65rem + 6px);
    border-radius: 2px;
    background: var(--color-gray-900);
    box-shadow: 0 0 0 2px var(--color-white);
}
.dark .vit-gauge .pin {
    background: #fff;
    box-shadow: 0 0 0 2px #0f172b;
}

.vit-dev {
    display: flex;
    align-items: center;
    gap: 0.7rem;
    padding: 0.75rem;
    border-radius: 1rem;
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition:
        transform 0.2s ease,
        border-color 0.2s ease;
}
.vit-dev:hover {
    transform: translateY(-2px);
    border-color: color-mix(
        in oklab,
        var(--vit-c) 35%,
        var(--color-border-color)
    );
}
.vit-conn {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.12rem 0.5rem;
    border-radius: 9999px;
    font-size: 0.6rem;
    font-weight: 800;
    text-transform: uppercase;
}
.vit-conn.on {
    color: #059669;
    background: rgba(16, 185, 129, 0.15);
}
.vit-conn.off {
    color: #64748b;
    background: rgba(100, 116, 139, 0.15);
}

.vit-in {
    width: 100%;
    padding: 0.65rem 0.8rem;
    border-radius: 0.7rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.85rem;
    font-weight: 600;
    outline: none;
    transition:
        border-color 0.16s ease,
        box-shadow 0.16s ease;
}
.vit-in:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 4px
        color-mix(in oklab, var(--color-primary) 14%, transparent);
}
.vit-lbl {
    display: block;
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--color-gray-500);
    margin-bottom: 0.3rem;
}

.vit-c-indigo {
    --vit-c: #6366f1;
}
.vit-c-sky {
    --vit-c: #0ea5e9;
}
.vit-c-rose {
    --vit-c: #f43f5e;
}
.vit-c-amber {
    --vit-c: #f59e0b;
}
.vit-c-emerald {
    --vit-c: #10b981;
}
.vit-c-violet {
    --vit-c: #8b5cf6;
}
.vit-c-teal {
    --vit-c: #14b8a6;
}
.vit-c-primary {
    --vit-c: var(--color-primary);
}
.vit-c-orange {
    --vit-c: #f97316;
}

.vit-sk {
    position: relative;
    overflow: hidden;
    background: color-mix(in oklab, var(--color-gray-500) 12%, transparent);
    border-radius: 0.75rem;
}
.vit-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in oklab, var(--color-white) 55%, transparent),
        transparent
    );
    animation: vit-shimmer 1.4s infinite;
}
.dark .vit-sk::after {
    background: linear-gradient(
        90deg,
        transparent,
        rgba(255, 255, 255, 0.06),
        transparent
    );
}
@keyframes vit-shimmer {
    100% {
        transform: translateX(100%);
    }
}

.vit-toast {
    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    z-index: 2000;
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.8rem 1.1rem;
    border-radius: 0.9rem;
    font-size: 0.85rem;
    font-weight: 700;
    color: #fff;
    box-shadow: 0 20px 45px -18px rgba(0, 0, 0, 0.5);
    animation: vit-toastin 0.25s ease;
}
@keyframes vit-toastin {
    from {
        opacity: 0;
        transform: translateY(12px);
    }
}
.vit-toast.success {
    background: linear-gradient(135deg, #f43f5e, #e11d48);
}
.vit-toast.info {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
}
.vit-toast.error {
    background: linear-gradient(135deg, #f43f5e, #e11d48);
}

@media (prefers-reduced-motion: reduce) {
    .vit-btn,
    .vit-stat,
    .vit-card,
    .vit-dev,
    .vit-ring .bar,
    .vit-dot,
    .vit-sk::after,
    .vit-icobtn,
    .vit-mini,
    .vit-drawer-panel,
    .vit-bulk {
        transition: none;
        animation: none;
    }
    .vit-btn:hover,
    .vit-stat:hover,
    .vit-card:hover,
    .vit-dev:hover,
    .vit-icobtn:hover,
    .vit-mini:hover {
        transform: none;
    }
}
@media print {
    .sidebar,
    header.navbar-header,
    .vit-print-hide {
        display: none !important;
    }
}

/* ============================================================
   CONSULTATION FEE MANAGEMENT · consultation-fees.html (page-exclusive)
   Do not reuse these classes in other modules.
   ============================================================ */
#cf-page {
    --cf-c: var(--color-primary);
}
.cf-surface {
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    border-radius: 1.25rem;
    box-shadow: 0 20px 45px -35px rgba(15, 23, 42, 0.4);
}
.cf-muted {
    color: var(--color-gray-500);
}

.cf-layout {
    display: grid;
    grid-template-columns: 1fr;
    gap: 1.25rem;
    align-items: start;
}
@media (min-width: 1280px) {
    .cf-layout {
        grid-template-columns: minmax(0, 1fr) 350px;
    }
}
.cf-grid {
    display: grid;
    gap: 0.9rem;
}
.cf-g3 {
    grid-template-columns: repeat(1, minmax(0, 1fr));
}
@media (min-width: 640px) {
    .cf-g3 {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}
@media (min-width: 960px) {
    .cf-g3 {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}
.cf-g6 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
}
@media (min-width: 700px) {
    .cf-g6 {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}
@media (min-width: 1200px) {
    .cf-g6 {
        grid-template-columns: repeat(6, minmax(0, 1fr));
    }
}
.cf-g4 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
}
@media (min-width: 700px) {
    .cf-g4 {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}
@media (min-width: 1200px) {
    .cf-g4 {
        grid-template-columns: repeat(4, minmax(0, 1fr));
    }
}
.cf-cards {
    display: grid;
    gap: 1rem;
    grid-template-columns: 1fr;
}
.cf-cards.hidden {
    display: none;
}
@media (min-width: 768px) {
    .cf-cards {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}
@media (min-width: 1500px) {
    .cf-cards {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}
.cf-price-grid {
    display: grid;
    gap: 0.85rem;
    grid-template-columns: 1fr;
}
@media (min-width: 600px) {
    .cf-price-grid {
        grid-template-columns: repeat(2, 1fr);
    }
}
@media (min-width: 1000px) {
    .cf-price-grid {
        grid-template-columns: repeat(4, 1fr);
    }
}

/* ---------- HERO ---------- */
.cf-hero {
    position: relative;
    overflow: hidden;
    border-radius: 1.5rem;
    padding: 1.75rem;
    color: #fff;
    background:
        radial-gradient(
            120% 140% at 0% 0%,
            rgba(16, 185, 129, 0.5),
            transparent 55%
        ),
        radial-gradient(
            120% 160% at 100% 0%,
            rgba(14, 165, 233, 0.55),
            transparent 50%
        ),
        linear-gradient(135deg, #0f172a, #0d2a2a 55%, #0b1220);
    box-shadow: 0 30px 60px -30px rgba(15, 23, 42, 0.7);
}
.cf-hero::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image: radial-gradient(
        rgba(255, 255, 255, 0.08) 1px,
        transparent 1px
    );
    background-size: 22px 22px;
    -webkit-mask-image: linear-gradient(180deg, #000, transparent 75%);
    mask-image: linear-gradient(180deg, #000, transparent 75%);
}
.cf-hero > * {
    position: relative;
    z-index: 1;
}
@media (min-width: 1024px) {
    .cf-hero {
        padding: 2rem 2.25rem;
    }
}
.cf-hbadge {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.28rem 0.7rem;
    border-radius: 9999px;
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    background: rgba(255, 255, 255, 0.14);
    border: 1px solid rgba(255, 255, 255, 0.22);
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
}
.cf-hmeta {
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
    padding: 0.5rem 0.85rem;
    border-radius: 0.85rem;
    background: rgba(255, 255, 255, 0.1);
    border: 1px solid rgba(255, 255, 255, 0.16);
    font-size: 0.74rem;
    font-weight: 700;
}
.cf-dot {
    width: 0.5rem;
    height: 0.5rem;
    border-radius: 9999px;
    background: #34d399;
    box-shadow: 0 0 0 4px rgba(52, 211, 153, 0.25);
    animation: cf-pulse 2s ease-in-out infinite;
}
@keyframes cf-pulse {
    0%,
    100% {
        opacity: 1;
    }
    50% {
        opacity: 0.4;
    }
}

/* ---------- BUTTONS ---------- */
.cf-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    padding: 0.55rem 0.9rem;
    border-radius: 0.8rem;
    font-size: 0.8rem;
    font-weight: 700;
    cursor: pointer;
    border: 1px solid transparent;
    white-space: nowrap;
    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease,
        background 0.2s ease,
        color 0.2s ease,
        border-color 0.2s ease;
}
.cf-btn:hover {
    transform: translateY(-2px);
}
.cf-btn-primary {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    box-shadow: 0 12px 24px -12px var(--color-primary);
}
.cf-btn-success {
    background: linear-gradient(135deg, #10b981, #059669);
    color: #fff;
    box-shadow: 0 12px 24px -12px #10b981;
}
.cf-btn-glass {
    background: rgba(255, 255, 255, 0.12);
    color: #fff;
    border-color: rgba(255, 255, 255, 0.24);
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
}
.cf-btn-glass:hover {
    background: rgba(255, 255, 255, 0.2);
}
.cf-btn-soft {
    background: var(--color-gray-100);
    color: var(--color-gray-700);
    border-color: var(--color-border-color);
}
.cf-btn-soft:hover {
    background: var(--color-gray-200);
}

/* ---------- KPI ---------- */
.cf-kpi {
    position: relative;
    overflow: hidden;
    padding: 1.1rem;
    border-radius: 1.2rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 16px 30px -28px rgba(15, 23, 42, 0.5);
    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease;
}
.cf-kpi:hover {
    transform: translateY(-4px);
    box-shadow: 0 26px 48px -30px rgba(15, 23, 42, 0.55);
}
.cf-kpi::after {
    content: "";
    position: absolute;
    right: -30px;
    top: -30px;
    width: 90px;
    height: 90px;
    border-radius: 9999px;
    background: var(--kc, #10b981);
    opacity: 0.08;
}
.cf-kpi-ic {
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 0.85rem;
    display: flex;
    align-items: center;
    justify-content: center;
}
.cf-kpi-v {
    font-size: 1.5rem;
    font-weight: 800;
    line-height: 1;
    color: var(--color-gray-900);
}
.cf-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.18rem 0.5rem;
    border-radius: 9999px;
    font-size: 0.66rem;
    font-weight: 800;
}
.cf-ring {
    transform: rotate(-90deg);
}
.cf-ring .bar {
    stroke-dasharray: 100 100;
    stroke-dashoffset: calc(100 - var(--p, 0));
    transition: stroke-dashoffset 1.1s cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* ---------- INPUTS ---------- */
.cf-inp {
    width: 100%;
    padding: 0.55rem 0.7rem;
    border-radius: 0.7rem;
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.8rem;
}
.cf-inp:focus {
    outline: none;
    border-color: var(--color-primary);
    box-shadow: 0 0 0 3px
        color-mix(in srgb, var(--color-primary) 20%, transparent);
}
.cf-lbl {
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--color-gray-600);
    margin-bottom: 0.3rem;
    display: block;
}
.cf-seg {
    display: inline-flex;
    padding: 0.2rem;
    border-radius: 0.7rem;
    background: var(--color-gray-100);
    border: 1px solid var(--color-border-color);
}
.cf-segb {
    padding: 0.4rem 0.75rem;
    border-radius: 0.5rem;
    font-size: 0.76rem;
    font-weight: 700;
    color: var(--color-gray-600);
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
}
.cf-segb.active {
    background: var(--color-white);
    color: var(--color-primary-text);
    box-shadow: 0 6px 14px -10px rgba(15, 23, 42, 0.5);
}

/* ---------- TABLE ---------- */
.cf-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0;
}
.cf-table th {
    text-align: left;
    font-size: 0.7rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: var(--color-gray-500);
    padding: 0.65rem 0.75rem;
    border-bottom: 1px solid var(--color-border-color);
    white-space: nowrap;
}
.cf-table td {
    padding: 0.7rem 0.75rem;
    border-bottom: 1px solid var(--color-border-color);
    font-size: 0.82rem;
}
.cf-table tbody tr {
    transition: background 0.15s ease;
}
.cf-table tbody tr:hover {
    background: var(--color-gray-100);
}
.cf-hidecol {
    display: none;
}

/* ---------- FEE CARD (grid) ---------- */
.cf-fcard {
    position: relative;
    overflow: hidden;
    border-radius: 1.25rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 18px 40px -34px rgba(15, 23, 42, 0.5);
    transition:
        transform 0.22s ease,
        box-shadow 0.22s ease,
        border-color 0.22s ease;
}
.cf-fcard:hover {
    transform: translateY(-4px);
    box-shadow: 0 28px 55px -30px rgba(15, 23, 42, 0.55);
    border-color: color-mix(in srgb, var(--fc) 40%, var(--color-border-color));
}
.cf-av {
    width: 2.6rem;
    height: 2.6rem;
    border-radius: 0.75rem;
    display: flex;
    align-items: center;
    justify-content: center;
    object-fit: cover;
    font-size: 0.72rem;
    font-weight: 800;
    color: #fff;
    flex: none;
}
.cf-av-sm {
    width: 2rem;
    height: 2rem;
    border-radius: 0.55rem;
    font-size: 0.62rem;
}

/* ---------- PRICING CARD ---------- */
.cf-pcard {
    position: relative;
    overflow: hidden;
    border-radius: 1.15rem;
    padding: 1.1rem;
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease;
    cursor: pointer;
}
.cf-pcard:hover {
    transform: translateY(-4px);
    box-shadow: 0 24px 45px -30px rgba(15, 23, 42, 0.5);
}
.cf-pcard::before {
    content: "";
    position: absolute;
    inset: 0 0 auto 0;
    height: 4px;
    background: var(--pc, #10b981);
}
.cf-pic {
    width: 2.6rem;
    height: 2.6rem;
    border-radius: 0.8rem;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.3rem;
    color: #fff;
}

.cf-tag {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.24rem 0.55rem;
    border-radius: 9999px;
    font-size: 0.66rem;
    font-weight: 700;
}
.cf-bar {
    height: 0.5rem;
    border-radius: 9999px;
    background: var(--color-gray-200);
    overflow: hidden;
}
.cf-bar > span {
    display: block;
    height: 100%;
    border-radius: 9999px;
}
.cf-dotstat {
    width: 0.55rem;
    height: 0.55rem;
    border-radius: 9999px;
    flex: none;
}

/* ---------- ACTION MENU ---------- */
.cf-menu {
    position: fixed;
    z-index: 80;
    width: 206px;
    max-height: 70vh;
    overflow: auto;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    border-radius: 0.85rem;
    box-shadow: 0 30px 60px -20px rgba(15, 23, 42, 0.5);
    padding: 0.35rem;
    display: none;
}
.cf-menu.open {
    display: block;
    animation: cf-pop 0.18s ease;
}
.cf-mi {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    padding: 0.5rem 0.6rem;
    border-radius: 0.55rem;
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--color-gray-700);
    cursor: pointer;
}
.cf-mi:hover {
    background: var(--color-gray-100);
}
.cf-mi.danger {
    color: #dc2626;
}
.cf-mi.danger:hover {
    background: color-mix(in srgb, #ef4444 12%, transparent);
}
.cf-sep {
    height: 1px;
    background: var(--color-border-color);
    margin: 0.3rem 0.2rem;
}

/* ---------- SKELETON ---------- */
.cf-sk {
    position: relative;
    overflow: hidden;
    background: var(--color-gray-100);
    border-radius: 1rem;
}
.cf-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in srgb, var(--color-gray-300) 55%, transparent),
        transparent
    );
    animation: cf-sh 1.4s infinite;
}
@keyframes cf-sh {
    100% {
        transform: translateX(100%);
    }
}

/* ---------- DRAWER ---------- */
.cf-drawer {
    position: fixed;
    inset: 0;
    z-index: 70;
    display: none;
}
.cf-drawer.open {
    display: block;
}
.cf-mask {
    position: absolute;
    inset: 0;
    background: rgba(15, 23, 42, 0.55);
    -webkit-backdrop-filter: blur(3px);
    backdrop-filter: blur(3px);
    animation: cf-fade 0.25s ease;
}
@keyframes cf-fade {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}
.cf-panel {
    position: absolute;
    top: 0;
    right: 0;
    height: 100%;
    width: min(480px, 100vw);
    background: var(--color-white);
    border-left: 1px solid var(--color-border-color);
    box-shadow: -30px 0 60px -30px rgba(15, 23, 42, 0.6);
    overflow-y: auto;
    animation: cf-slide 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
@keyframes cf-slide {
    from {
        transform: translateX(100%);
    }
    to {
        transform: none;
    }
}

/* ---------- MODAL ---------- */
.cf-modal {
    position: fixed;
    inset: 0;
    z-index: 75;
    display: none;
}
.cf-modal.open {
    display: block;
}
.cf-dialog {
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
    width: min(580px, 94vw);
    max-height: 90vh;
    overflow: auto;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    border-radius: 1.25rem;
    box-shadow: 0 40px 80px -30px rgba(15, 23, 42, 0.7);
    animation: cf-pop 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}
@keyframes cf-pop {
    from {
        opacity: 0;
        transform: translate(-50%, -46%) scale(0.96);
    }
    to {
        opacity: 1;
        transform: translate(-50%, -50%) scale(1);
    }
}
.cf-drop {
    border: 2px dashed var(--color-border-color);
    border-radius: 1rem;
    padding: 1.6rem;
    text-align: center;
    transition: all 0.2s ease;
    cursor: pointer;
}
.cf-drop:hover,
.cf-drop.drag {
    border-color: var(--color-primary);
    background: color-mix(in srgb, var(--color-primary) 6%, transparent);
}

/* ---------- BULK BAR ---------- */
.cf-bulk {
    position: fixed;
    left: 50%;
    bottom: 1.25rem;
    transform: translateX(-50%) translateY(160%);
    z-index: 60;
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.6rem 0.6rem 0.6rem 1rem;
    border-radius: 1rem;
    background: var(--color-gray-900);
    color: #fff;
    box-shadow: 0 30px 60px -20px rgba(0, 0, 0, 0.6);
    transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
    flex-wrap: wrap;
    max-width: 94vw;
}
.cf-bulk.show {
    transform: translateX(-50%) translateY(0);
}

/* ---------- TOAST ---------- */
#cf-toast {
    position: fixed;
    right: 1rem;
    bottom: 1rem;
    z-index: 90;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}
.cf-toast {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    padding: 0.7rem 0.95rem;
    border-radius: 0.8rem;
    background: var(--color-gray-900);
    color: #fff;
    font-size: 0.8rem;
    font-weight: 700;
    box-shadow: 0 18px 40px -18px rgba(0, 0, 0, 0.6);
    animation: cf-tin 0.3s ease;
}
@keyframes cf-tin {
    from {
        opacity: 0;
        transform: translateY(12px);
    }
    to {
        opacity: 1;
        transform: none;
    }
