    transition: stroke-dashoffset 1.1s cubic-bezier(0.4, 0, 0.2, 1);
}

/* ---------- MONITOR PANEL ---------- */
.im-monitor {
    position: relative;
    border-radius: 0.85rem;
    overflow: hidden;
    border: 1px solid color-mix(in srgb, var(--sv) 35%, var(--im-border));
    background: var(--im-surface);
    transition:
        box-shadow 0.18s,
        transform 0.18s;
}
.im-monitor:hover {
    box-shadow: 0 16px 34px -24px rgba(15, 23, 42, 0.45);
}
.im-monitor.alarm {
    border-color: var(--sv);
    box-shadow: 0 0 0 1px var(--sv);
}
.im-monitor::before {
    content: "";
    position: absolute;
    left: 0;
    top: 0;
    bottom: 0;
    width: 3px;
    background: var(--sv);
    z-index: 1;
}
.im-screen {
    background: var(--im-screen);
}
.im-ecg polyline {
    filter: drop-shadow(0 0 3px currentColor);
}
.im-vcell {
    background: var(--im-panel);
    border-radius: 0.45rem;
}
.im-stab {
    height: 6px;
    border-radius: 999px;
    background: var(--im-track);
    overflow: hidden;
}
.im-stab > span {
    display: block;
    height: 100%;
    border-radius: 999px;
    transition: width 0.5s;
}
.im-avatar {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    color: #fff;
    border-radius: 0.5rem;
}
