}

/* ---------- MENU / MODAL / DRAWER ---------- */
.im-menu {
    position: fixed;
    z-index: 120;
    width: 224px;
    max-height: 72vh;
    overflow-y: auto;
    background: var(--im-elev);
    border: 1px solid var(--im-border);
