    box-shadow: 0 24px 50px -18px rgba(15, 23, 42, 0.45);
    padding: 0.35rem;
    color: var(--im-text);
}
.im-menu button {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    width: 100%;
    text-align: left;
    font-size: 0.8rem;
    padding: 0.5rem 0.55rem;
    border-radius: 0.45rem;
    color: var(--im-text);
}
.im-menu button i {
    color: var(--im-mut);
    font-size: 0.95rem;
}
.im-menu button:hover {
    background: var(--im-hover);
}
.im-menu button.danger {
    color: #dc2626;
}
