    background: color-mix(in srgb, #ef4444 10%, transparent);
}
.im-menu-sep {
    height: 1px;
    background: var(--im-border);
    margin: 0.3rem 0.2rem;
}

.im-modal-wrap {
    position: fixed;
    inset: 0;
    z-index: 130;
    display: none;
}
.im-modal-wrap.open {
    display: block;
}
.im-modal-bg {
    position: absolute;
    inset: 0;
    background: rgba(8, 15, 26, 0.6);
    backdrop-filter: blur(5px);
    animation: im-fade 0.2s;
}
@keyframes im-fade {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}
.im-modal {
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
    width: min(600px, 94vw);
    max-height: 90vh;
    display: flex;
    flex-direction: column;
    background: var(--im-elev);
    color: var(--im-text);
    border: 1px solid var(--im-border);
    border-radius: 1rem;
    box-shadow: 0 40px 90px -24px rgba(2, 6, 15, 0.55);
    animation: im-pop 0.22s cubic-bezier(0.4, 0, 0.2, 1);
    overflow: hidden;
}
@keyframes im-pop {
    from {
        opacity: 0;
        transform: translate(-50%, -47%) scale(0.98);
    }
    to {
        opacity: 1;
        transform: translate(-50%, -50%) scale(1);
    }
}
.im-modal-head {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 1rem 1.15rem;
    border-bottom: 1px solid var(--im-border);
}
