    font-size: 1.05rem;
    flex: none;
}
.im-modal-body {
    padding: 1.15rem;
    overflow-y: auto;
}
.im-modal-foot {
    display: flex;
    justify-content: flex-end;
    gap: 0.5rem;
    padding: 0.9rem 1.15rem;
    border-top: 1px solid var(--im-border);
    background: var(--im-panel);
}
.im-formlabel {
    font-size: 0.72rem;
    font-weight: 600;
    color: var(--im-mut);
    text-transform: uppercase;
    letter-spacing: 0.03em;
}
.im-in {
    width: 100%;
    padding: 0.55rem 0.7rem;
    font-size: 0.82rem;
