    border-radius: 0.55rem;
    background: var(--im-surface);
    color: var(--im-text);
    transition:
        border-color 0.15s,
        box-shadow 0.15s;
}
.im-in:focus {
    outline: none;
    border-color: var(--im-accent);
    box-shadow: 0 0 0 3px color-mix(in srgb, var(--im-accent) 18%, transparent);
}
.im-in::placeholder {
    color: var(--im-soft);
}
.im-drawer {
    position: fixed;
    top: 0;
    right: 0;
    height: 100%;
    width: min(470px, 96vw);
    background: var(--im-elev);
    color: var(--im-text);
    z-index: 125;
    transform: translateX(100%);
    transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    box-shadow: -30px 0 70px -30px rgba(2, 6, 15, 0.5);
    overflow-y: auto;
    border-left: 1px solid var(--im-border);
}
.im-drawer.open {
    transform: none;
}

.im-toast {
    position: fixed;
    bottom: 1.25rem;
    left: 50%;
    transform: translateX(-50%) translateY(120%);
    z-index: 140;
    background: #0f1b2d;
    color: #e5edf5;
    border: 1px solid rgba(148, 163, 184, 0.2);
    padding: 0.7rem 1.05rem;
    border-radius: 0.65rem;
    font-size: 0.82rem;
    font-weight: 500;
    box-shadow: 0 18px 40px -18px rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    gap: 0.5rem;
    transition: transform 0.32s cubic-bezier(0.4, 0, 0.2, 1);
}
.im-toast.show {
    transform: translateX(-50%) translateY(0);
}
.im-bulk {
    position: sticky;
    bottom: 0.75rem;
    z-index: 40;
    background: #0f1b2d;
    color: #e5edf5;
    border-radius: 0.85rem;
    box-shadow: 0 18px 40px -18px rgba(0, 0, 0, 0.55);
    display: none;
    border: 1px solid rgba(148, 163, 184, 0.18);
}
.im-bulk.show {
    display: flex;
}

.im-sk {
    position: relative;
    overflow: hidden;
    background: var(--im-panel);
    border-radius: 0.85rem;
}
.im-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in srgb, var(--color-white) 45%, transparent),
        transparent
    );
    animation: im-shim 1.4s infinite;
}
@keyframes im-shim {
    100% {
        transform: translateX(100%);
    }
}
.im-drop {
    background-image: repeating-linear-gradient(
        0deg,
        var(--im-border) 0,
        var(--im-border) 6px,
        transparent 6px,
        transparent 12px
    );
}
.im-seg {
    display: inline-flex;
    background: var(--im-panel);
    border: 1px solid var(--im-border);
    border-radius: 0.6rem;
    padding: 0.18rem;
    gap: 0.12rem;
}
.im-seg button {
    padding: 0.35rem 0.7rem;
    font-size: 0.74rem;
    font-weight: 600;
    border-radius: 0.42rem;
    color: var(--im-mut);
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
}
.im-seg button.on {
    background: var(--im-surface);
    color: var(--im-text);
    box-shadow: 0 1px 3px rgba(15, 23, 42, 0.15);
