}
.em-muted {
    color: var(--color-gray-500);
}
.em-hairline {
    border-color: var(--color-border-color);
}
.em-card {
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    border-radius: 1.1rem;
    box-shadow: 0 16px 40px -38px rgba(15, 23, 42, 0.5);
}

/* ---------- HERO ---------- */
.em-hero {
    position: relative;
    overflow: hidden;
    border-radius: 1.5rem;
    padding: 1.75rem;
    color: #fff;
    background:
        radial-gradient(
            120% 140% at 0% 0%,
            rgba(20, 184, 166, 0.45),
            transparent 55%
        ),
        radial-gradient(
            120% 160% at 100% 0%,
            rgba(59, 130, 246, 0.5),
            transparent 50%
        ),
        linear-gradient(135deg, #0b1220, #0d2137 55%, #0f172a);
    box-shadow: 0 30px 60px -30px rgba(15, 23, 42, 0.7);
}
.em-hero::after {
    content: "";
    position: absolute;
    inset: 0;
    background-image: radial-gradient(
        rgba(255, 255, 255, 0.06) 1px,
