.dd-drawer {
    position: fixed;
    inset: 0;
    z-index: 70;
    display: none;
}
.dd-drawer.open {
    display: block;
}
.dd-mask {
    position: absolute;
    inset: 0;
    background: rgba(15, 23, 42, 0.55);
    -webkit-backdrop-filter: blur(3px);
    backdrop-filter: blur(3px);
    animation: dd-fade 0.25s ease;
}
@keyframes dd-fade {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}
.dd-panel {
    position: absolute;
    top: 0;
    right: 0;
    height: 100%;
    width: min(480px, 100vw);
    background: var(--color-white);
    border-left: 1px solid var(--color-border-color);
    box-shadow: -30px 0 60px -30px rgba(15, 23, 42, 0.6);
    overflow-y: auto;
    animation: dd-slide 0.3s cubic-bezier(0.4, 0, 0.2, 1);
