/* =====================================================================
   LANDING PAGE  ·  index.html (page-exclusive)
   Namespace: ld- · Marketing/landing page for the template itself.
   Do not reuse these classes in other modules.
   ===================================================================== */
.ld-grid {
    background-image:
        linear-gradient(to right, rgba(2, 113, 198, 0.07) 1px, transparent 1px),
        linear-gradient(to bottom, rgba(2, 113, 198, 0.07) 1px, transparent 1px);
    background-size: 46px 46px;
}
.dark .ld-grid {
    background-image:
        linear-gradient(
            to right,
            rgba(255, 255, 255, 0.05) 1px,
            transparent 1px
        ),
        linear-gradient(
            to bottom,
            rgba(255, 255, 255, 0.05) 1px,
            transparent 1px
        );
}
.ld-mask {
    -webkit-mask-image: radial-gradient(
        ellipse 75% 60% at 50% 0%,
        #000 35%,
        transparent 78%
    );
    mask-image: radial-gradient(
        ellipse 75% 60% at 50% 0%,
        #000 35%,
        transparent 78%
    );
}
.ld-aurora {
    filter: blur(70px);
}
.ld-gtext {
    background: linear-gradient(115deg, #38bdf8, #818cf8 45%, #e879f9);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
}
.ld-glass {
    background: color-mix(in oklab, #ffffff 68%, transparent);
    backdrop-filter: blur(18px) saturate(1.4);
    -webkit-backdrop-filter: blur(18px) saturate(1.4);
}
.dark .ld-glass {
    background: color-mix(in oklab, #0f172a 60%, transparent);
}
.ld-win {
    box-shadow: 0 44px 90px -34px rgba(2, 12, 40, 0.55);
}
.ld-soft {
    box-shadow: 0 24px 60px -30px rgba(2, 12, 40, 0.28);
}
.ld-ring {
    box-shadow: inset 0 0 0 1px rgba(2, 12, 40, 0.06);
}
.dark .ld-ring {
    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.08);
}

@keyframes ld-float {
    0%,
    100% {
        transform: translateY(0);
    }
    50% {
        transform: translateY(-16px);
    }
}
@keyframes ld-float-s {
    0%,
    100% {
        transform: translateY(0) rotate(0deg);
    }
    50% {
        transform: translateY(-11px) rotate(2.5deg);
    }
}
@keyframes ld-pulse-ring {
    0% {
        box-shadow: 0 0 0 0 rgba(16, 185, 129, 0.45);
    }
    70% {
        box-shadow: 0 0 0 10px rgba(16, 185, 129, 0);
    }
    100% {
        box-shadow: 0 0 0 0 rgba(16, 185, 129, 0);
    }
}
@keyframes ld-marquee {
    from {
        transform: translateX(0);
    }
    to {
        transform: translateX(-50%);
    }
}
@keyframes ld-grow {
    from {
        transform: scaleY(0.15);
    }
    to {
        transform: scaleY(1);
    }
}
.ld-float {
    animation: ld-float 6.5s ease-in-out infinite;
}
.ld-float-s {
    animation: ld-float-s 7.5s ease-in-out infinite;
}
.ld-live {
    animation: ld-pulse-ring 2s ease-out infinite;
}
.ld-marquee {
    animation: ld-marquee 30s linear infinite;
}
.ld-marquee-wrap:hover .ld-marquee {
    animation-play-state: paused;
}
.ld-bar {
    transform-origin: bottom;
    animation: ld-grow 0.9s cubic-bezier(0.22, 1, 0.36, 1) both;
}

.ld-tab {
    transition: all 0.25s ease;
}
.ld-tab.is-active {
    color: #fff;
    background-image: linear-gradient(120deg, var(--acc, #0371c6), #8b5cf6);
    box-shadow: 0 12px 26px -12px var(--acc, #0371c6);
}
.ld-tab.is-active .ld-tab-ic {
    color: #fff;
    background: rgba(255, 255, 255, 0.18);
}

.ld-mod {
    transition:
        transform 0.3s ease,
        box-shadow 0.3s ease,
        border-color 0.3s ease;
}
.ld-mod:hover {
    transform: translateY(-6px);
}
.ld-mod:hover .ld-mod-ic {
    transform: translateY(-4px) scale(1.08);
}
.ld-mod-ic {
    transition: transform 0.3s ease;
}

.ld-faq summary {
    list-style: none;
    cursor: pointer;
}
.ld-faq summary::-webkit-details-marker {
    display: none;
}
.ld-faq[open] .ld-faq-ic {
    transform: rotate(45deg);
}
.ld-faq-ic {
    transition: transform 0.25s ease;
}

.ld-underline {
    position: relative;
}
.ld-underline::after {
    content: "";
    position: absolute;
    left: 0;
    bottom: -2px;
    height: 2px;
    width: 0;
    background: linear-gradient(90deg, var(--acc, #0371c6), #8b5cf6);
    transition: width 0.3s ease;
}
.ld-nav-link:hover .ld-underline::after {
    width: 100%;
}

.ld-dot-flow {
    stroke-dasharray: 4 6;
    animation: ld-dash 1.4s linear infinite;
}
@keyframes ld-dash {
    to {
        stroke-dashoffset: -20;
    }
}

@media (prefers-reduced-motion: reduce) {
    .ld-float,
    .ld-float-s,
    .ld-live,
    .ld-marquee,
    .ld-bar,
    .ld-dot-flow {
        animation: none !important;
    }
}

