    border-radius: 0.75rem;
}
.bd-mut {
    color: var(--bd-mut);
}
.bd-head {
    color: var(--bd-text);
}
.bd-hicon {
    color: var(--bd-accent);
}
.bd-npill {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    font-size: 0.68rem;
    font-weight: 600;
    padding: 0.2rem 0.5rem;
    border-radius: 0.4rem;
    background: var(--bd-neutral);
    color: var(--bd-mut);
}
.bd-iconbadge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 0.5rem;
    background: var(--bd-neutral);
    color: var(--bd-mut);
}

/* ---------- HERO ---------- */
.bd-hero {
    position: relative;
    overflow: hidden;
    border-radius: 1rem;
    color: #f6e7e7;
    background: linear-gradient(135deg, #1c0a0f 0%, #2c1017 48%, #160a12 100%);
    border: 1px solid rgba(148, 163, 184, 0.16);
    box-shadow: 0 20px 50px -34px rgba(2, 6, 15, 0.7);
}
.bd-hgrid {
    position: absolute;
    inset: 0;
    background-image:
        linear-gradient(rgba(255, 255, 255, 0.04) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255, 255, 255, 0.04) 1px, transparent 1px);
    background-size: 28px 28px;
    pointer-events: none;
}
.bd-hbadge {
    background: rgba(255, 255, 255, 0.06);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 0.6rem;
    padding: 0.6rem 0.8rem;
}

.bd-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.68rem;
    font-weight: 700;
    padding: 0.2rem 0.55rem;
    border-radius: 0.4rem;
}
.bd-dot {
    width: 7px;
    height: 7px;
    border-radius: 50%;
    display: inline-block;
}
@keyframes bd-pulse {
    0%,
    100% {
        opacity: 1;
    }
    50% {
        opacity: 0.35;
    }
}
.bd-live {
    animation: bd-pulse 1.5s infinite;
}
.bd-btn {
    font-size: 0.82rem;
    font-weight: 600;
    padding: 0.55rem 0.95rem;
    border-radius: 0.55rem;
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    transition: 0.15s;
}
.bd-btn-primary {
    background: #dc2626;
    color: #fff;
}
.bd-btn-primary:hover {
    background: #b91c1c;
}
.bd-btn-ghost {
    background: transparent;
    border: 1px solid var(--bd-border);
    color: var(--bd-text);
}
.bd-btn-ghost:hover {
    background: var(--bd-hover);
}
.bd-btn-danger {
    background: #dc2626;
    color: #fff;
}
.bd-btn-danger:hover {
    background: #b91c1c;
}

/* eligibility palette */
.el-elig {
    --ev: #15803d;
}
.el-soon {
    --ev: #b7791f;
}
.el-defer {
    --ev: #dc2626;
}
.el-new {
    --ev: #1d4ed8;
}
.dark .el-elig {
    --ev: #4ade80;
}
.dark .el-soon {
    --ev: #eab308;
}
.dark .el-defer {
    --ev: #f87171;
}
.dark .el-new {
    --ev: #60a5fa;
}

/* ---------- DONOR CARD (premium) ---------- */
.bd-donor {
    position: relative;
    border-radius: 1.1rem;
    overflow: hidden;
    background: var(--bd-surface);
    border: 1px solid var(--bd-border);
    transition:
        box-shadow 0.25s,
        transform 0.25s,
        border-color 0.25s;
}
.bd-donor:hover {
    box-shadow: 0 26px 50px -26px
        color-mix(in srgb, var(--ev) 45%, rgba(15, 23, 42, 0.4));
    transform: translateY(-4px);
    border-color: color-mix(in srgb, var(--ev) 35%, var(--bd-border));
}
.bd-donor-banner {
    height: 68px;
    position: relative;
    overflow: hidden;
    background: linear-gradient(
        135deg,
        color-mix(in srgb, var(--ev) 62%, #2c1017),
        color-mix(in srgb, var(--ev) 26%, #2c1017)
    );
}
.bd-donor-banner::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image: radial-gradient(
        circle at 88% -30%,
        color-mix(in srgb, #fff 26%, transparent),
        transparent 55%
    );
}
.bd-donor-banner::after {
    content: "";
    position: absolute;
    inset: 0;
    background-image:
        linear-gradient(rgba(255, 255, 255, 0.07) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255, 255, 255, 0.07) 1px, transparent 1px);
    background-size: 16px 16px;
    mask-image: linear-gradient(180deg, #000, transparent);
    -webkit-mask-image: linear-gradient(180deg, #000, transparent);
}
.bd-donor-menubtn {
    background: rgba(0, 0, 0, 0.25);
    color: #fff;
    backdrop-filter: blur(6px);
    transition: background 0.15s;
}
.bd-donor-menubtn:hover {
    background: rgba(0, 0, 0, 0.4);
}
.bd-avatar-ring {
    position: relative;
    padding: 3px;
    border-radius: 1rem;
    background: var(--bd-surface);
    box-shadow: 0 12px 26px -12px rgba(0, 0, 0, 0.4);
}
.bd-avatar {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    font-weight: 700;
    color: #fff;
    border-radius: 0.8rem;
    box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.14);
}
.bd-avatar.round {
    border-radius: 50%;
}
.bd-gtag {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 0.5rem;
    color: #fff;
    font-weight: 800;
    box-shadow:
        0 8px 18px -8px rgba(0, 0, 0, 0.4),
        inset 0 0 0 1px rgba(255, 255, 255, 0.16);
    position: relative;
}
.bd-statusdot {
    width: 13px;
    height: 13px;
    border-radius: 50%;
    border: 2.5px solid var(--bd-surface);
    box-shadow: 0 0 0 2px color-mix(in srgb, var(--ev) 35%, transparent);
}
.bd-donor-name {
    font-size: 0.98rem;
    font-weight: 800;
    letter-spacing: -0.01em;
    color: var(--bd-text);
}
.bd-stat-row {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 0.5rem;
}
.bd-stat {
    background: var(--bd-panel);
    border: 1px solid var(--bd-border);
    border-radius: 0.7rem;
    padding: 0.5rem 0.3rem;
    text-align: center;
    transition: border-color 0.2s;
}
.bd-donor:hover .bd-stat {
    border-color: color-mix(in srgb, var(--ev) 22%, var(--bd-border));
}
.bd-stat-ic {
    width: 20px;
    height: 20px;
    margin: 0 auto 0.3rem;
    border-radius: 0.4rem;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.68rem;
}
.bd-stat-val {
    font-size: 0.86rem;
    font-weight: 800;
    line-height: 1.1;
}
.bd-stat-lbl {
    font-size: 0.6rem;
    font-weight: 600;
    color: var(--bd-mut);
    text-transform: uppercase;
    letter-spacing: 0.02em;
    margin-top: 0.15rem;
}
.bd-stab {
    height: 6px;
    border-radius: 999px;
    background: var(--bd-track);
    overflow: hidden;
}
.bd-stab > span {
    display: block;
    height: 100%;
    border-radius: 999px;
}
.bd-star {
    color: #f59e0b;
}

/* list row */
.bd-row {
    display: grid;
    grid-template-columns: auto 1.6fr 80px 1fr 1fr auto;
    gap: 0.75rem;
    align-items: center;
    padding: 0.65rem 0.85rem;
    border-bottom: 1px solid var(--bd-border);
}
.bd-row:hover {
    background: color-mix(in srgb, var(--bd-c) 4%, transparent);
}

/* ---------- MENU / MODAL / DRAWER ---------- */
.bd-menu {
    position: fixed;
    z-index: 120;
    width: 214px;
    max-height: 72vh;
    overflow-y: auto;
    background: var(--bd-elev);
    border: 1px solid var(--bd-border);
    border-radius: 0.75rem;
    box-shadow: 0 24px 50px -18px rgba(15, 23, 42, 0.45);
    padding: 0.35rem;
    color: var(--bd-text);
}
.bd-menu button {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    width: 100%;
    text-align: left;
    font-size: 0.8rem;
    padding: 0.5rem 0.55rem;
    border-radius: 0.45rem;
    color: var(--bd-text);
}
.bd-menu button i {
    color: var(--bd-mut);
    font-size: 0.95rem;
}
.bd-menu button:hover {
    background: var(--bd-hover);
}
.bd-menu button.danger {
    color: #dc2626;
}
.bd-menu button.danger i {
    color: #dc2626;
}
.bd-menu button.danger:hover {
    background: color-mix(in srgb, #ef4444 10%, transparent);
}
.bd-menu-sep {
    height: 1px;
    background: var(--bd-border);
    margin: 0.3rem 0.2rem;
}

.bd-modal-wrap {
    position: fixed;
    inset: 0;
    z-index: 130;
    display: none;
}
.bd-modal-wrap.open {
    display: block;
}
.bd-modal-bg {
    position: absolute;
    inset: 0;
    background: rgba(8, 15, 26, 0.6);
    backdrop-filter: blur(5px);
    animation: bd-fade 0.2s;
}
@keyframes bd-fade {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}
.bd-modal {
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
    width: min(600px, 94vw);
    max-height: 90vh;
    display: flex;
    flex-direction: column;
    background: var(--bd-elev);
    color: var(--bd-text);
    border: 1px solid var(--bd-border);
    border-radius: 1rem;
    box-shadow: 0 40px 90px -24px rgba(2, 6, 15, 0.55);
    animation: bd-pop 0.22s cubic-bezier(0.4, 0, 0.2, 1);
    overflow: hidden;
}
@keyframes bd-pop {
    from {
        opacity: 0;
        transform: translate(-50%, -47%) scale(0.98);
    }
    to {
        opacity: 1;
        transform: translate(-50%, -50%) scale(1);
    }
}
.bd-modal-head {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 1rem 1.15rem;
    border-bottom: 1px solid var(--bd-border);
}
.bd-modal-badge {
    width: 38px;
    height: 38px;
    border-radius: 0.6rem;
    display: flex;
    align-items: center;
    justify-content: center;
    background: color-mix(in srgb, #dc2626 15%, transparent);
    color: #dc2626;
    font-size: 1.05rem;
    flex: none;
}
.bd-modal-body {
    padding: 1.15rem;
    overflow-y: auto;
}
.bd-modal-foot {
    display: flex;
    justify-content: flex-end;
    gap: 0.5rem;
    padding: 0.9rem 1.15rem;
    border-top: 1px solid var(--bd-border);
    background: var(--bd-panel);
}
.bd-formlabel {
    font-size: 0.72rem;
    font-weight: 600;
    color: var(--bd-mut);
    text-transform: uppercase;
    letter-spacing: 0.03em;
}
.bd-in {
    width: 100%;
    padding: 0.55rem 0.7rem;
    font-size: 0.82rem;
    border: 1px solid var(--bd-border);
    border-radius: 0.55rem;
    background: var(--bd-surface);
    color: var(--bd-text);
    transition:
        border-color 0.15s,
        box-shadow 0.15s;
}
.bd-in:focus {
    outline: none;
    border-color: #dc2626;
    box-shadow: 0 0 0 3px color-mix(in srgb, #dc2626 18%, transparent);
}
.bd-in::placeholder {
    color: var(--bd-soft);
}
.bd-drawer {
    position: fixed;
    top: 0;
    right: 0;
    height: 100%;
    width: min(470px, 96vw);
    background: var(--bd-elev);
    color: var(--bd-text);
    z-index: 125;
    transform: translateX(100%);
    transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    box-shadow: -30px 0 70px -30px rgba(2, 6, 15, 0.5);
    overflow-y: auto;
    border-left: 1px solid var(--bd-border);
}
.bd-drawer.open {
    transform: none;
}

.bd-toast {
    position: fixed;
    bottom: 1.25rem;
    left: 50%;
    transform: translateX(-50%) translateY(120%);
    z-index: 140;
    background: #0f1b2d;
    color: #e5edf5;
    border: 1px solid rgba(148, 163, 184, 0.2);
    padding: 0.7rem 1.05rem;
    border-radius: 0.65rem;
    font-size: 0.82rem;
    font-weight: 500;
    box-shadow: 0 18px 40px -18px rgba(0, 0, 0, 0.5);
    display: flex;
    align-items: center;
    gap: 0.5rem;
    transition: transform 0.32s cubic-bezier(0.4, 0, 0.2, 1);
}
.bd-toast.show {
    transform: translateX(-50%) translateY(0);
}
.bd-bulk {
    position: sticky;
    bottom: 0.75rem;
    z-index: 40;
    background: #0f1b2d;
    color: #e5edf5;
    border-radius: 0.85rem;
    box-shadow: 0 18px 40px -18px rgba(0, 0, 0, 0.55);
    display: none;
    border: 1px solid rgba(148, 163, 184, 0.18);
}
.bd-bulk.show {
    display: flex;
}

.bd-sk {
    position: relative;
    overflow: hidden;
    background: var(--bd-panel);
    border-radius: 0.85rem;
}
.bd-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in srgb, var(--color-white) 45%, transparent),
        transparent
    );
    animation: bd-shim 1.4s infinite;
}
@keyframes bd-shim {
    100% {
        transform: translateX(100%);
    }
}
.bd-dropz {
    background-image: repeating-linear-gradient(
        0deg,
        var(--bd-border) 0,
        var(--bd-border) 6px,
        transparent 6px,
        transparent 12px
    );
}
.bd-seg {
    display: inline-flex;
    background: var(--bd-panel);
    border: 1px solid var(--bd-border);
    border-radius: 0.6rem;
    padding: 0.18rem;
    gap: 0.12rem;
}
.bd-seg button {
    padding: 0.35rem 0.7rem;
    font-size: 0.74rem;
    font-weight: 600;
    border-radius: 0.42rem;
    color: var(--bd-mut);
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
}
.bd-seg button.on {
    background: var(--bd-surface);
    color: var(--bd-text);
    box-shadow: 0 1px 3px rgba(15, 23, 42, 0.15);
}

/* ============================================================
   DOCTOR SCHEDULE · doctor-schedule.html (page-exclusive)
   Do not reuse these classes in other modules.
   ============================================================ */
#ds-page {
    --ds-c: var(--color-primary);
}
.ds-surface {
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    border-radius: 1.25rem;
    box-shadow: 0 20px 45px -35px rgba(15, 23, 42, 0.4);
}
.ds-muted {
    color: var(--color-gray-500);
}

.ds-layout {
    display: grid;
    grid-template-columns: 1fr;
    gap: 1.25rem;
    align-items: start;
}
@media (min-width: 1280px) {
    .ds-layout {
        grid-template-columns: minmax(0, 1fr) 330px;
    }
}
.ds-grid {
    display: grid;
    gap: 0.9rem;
}
.ds-g6 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
}
@media (min-width: 700px) {
    .ds-g6 {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}
@media (min-width: 1200px) {
    .ds-g6 {
        grid-template-columns: repeat(6, minmax(0, 1fr));
    }
}

/* ---------- HERO ---------- */
.ds-hero {
    position: relative;
    overflow: hidden;
    border-radius: 1.5rem;
    padding: 1.75rem;
    color: #fff;
    background:
        radial-gradient(
            120% 140% at 0% 0%,
            rgba(14, 165, 233, 0.5),
            transparent 55%
        ),
        radial-gradient(
            120% 160% at 100% 0%,
            rgba(20, 184, 166, 0.5),
            transparent 50%
        ),
        linear-gradient(135deg, #0f172a, #0d2436 55%, #0b1220);
    box-shadow: 0 30px 60px -30px rgba(15, 23, 42, 0.7);
}
.ds-hero::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image: radial-gradient(
        rgba(255, 255, 255, 0.08) 1px,
        transparent 1px
    );
    background-size: 22px 22px;
    -webkit-mask-image: linear-gradient(180deg, #000, transparent 75%);
    mask-image: linear-gradient(180deg, #000, transparent 75%);
}
.ds-hero > * {
    position: relative;
    z-index: 1;
}
@media (min-width: 1024px) {
    .ds-hero {
        padding: 2rem 2.25rem;
    }
}
.ds-hbadge {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.25rem 0.7rem;
    border-radius: 9999px;
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    background: rgba(255, 255, 255, 0.14);
    border: 1px solid rgba(255, 255, 255, 0.22);
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
}
.ds-hmeta {
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
    padding: 0.45rem 0.8rem;
    border-radius: 0.8rem;
    background: rgba(255, 255, 255, 0.1);
    border: 1px solid rgba(255, 255, 255, 0.16);
    font-size: 0.72rem;
    font-weight: 700;
}
.ds-dot {
    width: 0.5rem;
    height: 0.5rem;
    border-radius: 9999px;
    background: #2dd4bf;
    box-shadow: 0 0 0 4px rgba(45, 212, 191, 0.25);
    animation: ds-pulse 2s ease-in-out infinite;
}
@keyframes ds-pulse {
    0%,
    100% {
        opacity: 1;
    }
    50% {
        opacity: 0.4;
    }
}

/* ---------- BUTTONS ---------- */
.ds-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    padding: 0.55rem 0.9rem;
    border-radius: 0.8rem;
    font-size: 0.8rem;
    font-weight: 700;
    cursor: pointer;
    border: 1px solid transparent;
    white-space: nowrap;
    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease,
        background 0.2s ease,
        color 0.2s ease,
        border-color 0.2s ease;
}
.ds-btn:hover {
    transform: translateY(-2px);
}
.ds-btn-primary {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    box-shadow: 0 12px 24px -12px var(--color-primary);
}
.ds-btn-success {
    background: linear-gradient(135deg, #14b8a6, #0d9488);
    color: #fff;
    box-shadow: 0 12px 24px -12px #14b8a6;
}
.ds-btn-glass {
    background: rgba(255, 255, 255, 0.12);
    color: #fff;
    border-color: rgba(255, 255, 255, 0.24);
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
}
.ds-btn-glass:hover {
    background: rgba(255, 255, 255, 0.2);
}
.ds-btn-soft {
    background: var(--color-gray-100);
    color: var(--color-gray-700);
    border-color: var(--color-border-color);
}
.ds-btn-soft:hover {
    background: var(--color-gray-200);
}

/* ---------- KPI ---------- */
.ds-kpi {
    position: relative;
    overflow: hidden;
    padding: 1rem 1.05rem;
    border-radius: 1.1rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 16px 30px -28px rgba(15, 23, 42, 0.5);
}
.ds-kpi-ic {
    width: 2.4rem;
    height: 2.4rem;
    border-radius: 0.8rem;
    display: flex;
    align-items: center;
    justify-content: center;
}
.ds-kpi-v {
    font-size: 1.55rem;
    font-weight: 800;
    line-height: 1;
    color: var(--color-gray-900);
}
.ds-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.18rem 0.5rem;
    border-radius: 9999px;
    font-size: 0.66rem;
    font-weight: 800;
}

/* ---------- SEGMENT / TABS ---------- */
.ds-seg {
    display: inline-flex;
    padding: 0.2rem;
    border-radius: 0.7rem;
    background: var(--color-gray-100);
    border: 1px solid var(--color-border-color);
}
.ds-segb {
    padding: 0.4rem 0.8rem;
    border-radius: 0.5rem;
    font-size: 0.76rem;
    font-weight: 700;
    color: var(--color-gray-600);
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    white-space: nowrap;
}
.ds-segb.active {
    background: var(--color-white);
    color: var(--color-primary-text);
    box-shadow: 0 6px 14px -10px rgba(15, 23, 42, 0.5);
}

/* ---------- ROSTER GRID (week view) ---------- */
.ds-week {
    display: grid;
    grid-template-columns: 180px repeat(7, minmax(88px, 1fr));
    border: 1px solid var(--color-border-color);
    border-radius: 1rem;
    overflow: hidden;
    min-width: 820px;
}
.ds-wc {
    border-right: 1px solid var(--color-border-color);
    border-bottom: 1px solid var(--color-border-color);
    padding: 0.55rem;
}
.ds-whd {
    background: var(--color-gray-100);
    font-size: 0.72rem;
    font-weight: 800;
    text-align: center;
    color: var(--color-gray-700);
}
.ds-whd.today {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
}
.ds-doccell {
    display: flex;
    align-items: center;
    gap: 0.6rem;
    background: var(--color-white);
}
.ds-av {
    width: 2.1rem;
    height: 2.1rem;
    border-radius: 0.6rem;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.65rem;
    font-weight: 800;
    color: #fff;
    flex: none;
}
.ds-shift {
    display: block;
    width: 100%;
    padding: 0.35rem 0.3rem;
    border-radius: 0.5rem;
    font-size: 0.64rem;
    font-weight: 700;
    text-align: center;
    margin-bottom: 0.2rem;
    line-height: 1.15;
    cursor: pointer;
    transition: transform 0.12s ease;
}
.ds-shift:hover {
    transform: scale(1.04);
}
.ds-off {
    font-size: 0.62rem;
    color: var(--color-gray-400);
    text-align: center;
    font-weight: 700;
    padding-top: 0.3rem;
}

/* ---------- TIMELINE (day view) ---------- */
.ds-tl-row {
    display: grid;
    grid-template-columns: 180px 1fr;
    gap: 0.5rem;
    align-items: center;
    padding: 0.5rem 0;
    border-bottom: 1px dashed var(--color-border-color);
}
.ds-tl-track {
    position: relative;
    height: 2.2rem;
    background: var(--color-gray-100);
    border-radius: 0.6rem;
    overflow: hidden;
}
.ds-tl-block {
    position: absolute;
    top: 0.25rem;
    bottom: 0.25rem;
    border-radius: 0.45rem;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.62rem;
    font-weight: 800;
    color: #fff;
    overflow: hidden;
    cursor: pointer;
    white-space: nowrap;
    padding: 0 0.3rem;
}
.ds-tl-axis {
    display: grid;
    grid-template-columns: 180px 1fr;
    gap: 0.5rem;
}
.ds-tl-ticks {
    display: flex;
    justify-content: space-between;
    font-size: 0.6rem;
    color: var(--color-gray-400);
    font-weight: 700;
}

/* ---------- LEAVE ROW ---------- */
.ds-row {
    display: flex;
    align-items: center;
    gap: 0.9rem;
    padding: 0.75rem;
    border: 1px solid var(--color-border-color);
    border-radius: 0.9rem;
    transition: all 0.18s ease;
}
.ds-row:hover {
    border-color: var(--color-primary);
    box-shadow: 0 12px 26px -22px rgba(15, 23, 42, 0.5);
}

.ds-tag {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.24rem 0.55rem;
    border-radius: 9999px;
    font-size: 0.66rem;
    font-weight: 700;
}
.ds-bar {
    height: 0.5rem;
    border-radius: 9999px;
    background: var(--color-gray-200);
    overflow: hidden;
}
.ds-bar > span {
    display: block;
    height: 100%;
    border-radius: 9999px;
}
.ds-inp {
    width: 100%;
    padding: 0.6rem 0.75rem;
    border-radius: 0.7rem;
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.82rem;
}
.ds-inp:focus {
    outline: none;
    border-color: var(--color-primary);
    box-shadow: 0 0 0 3px
        color-mix(in srgb, var(--color-primary) 20%, transparent);
}
.ds-lbl {
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--color-gray-600);
    margin-bottom: 0.3rem;
    display: block;
}

/* ---------- SKELETON ---------- */
.ds-sk {
    position: relative;
    overflow: hidden;
    background: var(--color-gray-100);
    border-radius: 1rem;
}
.ds-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in srgb, var(--color-gray-300) 55%, transparent),
        transparent
    );
    animation: ds-sh 1.4s infinite;
}
@keyframes ds-sh {
    100% {
        transform: translateX(100%);
    }
}

/* ---------- MODAL ---------- */
.ds-modal {
    position: fixed;
    inset: 0;
    z-index: 75;
    display: none;
}
.ds-modal.open {
    display: block;
}
.ds-mask {
    position: absolute;
    inset: 0;
    background: rgba(15, 23, 42, 0.55);
    -webkit-backdrop-filter: blur(3px);
    backdrop-filter: blur(3px);
    animation: ds-fade 0.25s ease;
}
@keyframes ds-fade {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}
.ds-dialog {
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
    width: min(540px, 94vw);
    max-height: 90vh;
    overflow: auto;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    border-radius: 1.25rem;
    box-shadow: 0 40px 80px -30px rgba(15, 23, 42, 0.7);
    animation: ds-pop 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}
@keyframes ds-pop {
    from {
        opacity: 0;
        transform: translate(-50%, -46%) scale(0.96);
    }
    to {
        opacity: 1;
        transform: translate(-50%, -50%) scale(1);
    }
}

/* ---------- TOAST ---------- */
#ds-toast {
    position: fixed;
    right: 1rem;
    bottom: 1rem;
    z-index: 90;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}
.ds-toast {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    padding: 0.7rem 0.95rem;
    border-radius: 0.8rem;
    background: var(--color-gray-900);
    color: #fff;
    font-size: 0.8rem;
    font-weight: 700;
    box-shadow: 0 18px 40px -18px rgba(0, 0, 0, 0.6);
    animation: ds-tin 0.3s ease;
}
@keyframes ds-tin {
    from {
        opacity: 0;
        transform: translateY(12px);
    }
    to {
        opacity: 1;
        transform: none;
    }
}

