/* ---------- HERO / PROFILE HEADER ---------- */
.dp-hero {
    position: relative;
    overflow: hidden;
    border-radius: 1.5rem;
    color: #fff;
    background:
        radial-gradient(
            120% 140% at 0% 0%,
            rgba(14, 165, 233, 0.5),
            transparent 55%
        ),
        radial-gradient(
            120% 160% at 100% 0%,
            rgba(99, 102, 241, 0.55),
            transparent 50%
        ),
