    font-weight: 800;
}

/* ---------- TABS ---------- */
.sup-tabs {
    display: flex;
    gap: 0.35rem;
    overflow-x: auto;
    padding: 0.3rem;
    border-radius: 1rem;
    background: var(--color-gray-100);
    border: 1px solid var(--color-border-color);
}
.sup-tab {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.55rem 0.95rem;
    border-radius: 0.75rem;
    font-size: 0.8rem;
    font-weight: 700;
    color: var(--color-gray-600);
    cursor: pointer;
    white-space: nowrap;
    transition: all 0.2s ease;
}
.sup-tab:hover {
    color: var(--color-gray-900);
}
.sup-tab.active {
    background: var(--color-white);
    color: var(--color-primary-text);
    box-shadow: 0 8px 18px -12px rgba(15, 23, 42, 0.4);
}
.sup-panel {
    animation: sup-fade 0.35s ease;
}
@keyframes sup-fade {
    from {
        opacity: 0;
        transform: translateY(8px);
    }
    to {
        opacity: 1;
        transform: none;
    }
}

/* ---------- RINGS ---------- */
.sup-ring {
    transform: rotate(-90deg);
}
.sup-ring .bar {
    stroke-dasharray: 100 100;
    stroke-dashoffset: calc(100 - var(--p, 0));
    transition: stroke-dashoffset 1.1s cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* ---------- MISC ---------- */
.sup-tag {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.3rem 0.65rem;
    border-radius: 9999px;
    font-size: 0.72rem;
    font-weight: 700;
    background: var(--color-gray-100);
    color: var(--color-gray-700);
    border: 1px solid var(--color-border-color);
}
.sup-bar {
    height: 0.5rem;
    border-radius: 9999px;
    background: var(--color-gray-200);
    overflow: hidden;
}
.sup-bar > span {
    display: block;
    height: 100%;
    border-radius: 9999px;
    background: linear-gradient(90deg, var(--color-primary), #6366f1);
}
.sup-star {
    color: #f59e0b;
}
.sup-timeitem {
    position: relative;
    padding-left: 1.4rem;
    padding-bottom: 1.1rem;
}
.sup-timeitem::before {
    content: "";
    position: absolute;
    left: 0.28rem;
    top: 0.3rem;
    bottom: 0;
    width: 2px;
    background: var(--color-border-color);
}
.sup-timeitem:last-child::before {
    display: none;
}
.sup-timedot {
    position: absolute;
    left: 0;
    top: 0.25rem;
    width: 0.65rem;
    height: 0.65rem;
    border-radius: 9999px;
    background: var(--color-primary);
    box-shadow: 0 0 0 4px
        color-mix(in srgb, var(--color-primary) 20%, transparent);
}
