    color: #fff;
    flex: none;
}

/* ---------- SKELETON ---------- */
.sup-sk {
    position: relative;
    overflow: hidden;
    background: var(--color-gray-100);
    border-radius: 1rem;
}
.sup-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in srgb, var(--color-gray-300) 55%, transparent),
        transparent
    );
    animation: sup-sh 1.4s infinite;
}
@keyframes sup-sh {
    100% {
        transform: translateX(100%);
    }
}

/* ---------- MODAL / DRAWER ---------- */
.sup-modal {
    position: fixed;
    inset: 0;
    z-index: 70;
    display: none;
}
.sup-modal.open {
    display: block;
}
.sup-mask {
    position: absolute;
    inset: 0;
    background: rgba(15, 23, 42, 0.55);
    -webkit-backdrop-filter: blur(3px);
    backdrop-filter: blur(3px);
    animation: sup-fade 0.25s ease;
}
.sup-dialog {
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
    width: min(560px, 94vw);
    max-height: 90vh;
    overflow: auto;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    border-radius: 1.25rem;
    box-shadow: 0 40px 80px -30px rgba(15, 23, 42, 0.7);
    animation: sup-pop 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}
@keyframes sup-pop {
    from {
        opacity: 0;
        transform: translate(-50%, -46%) scale(0.96);
    }
    to {
        opacity: 1;
        transform: translate(-50%, -50%) scale(1);
    }
}
.sup-inp {
    width: 100%;
    padding: 0.6rem 0.75rem;
    border-radius: 0.7rem;
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.82rem;
}
.sup-inp:focus {
    outline: none;
    border-color: var(--color-primary);
    box-shadow: 0 0 0 3px
        color-mix(in srgb, var(--color-primary) 20%, transparent);
}
.sup-lbl {
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--color-gray-600);
    margin-bottom: 0.3rem;
    display: block;
}

/* ---------- TOAST ---------- */
#sup-toast {
    position: fixed;
    right: 1rem;
    bottom: 1rem;
    z-index: 90;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}
.sup-toast {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    padding: 0.7rem 0.95rem;
    border-radius: 0.8rem;
    background: var(--color-gray-900);
    color: #fff;
    font-size: 0.8rem;
    font-weight: 700;
    box-shadow: 0 18px 40px -18px rgba(0, 0, 0, 0.6);
    animation: sup-tin 0.3s ease;
}
@keyframes sup-tin {
    from {
        opacity: 0;
        transform: translateY(12px);
    }
    to {
        opacity: 1;
        transform: none;
    }
}

