    place-items: center;
    width: 2.4rem;
    height: 2.4rem;
    border-radius: 0.8rem;
    color: #fff;
    font-size: 1.05rem;
}

/* Reference-range bar — plain divs (not SVG rx) so the pill ends stay
   perfectly round no matter how wide the track renders. */
.lrd-range {
    margin-top: 0.85rem;
}
.lrd-range-track {
    position: relative;
    height: 0.4rem;
    border-radius: 9999px;
    background: var(--color-gray-100);
}
.dark .lrd-range-track {
    background: rgba(255, 255, 255, 0.08);
}
.lrd-range-zone {
    position: absolute;
    top: 0;
    bottom: 0;
    border-radius: 9999px;
    background: color-mix(in oklab, var(--lrd-c) 35%, transparent);
}
.lrd-range-marker {
    position: absolute;
    top: 50%;
    width: 0.9rem;
    height: 0.9rem;
    border-radius: 9999px;
    background: #fff;
    border-width: 3px;
    border-style: solid;
    transform: translate(-50%, -50%);
    box-shadow: 0 2px 6px rgba(15, 23, 42, 0.3);
}
.lrd-range-labels {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-top: 0.4rem;
    font-size: 0.66rem;
    font-weight: 700;
    color: var(--color-gray-400);
}
.lrd-range-ref {
    color: var(--color-gray-400);
    font-weight: 600;
}

/* Trend sparkline. */
.lrd-spark-wrap {
    width: 7.5rem;
    height: 2.25rem;
    flex-shrink: 0;
}
.lrd-spark {
    width: 100%;
    height: 100%;
    display: block;
}

