    position: relative;
    display: flex;
    gap: 0.7rem;
    padding-bottom: 1rem;
}
.lrd-tl:last-child {
    padding-bottom: 0;
}
.lrd-tl:not(:last-child)::before {
    content: "";
    position: absolute;
    left: 0.55rem;
    top: 1.4rem;
    bottom: 0;
    width: 1px;
    background: var(--color-border-color);
}
.dark .lrd-tl:not(:last-child)::before {
    background: rgba(255, 255, 255, 0.1);
}
.lrd-tl-dot {
    position: relative;
    z-index: 1;
    flex-shrink: 0;
    display: grid;
    place-items: center;
