}

/* ---------- SKELETON ---------- */
.da-sk {
    position: relative;
    overflow: hidden;
    background: var(--color-gray-100);
    border-radius: 1rem;
}
.da-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in srgb, var(--color-gray-300) 55%, transparent),
        transparent
    );
    animation: da-sh 1.4s infinite;
}
@keyframes da-sh {
    100% {
        transform: translateX(100%);
    }
}

/* ---------- DRAWER ---------- */
.da-drawer {
    position: fixed;
    inset: 0;
    z-index: 70;
    display: none;
}
.da-drawer.open {
    display: block;
}
.da-mask {
    position: absolute;
    inset: 0;
    background: rgba(15, 23, 42, 0.55);
    -webkit-backdrop-filter: blur(3px);
    backdrop-filter: blur(3px);
    animation: da-fade 0.25s ease;
}
@keyframes da-fade {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}
.da-panel {
    position: absolute;
    top: 0;
    right: 0;
    height: 100%;
    width: min(480px, 100vw);
    background: var(--color-white);
    border-left: 1px solid var(--color-border-color);
    box-shadow: -30px 0 60px -30px rgba(15, 23, 42, 0.6);
    overflow-y: auto;
    animation: da-slide 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
@keyframes da-slide {
    from {
        transform: translateX(100%);
    }
    to {
        transform: none;
    }
}

/* ---------- MODAL ---------- */
.da-modal {
    position: fixed;
    inset: 0;
    z-index: 75;
    display: none;
}
.da-modal.open {
    display: block;
}
.da-dialog {
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
    width: min(560px, 94vw);
    max-height: 90vh;
    overflow: auto;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    border-radius: 1.25rem;
    box-shadow: 0 40px 80px -30px rgba(15, 23, 42, 0.7);
    animation: da-pop 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}
@keyframes da-pop {
    from {
        opacity: 0;
        transform: translate(-50%, -46%) scale(0.96);
    }
    to {
        opacity: 1;
        transform: translate(-50%, -50%) scale(1);
    }
}
.da-drop {
    border: 2px dashed var(--color-border-color);
    border-radius: 1rem;
    padding: 1.6rem;
