    border: 1px solid var(--color-border-color);
    border-radius: 0.85rem;
    padding: 0.75rem;
    margin-bottom: 0.6rem;
    cursor: grab;
    box-shadow: 0 10px 24px -22px rgba(15, 23, 42, 0.5);
    transition:
        transform 0.15s ease,
        box-shadow 0.15s ease;
    border-left: 3px solid var(--kc, #94a3b8);
}
.lv-kcard:hover {
    transform: translateY(-2px);
    box-shadow: 0 16px 30px -20px rgba(15, 23, 42, 0.5);
}
.lv-kcard.dragging {
    opacity: 0.5;
}

.lv-av {
    width: 2rem;
    height: 2rem;
    border-radius: 0.55rem;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.62rem;
    font-weight: 800;
    color: #fff;
    flex: none;
}
.lv-tag {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.24rem 0.55rem;
    border-radius: 9999px;
    font-size: 0.66rem;
    font-weight: 700;
}
.lv-bar {
    height: 0.5rem;
    border-radius: 9999px;
    background: var(--color-gray-200);
    overflow: hidden;
}
.lv-bar > span {
    display: block;
    height: 100%;
    border-radius: 9999px;
}
.lv-dotstat {
    width: 0.55rem;
    height: 0.55rem;
    border-radius: 9999px;
    flex: none;
}

/* ---------- ACTION MENU ---------- */
.lv-menu {
    position: fixed;
    z-index: 80;
    width: 212px;
    max-height: 70vh;
    overflow: auto;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    border-radius: 0.85rem;
    box-shadow: 0 30px 60px -20px rgba(15, 23, 42, 0.5);
    padding: 0.35rem;
    display: none;
}
.lv-menu.open {
    display: block;
    animation: lv-pop 0.18s ease;
}
.lv-mi {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    padding: 0.5rem 0.6rem;
    border-radius: 0.55rem;
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--color-gray-700);
    cursor: pointer;
}
.lv-mi:hover {
    background: var(--color-gray-100);
}
.lv-mi.danger {
    color: #dc2626;
}
.lv-mi.danger:hover {
    background: color-mix(in srgb, #ef4444 12%, transparent);
}
.lv-mi.ok {
    color: #059669;
}
.lv-mi.ok:hover {
    background: color-mix(in srgb, #10b981 12%, transparent);
}
.lv-sep {
    height: 1px;
    background: var(--color-border-color);
    margin: 0.3rem 0.2rem;
}

/* ---------- SKELETON ---------- */
.lv-sk {
    position: relative;
    overflow: hidden;
    background: var(--color-gray-100);
    border-radius: 1rem;
}
.lv-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in srgb, var(--color-gray-300) 55%, transparent),
        transparent
    );
    animation: lv-sh 1.4s infinite;
}
@keyframes lv-sh {
    100% {
        transform: translateX(100%);
    }
}

/* ---------- DRAWER ---------- */
.lv-drawer {
    position: fixed;
    inset: 0;
    z-index: 70;
    display: none;
}
.lv-drawer.open {
    display: block;
}
.lv-mask {
    position: absolute;
    inset: 0;
    background: rgba(15, 23, 42, 0.55);
    -webkit-backdrop-filter: blur(3px);
    backdrop-filter: blur(3px);
    animation: lv-fade 0.25s ease;
}
@keyframes lv-fade {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}
.lv-panel {
    position: absolute;
    top: 0;
    right: 0;
    height: 100%;
    width: min(480px, 100vw);
    background: var(--color-white);
    border-left: 1px solid var(--color-border-color);
    box-shadow: -30px 0 60px -30px rgba(15, 23, 42, 0.6);
    overflow-y: auto;
    animation: lv-slide 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
@keyframes lv-slide {
    from {
        transform: translateX(100%);
    }
    to {
        transform: none;
    }
}

/* ---------- MODAL ---------- */
.lv-modal {
    position: fixed;
    inset: 0;
    z-index: 75;
    display: none;
}
.lv-modal.open {
    display: block;
}
.lv-dialog {
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
    width: min(560px, 94vw);
    max-height: 90vh;
    overflow: auto;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    border-radius: 1.25rem;
    box-shadow: 0 40px 80px -30px rgba(15, 23, 42, 0.7);
    animation: lv-pop 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}
@keyframes lv-pop {
    from {
        opacity: 0;
        transform: translate(-50%, -46%) scale(0.96);
    }
    to {
        opacity: 1;
        transform: translate(-50%, -50%) scale(1);
    }
}
.lv-drop {
    border: 2px dashed var(--color-border-color);
    border-radius: 1rem;
    padding: 1.6rem;
    text-align: center;
    transition: all 0.2s ease;
    cursor: pointer;
}
.lv-drop:hover,
.lv-drop.drag {
    border-color: var(--color-primary);
    background: color-mix(in srgb, var(--color-primary) 6%, transparent);
}

/* ---------- BULK BAR ---------- */
.lv-bulk {
    position: fixed;
    left: 50%;
    bottom: 1.25rem;
    transform: translateX(-50%) translateY(160%);
    z-index: 60;
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.6rem 0.6rem 0.6rem 1rem;
    border-radius: 1rem;
    background: var(--color-gray-900);
    color: #fff;
    box-shadow: 0 30px 60px -20px rgba(0, 0, 0, 0.6);
    transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
    flex-wrap: wrap;
    max-width: 94vw;
}
.lv-bulk.show {
    transform: translateX(-50%) translateY(0);
}

/* ---------- TOAST ---------- */
#lv-toast {
    position: fixed;
    right: 1rem;
    bottom: 1rem;
    z-index: 90;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}
.lv-toast {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    padding: 0.7rem 0.95rem;
    border-radius: 0.8rem;
    background: var(--color-gray-900);
    color: #fff;
    font-size: 0.8rem;
    font-weight: 700;
    box-shadow: 0 18px 40px -18px rgba(0, 0, 0, 0.6);
    animation: lv-tin 0.3s ease;
}
@keyframes lv-tin {
    from {
        opacity: 0;
        transform: translateY(12px);
    }
    to {
        opacity: 1;
        transform: none;
    }
}

input[type="checkbox"].lv-cb {
    width: 1.05rem;
    height: 1.05rem;
    border-radius: 0.35rem;
    accent-color: var(--color-primary);
    cursor: pointer;
}

/* =====================================================================
   CASCADE-SAFE OVERRIDE UTILITIES
   Every page-exclusive CSS section above is intentionally unlayered (to
   win over @layer components). Per CSS cascade-layers rules, unlayered
   declarations always beat layered ones — including every Tailwind
   utility class, which compiles into @layer utilities — regardless of
   specificity or source order. So whenever an element carries a
   page-specific component class (e.g. a skeleton-loader base class)
   that already sets a property as a default, a Tailwind arbitrary-value
   class trying to override that same property on that element silently
   does nothing. These small unlayered classes exist so such per-instance
   overrides actually apply; use them instead of a Tailwind class
   whenever the underlying component class already sets the same
   property. Shared across pages — do not scope-prefix these.
   ===================================================================== */
.radius-override-90 {
    border-radius: 0.9rem;
}
.radius-override-100 {
    border-radius: 1rem;
}
.radius-override-125 {
    border-radius: 1.25rem;
}
.radius-override-150 {
    border-radius: 1.5rem;
}
.margin-top-auto-override {
    margin-top: auto;
}

/* =====================================================================
   PATIENT DOCUMENT MANAGEMENT CENTER  ·  patient-documents.html (page-exclusive)
   ===================================================================== */
/* ================================================================
               PATIENT DOCUMENT MANAGEMENT CENTER — self-contained (inline).
               Design-system CSS variables → automatic light / dark.
               ================================================================ */
#doc-page {
    --doc-c: var(--color-primary);
}
.doc-surface {
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    border-radius: 1.25rem;
    box-shadow: 0 20px 45px -35px rgba(15, 23, 42, 0.4);
}

.doc-layout {
    display: grid;
    grid-template-columns: 1fr;
    gap: 1.25rem;
    align-items: start;
}
@media (min-width: 1280px) {
    .doc-layout {
        grid-template-columns: minmax(0, 1fr) 340px;
    }
}
.doc-grid {
    display: grid;
    gap: 0.9rem;
}
.doc-g3 {
    grid-template-columns: repeat(1, minmax(0, 1fr));
}
.doc-g6 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
}
@media (min-width: 640px) {
    .doc-g3 {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}
@media (min-width: 900px) {
    .doc-g3 {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
    .doc-g6 {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}
@media (min-width: 1200px) {
    .doc-g6 {
        grid-template-columns: repeat(6, minmax(0, 1fr));
    }
}
.doc-cards {
    display: grid;
    gap: 1rem;
    grid-template-columns: 1fr;
}
.doc-cards.hidden {
    display: none;
}
@media (min-width: 560px) {
    .doc-cards {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}
@media (min-width: 1100px) {
    .doc-cards {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}
@media (min-width: 1500px) {
    .doc-cards {
        grid-template-columns: repeat(4, minmax(0, 1fr));
    }
}

.doc-hero {
    position: relative;
    overflow: hidden;
    border-radius: 1.5rem;
    padding: 1.75rem;
    color: #fff;
    background:
        radial-gradient(
            120% 140% at 0% 0%,
            rgba(56, 189, 248, 0.5),
            transparent 55%
        ),
        radial-gradient(
            120% 160% at 100% 0%,
            rgba(16, 185, 129, 0.5),
            transparent 50%
        ),
        linear-gradient(135deg, #0f172a, #0b2a33 55%, #0b1220);
    box-shadow: 0 30px 60px -30px rgba(15, 23, 42, 0.7);
}
.doc-hero::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image: radial-gradient(
        rgba(255, 255, 255, 0.08) 1px,
        transparent 1px
    );
    background-size: 22px 22px;
    -webkit-mask-image: linear-gradient(180deg, #000, transparent 75%);
    mask-image: linear-gradient(180deg, #000, transparent 75%);
}
.doc-hero > * {
    position: relative;
    z-index: 1;
}
@media (min-width: 1024px) {
    .doc-hero {
        padding: 2rem 2.25rem;
    }
}
.doc-hbadge {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.25rem 0.7rem;
    border-radius: 9999px;
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    background: rgba(255, 255, 255, 0.14);
    border: 1px solid rgba(255, 255, 255, 0.22);
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
}
.doc-hmeta {
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
    padding: 0.45rem 0.8rem;
    border-radius: 0.8rem;
    background: rgba(255, 255, 255, 0.1);
    border: 1px solid rgba(255, 255, 255, 0.16);
    font-size: 0.72rem;
    font-weight: 700;
}
.doc-dot {
    width: 0.5rem;
    height: 0.5rem;
    border-radius: 9999px;
    background: #38bdf8;
    box-shadow: 0 0 0 4px rgba(56, 189, 248, 0.25);
    animation: doc-pulse 2s ease-in-out infinite;
}
@keyframes doc-pulse {
    0%,
    100% {
        opacity: 1;
    }
    50% {
        opacity: 0.4;
    }
}

.doc-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    padding: 0.55rem 0.9rem;
    border-radius: 0.8rem;
    font-size: 0.8rem;
    font-weight: 700;
    cursor: pointer;
    border: 1px solid transparent;
    white-space: nowrap;
    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease,
        background 0.2s ease,
        color 0.2s ease,
        border-color 0.2s ease;
}
.doc-btn:hover {
    transform: translateY(-2px);
}
.doc-btn-primary {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    box-shadow: 0 12px 24px -12px var(--color-primary);
}
.doc-btn-success {
    background: linear-gradient(135deg, #0ea5e9, #0284c7);
    color: #fff;
    box-shadow: 0 12px 24px -12px #0ea5e9;
}
.doc-btn-glass {
    background: rgba(255, 255, 255, 0.12);
    color: #fff;
    border-color: rgba(255, 255, 255, 0.24);
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
}
.doc-btn-glass:hover {
    background: rgba(255, 255, 255, 0.2);
}
.doc-btn-solid {
    background: var(--color-white);
    color: var(--color-gray-900);
    border-color: var(--color-border-color);
}
.doc-btn-solid:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.doc-btn-danger {
    background: #e11d48;
    color: #fff;
}
.doc-icobtn {
    display: grid;
    place-items: center;
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 0.75rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-500);
    cursor: pointer;
    transition: all 0.16s ease;
    flex-shrink: 0;
}
.doc-icobtn:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
    transform: translateY(-1px);
}

.doc-stat {
    position: relative;
    overflow: hidden;
    border-radius: 1.25rem;
    padding: 1.1rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 18px 40px -30px rgba(15, 23, 42, 0.45);
    transition:
        transform 0.25s ease,
        box-shadow 0.25s ease,
        border-color 0.25s ease;
}
.doc-stat::after {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(
        135deg,
        color-mix(in oklab, var(--doc-c) 12%, transparent),
        transparent 60%
    );
    pointer-events: none;
}
.doc-stat:hover {
    transform: translateY(-4px);
    box-shadow: 0 26px 50px -26px
        color-mix(in oklab, var(--doc-c) 55%, rgba(15, 23, 42, 0.5));
    border-color: color-mix(
        in oklab,
        var(--doc-c) 40%,
        var(--color-border-color)
    );
}
.doc-stat > * {
    position: relative;
    z-index: 1;
}
.doc-stat-ico {
    display: grid;
    place-items: center;
    width: 2.9rem;
    height: 2.9rem;
    border-radius: 0.9rem;
    color: #fff;
    font-size: 1.15rem;
    background: linear-gradient(
        135deg,
        var(--doc-c),
        color-mix(in oklab, var(--doc-c) 55%, #6366f1)
    );
    box-shadow: 0 10px 20px -10px var(--doc-c);
}
.doc-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.15rem 0.5rem;
    border-radius: 9999px;
    font-size: 0.62rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    color: color-mix(in oklab, var(--doc-c) 70%, #1e293b);
    background: color-mix(in oklab, var(--doc-c) 16%, transparent);
}
.dark .doc-chip {
    color: color-mix(in oklab, var(--doc-c) 55%, #fff);
}
.doc-ring {
    --p: 0;
    width: 3rem;
    height: 3rem;
    transform: rotate(-90deg);
}
.doc-ring circle {
    fill: none;
    stroke-width: 4;
}
.doc-ring .trk {
    stroke: color-mix(in oklab, var(--doc-c) 16%, transparent);
}
.doc-ring .bar {
    stroke: var(--doc-c);
    stroke-linecap: round;
    stroke-dasharray: 100 100;
    stroke-dashoffset: calc(100 - var(--p));
    transition: stroke-dashoffset 0.9s cubic-bezier(0.16, 1, 0.3, 1);
}

.doc-head {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 1rem 1.15rem;
    border-bottom: 1px solid var(--color-border-color);
}
.doc-head .ico {
    display: grid;
    place-items: center;
    width: 2.3rem;
    height: 2.3rem;
    border-radius: 0.75rem;
    color: #fff;
    font-size: 0.95rem;
    background: linear-gradient(
        135deg,
        color-mix(in oklab, var(--doc-c) 90%, #000),
        color-mix(in oklab, var(--doc-c) 55%, #6366f1)
    );
    box-shadow: 0 10px 18px -12px var(--doc-c);
    flex-shrink: 0;
}
.doc-t {
    font-weight: 800;
    color: var(--color-gray-900);
    font-size: 0.9rem;
}

.doc-search {
    position: relative;
    flex: 1 1 220px;
    min-width: 180px;
}
.doc-search input {
    width: 100%;
    padding: 0.6rem 0.9rem 0.6rem 2.5rem;
    border-radius: 0.85rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.85rem;
    font-weight: 600;
    outline: none;
    transition:
        border-color 0.18s ease,
        box-shadow 0.18s ease;
}
.doc-search input:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 4px
        color-mix(in oklab, var(--color-primary) 14%, transparent);
}
.doc-search .ico {
    position: absolute;
    left: 0.85rem;
    top: 50%;
    transform: translateY(-50%);
    color: var(--color-gray-400, #94a3b8);
    pointer-events: none;
}
.doc-tool {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.55rem 0.8rem;
    border-radius: 0.8rem;
    font-size: 0.8rem;
    font-weight: 700;
    cursor: pointer;
    white-space: nowrap;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-600, #475569);
    transition:
        border-color 0.18s ease,
        color 0.18s ease,
        transform 0.18s ease;
}
.doc-tool:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
    transform: translateY(-1px);
}
.doc-seg {
    display: inline-flex;
    padding: 0.25rem;
    border-radius: 0.85rem;
    background: color-mix(in oklab, var(--color-gray-500) 14%, transparent);
}
.doc-seg button {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.4rem 0.7rem;
    border-radius: 0.65rem;
    font-size: 0.78rem;
    font-weight: 700;
    color: var(--color-gray-500);
    transition: all 0.18s ease;
}
.doc-seg button.is-active {
    background: var(--color-white);
    color: var(--color-primary-text);
    box-shadow: 0 4px 10px -6px rgba(15, 23, 42, 0.4);
}

.doc-card {
    position: relative;
    overflow: hidden;
    border-radius: 1.1rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 18px 40px -32px rgba(15, 23, 42, 0.5);
    transition:
        transform 0.25s ease,
        box-shadow 0.25s ease,
        border-color 0.25s ease;
}
.doc-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 26px 48px -26px
        color-mix(in oklab, var(--doc-c) 45%, rgba(15, 23, 42, 0.5));
    border-color: color-mix(
        in oklab,
        var(--doc-c) 35%,
        var(--color-border-color)
    );
}
.doc-card.is-selected {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 2px
        color-mix(in oklab, var(--color-primary) 40%, transparent);
}
.doc-thumb {
    position: relative;
    height: 7rem;
    display: grid;
    place-items: center;
    background: linear-gradient(
        135deg,
        color-mix(in oklab, var(--doc-c) 16%, transparent),
        color-mix(in oklab, var(--doc-c) 6%, transparent)
    );
}
.doc-thumb .big {
    font-size: 2.3rem;
    color: var(--doc-c);
}
.doc-ext {
    position: absolute;
    bottom: 0.5rem;
    left: 0.6rem;
    padding: 0.1rem 0.45rem;
    border-radius: 0.4rem;
    font-size: 0.58rem;
    font-weight: 800;
    text-transform: uppercase;
    color: #fff;
    background: var(--doc-c);
}

.doc-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.15rem 0.55rem;
    border-radius: 9999px;
    font-size: 0.62rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    white-space: nowrap;
}
.doc-badge.verified {
    color: #059669;
    background: rgba(16, 185, 129, 0.15);
}
.doc-badge.signed {
    color: var(--color-primary-text);
    background: color-mix(in oklab, var(--color-primary) 15%, transparent);
}
.doc-badge.pending {
    color: #d97706;
    background: rgba(245, 158, 11, 0.15);
}
.doc-badge.archived {
    color: #64748b;
    background: rgba(100, 116, 139, 0.15);
}
.doc-tag {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.1rem 0.45rem;
    border-radius: 0.5rem;
    font-size: 0.62rem;
    font-weight: 700;
    background: color-mix(in oklab, var(--doc-c) 14%, transparent);
    color: var(--doc-c);
}
.doc-mini {
    display: grid;
    place-items: center;
    width: 2rem;
    height: 2rem;
    border-radius: 0.6rem;
    color: var(--color-gray-500);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.16s ease;
}
.doc-mini:hover {
    border-color: var(--doc-c);
    color: var(--doc-c);
    transform: translateY(-1px);
}
.doc-kv {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    font-size: 0.72rem;
    color: var(--color-gray-500);
    min-width: 0;
}
.doc-kv b {
    color: var(--color-gray-900);
    font-weight: 700;
}

.doc-fold {
    display: flex;
    align-items: center;
    gap: 0.7rem;
    padding: 0.85rem;
    border-radius: 1rem;
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    cursor: pointer;
    transition:
        transform 0.2s ease,
        border-color 0.2s ease,
        box-shadow 0.2s ease;
}
.doc-fold:hover {
    transform: translateY(-3px);
    border-color: color-mix(
        in oklab,
        var(--doc-c) 40%,
        var(--color-border-color)
    );
    box-shadow: 0 16px 30px -22px
        color-mix(in oklab, var(--doc-c) 55%, rgba(15, 23, 42, 0.5));
}
.doc-fold.is-active {
    border-color: var(--doc-c);
    box-shadow: 0 0 0 2px color-mix(in oklab, var(--doc-c) 30%, transparent);
}
.doc-fold-ico {
    display: grid;
    place-items: center;
    width: 2.6rem;
    height: 2.6rem;
    border-radius: 0.8rem;
    font-size: 1.1rem;
    color: #fff;
    background: linear-gradient(
        135deg,
        var(--doc-c),
        color-mix(in oklab, var(--doc-c) 55%, #6366f1)
    );
    flex-shrink: 0;
}

.doc-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0;
}
.doc-table thead th {
    text-align: left;
    font-size: 0.66rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--color-gray-400, #94a3b8);
    padding: 0.75rem 1rem;
    border-bottom: 1px solid var(--color-border-color);
    white-space: nowrap;
    background: color-mix(in oklab, var(--color-gray-500) 5%, transparent);
}
.doc-table tbody td {
    padding: 0.7rem 1rem;
    border-bottom: 1px solid var(--color-border-color);
    font-size: 0.82rem;
    color: var(--color-gray-900);
    vertical-align: middle;
    white-space: nowrap;
}
.doc-table tbody tr {
    transition: background 0.15s ease;
}
.doc-table tbody tr:hover {
    background: color-mix(in oklab, var(--color-primary) 5%, transparent);
}
.doc-table tbody tr.is-selected {
    background: color-mix(in oklab, var(--color-primary) 9%, transparent);
}
.doc-check {
    width: 1.05rem;
    height: 1.05rem;
    border-radius: 0.35rem;
    accent-color: var(--color-primary);
    cursor: pointer;
}
.doc-fileico {
    display: grid;
    place-items: center;
    width: 2rem;
    height: 2rem;
    border-radius: 0.55rem;
    font-size: 0.9rem;
    color: var(--doc-c);
    background: color-mix(in oklab, var(--doc-c) 14%, transparent);
    flex-shrink: 0;
}

.doc-menu {
    position: absolute;
    z-index: 1100;
    min-width: 14rem;
    max-height: 26rem;
    overflow-y: auto;
    padding: 0.4rem;
    border-radius: 1rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 30px 60px -24px rgba(2, 12, 40, 0.5);
    animation: doc-pop 0.16s ease;
}
@keyframes doc-pop {
    from {
        opacity: 0;
        transform: translateY(-6px) scale(0.97);
    }
}
.doc-menu button,
.doc-menu a {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    width: 100%;
    padding: 0.45rem 0.55rem;
    border-radius: 0.55rem;
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--color-gray-900);
    text-align: left;
    transition:
        background 0.14s ease,
        color 0.14s ease;
}
.doc-menu button:hover,
.doc-menu a:hover {
    background: color-mix(in oklab, var(--color-primary) 8%, transparent);
    color: var(--color-primary-text);
}
.doc-menu .danger {
    color: #e11d48;
}
.doc-menu .danger:hover {
    background: rgba(244, 63, 94, 0.1);
}
.doc-menu-sep {
    height: 1px;
    margin: 0.3rem 0.2rem;
    background: var(--color-border-color);
}
.doc-menu-lbl {
    padding: 0.4rem 0.55rem 0.15rem;
    font-size: 0.58rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--color-gray-400, #94a3b8);
}

.doc-drawer {
    position: fixed;
    inset: 0;
    z-index: 1200;
    visibility: hidden;
}
.doc-drawer.open {
    visibility: visible;
}
.doc-drawer-back {
    position: absolute;
    inset: 0;
    background: rgba(8, 12, 30, 0.5);
    opacity: 0;
    transition: opacity 0.3s ease;
}
.doc-drawer.open .doc-drawer-back {
    opacity: 1;
}
.doc-drawer-panel {
    position: absolute;
    top: 0;
    right: 0;
    height: 100%;
    width: min(500px, 94vw);
    background: var(--color-white);
    box-shadow: -30px 0 60px -30px rgba(2, 12, 40, 0.55);
    transform: translateX(100%);
    transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1);
    display: flex;
    flex-direction: column;
}
.doc-drawer.open .doc-drawer-panel {
    transform: translateX(0);
}
.doc-drawer-panel.left {
    right: auto;
    left: 0;
    transform: translateX(-100%);
    box-shadow: 30px 0 60px -30px rgba(2, 12, 40, 0.55);
}
.doc-drawer.open .doc-drawer-panel.left {
    transform: translateX(0);
}
.doc-drawer-hero {
    position: relative;
    padding: 1.5rem;
    color: #fff;
    background:
        radial-gradient(
            120% 130% at 100% 0%,
            rgba(16, 185, 129, 0.55),
            transparent 55%
        ),
        linear-gradient(135deg, #0284c7, #0f172a);
}

.doc-modal {
    position: fixed;
    inset: 0;
    z-index: 1300;
    display: none;
    align-items: center;
    justify-content: center;
    padding: 1rem;
}
.doc-modal.open {
    display: flex;
}
.doc-modal-back {
    position: absolute;
    inset: 0;
    background: rgba(8, 12, 30, 0.5);
    -webkit-backdrop-filter: blur(3px);
    backdrop-filter: blur(3px);
    animation: doc-fadein 0.2s ease;
}
@keyframes doc-fadein {
    from {
        opacity: 0;
    }
}
.doc-modal-panel {
    position: relative;
    width: 100%;
    max-width: 36rem;
    max-height: 90vh;
    overflow-y: auto;
    border-radius: 1.25rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 40px 80px -30px rgba(2, 12, 40, 0.6);
    animation: doc-modin 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes doc-modin {
    from {
        opacity: 0;
        transform: translateY(16px) scale(0.97);
    }
}
.doc-doc-ico {
    display: grid;
    place-items: center;
    width: 2.75rem;
    height: 2.75rem;
    border-radius: 0.8rem;
    color: var(--doc-c);
    font-size: 1.15rem;
    background: color-mix(in oklab, var(--doc-c) 14%, transparent);
}

.doc-bulk {
    position: sticky;
    bottom: 1rem;
    z-index: 40;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.55rem;
    padding: 0.7rem 0.9rem;
    border-radius: 1.25rem;
    background: color-mix(in oklab, var(--color-white) 85%, transparent);
    -webkit-backdrop-filter: blur(16px);
    backdrop-filter: blur(16px);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 20px 45px -22px rgba(15, 23, 42, 0.55);
    transform: translateY(160%);
    transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}
.doc-bulk.show {
    transform: translateY(0);
}
.doc-bulk-btn {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.4rem 0.7rem;
    border-radius: 0.7rem;
    font-size: 0.76rem;
    font-weight: 700;
    color: var(--color-gray-700, #374151);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.15s ease;
    white-space: nowrap;
}
.dark .doc-bulk-btn {
    color: var(--color-gray-900);
}
.doc-bulk-btn:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.doc-bulk-btn.danger {
    color: #e11d48;
}
.doc-bulk-btn.danger:hover {
    border-color: #e11d48;
    background: rgba(244, 63, 94, 0.08);
}

.doc-pg {
    display: grid;
    place-items: center;
    min-width: 2.1rem;
    height: 2.1rem;
    padding: 0 0.5rem;
    border-radius: 0.6rem;
    font-size: 0.8rem;
    font-weight: 700;
    color: var(--color-gray-600, #475569);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.15s ease;
    cursor: pointer;
}
.doc-pg:hover:not(:disabled) {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.doc-pg.is-active {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    border-color: transparent;
}
.doc-pg:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

.doc-bar {
    height: 0.5rem;
    border-radius: 9999px;
    background: color-mix(in oklab, var(--doc-c) 14%, transparent);
    overflow: hidden;
}
.doc-bar > i {
    display: block;
    height: 100%;
    border-radius: 9999px;
    background: linear-gradient(
        90deg,
        var(--doc-c),
        color-mix(in oklab, var(--doc-c) 55%, #6366f1)
    );
}
.doc-recent {
    display: flex;
    align-items: center;
    gap: 0.7rem;
    padding: 0.6rem;
    border-radius: 0.8rem;
    transition: background 0.15s ease;
}
.doc-recent:hover {
    background: color-mix(in oklab, var(--color-primary) 6%, transparent);
}

.doc-in {
    width: 100%;
    padding: 0.65rem 0.8rem;
    border-radius: 0.7rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.85rem;
    font-weight: 600;
    outline: none;
    transition:
        border-color 0.16s ease,
        box-shadow 0.16s ease;
}
.doc-in:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 4px
        color-mix(in oklab, var(--color-primary) 14%, transparent);
}
.doc-lbl {
    display: block;
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--color-gray-500);
    margin-bottom: 0.3rem;
}
.doc-drop {
    border: 2px dashed var(--color-border-color);
    border-radius: 0.9rem;
    padding: 1.75rem;
    text-align: center;
    color: var(--color-gray-500);
    transition:
        border-color 0.15s ease,
        background 0.15s ease;
}
.doc-drop.drag {
    border-color: var(--color-primary);
    background: color-mix(in oklab, var(--color-primary) 6%, transparent);
}

.doc-c-indigo {
    --doc-c: #6366f1;
}
.doc-c-sky {
    --doc-c: #0ea5e9;
}
.doc-c-rose {
    --doc-c: #f43f5e;
}
.doc-c-amber {
    --doc-c: #f59e0b;
}
.doc-c-emerald {
    --doc-c: #10b981;
}
.doc-c-violet {
    --doc-c: #8b5cf6;
}
.doc-c-teal {
    --doc-c: #14b8a6;
}
.doc-c-primary {
    --doc-c: var(--color-primary);
}
.doc-c-slate {
    --doc-c: #64748b;
}

.doc-sk {
    position: relative;
    overflow: hidden;
    background: color-mix(in oklab, var(--color-gray-500) 12%, transparent);
    border-radius: 0.75rem;
}
.doc-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in oklab, var(--color-white) 55%, transparent),
        transparent
    );
    animation: doc-shimmer 1.4s infinite;
}
.dark .doc-sk::after {
    background: linear-gradient(
        90deg,
        transparent,
        rgba(255, 255, 255, 0.06),
        transparent
    );
}
@keyframes doc-shimmer {
    100% {
        transform: translateX(100%);
    }
}

.doc-toast {
    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    z-index: 2000;
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.8rem 1.1rem;
    border-radius: 0.9rem;
    font-size: 0.85rem;
    font-weight: 700;
    color: #fff;
    box-shadow: 0 20px 45px -18px rgba(0, 0, 0, 0.5);
    animation: doc-toastin 0.25s ease;
}
@keyframes doc-toastin {
    from {
        opacity: 0;
        transform: translateY(12px);
    }
}
.doc-toast.success {
    background: linear-gradient(135deg, #0ea5e9, #0284c7);
}
.doc-toast.info {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
}
.doc-toast.error {
    background: linear-gradient(135deg, #f43f5e, #e11d48);
}

/* Per-instance modifiers (unlayered so they win over the shared .doc-hbadge/.doc-ring/.doc-tool/.doc-btn defaults above) */
.doc-hbadge-emerald {
    background: rgba(16, 185, 129, 0.18);
    border-color: rgba(16, 185, 129, 0.4);
}
.doc-hbadge-amber {
    background: rgba(245, 158, 11, 0.18);
    border-color: rgba(245, 158, 11, 0.4);
}
.doc-ring-lg {
    width: 4.5rem;
    height: 4.5rem;
}
.doc-tool-sm {
    padding: 0.35rem 0.6rem;
}
.doc-tool-xs {
    padding: 0.35rem 0.5rem;
}
.doc-btn-sm {
    padding: 0.45rem 0.8rem;
}

@media (prefers-reduced-motion: reduce) {
    .doc-btn,
    .doc-stat,
    .doc-card,
    .doc-fold,
    .doc-ring .bar,
    .doc-dot,
    .doc-sk::after,
    .doc-icobtn,
    .doc-mini,
    .doc-drawer-panel,
    .doc-bulk {
        transition: none;
        animation: none;
    }
    .doc-btn:hover,
    .doc-stat:hover,
    .doc-card:hover,
    .doc-fold:hover,
    .doc-icobtn:hover,
    .doc-mini:hover {
        transform: none;
    }
}
@media print {
    .sidebar,
    header.navbar-header,
    .doc-print-hide {
        display: none !important;
    }
}

/* =====================================================================
   PATIENT PRESCRIPTIONS CENTER  ·  patient-prescriptions.html (page-exclusive)
   Renamed from the original rx- prefix to prx- to avoid colliding with
   the unrelated pharmacy prescriptions.html page, which already owns rx-.
   ===================================================================== */
/* ================================================================
               PATIENT PRESCRIPTIONS CENTER — self-contained (inline).
               Design-system CSS variables → automatic light / dark.
               ================================================================ */
#prx-page {
    --prx-c: var(--color-primary);
}
.prx-surface {
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    border-radius: 1.25rem;
    box-shadow: 0 20px 45px -35px rgba(15, 23, 42, 0.4);
}

.prx-layout {
    display: grid;
    grid-template-columns: 1fr;
    gap: 1.25rem;
    align-items: start;
}
@media (min-width: 1280px) {
    .prx-layout {
        grid-template-columns: minmax(0, 1fr) 340px;
    }
}
.prx-grid {
    display: grid;
    gap: 0.9rem;
}
.prx-g3 {
    grid-template-columns: repeat(1, minmax(0, 1fr));
}
.prx-g6 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
}
@media (min-width: 640px) {
    .prx-g3 {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}
@media (min-width: 900px) {
    .prx-g3 {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
    .prx-g6 {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}
@media (min-width: 1200px) {
    .prx-g6 {
        grid-template-columns: repeat(6, minmax(0, 1fr));
    }
}
.prx-cards {
    display: grid;
    gap: 1rem;
    grid-template-columns: 1fr;
}
.prx-cards.hidden {
    display: none;
}
@media (min-width: 640px) {
    .prx-cards {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}
@media (min-width: 1300px) {
    .prx-cards {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}

.prx-hero {
    position: relative;
    overflow: hidden;
    border-radius: 1.5rem;
    padding: 1.75rem;
    color: #fff;
    background:
        radial-gradient(
            120% 140% at 0% 0%,
            rgba(16, 185, 129, 0.5),
            transparent 55%
        ),
        radial-gradient(
            120% 160% at 100% 0%,
            rgba(20, 184, 166, 0.5),
            transparent 50%
        ),
        linear-gradient(135deg, #0f172a, #0b2e2a 55%, #0b1220);
    box-shadow: 0 30px 60px -30px rgba(15, 23, 42, 0.7);
}
.prx-hero::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image: radial-gradient(
        rgba(255, 255, 255, 0.08) 1px,
        transparent 1px
    );
    background-size: 22px 22px;
    -webkit-mask-image: linear-gradient(180deg, #000, transparent 75%);
    mask-image: linear-gradient(180deg, #000, transparent 75%);
}
.prx-hero > * {
    position: relative;
    z-index: 1;
}
@media (min-width: 1024px) {
    .prx-hero {
        padding: 2rem 2.25rem;
    }
}
.prx-hbadge {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.25rem 0.7rem;
    border-radius: 9999px;
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    background: rgba(255, 255, 255, 0.14);
    border: 1px solid rgba(255, 255, 255, 0.22);
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
}
.prx-hmeta {
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
    padding: 0.45rem 0.8rem;
    border-radius: 0.8rem;
    background: rgba(255, 255, 255, 0.1);
    border: 1px solid rgba(255, 255, 255, 0.16);
    font-size: 0.72rem;
    font-weight: 700;
}
.prx-dot {
    width: 0.5rem;
    height: 0.5rem;
    border-radius: 9999px;
    background: #34d399;
    box-shadow: 0 0 0 4px rgba(52, 211, 153, 0.25);
    animation: prx-pulse 2s ease-in-out infinite;
}
@keyframes prx-pulse {
    0%,
    100% {
        opacity: 1;
    }
    50% {
        opacity: 0.4;
    }
}
.prx-hava {
    width: 3.5rem;
    height: 3.5rem;
    border-radius: 1rem;
    display: grid;
    place-items: center;
    font-weight: 800;
    font-size: 1.1rem;
    color: #fff;
    background: rgba(255, 255, 255, 0.16);
    border: 1px solid rgba(255, 255, 255, 0.28);
}

.prx-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    padding: 0.55rem 0.9rem;
    border-radius: 0.8rem;
    font-size: 0.8rem;
    font-weight: 700;
    cursor: pointer;
    border: 1px solid transparent;
    white-space: nowrap;
    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease,
        background 0.2s ease,
        color 0.2s ease,
        border-color 0.2s ease;
}
.prx-btn:hover {
    transform: translateY(-2px);
}
.prx-btn-primary {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    box-shadow: 0 12px 24px -12px var(--color-primary);
}
.prx-btn-success {
    background: linear-gradient(135deg, #10b981, #059669);
    color: #fff;
    box-shadow: 0 12px 24px -12px #10b981;
}
.prx-btn-glass {
    background: rgba(255, 255, 255, 0.12);
    color: #fff;
    border-color: rgba(255, 255, 255, 0.24);
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
}
.prx-btn-glass:hover {
    background: rgba(255, 255, 255, 0.2);
}
.prx-btn-solid {
    background: var(--color-white);
    color: var(--color-gray-900);
    border-color: var(--color-border-color);
}
.prx-btn-solid:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.prx-btn-danger {
    background: #e11d48;
    color: #fff;
}
.prx-icobtn {
    display: grid;
    place-items: center;
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 0.75rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-500);
    cursor: pointer;
    transition: all 0.16s ease;
    flex-shrink: 0;
}
.prx-icobtn:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
    transform: translateY(-1px);
}

.prx-stat {
    position: relative;
    overflow: hidden;
    border-radius: 1.25rem;
    padding: 1.1rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 18px 40px -30px rgba(15, 23, 42, 0.45);
    transition:
        transform 0.25s ease,
        box-shadow 0.25s ease,
        border-color 0.25s ease;
}
.prx-stat::after {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(
        135deg,
        color-mix(in oklab, var(--prx-c) 12%, transparent),
        transparent 60%
    );
    pointer-events: none;
}
.prx-stat:hover {
    transform: translateY(-4px);
    box-shadow: 0 26px 50px -26px
        color-mix(in oklab, var(--prx-c) 55%, rgba(15, 23, 42, 0.5));
    border-color: color-mix(
        in oklab,
        var(--prx-c) 40%,
        var(--color-border-color)
    );
}
.prx-stat > * {
    position: relative;
    z-index: 1;
}
.prx-stat-ico {
    display: grid;
    place-items: center;
    width: 2.9rem;
    height: 2.9rem;
    border-radius: 0.9rem;
    color: #fff;
    font-size: 1.15rem;
    background: linear-gradient(
        135deg,
        var(--prx-c),
        color-mix(in oklab, var(--prx-c) 55%, #6366f1)
    );
    box-shadow: 0 10px 20px -10px var(--prx-c);
}
.prx-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.15rem 0.5rem;
    border-radius: 9999px;
    font-size: 0.62rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    color: color-mix(in oklab, var(--prx-c) 70%, #1e293b);
    background: color-mix(in oklab, var(--prx-c) 16%, transparent);
}
.dark .prx-chip {
    color: color-mix(in oklab, var(--prx-c) 55%, #fff);
}
.prx-ring {
    --p: 0;
    width: 3rem;
    height: 3rem;
    transform: rotate(-90deg);
}
.prx-ring circle {
    fill: none;
    stroke-width: 4;
}
.prx-ring .trk {
    stroke: color-mix(in oklab, var(--prx-c) 16%, transparent);
}
.prx-ring .bar {
    stroke: var(--prx-c);
    stroke-linecap: round;
    stroke-dasharray: 100 100;
    stroke-dashoffset: calc(100 - var(--p));
    transition: stroke-dashoffset 0.9s cubic-bezier(0.16, 1, 0.3, 1);
}

.prx-head {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 1rem 1.15rem;
    border-bottom: 1px solid var(--color-border-color);
}
.prx-head .ico {
    display: grid;
    place-items: center;
    width: 2.3rem;
    height: 2.3rem;
    border-radius: 0.75rem;
    color: #fff;
    font-size: 0.95rem;
    background: linear-gradient(
        135deg,
        color-mix(in oklab, var(--prx-c) 90%, #000),
        color-mix(in oklab, var(--prx-c) 55%, #6366f1)
    );
    box-shadow: 0 10px 18px -12px var(--prx-c);
    flex-shrink: 0;
}
.prx-t {
    font-weight: 800;
    color: var(--color-gray-900);
    font-size: 0.9rem;
}

.prx-search {
    position: relative;
    flex: 1 1 220px;
    min-width: 180px;
}
.prx-search input {
    width: 100%;
    padding: 0.6rem 0.9rem 0.6rem 2.5rem;
    border-radius: 0.85rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.85rem;
    font-weight: 600;
    outline: none;
    transition:
        border-color 0.18s ease,
        box-shadow 0.18s ease;
}
.prx-search input:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 4px
        color-mix(in oklab, var(--color-primary) 14%, transparent);
}
.prx-search .ico {
    position: absolute;
    left: 0.85rem;
    top: 50%;
    transform: translateY(-50%);
    color: var(--color-gray-400, #94a3b8);
    pointer-events: none;
}
.prx-tool {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.55rem 0.8rem;
    border-radius: 0.8rem;
    font-size: 0.8rem;
    font-weight: 700;
    cursor: pointer;
    white-space: nowrap;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-600, #475569);
    transition:
        border-color 0.18s ease,
        color 0.18s ease,
        transform 0.18s ease;
}
.prx-tool:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
    transform: translateY(-1px);
}
.prx-seg {
    display: inline-flex;
    padding: 0.25rem;
    border-radius: 0.85rem;
    background: color-mix(in oklab, var(--color-gray-500) 14%, transparent);
}
.prx-seg button {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.4rem 0.7rem;
    border-radius: 0.65rem;
    font-size: 0.78rem;
    font-weight: 700;
    color: var(--color-gray-500);
    transition: all 0.18s ease;
}
.prx-seg button.is-active {
    background: var(--color-white);
    color: var(--color-primary-text);
    box-shadow: 0 4px 10px -6px rgba(15, 23, 42, 0.4);
}

.prx-card {
    position: relative;
    overflow: hidden;
    border-radius: 1.25rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 18px 40px -32px rgba(15, 23, 42, 0.5);
    transition:
        transform 0.25s ease,
        box-shadow 0.25s ease,
        border-color 0.25s ease;
    border-left: 3px solid var(--prx-c);
}
.prx-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 26px 48px -26px
        color-mix(in oklab, var(--prx-c) 45%, rgba(15, 23, 42, 0.5));
    border-color: color-mix(
        in oklab,
        var(--prx-c) 35%,
        var(--color-border-color)
    );
    border-left-color: var(--prx-c);
}
.prx-card.is-selected {
    box-shadow: 0 0 0 2px
        color-mix(in oklab, var(--color-primary) 40%, transparent);
}
.prx-pico {
    display: grid;
    place-items: center;
    width: 2.8rem;
    height: 2.8rem;
    border-radius: 0.9rem;
    font-size: 1.2rem;
    color: #fff;
    background: linear-gradient(
        135deg,
        var(--prx-c),
        color-mix(in oklab, var(--prx-c) 55%, #6366f1)
    );
    box-shadow: 0 10px 20px -10px var(--prx-c);
}

.prx-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.15rem 0.55rem;
    border-radius: 9999px;
    font-size: 0.62rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    white-space: nowrap;
}
.prx-badge.active {
    color: #059669;
    background: rgba(16, 185, 129, 0.15);
}
.prx-badge.pending {
    color: #d97706;
    background: rgba(245, 158, 11, 0.15);
}
.prx-badge.completed {
    color: var(--color-primary-text);
    background: color-mix(in oklab, var(--color-primary) 15%, transparent);
}
.prx-badge.paused {
    color: #8b5cf6;
    background: rgba(139, 92, 246, 0.15);
}
.prx-badge.stopped {
    color: #e11d48;
    background: rgba(244, 63, 94, 0.15);
}
.prx-tag {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.1rem 0.45rem;
    border-radius: 0.5rem;
    font-size: 0.62rem;
    font-weight: 700;
    background: color-mix(in oklab, var(--prx-c) 14%, transparent);
    color: var(--prx-c);
}
.prx-mini {
    display: grid;
    place-items: center;
    width: 2rem;
    height: 2rem;
    border-radius: 0.6rem;
    color: var(--color-gray-500);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.16s ease;
}
.prx-mini:hover {
    border-color: var(--prx-c);
    color: var(--prx-c);
    transform: translateY(-1px);
}
.prx-kv {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    font-size: 0.72rem;
    color: var(--color-gray-500);
    min-width: 0;
}
.prx-kv b {
    color: var(--color-gray-900);
    font-weight: 700;
}

.prx-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0;
}
.prx-table thead th {
    text-align: left;
    font-size: 0.66rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--color-gray-400, #94a3b8);
    padding: 0.75rem 1rem;
    border-bottom: 1px solid var(--color-border-color);
    white-space: nowrap;
    background: color-mix(in oklab, var(--color-gray-500) 5%, transparent);
}
.prx-table tbody td {
    padding: 0.7rem 1rem;
    border-bottom: 1px solid var(--color-border-color);
    font-size: 0.82rem;
    color: var(--color-gray-900);
    vertical-align: middle;
    white-space: nowrap;
}
.prx-table tbody tr {
    transition: background 0.15s ease;
}
.prx-table tbody tr:hover {
    background: color-mix(in oklab, var(--color-primary) 5%, transparent);
}
.prx-table tbody tr.is-selected {
    background: color-mix(in oklab, var(--color-primary) 9%, transparent);
}
.prx-check {
    width: 1.05rem;
    height: 1.05rem;
    border-radius: 0.35rem;
    accent-color: var(--color-primary);
    cursor: pointer;
}
.prx-fileico {
    display: grid;
    place-items: center;
    width: 2rem;
    height: 2rem;
    border-radius: 0.55rem;
    font-size: 0.9rem;
    color: var(--prx-c);
    background: color-mix(in oklab, var(--prx-c) 14%, transparent);
    flex-shrink: 0;
}

.prx-menu {
    position: absolute;
    z-index: 1100;
    min-width: 14rem;
    max-height: 26rem;
    overflow-y: auto;
    padding: 0.4rem;
    border-radius: 1rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 30px 60px -24px rgba(2, 12, 40, 0.5);
    animation: prx-pop 0.16s ease;
}
@keyframes prx-pop {
    from {
        opacity: 0;
        transform: translateY(-6px) scale(0.97);
    }
}
.prx-menu button,
.prx-menu a {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    width: 100%;
    padding: 0.45rem 0.55rem;
    border-radius: 0.55rem;
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--color-gray-900);
    text-align: left;
    transition:
        background 0.14s ease,
        color 0.14s ease;
}
.prx-menu button:hover,
.prx-menu a:hover {
    background: color-mix(in oklab, var(--color-primary) 8%, transparent);
    color: var(--color-primary-text);
}
.prx-menu .danger {
    color: #e11d48;
}
.prx-menu .danger:hover {
    background: rgba(244, 63, 94, 0.1);
}
.prx-menu-sep {
    height: 1px;
    margin: 0.3rem 0.2rem;
    background: var(--color-border-color);
}
.prx-menu-lbl {
    padding: 0.4rem 0.55rem 0.15rem;
    font-size: 0.58rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--color-gray-400, #94a3b8);
}

.prx-drawer {
    position: fixed;
    inset: 0;
    z-index: 1200;
    visibility: hidden;
}
.prx-drawer.open {
    visibility: visible;
}
.prx-drawer-back {
    position: absolute;
    inset: 0;
    background: rgba(8, 12, 30, 0.5);
    opacity: 0;
    transition: opacity 0.3s ease;
}
.prx-drawer.open .prx-drawer-back {
    opacity: 1;
}
.prx-drawer-panel {
    position: absolute;
    top: 0;
    right: 0;
    height: 100%;
    width: min(490px, 94vw);
    background: var(--color-white);
    box-shadow: -30px 0 60px -30px rgba(2, 12, 40, 0.55);
    transform: translateX(100%);
    transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1);
    display: flex;
    flex-direction: column;
}
.prx-drawer.open .prx-drawer-panel {
    transform: translateX(0);
}
.prx-drawer-panel.left {
    right: auto;
    left: 0;
    transform: translateX(-100%);
    box-shadow: 30px 0 60px -30px rgba(2, 12, 40, 0.55);
}
.prx-drawer.open .prx-drawer-panel.left {
    transform: translateX(0);
}
.prx-drawer-hero {
    position: relative;
    padding: 1.5rem;
    color: #fff;
    background:
        radial-gradient(
            120% 130% at 100% 0%,
            rgba(20, 184, 166, 0.55),
            transparent 55%
        ),
        linear-gradient(135deg, #059669, #0f172a);
}

.prx-modal {
    position: fixed;
    inset: 0;
    z-index: 1300;
    display: none;
    align-items: center;
    justify-content: center;
    padding: 1rem;
}
.prx-modal.open {
    display: flex;
}
.prx-modal-back {
    position: absolute;
    inset: 0;
    background: rgba(8, 12, 30, 0.5);
    -webkit-backdrop-filter: blur(3px);
    backdrop-filter: blur(3px);
    animation: prx-fadein 0.2s ease;
}
@keyframes prx-fadein {
    from {
        opacity: 0;
    }
}
.prx-modal-panel {
    position: relative;
    width: 100%;
    max-width: 38rem;
    max-height: 90vh;
    overflow-y: auto;
    border-radius: 1.25rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 40px 80px -30px rgba(2, 12, 40, 0.6);
    animation: prx-modin 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes prx-modin {
    from {
        opacity: 0;
        transform: translateY(16px) scale(0.97);
    }
}
.prx-doc-ico {
    display: grid;
    place-items: center;
    width: 2.75rem;
    height: 2.75rem;
    border-radius: 0.8rem;
    color: var(--prx-c);
    font-size: 1.15rem;
    background: color-mix(in oklab, var(--prx-c) 14%, transparent);
}

.prx-bulk {
    position: sticky;
    bottom: 1rem;
    z-index: 40;
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.55rem;
    padding: 0.7rem 0.9rem;
    border-radius: 1.25rem;
    background: color-mix(in oklab, var(--color-white) 85%, transparent);
    -webkit-backdrop-filter: blur(16px);
    backdrop-filter: blur(16px);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 20px 45px -22px rgba(15, 23, 42, 0.55);
    transform: translateY(160%);
    transition: transform 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}
.prx-bulk.show {
    transform: translateY(0);
}
.prx-bulk-btn {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.4rem 0.7rem;
    border-radius: 0.7rem;
    font-size: 0.76rem;
    font-weight: 700;
    color: var(--color-gray-700, #374151);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.15s ease;
    white-space: nowrap;
}
.dark .prx-bulk-btn {
    color: var(--color-gray-900);
}
.prx-bulk-btn:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.prx-bulk-btn.danger {
    color: #e11d48;
}
.prx-bulk-btn.danger:hover {
    border-color: #e11d48;
    background: rgba(244, 63, 94, 0.08);
}

.prx-pg {
    display: grid;
    place-items: center;
    min-width: 2.1rem;
    height: 2.1rem;
    padding: 0 0.5rem;
    border-radius: 0.6rem;
    font-size: 0.8rem;
    font-weight: 700;
    color: var(--color-gray-600, #475569);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.15s ease;
    cursor: pointer;
}
.prx-pg:hover:not(:disabled) {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.prx-pg.is-active {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    border-color: transparent;
}
.prx-pg:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

.prx-bar {
    height: 0.5rem;
    border-radius: 9999px;
    background: color-mix(in oklab, var(--prx-c) 14%, transparent);
    overflow: hidden;
}
.prx-bar > i {
    display: block;
    height: 100%;
    border-radius: 9999px;
    background: linear-gradient(
        90deg,
        var(--prx-c),
        color-mix(in oklab, var(--prx-c) 55%, #6366f1)
    );
}
.prx-recent {
    display: flex;
    align-items: center;
    gap: 0.7rem;
    padding: 0.6rem;
    border-radius: 0.8rem;
    transition: background 0.15s ease;
}
.prx-recent:hover {
    background: color-mix(in oklab, var(--color-primary) 6%, transparent);
}

/* dose schedule */
.prx-dose-col {
    border-radius: 1rem;
    border: 1px solid var(--color-border-color);
    overflow: hidden;
}
.prx-dose-head {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.6rem 0.75rem;
    font-size: 0.75rem;
    font-weight: 800;
    color: #fff;
    background: linear-gradient(
        135deg,
        var(--prx-c),
        color-mix(in oklab, var(--prx-c) 55%, #6366f1)
    );
}
.prx-dose-item {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.5rem 0.6rem;
    font-size: 0.72rem;
    border-bottom: 1px solid var(--color-border-color);
}
.prx-dose-item:last-child {
    border-bottom: 0;
}
.prx-pilltoggle {
    width: 1.1rem;
    height: 1.1rem;
    border-radius: 0.35rem;
    border: 1.5px solid var(--color-border-color);
    display: grid;
    place-items: center;
    cursor: pointer;
    flex-shrink: 0;
    transition: all 0.15s ease;
}
.prx-pilltoggle.done {
    background: #10b981;
    border-color: #10b981;
    color: #fff;
}
.prx-pilltoggle i {
    display: none;
}
.prx-pilltoggle.done i {
    display: block;
}

.prx-in {
    width: 100%;
    padding: 0.65rem 0.8rem;
    border-radius: 0.7rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.85rem;
    font-weight: 600;
    outline: none;
    transition:
        border-color 0.16s ease,
        box-shadow 0.16s ease;
}
.prx-in:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 4px
        color-mix(in oklab, var(--color-primary) 14%, transparent);
}
.prx-lbl {
    display: block;
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--color-gray-500);
    margin-bottom: 0.3rem;
}

.prx-c-indigo {
    --prx-c: #6366f1;
}
.prx-c-sky {
    --prx-c: #0ea5e9;
}
.prx-c-rose {
    --prx-c: #f43f5e;
}
.prx-c-amber {
    --prx-c: #f59e0b;
}
.prx-c-emerald {
    --prx-c: #10b981;
}
.prx-c-violet {
    --prx-c: #8b5cf6;
}
.prx-c-teal {
    --prx-c: #14b8a6;
}
.prx-c-primary {
    --prx-c: var(--color-primary);
}

.prx-sk {
    position: relative;
    overflow: hidden;
    background: color-mix(in oklab, var(--color-gray-500) 12%, transparent);
    border-radius: 0.75rem;
}
.prx-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in oklab, var(--color-white) 55%, transparent),
        transparent
    );
    animation: prx-shimmer 1.4s infinite;
}
.dark .prx-sk::after {
    background: linear-gradient(
        90deg,
        transparent,
        rgba(255, 255, 255, 0.06),
        transparent
    );
}
@keyframes prx-shimmer {
    100% {
        transform: translateX(100%);
    }
}

.prx-toast {
    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    z-index: 2000;
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.8rem 1.1rem;
    border-radius: 0.9rem;
    font-size: 0.85rem;
    font-weight: 700;
    color: #fff;
    box-shadow: 0 20px 45px -18px rgba(0, 0, 0, 0.5);
    animation: prx-toastin 0.25s ease;
}
@keyframes prx-toastin {
    from {
        opacity: 0;
        transform: translateY(12px);
    }
}
.prx-toast.success {
    background: linear-gradient(135deg, #10b981, #059669);
}
.prx-toast.info {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
}
.prx-toast.error {
    background: linear-gradient(135deg, #f43f5e, #e11d48);
}

/* Per-instance modifiers (unlayered so they win over the shared .prx-hbadge/.prx-ring/.prx-tool/.prx-sk defaults above) */
.prx-hbadge-amber {
    background: rgba(245, 158, 11, 0.18);
    border-color: rgba(245, 158, 11, 0.4);
}
.prx-hbadge-rose {
    background: rgba(244, 63, 94, 0.18);
    border-color: rgba(244, 63, 94, 0.4);
}
.prx-ring-lg {
    width: 4.5rem;
    height: 4.5rem;
}
.prx-tool-sm {
    padding: 0.35rem 0.6rem;
}
.prx-tool-xs {
    padding: 0.35rem 0.5rem;
}
.prx-sk-r125 {
    border-radius: 1.25rem;
}
.prx-sk-r150 {
    border-radius: 1.5rem;
}

@media (prefers-reduced-motion: reduce) {
    .prx-btn,
    .prx-stat,
    .prx-card,
    .prx-ring .bar,
    .prx-dot,
    .prx-sk::after,
    .prx-icobtn,
    .prx-mini,
    .prx-drawer-panel,
    .prx-bulk {
        transition: none;
        animation: none;
    }
    .prx-btn:hover,
    .prx-stat:hover,
    .prx-card:hover,
    .prx-icobtn:hover,
    .prx-mini:hover {
        transform: none;
    }
}
@media print {
    .sidebar,
    header.navbar-header,
    .prx-print-hide {
        display: none !important;
    }
}

/* =====================================================================
   DIGITAL WAITING ROOM COMMAND CENTER  ·  waiting-room.html (page-exclusive)
   ===================================================================== */
/* ================================================================
               DIGITAL WAITING ROOM COMMAND CENTER — self-contained (inline).
               Design-system CSS variables → automatic light / dark.
               ================================================================ */
#wr-page {
    --wr-c: var(--color-primary);
}
.wr-surface {
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    border-radius: 1.25rem;
    box-shadow: 0 20px 45px -35px rgba(15, 23, 42, 0.4);
}
.wr-muted {
    color: var(--color-gray-500);
}

.wr-layout {
    display: grid;
    grid-template-columns: 1fr;
    gap: 1.25rem;
    align-items: start;
}
@media (min-width: 1280px) {
    .wr-layout {
        grid-template-columns: minmax(0, 1fr) 340px;
    }
}
.wr-grid {
    display: grid;
    gap: 0.9rem;
}
.wr-g3 {
    grid-template-columns: repeat(1, minmax(0, 1fr));
}
@media (min-width: 640px) {
    .wr-g3 {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}
@media (min-width: 960px) {
    .wr-g3 {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}
.wr-g6 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
}
@media (min-width: 700px) {
    .wr-g6 {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}
@media (min-width: 1200px) {
    .wr-g6 {
        grid-template-columns: repeat(6, minmax(0, 1fr));
    }
}
.wr-cards {
    display: grid;
    gap: 1rem;
    grid-template-columns: 1fr;
}
.wr-cards.hidden {
    display: none;
}
@media (min-width: 768px) {
    .wr-cards {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}
@media (min-width: 1500px) {
    .wr-cards {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}

/* ---------- HERO ---------- */
.wr-hero {
    position: relative;
    overflow: hidden;
    border-radius: 1.5rem;
    padding: 1.75rem;
    color: #fff;
    background:
        radial-gradient(
            120% 140% at 0% 0%,
            rgba(20, 184, 166, 0.5),
            transparent 55%
        ),
        radial-gradient(
            120% 160% at 100% 0%,
            rgba(14, 165, 233, 0.55),
            transparent 50%
        ),
        linear-gradient(135deg, #0f172a, #0d2436 55%, #0b1220);
    box-shadow: 0 30px 60px -30px rgba(15, 23, 42, 0.7);
}
.wr-hero::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image: radial-gradient(
        rgba(255, 255, 255, 0.08) 1px,
        transparent 1px
    );
    background-size: 22px 22px;
    -webkit-mask-image: linear-gradient(180deg, #000, transparent 75%);
    mask-image: linear-gradient(180deg, #000, transparent 75%);
}
.wr-hero > * {
    position: relative;
    z-index: 1;
}
@media (min-width: 1024px) {
    .wr-hero {
        padding: 2rem 2.25rem;
    }
}
.wr-hbadge {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.28rem 0.7rem;
    border-radius: 9999px;
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    background: rgba(255, 255, 255, 0.14);
    border: 1px solid rgba(255, 255, 255, 0.22);
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
}
.wr-hmeta {
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
    padding: 0.5rem 0.85rem;
    border-radius: 0.85rem;
    background: rgba(255, 255, 255, 0.1);
    border: 1px solid rgba(255, 255, 255, 0.16);
    font-size: 0.74rem;
    font-weight: 700;
}
.wr-dot {
    width: 0.5rem;
    height: 0.5rem;
    border-radius: 9999px;
    background: #2dd4bf;
    box-shadow: 0 0 0 4px rgba(45, 212, 191, 0.25);
    animation: wr-pulse 2s ease-in-out infinite;
}
@keyframes wr-pulse {
    0%,
    100% {
        opacity: 1;
    }
    50% {
        opacity: 0.4;
    }
}

/* ---------- BUTTONS ---------- */
.wr-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    padding: 0.55rem 0.9rem;
    border-radius: 0.8rem;
    font-size: 0.8rem;
    font-weight: 700;
    cursor: pointer;
    border: 1px solid transparent;
    white-space: nowrap;
    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease,
        background 0.2s ease,
        color 0.2s ease,
        border-color 0.2s ease;
}
.wr-btn:hover {
    transform: translateY(-2px);
}
.wr-btn-primary {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    box-shadow: 0 12px 24px -12px var(--color-primary);
}
.wr-btn-teal {
    background: linear-gradient(135deg, #14b8a6, #0d9488);
    color: #fff;
    box-shadow: 0 12px 24px -12px #14b8a6;
}
.wr-btn-glass {
    background: rgba(255, 255, 255, 0.12);
    color: #fff;
    border-color: rgba(255, 255, 255, 0.24);
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
}
.wr-btn-glass:hover {
    background: rgba(255, 255, 255, 0.2);
}
.wr-btn-soft {
    background: var(--color-gray-100);
    color: var(--color-gray-700);
    border-color: var(--color-border-color);
}
.wr-btn-soft:hover {
    background: var(--color-gray-200);
}

/* ---------- KPI ---------- */
.wr-kpi {
    position: relative;
    overflow: hidden;
    padding: 1.1rem;
    border-radius: 1.2rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 16px 30px -28px rgba(15, 23, 42, 0.5);
    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease;
}
.wr-kpi:hover {
    transform: translateY(-4px);
    box-shadow: 0 26px 48px -30px rgba(15, 23, 42, 0.55);
}
.wr-kpi::after {
    content: "";
    position: absolute;
    right: -30px;
    top: -30px;
    width: 90px;
    height: 90px;
    border-radius: 9999px;
    background: var(--kc, #14b8a6);
    opacity: 0.08;
}
.wr-kpi-ic {
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 0.85rem;
    display: flex;
    align-items: center;
    justify-content: center;
}
.wr-kpi-v {
    font-size: 1.55rem;
    font-weight: 800;
    line-height: 1;
    color: var(--color-gray-900);
}
.wr-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.18rem 0.5rem;
    border-radius: 9999px;
    font-size: 0.66rem;
    font-weight: 800;
}
.wr-ring {
    transform: rotate(-90deg);
}
.wr-ring .bar {
    stroke-dasharray: 100 100;
    stroke-dashoffset: calc(100 - var(--p, 0));
    transition: stroke-dashoffset 1.1s cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* ---------- INPUTS ---------- */
.wr-inp {
    width: 100%;
    padding: 0.55rem 0.7rem;
    border-radius: 0.7rem;
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.8rem;
}
.wr-inp:focus {
    outline: none;
    border-color: var(--color-primary);
    box-shadow: 0 0 0 3px
        color-mix(in srgb, var(--color-primary) 20%, transparent);
}
.wr-lbl {
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--color-gray-600);
    margin-bottom: 0.3rem;
    display: block;
}
.wr-seg {
    display: inline-flex;
    padding: 0.2rem;
    border-radius: 0.7rem;
    background: var(--color-gray-100);
    border: 1px solid var(--color-border-color);
}
.wr-segb {
    padding: 0.4rem 0.7rem;
    border-radius: 0.5rem;
    font-size: 0.76rem;
    font-weight: 700;
    color: var(--color-gray-600);
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
}
.wr-segb.active {
    background: var(--color-white);
    color: var(--color-primary-text);
    box-shadow: 0 6px 14px -10px rgba(15, 23, 42, 0.5);
}

/* ---------- TABLE ---------- */
.wr-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0;
}
.wr-table th {
    text-align: left;
    font-size: 0.7rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: var(--color-gray-500);
    padding: 0.65rem 0.75rem;
    border-bottom: 1px solid var(--color-border-color);
    white-space: nowrap;
}
.wr-table td {
    padding: 0.7rem 0.75rem;
    border-bottom: 1px solid var(--color-border-color);
    font-size: 0.82rem;
}
.wr-table tbody tr {
    transition: background 0.15s ease;
}
.wr-table tbody tr:hover {
    background: var(--color-gray-100);
}
.wr-hidecol {
    display: none;
}

/* ---------- KANBAN BOARD ---------- */
.wr-kanban {
    display: grid;
    gap: 0.85rem;
    grid-template-columns: 1fr;
}
@media (min-width: 700px) {
    .wr-kanban {
        grid-template-columns: repeat(2, 1fr);
    }
}
@media (min-width: 1100px) {
    .wr-kanban {
        grid-template-columns: repeat(4, 1fr);
    }
}
.wr-kcol {
    background: var(--color-gray-100);
    border: 1px solid var(--color-border-color);
    border-radius: 1rem;
    padding: 0.6rem;
    min-height: 120px;
    transition:
        border-color 0.15s ease,
        background 0.15s ease;
}
.wr-kcol.drop {
    border-color: var(--color-primary);
    background: color-mix(
        in srgb,
        var(--color-primary) 7%,
        var(--color-gray-100)
    );
}
.wr-khd {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.3rem 0.4rem 0.6rem;
    font-size: 0.78rem;
    font-weight: 800;
}
.wr-kcard {
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    border-radius: 0.85rem;
    padding: 0.7rem;
    margin-bottom: 0.6rem;
    box-shadow: 0 10px 24px -22px rgba(15, 23, 42, 0.5);
    transition:
        transform 0.15s ease,
        box-shadow 0.15s ease,
        opacity 0.15s ease;
    border-left: 3px solid var(--kc, #94a3b8);
    cursor: grab;
}
.wr-kcard.dragging {
    opacity: 0.5;
}
.wr-kcard:hover {
    transform: translateY(-2px);
    box-shadow: 0 16px 30px -20px rgba(15, 23, 42, 0.5);
}

/* ---------- TOKEN ---------- */
.wr-token {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 2.6rem;
    height: 1.7rem;
    padding: 0 0.5rem;
    border-radius: 0.55rem;
    font-size: 0.78rem;
    font-weight: 800;
    letter-spacing: 0.02em;
}

.wr-av {
    width: 2.4rem;
    height: 2.4rem;
    border-radius: 0.7rem;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.7rem;
    font-weight: 800;
    color: #fff;
    flex: none;
    border: 2px solid var(--color-white);
}
.wr-av-sm {
    width: 2rem;
    height: 2rem;
    border-radius: 0.55rem;
    font-size: 0.6rem;
}

.wr-tag {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.24rem 0.55rem;
    border-radius: 9999px;
    font-size: 0.66rem;
    font-weight: 700;
}
.wr-bar {
    height: 0.5rem;
    border-radius: 9999px;
    background: var(--color-gray-200);
    overflow: hidden;
}
.wr-bar > span {
    display: block;
    height: 100%;
    border-radius: 9999px;
    transition: width 0.6s ease;
}
.wr-dotstat {
    width: 0.55rem;
    height: 0.55rem;
    border-radius: 9999px;
    flex: none;
}

/* ---------- ACTION MENU ---------- */
.wr-menu {
    position: fixed;
    z-index: 80;
    width: 214px;
    max-height: 70vh;
    overflow: auto;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    border-radius: 0.85rem;
    box-shadow: 0 30px 60px -20px rgba(15, 23, 42, 0.5);
    padding: 0.35rem;
    display: none;
}
.wr-menu.open {
    display: block;
    animation: wr-pop 0.18s ease;
}
.wr-mi {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    padding: 0.5rem 0.6rem;
    border-radius: 0.55rem;
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--color-gray-700);
    cursor: pointer;
}
.wr-mi:hover {
    background: var(--color-gray-100);
}
.wr-mi.danger {
    color: #dc2626;
}
.wr-mi.danger:hover {
    background: color-mix(in srgb, #ef4444 12%, transparent);
}
.wr-mi.ok {
    color: #059669;
}
.wr-mi.ok:hover {
    background: color-mix(in srgb, #10b981 12%, transparent);
}
.wr-sep {
    height: 1px;
    background: var(--color-border-color);
    margin: 0.3rem 0.2rem;
}

/* ---------- SKELETON ---------- */
.wr-sk {
    position: relative;
    overflow: hidden;
    background: var(--color-gray-100);
    border-radius: 1rem;
}
.wr-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in srgb, var(--color-gray-300) 55%, transparent),
        transparent
    );
    animation: wr-sh 1.4s infinite;
}
@keyframes wr-sh {
    100% {
        transform: translateX(100%);
    }
}

/* ---------- DRAWER ---------- */
.wr-drawer {
    position: fixed;
    inset: 0;
    z-index: 70;
    display: none;
}
.wr-drawer.open {
    display: block;
}
.wr-mask {
    position: absolute;
    inset: 0;
    background: rgba(15, 23, 42, 0.55);
    -webkit-backdrop-filter: blur(3px);
    backdrop-filter: blur(3px);
    animation: wr-fade 0.25s ease;
}
@keyframes wr-fade {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}
.wr-panel {
    position: absolute;
    top: 0;
    right: 0;
    height: 100%;
    width: min(480px, 100vw);
    background: var(--color-white);
    border-left: 1px solid var(--color-border-color);
    box-shadow: -30px 0 60px -30px rgba(15, 23, 42, 0.6);
    overflow-y: auto;
    animation: wr-slide 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
@keyframes wr-slide {
    from {
        transform: translateX(100%);
    }
    to {
        transform: none;
    }
}

/* ---------- MODAL ---------- */
.wr-modal {
    position: fixed;
    inset: 0;
    z-index: 75;
    display: none;
}
.wr-modal.open {
    display: block;
}
.wr-dialog {
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
    width: min(560px, 94vw);
    max-height: 90vh;
    overflow: auto;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    border-radius: 1.25rem;
    box-shadow: 0 40px 80px -30px rgba(15, 23, 42, 0.7);
    animation: wr-pop 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}
@keyframes wr-pop {
    from {
        opacity: 0;
        transform: translate(-50%, -46%) scale(0.96);
    }
    to {
        opacity: 1;
        transform: translate(-50%, -50%) scale(1);
    }
}
.wr-drop {
    border: 2px dashed var(--color-border-color);
    border-radius: 1rem;
    padding: 1.6rem;
    text-align: center;
    transition: all 0.2s ease;
    cursor: pointer;
}
.wr-drop:hover,
.wr-drop.drag {
    border-color: var(--color-primary);
    background: color-mix(in srgb, var(--color-primary) 6%, transparent);
}

/* ---------- CALL BANNER ---------- */
.wr-callnow {
    position: relative;
    overflow: hidden;
    border-radius: 1.25rem;
    padding: 1.25rem 1.5rem;
    color: #fff;
    background: linear-gradient(135deg, #0f766e, #0d9488 55%, #14b8a6);
    box-shadow: 0 24px 45px -25px rgba(13, 148, 136, 0.7);
}
.wr-callnow::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image: radial-gradient(
        rgba(255, 255, 255, 0.12) 1px,
        transparent 1px
    );
    background-size: 16px 16px;
    opacity: 0.5;
}
.wr-callnow > * {
    position: relative;
    z-index: 1;
}
.wr-bigtoken {
    font-size: 2.6rem;
    font-weight: 900;
    line-height: 1;
    letter-spacing: 0.02em;
}

/* ---------- BULK BAR ---------- */
.wr-bulk {
    position: fixed;
    left: 50%;
    bottom: 1.25rem;
    transform: translateX(-50%) translateY(160%);
    z-index: 60;
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.6rem 0.6rem 0.6rem 1rem;
    border-radius: 1rem;
    background: var(--color-gray-900);
    color: #fff;
    box-shadow: 0 30px 60px -20px rgba(0, 0, 0, 0.6);
    transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
    flex-wrap: wrap;
    max-width: 94vw;
}
.wr-bulk.show {
    transform: translateX(-50%) translateY(0);
}

/* ---------- TOAST ---------- */
#wr-toast {
    position: fixed;
    right: 1rem;
    bottom: 1rem;
    z-index: 90;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}
.wr-toast {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    padding: 0.7rem 0.95rem;
    border-radius: 0.8rem;
    background: var(--color-gray-900);
    color: #fff;
    font-size: 0.8rem;
    font-weight: 700;
    box-shadow: 0 18px 40px -18px rgba(0, 0, 0, 0.6);
    animation: wr-tin 0.3s ease;
}
@keyframes wr-tin {
    from {
        opacity: 0;
        transform: translateY(12px);
    }
    to {
        opacity: 1;
        transform: none;
    }
}

input[type="checkbox"].wr-cb {
    width: 1.05rem;
    height: 1.05rem;
    border-radius: 0.35rem;
    accent-color: var(--color-primary);
    cursor: pointer;
}

/* cascade-safe per-instance modifiers (unlayered — see CASCADE-SAFE OVERRIDE UTILITIES note) */
.wr-bar-glass {
    background: rgba(255, 255, 255, 0.2);
}

/* =====================================================================
   DOCTORS  ·  doctors.html (page-exclusive)
   ===================================================================== */
/* ================================================================
               DOCTOR MANAGEMENT CENTER — self-contained (inline).
               Design-system CSS variables → automatic light / dark.
               ================================================================ */
#dr-page {
    --dr-c: var(--color-primary);
}
.dr-surface {
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    border-radius: 1.25rem;
    box-shadow: 0 20px 45px -35px rgba(15, 23, 42, 0.4);
}

.dr-layout {
    display: grid;
    grid-template-columns: 1fr;
    gap: 1.25rem;
    align-items: start;
}
@media (min-width: 1280px) {
    .dr-layout {
        grid-template-columns: minmax(0, 1fr) 340px;
    }
}
.dr-grid {
    display: grid;
    gap: 0.9rem;
}
.dr-g3 {
    grid-template-columns: repeat(1, minmax(0, 1fr));
}
.dr-g6 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
}
@media (min-width: 640px) {
    .dr-g3 {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}
@media (min-width: 900px) {
    .dr-g3 {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
    .dr-g6 {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}
@media (min-width: 1200px) {
    .dr-g6 {
        grid-template-columns: repeat(6, minmax(0, 1fr));
    }
}
.dr-cards {
    display: grid;
    gap: 1.35rem;
    grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
}
.dr-cards.hidden {
    display: none;
}

.dr-hero {
    position: relative;
    overflow: hidden;
    border-radius: 1.5rem;
    padding: 1.75rem;
    color: #fff;
    background:
        radial-gradient(
            120% 140% at 0% 0%,
            rgba(14, 165, 233, 0.5),
            transparent 55%
        ),
        radial-gradient(
            120% 160% at 100% 0%,
            rgba(99, 102, 241, 0.55),
            transparent 50%
        ),
        linear-gradient(135deg, #0f172a, #10233f 55%, #0b1220);
    box-shadow: 0 30px 60px -30px rgba(15, 23, 42, 0.7);
}
.dr-hero::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image: radial-gradient(
        rgba(255, 255, 255, 0.08) 1px,
        transparent 1px
    );
    background-size: 22px 22px;
    -webkit-mask-image: linear-gradient(180deg, #000, transparent 75%);
    mask-image: linear-gradient(180deg, #000, transparent 75%);
}
.dr-hero > * {
    position: relative;
    z-index: 1;
}
@media (min-width: 1024px) {
    .dr-hero {
        padding: 2rem 2.25rem;
    }
}
.dr-hbadge {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.25rem 0.7rem;
    border-radius: 9999px;
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    background: rgba(255, 255, 255, 0.14);
    border: 1px solid rgba(255, 255, 255, 0.22);
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
}
.dr-hmeta {
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
    padding: 0.45rem 0.8rem;
    border-radius: 0.8rem;
    background: rgba(255, 255, 255, 0.1);
    border: 1px solid rgba(255, 255, 255, 0.16);
    font-size: 0.72rem;
    font-weight: 700;
}
.dr-dot {
    width: 0.5rem;
    height: 0.5rem;
    border-radius: 9999px;
    background: #38bdf8;
    box-shadow: 0 0 0 4px rgba(56, 189, 248, 0.25);
    animation: dr-pulse 2s ease-in-out infinite;
}
@keyframes dr-pulse {
    0%,
    100% {
        opacity: 1;
    }
    50% {
        opacity: 0.4;
    }
}

.dr-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    padding: 0.55rem 0.9rem;
    border-radius: 0.8rem;
    font-size: 0.8rem;
    font-weight: 700;
    cursor: pointer;
    border: 1px solid transparent;
    white-space: nowrap;
    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease,
        background 0.2s ease,
        color 0.2s ease,
        border-color 0.2s ease;
}
.dr-btn:hover {
    transform: translateY(-2px);
}
.dr-btn-primary {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    box-shadow: 0 12px 24px -12px var(--color-primary);
}
.dr-btn-success {
    background: linear-gradient(135deg, #0ea5e9, #0284c7);
    color: #fff;
    box-shadow: 0 12px 24px -12px #0ea5e9;
}
.dr-btn-glass {
    background: rgba(255, 255, 255, 0.12);
    color: #fff;
    border-color: rgba(255, 255, 255, 0.24);
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
}
.dr-btn-glass:hover {
    background: rgba(255, 255, 255, 0.2);
}
.dr-btn-solid {
    background: var(--color-white);
    color: var(--color-gray-900);
    border-color: var(--color-border-color);
}
.dr-btn-solid:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.dr-btn-danger {
    background: #e11d48;
    color: #fff;
}
.dr-icobtn {
    display: grid;
    place-items: center;
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 0.75rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-500);
    cursor: pointer;
    transition: all 0.16s ease;
    flex-shrink: 0;
}
.dr-icobtn:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
    transform: translateY(-1px);
}

.dr-stat {
    position: relative;
    overflow: hidden;
    border-radius: 1.25rem;
    padding: 1.1rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 18px 40px -30px rgba(15, 23, 42, 0.45);
    transition:
        transform 0.25s ease,
        box-shadow 0.25s ease,
        border-color 0.25s ease;
}
.dr-stat::after {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(
        135deg,
        color-mix(in oklab, var(--dr-c) 12%, transparent),
        transparent 60%
    );
    pointer-events: none;
}
.dr-stat:hover {
    transform: translateY(-4px);
    box-shadow: 0 26px 50px -26px
        color-mix(in oklab, var(--dr-c) 55%, rgba(15, 23, 42, 0.5));
    border-color: color-mix(
        in oklab,
        var(--dr-c) 40%,
        var(--color-border-color)
    );
}
.dr-stat > * {
    position: relative;
    z-index: 1;
}
.dr-stat-ico {
    display: grid;
    place-items: center;
    width: 2.9rem;
    height: 2.9rem;
    border-radius: 0.9rem;
    color: #fff;
    font-size: 1.15rem;
    background: linear-gradient(
        135deg,
        var(--dr-c),
        color-mix(in oklab, var(--dr-c) 55%, #6366f1)
    );
    box-shadow: 0 10px 20px -10px var(--dr-c);
}
.dr-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.15rem 0.5rem;
    border-radius: 9999px;
    font-size: 0.62rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    color: color-mix(in oklab, var(--dr-c) 70%, #1e293b);
    background: color-mix(in oklab, var(--dr-c) 16%, transparent);
}
.dark .dr-chip {
    color: color-mix(in oklab, var(--dr-c) 55%, #fff);
}
.dr-ring {
    --p: 0;
    width: 3rem;
    height: 3rem;
    transform: rotate(-90deg);
}
.dr-ring circle {
    fill: none;
    stroke-width: 4;
}
.dr-ring .trk {
    stroke: color-mix(in oklab, var(--dr-c) 16%, transparent);
}
.dr-ring .bar {
    stroke: var(--dr-c);
    stroke-linecap: round;
    stroke-dasharray: 100 100;
    stroke-dashoffset: calc(100 - var(--p));
    transition: stroke-dashoffset 0.9s cubic-bezier(0.16, 1, 0.3, 1);
}

.dr-head {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 1rem 1.15rem;
    border-bottom: 1px solid var(--color-border-color);
}
.dr-head .ico {
    display: grid;
    place-items: center;
    width: 2.3rem;
    height: 2.3rem;
    border-radius: 0.75rem;
    color: #fff;
    font-size: 0.95rem;
    background: linear-gradient(
        135deg,
        color-mix(in oklab, var(--dr-c) 90%, #000),
        color-mix(in oklab, var(--dr-c) 55%, #6366f1)
    );
    box-shadow: 0 10px 18px -12px var(--dr-c);
    flex-shrink: 0;
}
.dr-t {
    font-weight: 800;
    color: var(--color-gray-900);
    font-size: 0.9rem;
}

.dr-search {
    position: relative;
    flex: 1 1 220px;
    min-width: 180px;
}
.dr-search input {
    width: 100%;
    padding: 0.6rem 0.9rem 0.6rem 2.5rem;
    border-radius: 0.85rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.85rem;
    font-weight: 600;
    outline: none;
    transition:
        border-color 0.18s ease,
        box-shadow 0.18s ease;
}
.dr-search input:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 4px
        color-mix(in oklab, var(--color-primary) 14%, transparent);
}
.dr-search .ico {
    position: absolute;
    left: 0.85rem;
    top: 50%;
    transform: translateY(-50%);
    color: var(--color-gray-400, #94a3b8);
    pointer-events: none;
}
.dr-tool {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.55rem 0.8rem;
    border-radius: 0.8rem;
    font-size: 0.8rem;
    font-weight: 700;
    cursor: pointer;
    white-space: nowrap;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-600, #475569);
    transition:
        border-color 0.18s ease,
        color 0.18s ease,
        transform 0.18s ease;
}
.dr-tool:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
    transform: translateY(-1px);
}
.dr-seg {
    display: inline-flex;
    padding: 0.25rem;
    border-radius: 0.85rem;
    background: color-mix(in oklab, var(--color-gray-500) 14%, transparent);
}
.dr-seg button {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.4rem 0.7rem;
    border-radius: 0.65rem;
    font-size: 0.78rem;
    font-weight: 700;
    color: var(--color-gray-500);
    transition: all 0.18s ease;
}
.dr-seg button.is-active {
    background: var(--color-white);
    color: var(--color-primary-text);
    box-shadow: 0 4px 10px -6px rgba(15, 23, 42, 0.4);
}

.dr-card {
    position: relative;
    overflow: hidden;
    border-radius: 1.5rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow:
        0 1px 2px rgba(15, 23, 42, 0.05),
        0 20px 44px -32px rgba(15, 23, 42, 0.45);
    transition:
        transform 0.3s cubic-bezier(0.16, 1, 0.3, 1),
        box-shadow 0.3s cubic-bezier(0.16, 1, 0.3, 1),
        border-color 0.3s ease;
}
.dr-card:hover {
    transform: translateY(-6px);
    box-shadow:
        0 1px 2px rgba(15, 23, 42, 0.05),
        0 34px 60px -26px
            color-mix(in oklab, var(--dr-c) 50%, rgba(15, 23, 42, 0.55));
    border-color: color-mix(
        in oklab,
        var(--dr-c) 40%,
        var(--color-border-color)
    );
}
.dr-card.is-selected {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 2px
        color-mix(in oklab, var(--color-primary) 40%, transparent);
}
.dr-cardtop {
    position: relative;
    height: 5.5rem;
    overflow: hidden;
    background: linear-gradient(
        135deg,
        var(--dr-c),
        color-mix(in oklab, var(--dr-c) 45%, #0f172a)
    );
}
.dr-cardtop::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image: radial-gradient(
        rgba(255, 255, 255, 0.18) 1px,
        transparent 1px
    );
    background-size: 14px 14px;
    -webkit-mask-image: linear-gradient(180deg, #000, transparent 85%);
    mask-image: linear-gradient(180deg, #000, transparent 85%);
}
.dr-cardtop::after {
    content: "";
    position: absolute;
    right: -2rem;
    top: -2.5rem;
    width: 8rem;
    height: 8rem;
    border-radius: 9999px;
    background: rgba(255, 255, 255, 0.12);
}
.dr-ava {
    position: relative;
    width: 4.25rem;
    height: 4.25rem;
    border-radius: 1.15rem;
    display: grid;
    place-items: center;
    color: #fff;
    font-weight: 800;
    font-size: 1.1rem;
    background: linear-gradient(
        135deg,
        var(--dr-c),
        color-mix(in oklab, var(--dr-c) 55%, #6366f1)
    );
    border: 3.5px solid var(--color-white);
    box-shadow: 0 10px 22px -10px
        color-mix(in oklab, var(--dr-c) 60%, transparent);
    flex-shrink: 0;
}
.dark .dr-ava {
    border-color: var(--color-white);
}
.dr-ava-photo img {
    width: 100%;
    height: 100%;
    border-radius: inherit;
    object-fit: cover;
    display: block;
}
.dr-ava-photo::after {
    content: "";
    position: absolute;
    right: -3px;
    bottom: -3px;
    width: 0.9rem;
    height: 0.9rem;
    border-radius: 9999px;
    background: var(--dr-ring, #10b981);
    border: 2.5px solid var(--color-white);
}
.dark .dr-ava-photo::after {
    border-color: var(--color-white);
}
.dr-ava-sm {
    width: 2.6rem;
    height: 2.6rem;
    border-radius: 0.8rem;
    display: grid;
    place-items: center;
    color: #fff;
    font-weight: 800;
    font-size: 0.8rem;
    background: linear-gradient(
        135deg,
        var(--dr-c),
        color-mix(in oklab, var(--dr-c) 55%, #6366f1)
    );
    flex-shrink: 0;
    overflow: hidden;
}
.dr-ava-sm-photo img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
}

.dr-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.2rem 0.65rem;
    border-radius: 9999px;
    font-size: 0.62rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    white-space: nowrap;
    border: 1px solid transparent;
}
.dr-badge::before {
    content: "";
    width: 0.35rem;
    height: 0.35rem;
    border-radius: 9999px;
    background: currentColor;
    flex-shrink: 0;
}
.dr-badge.available {
    color: #059669;
    background: rgba(16, 185, 129, 0.13);
    border-color: rgba(16, 185, 129, 0.28);
}
.dr-badge.busy {
    color: #d97706;
    background: rgba(245, 158, 11, 0.13);
    border-color: rgba(245, 158, 11, 0.28);
}
.dr-badge.leave {
    color: #8b5cf6;
    background: rgba(139, 92, 246, 0.13);
    border-color: rgba(139, 92, 246, 0.28);
}
.dr-badge.offduty {
    color: #64748b;
    background: rgba(100, 116, 139, 0.13);
    border-color: rgba(100, 116, 139, 0.28);
}
.dr-tag {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.2rem 0.55rem;
    border-radius: 0.6rem;
    font-size: 0.64rem;
    font-weight: 700;
    background: color-mix(in oklab, var(--dr-c) 12%, transparent);
    color: var(--dr-c);
    border: 1px solid color-mix(in oklab, var(--dr-c) 20%, transparent);
}
.dr-stars {
    display: inline-flex;
    gap: 0.08rem;
    color: #f59e0b;
    font-size: 0.82rem;
}
.dr-stars .off {
    color: color-mix(in oklab, var(--color-gray-500) 30%, transparent);
}
.dr-mini {
    display: grid;
    place-items: center;
    width: 2.1rem;
    height: 2.1rem;
    border-radius: 0.7rem;
    color: var(--color-gray-500);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.18s ease;
}
.dr-mini:hover {
    border-color: var(--dr-c);
    color: var(--dr-c);
    background: color-mix(in oklab, var(--dr-c) 8%, var(--color-white));
    transform: translateY(-2px);
}
.dr-mini.dr-book {
    color: var(--dr-c);
    background: color-mix(in oklab, var(--dr-c) 10%, transparent);
    border-color: color-mix(in oklab, var(--dr-c) 22%, transparent);
}
.dr-mini.dr-book:hover {
    background: var(--dr-c);
    color: #fff;
}
.dr-kv {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    font-size: 0.72rem;
    color: var(--color-gray-500);
    min-width: 0;
}
.dr-kv b {
    color: var(--color-gray-900);
    font-weight: 700;
}
.dr-statbox {
    text-align: center;
    padding: 0.6rem 0.4rem;
    border-radius: 0.9rem;
    background: color-mix(in oklab, var(--dr-c) 7%, var(--color-gray-100));
    border: 1px solid color-mix(in oklab, var(--dr-c) 12%, transparent);
    min-width: 0;
}
.dark .dr-statbox {
    background: color-mix(in oklab, var(--dr-c) 16%, transparent);
    border-color: color-mix(in oklab, var(--dr-c) 24%, transparent);
}
.dr-statbox b {
    display: block;
    font-size: 0.95rem;
    font-weight: 800;
    color: var(--color-gray-900);
    line-height: 1.2;
}
.dark .dr-statbox b {
    color: #fff;
}
.dr-statbox span {
    display: block;
    font-size: 0.62rem;
    font-weight: 700;
    color: var(--color-gray-500);
    margin-top: 0.15rem;
    text-transform: uppercase;
    letter-spacing: 0.02em;
}
.dr-metarow {
    display: flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.72rem;
    font-weight: 600;
    color: var(--color-gray-500);
}
.dr-metarow i {
    color: var(--dr-c);
}

.dr-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0;
}
.dr-table thead th {
    text-align: left;
    font-size: 0.66rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--color-gray-400, #94a3b8);
    padding: 0.75rem 1rem;
    border-bottom: 1px solid var(--color-border-color);
    white-space: nowrap;
    background: color-mix(in oklab, var(--color-gray-500) 5%, transparent);
}
.dr-table tbody td {
    padding: 0.7rem 1rem;
    border-bottom: 1px solid var(--color-border-color);
    font-size: 0.82rem;
    color: var(--color-gray-900);
    vertical-align: middle;
    white-space: nowrap;
}
.dr-table tbody tr {
    transition: background 0.15s ease;
}
.dr-table tbody tr:hover {
    background: color-mix(in oklab, var(--color-primary) 5%, transparent);
}
.dr-table tbody tr.is-selected {
    background: color-mix(in oklab, var(--color-primary) 9%, transparent);
}
.dr-check {
    width: 1.05rem;
    height: 1.05rem;
    border-radius: 0.35rem;
    accent-color: var(--color-primary);
    cursor: pointer;
}

.dr-menu {
    position: absolute;
    z-index: 1100;
    min-width: 14rem;
    max-height: 26rem;
    overflow-y: auto;
    padding: 0.4rem;
    border-radius: 1rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 30px 60px -24px rgba(2, 12, 40, 0.5);
    animation: dr-pop 0.16s ease;
}
@keyframes dr-pop {
    from {
        opacity: 0;
        transform: translateY(-6px) scale(0.97);
    }
}
.dr-menu button,
.dr-menu a {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    width: 100%;
    padding: 0.45rem 0.55rem;
    border-radius: 0.55rem;
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--color-gray-900);
    text-align: left;
    transition:
        background 0.14s ease,
        color 0.14s ease;
}
.dr-menu button:hover,
.dr-menu a:hover {
    background: color-mix(in oklab, var(--color-primary) 8%, transparent);
    color: var(--color-primary-text);
}
.dr-menu .danger {
    color: #e11d48;
}
.dr-menu .danger:hover {
    background: rgba(244, 63, 94, 0.1);
}
.dr-menu-sep {
    height: 1px;
    margin: 0.3rem 0.2rem;
    background: var(--color-border-color);
}
.dr-menu-lbl {
    padding: 0.4rem 0.55rem 0.15rem;
    font-size: 0.58rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--color-gray-400, #94a3b8);
}

.dr-drawer {
    position: fixed;
    inset: 0;
    z-index: 1200;
    visibility: hidden;
}
.dr-drawer.open {
    visibility: visible;
}
.dr-drawer-back {
    position: absolute;
    inset: 0;
    background: rgba(8, 12, 30, 0.5);
    opacity: 0;
    transition: opacity 0.3s ease;
}
.dr-drawer.open .dr-drawer-back {
    opacity: 1;
}
.dr-drawer-panel {
    position: absolute;
    top: 0;
    right: 0;
    height: 100%;
    width: min(500px, 94vw);
    background: var(--color-white);
    box-shadow: -30px 0 60px -30px rgba(2, 12, 40, 0.55);
    transform: translateX(100%);
    transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1);
    display: flex;
    flex-direction: column;
}
.dr-drawer.open .dr-drawer-panel {
    transform: translateX(0);
}
.dr-drawer-panel.left {
    right: auto;
    left: 0;
    transform: translateX(-100%);
    box-shadow: 30px 0 60px -30px rgba(2, 12, 40, 0.55);
}
.dr-drawer.open .dr-drawer-panel.left {
    transform: translateX(0);
}
.dr-drawer-hero {
    position: relative;
    padding: 1.5rem;
    color: #fff;
    background:
        radial-gradient(
            120% 130% at 100% 0%,
            rgba(99, 102, 241, 0.55),
            transparent 55%
        ),
        linear-gradient(135deg, #0284c7, #0f172a);
}

.dr-modal {
    position: fixed;
    inset: 0;
    z-index: 1300;
    display: none;
    align-items: center;
    justify-content: center;
    padding: 1rem;
}
.dr-modal.open {
    display: flex;
}
.dr-modal-back {
    position: absolute;
    inset: 0;
    background: rgba(8, 12, 30, 0.5);
    -webkit-backdrop-filter: blur(3px);
    backdrop-filter: blur(3px);
    animation: dr-fadein 0.2s ease;
}
@keyframes dr-fadein {
    from {
        opacity: 0;
    }
}
.dr-modal-panel {
    position: relative;
    width: 100%;
    max-width: 38rem;
    max-height: 90vh;
    overflow-y: auto;
    border-radius: 1.25rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 40px 80px -30px rgba(2, 12, 40, 0.6);
    animation: dr-modin 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes dr-modin {
    from {
        opacity: 0;
        transform: translateY(16px) scale(0.97);
    }
}
.dr-doc-ico {
    display: grid;
    place-items: center;
    width: 2.75rem;
    height: 2.75rem;
    border-radius: 0.8rem;
    color: var(--dr-c);
    font-size: 1.15rem;
    background: color-mix(in oklab, var(--dr-c) 14%, transparent);
}

.dr-bulk {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.55rem;
    padding: 0.7rem 0.9rem;
    border-radius: 1.25rem;
    background: color-mix(in oklab, var(--color-white) 85%, transparent);
    -webkit-backdrop-filter: blur(16px);
    backdrop-filter: blur(16px);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 12px 28px -18px rgba(15, 23, 42, 0.45);
    animation: dr-bulk-in 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes dr-bulk-in {
    from {
        opacity: 0;
        transform: translateY(-8px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}
.dr-bulk-btn {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.4rem 0.7rem;
    border-radius: 0.7rem;
    font-size: 0.76rem;
    font-weight: 700;
    color: var(--color-gray-700, #374151);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.15s ease;
    white-space: nowrap;
}
.dark .dr-bulk-btn {
    color: var(--color-gray-900);
}
.dr-bulk-btn:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.dr-bulk-btn.danger {
    color: #e11d48;
}
.dr-bulk-btn.danger:hover {
    border-color: #e11d48;
    background: rgba(244, 63, 94, 0.08);
}

.dr-pg {
    display: grid;
    place-items: center;
    min-width: 2.1rem;
    height: 2.1rem;
    padding: 0 0.5rem;
    border-radius: 0.6rem;
    font-size: 0.8rem;
    font-weight: 700;
    color: var(--color-gray-600, #475569);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.15s ease;
    cursor: pointer;
}
.dr-pg:hover:not(:disabled) {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.dr-pg.is-active {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    border-color: transparent;
}
.dr-pg:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

.dr-bar {
    height: 0.5rem;
    border-radius: 9999px;
    background: color-mix(in oklab, var(--dr-c) 14%, transparent);
    overflow: hidden;
}
.dr-bar > i {
    display: block;
    height: 100%;
    border-radius: 9999px;
    background: linear-gradient(
        90deg,
        var(--dr-c),
        color-mix(in oklab, var(--dr-c) 55%, #6366f1)
    );
}
.dr-recent {
    display: flex;
    align-items: center;
    gap: 0.7rem;
    padding: 0.6rem;
    border-radius: 0.8rem;
    transition: background 0.15s ease;
}
.dr-recent:hover {
    background: color-mix(in oklab, var(--color-primary) 6%, transparent);
}

/* schedule strip */
.dr-week {
    display: grid;
    grid-template-columns: repeat(7, minmax(0, 1fr));
    gap: 0.4rem;
}
.dr-day {
    border-radius: 0.7rem;
    border: 1px solid var(--color-border-color);
    padding: 0.5rem;
    text-align: center;
}
.dr-day.on {
    background: color-mix(in oklab, var(--dr-c) 12%, transparent);
    border-color: color-mix(
        in oklab,
        var(--dr-c) 35%,
        var(--color-border-color)
    );
}
.dr-day .d {
    font-size: 0.6rem;
    font-weight: 800;
    text-transform: uppercase;
    color: var(--color-gray-400, #94a3b8);
}

.dr-in {
    width: 100%;
    padding: 0.65rem 0.8rem;
    border-radius: 0.7rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.85rem;
    font-weight: 600;
    outline: none;
    transition:
        border-color 0.16s ease,
        box-shadow 0.16s ease;
}
.dr-in:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 4px
        color-mix(in oklab, var(--color-primary) 14%, transparent);
}
.dr-lbl {
    display: block;
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--color-gray-500);
    margin-bottom: 0.3rem;
}

.dr-c-indigo {
    --dr-c: #6366f1;
}
.dr-c-sky {
    --dr-c: #0ea5e9;
}
.dr-c-rose {
    --dr-c: #f43f5e;
}
.dr-c-amber {
    --dr-c: #f59e0b;
}
.dr-c-emerald {
    --dr-c: #10b981;
}
.dr-c-violet {
    --dr-c: #8b5cf6;
}
.dr-c-teal {
    --dr-c: #14b8a6;
}
.dr-c-primary {
    --dr-c: var(--color-primary);
}
.dr-c-blue {
    --dr-c: #3b82f6;
}

.dr-sk {
    position: relative;
    overflow: hidden;
    background: color-mix(in oklab, var(--color-gray-500) 12%, transparent);
    border-radius: 0.75rem;
}
.dr-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in oklab, var(--color-white) 55%, transparent),
        transparent
    );
    animation: dr-shimmer 1.4s infinite;
}
.dark .dr-sk::after {
    background: linear-gradient(
        90deg,
        transparent,
        rgba(255, 255, 255, 0.06),
        transparent
    );
}
@keyframes dr-shimmer {
    100% {
        transform: translateX(100%);
    }
}

/* cascade-safe per-instance modifiers (unlayered — see CASCADE-SAFE OVERRIDE UTILITIES note) */
.dr-hbadge-emerald {
    background: rgba(16, 185, 129, 0.18);
    border-color: rgba(16, 185, 129, 0.4);
}
.dr-hbadge-amber {
    background: rgba(245, 158, 11, 0.18);
    border-color: rgba(245, 158, 11, 0.4);
}
.dr-ring-lg {
    width: 4.5rem;
    height: 4.5rem;
}
.dr-tool-compact {
    padding: 0.35rem 0.6rem;
}
.dr-tool-compact-sm {
    padding: 0.35rem 0.5rem;
}

.dr-toast {
    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    z-index: 2000;
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.8rem 1.1rem;
    border-radius: 0.9rem;
    font-size: 0.85rem;
    font-weight: 700;
    color: #fff;
    box-shadow: 0 20px 45px -18px rgba(0, 0, 0, 0.5);
    animation: dr-toastin 0.25s ease;
}
@keyframes dr-toastin {
    from {
        opacity: 0;
        transform: translateY(12px);
    }
}
.dr-toast.success {
    background: linear-gradient(135deg, #0ea5e9, #0284c7);
}
.dr-toast.info {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
}
.dr-toast.error {
    background: linear-gradient(135deg, #f43f5e, #e11d48);
}

@media (prefers-reduced-motion: reduce) {
    .dr-btn,
    .dr-stat,
    .dr-card,
    .dr-ring .bar,
    .dr-dot,
    .dr-sk::after,
    .dr-icobtn,
    .dr-mini,
    .dr-drawer-panel,
    .dr-bulk {
        transition: none;
        animation: none;
    }
    .dr-btn:hover,
    .dr-stat:hover,
    .dr-card:hover,
    .dr-icobtn:hover,
    .dr-mini:hover {
        transform: none;
    }
}
@media print {
    .sidebar,
    header.navbar-header,
    .dr-print-hide {
        display: none !important;
    }
}

/* =====================================================================
   ADMISSIONS  ·  admissions.html (page-exclusive)
   ===================================================================== */
/* ================================================================
               PATIENT ADMISSIONS CENTER — self-contained (inline) styles.
               Design-system CSS variables → automatic light / dark.
               ================================================================ */
#ad-page {
    --ad-c: var(--color-primary);
}
.ad-surface {
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    border-radius: 1.25rem;
    box-shadow: 0 20px 45px -35px rgba(15, 23, 42, 0.4);
}

.ad-layout {
    display: grid;
    grid-template-columns: 1fr;
    gap: 1.25rem;
    align-items: start;
}
@media (min-width: 1280px) {
    .ad-layout {
        grid-template-columns: minmax(0, 1fr) 330px;
    }
}
.ad-grid {
    display: grid;
    gap: 0.9rem;
}
.ad-g2 {
    grid-template-columns: repeat(1, minmax(0, 1fr));
}
.ad-g3 {
    grid-template-columns: repeat(1, minmax(0, 1fr));
}
.ad-g4 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
}
.ad-g6 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
}
@media (min-width: 640px) {
    .ad-g2 {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
    .ad-g3 {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}
@media (min-width: 900px) {
    .ad-g3 {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
    .ad-g6 {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}
@media (min-width: 1200px) {
    .ad-g6 {
        grid-template-columns: repeat(6, minmax(0, 1fr));
    }
    .ad-g4 {
        grid-template-columns: repeat(4, minmax(0, 1fr));
    }
}
.ad-cards {
    display: grid;
    gap: 1rem;
    grid-template-columns: 1fr;
}
.ad-cards.hidden {
    display: none;
}
@media (min-width: 700px) {
    .ad-cards {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}
@media (min-width: 1500px) {
    .ad-cards {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}

/* Hero */
.ad-hero {
    position: relative;
    overflow: hidden;
    border-radius: 1.5rem;
    padding: 1.75rem;
    color: #fff;
    background:
        radial-gradient(
            120% 140% at 0% 0%,
            rgba(99, 102, 241, 0.55),
            transparent 55%
        ),
        radial-gradient(
            120% 160% at 100% 0%,
            rgba(20, 184, 166, 0.5),
            transparent 50%
        ),
        linear-gradient(135deg, #0f172a, #0b2b2b 60%, #0b1220);
    box-shadow: 0 30px 60px -30px rgba(15, 23, 42, 0.7);
}
.ad-hero::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image: radial-gradient(
        rgba(255, 255, 255, 0.08) 1px,
        transparent 1px
    );
    background-size: 22px 22px;
    -webkit-mask-image: linear-gradient(180deg, #000, transparent 75%);
    mask-image: linear-gradient(180deg, #000, transparent 75%);
}
.ad-hero > * {
    position: relative;
    z-index: 1;
}
@media (min-width: 1024px) {
    .ad-hero {
        padding: 2rem 2.25rem;
    }
}
.ad-hbadge {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.25rem 0.7rem;
    border-radius: 9999px;
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    background: rgba(255, 255, 255, 0.14);
    border: 1px solid rgba(255, 255, 255, 0.22);
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
}
.ad-hmeta {
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
    padding: 0.45rem 0.8rem;
    border-radius: 0.8rem;
    background: rgba(255, 255, 255, 0.1);
    border: 1px solid rgba(255, 255, 255, 0.16);
    font-size: 0.72rem;
    font-weight: 700;
}
.ad-dot {
    width: 0.5rem;
    height: 0.5rem;
    border-radius: 9999px;
    background: #34d399;
    box-shadow: 0 0 0 4px rgba(52, 211, 153, 0.25);
    animation: ad-pulse 2s ease-in-out infinite;
}
@keyframes ad-pulse {
    0%,
    100% {
        opacity: 1;
    }
    50% {
        opacity: 0.4;
    }
}
.ad-occ {
    height: 0.5rem;
    border-radius: 9999px;
    background: rgba(255, 255, 255, 0.18);
    overflow: hidden;
}
.ad-occ > i {
    display: block;
    height: 100%;
    border-radius: 9999px;
    background: linear-gradient(90deg, #34d399, #0ea5e9);
}

/* Buttons */
.ad-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    padding: 0.55rem 0.9rem;
    border-radius: 0.8rem;
    font-size: 0.8rem;
    font-weight: 700;
    cursor: pointer;
    border: 1px solid transparent;
    white-space: nowrap;
    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease,
        background 0.2s ease,
        color 0.2s ease,
        border-color 0.2s ease;
}
.ad-btn:hover {
    transform: translateY(-2px);
}
.ad-btn-primary {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    box-shadow: 0 12px 24px -12px var(--color-primary);
}
.ad-btn-success {
    background: linear-gradient(135deg, #10b981, #059669);
    color: #fff;
    box-shadow: 0 12px 24px -12px #10b981;
}
.ad-btn-danger-solid {
    background: linear-gradient(135deg, #f43f5e, #e11d48);
    color: #fff;
    box-shadow: 0 12px 24px -12px #f43f5e;
}
.ad-btn-glass {
    background: rgba(255, 255, 255, 0.12);
    color: #fff;
    border-color: rgba(255, 255, 255, 0.24);
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
}
.ad-btn-glass:hover {
    background: rgba(255, 255, 255, 0.2);
}
.ad-btn-solid {
    background: var(--color-white);
    color: var(--color-gray-900);
    border-color: var(--color-border-color);
}
.ad-btn-solid:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.ad-btn-danger {
    background: #e11d48;
    color: #fff;
}
.ad-icobtn {
    display: grid;
    place-items: center;
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 0.75rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-500);
    cursor: pointer;
    transition: all 0.16s ease;
    flex-shrink: 0;
}
.ad-icobtn:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
    transform: translateY(-1px);
}
.ad-icobtn.is-active {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
    background: color-mix(in oklab, var(--color-primary) 10%, transparent);
}

/* KPI stat */
.ad-stat {
    position: relative;
    overflow: hidden;
    border-radius: 1.25rem;
    padding: 1.1rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 18px 40px -30px rgba(15, 23, 42, 0.45);
    transition:
        transform 0.25s ease,
        box-shadow 0.25s ease,
        border-color 0.25s ease;
}
.ad-stat::after {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(
        135deg,
        color-mix(in oklab, var(--ad-c) 12%, transparent),
        transparent 60%
    );
    pointer-events: none;
}
.ad-stat:hover {
    transform: translateY(-4px);
    box-shadow: 0 26px 50px -26px
        color-mix(in oklab, var(--ad-c) 55%, rgba(15, 23, 42, 0.5));
    border-color: color-mix(
        in oklab,
        var(--ad-c) 40%,
        var(--color-border-color)
    );
}
.ad-stat > * {
    position: relative;
    z-index: 1;
}
.ad-stat-ico {
    display: grid;
    place-items: center;
    width: 2.9rem;
    height: 2.9rem;
    border-radius: 0.9rem;
    color: #fff;
    font-size: 1.15rem;
    background: linear-gradient(
        135deg,
        var(--ad-c),
        color-mix(in oklab, var(--ad-c) 55%, #6366f1)
    );
    box-shadow: 0 10px 20px -10px var(--ad-c);
}
.ad-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.15rem 0.5rem;
    border-radius: 9999px;
    font-size: 0.62rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    color: color-mix(in oklab, var(--ad-c) 70%, #1e293b);
    background: color-mix(in oklab, var(--ad-c) 16%, transparent);
}
.dark .ad-chip {
    color: color-mix(in oklab, var(--ad-c) 55%, #fff);
}
.ad-ring {
    --p: 0;
    width: 3rem;
    height: 3rem;
    transform: rotate(-90deg);
}
.ad-ring circle {
    fill: none;
    stroke-width: 4;
}
.ad-ring .trk {
    stroke: color-mix(in oklab, var(--ad-c) 16%, transparent);
}
.ad-ring .bar {
    stroke: var(--ad-c);
    stroke-linecap: round;
    stroke-dasharray: 100 100;
    stroke-dashoffset: calc(100 - var(--p));
    transition: stroke-dashoffset 0.9s cubic-bezier(0.16, 1, 0.3, 1);
}

/* Card head */
.ad-head {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 1rem 1.15rem;
    border-bottom: 1px solid var(--color-border-color);
}
.ad-head .ico {
    display: grid;
    place-items: center;
    width: 2.3rem;
    height: 2.3rem;
    border-radius: 0.75rem;
    color: #fff;
    font-size: 0.95rem;
    background: linear-gradient(
        135deg,
        color-mix(in oklab, var(--ad-c) 90%, #000),
        color-mix(in oklab, var(--ad-c) 55%, #6366f1)
    );
    box-shadow: 0 10px 18px -12px var(--ad-c);
    flex-shrink: 0;
}
.ad-title {
    font-weight: 800;
    color: var(--color-gray-900);
    font-size: 0.9rem;
}

/* Toolbar */
.ad-search {
    position: relative;
    flex: 1 1 220px;
    min-width: 180px;
}
.ad-search input {
    width: 100%;
    padding: 0.6rem 0.9rem 0.6rem 2.5rem;
    border-radius: 0.85rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.85rem;
    font-weight: 600;
    outline: none;
    transition:
        border-color 0.18s ease,
        box-shadow 0.18s ease;
}
.ad-search input:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 4px
        color-mix(in oklab, var(--color-primary) 14%, transparent);
}
.ad-search .ico {
    position: absolute;
    left: 0.85rem;
    top: 50%;
    transform: translateY(-50%);
    color: var(--color-gray-400, #94a3b8);
    pointer-events: none;
}
.ad-tool {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.55rem 0.8rem;
    border-radius: 0.8rem;
    font-size: 0.8rem;
    font-weight: 700;
    cursor: pointer;
    white-space: nowrap;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-600, #475569);
    transition:
        border-color 0.18s ease,
        color 0.18s ease,
        transform 0.18s ease;
}
.ad-tool:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
    transform: translateY(-1px);
}
.ad-seg {
    display: inline-flex;
    padding: 0.25rem;
    border-radius: 0.85rem;
    background: color-mix(in oklab, var(--color-gray-500) 14%, transparent);
}
.ad-seg button {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.4rem 0.7rem;
    border-radius: 0.65rem;
    font-size: 0.78rem;
    font-weight: 700;
    color: var(--color-gray-500);
    transition: all 0.18s ease;
}
.ad-seg button.is-active {
    background: var(--color-white);
    color: var(--color-primary-text);
    box-shadow: 0 4px 10px -6px rgba(15, 23, 42, 0.4);
}

/* Admission card */
.ad-card {
    position: relative;
    overflow: hidden;
    border-radius: 1.25rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 18px 40px -32px rgba(15, 23, 42, 0.5);
    transition:
        transform 0.25s ease,
        box-shadow 0.25s ease,
        border-color 0.25s ease;
}
.ad-card::before {
    content: "";
    position: absolute;
    inset: 0 0 auto 0;
    height: 3px;
    background: linear-gradient(
        90deg,
        var(--ad-c),
        color-mix(in oklab, var(--ad-c) 40%, #6366f1)
    );
}
.ad-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 26px 48px -26px
        color-mix(in oklab, var(--ad-c) 45%, rgba(15, 23, 42, 0.5));
    border-color: color-mix(
        in oklab,
        var(--ad-c) 35%,
        var(--color-border-color)
    );
}
.ad-card.is-selected {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 2px
        color-mix(in oklab, var(--color-primary) 40%, transparent);
}
.ad-ava {
    width: 3rem;
    height: 3rem;
    border-radius: 0.85rem;
    display: grid;
    place-items: center;
    color: #fff;
    font-weight: 800;
    font-size: 0.95rem;
    background: linear-gradient(
        135deg,
        var(--ad-c),
        color-mix(in oklab, var(--ad-c) 55%, #6366f1)
    );
}
.ad-ava-ring {
    padding: 2px;
    border-radius: 1rem;
    background: linear-gradient(
        135deg,
        var(--ad-c),
        color-mix(in oklab, var(--ad-c) 40%, #6366f1)
    );
    flex-shrink: 0;
}

/* Badges */
.ad-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.15rem 0.55rem;
    border-radius: 9999px;
    font-size: 0.64rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    white-space: nowrap;
}
.ad-badge.admitted {
    color: #059669;
    background: rgba(16, 185, 129, 0.15);
}
.ad-badge.pending {
    color: #d97706;
    background: rgba(245, 158, 11, 0.15);
}
.ad-badge.reserved {
    color: var(--color-primary-text);
    background: color-mix(in oklab, var(--color-primary) 15%, transparent);
}
.ad-badge.discharged {
    color: #64748b;
    background: rgba(100, 116, 139, 0.15);
}
.ad-tag {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.1rem 0.45rem;
    border-radius: 0.5rem;
    font-size: 0.62rem;
    font-weight: 700;
    background: color-mix(in oklab, var(--ad-c) 14%, transparent);
    color: var(--ad-c);
}
.ad-bed {
    display: inline-grid;
    place-items: center;
    min-width: 2rem;
    padding: 0.1rem 0.4rem;
    border-radius: 0.5rem;
    font-size: 0.7rem;
    font-weight: 800;
    color: var(--color-primary-text);
    background: color-mix(in oklab, var(--color-primary) 12%, transparent);
}
.ad-mini {
    display: grid;
    place-items: center;
    width: 2rem;
    height: 2rem;
    border-radius: 0.6rem;
    color: var(--color-gray-500);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.16s ease;
}
.ad-mini:hover {
    border-color: var(--ad-c);
    color: var(--ad-c);
    transform: translateY(-1px);
}
.ad-kv {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    font-size: 0.72rem;
    color: var(--color-gray-500);
    min-width: 0;
}
.ad-kv b {
    color: var(--color-gray-900);
    font-weight: 700;
}

/* Table */
.ad-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0;
}
.ad-table thead th {
    text-align: left;
    font-size: 0.66rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--color-gray-400, #94a3b8);
    padding: 0.75rem 1rem;
    border-bottom: 1px solid var(--color-border-color);
    white-space: nowrap;
    background: color-mix(in oklab, var(--color-gray-500) 5%, transparent);
}
.ad-table tbody td {
    padding: 0.7rem 1rem;
    border-bottom: 1px solid var(--color-border-color);
    font-size: 0.82rem;
    color: var(--color-gray-900);
    vertical-align: middle;
    white-space: nowrap;
}
.ad-table tbody tr {
    transition: background 0.15s ease;
}
.ad-table tbody tr:hover {
    background: color-mix(in oklab, var(--color-primary) 5%, transparent);
}
.ad-table tbody tr.is-selected {
    background: color-mix(in oklab, var(--color-primary) 9%, transparent);
}
.ad-check {
    width: 1.05rem;
    height: 1.05rem;
    border-radius: 0.35rem;
    accent-color: var(--color-primary);
    cursor: pointer;
}

/* Menu */
.ad-menu {
    position: absolute;
    z-index: 1100;
    min-width: 14rem;
    max-height: 24rem;
    overflow-y: auto;
    padding: 0.4rem;
    border-radius: 1rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 30px 60px -24px rgba(2, 12, 40, 0.5);
    animation: ad-pop 0.16s ease;
}
@keyframes ad-pop {
    from {
        opacity: 0;
        transform: translateY(-6px) scale(0.97);
    }
}
.ad-menu button,
.ad-menu a {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    width: 100%;
    padding: 0.45rem 0.55rem;
    border-radius: 0.55rem;
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--color-gray-900);
    text-align: left;
    transition:
        background 0.14s ease,
        color 0.14s ease;
}
.ad-menu button:hover,
.ad-menu a:hover {
    background: color-mix(in oklab, var(--color-primary) 8%, transparent);
    color: var(--color-primary-text);
}
.ad-menu .danger {
    color: #e11d48;
}
.ad-menu .danger:hover {
    background: rgba(244, 63, 94, 0.1);
}
.ad-menu-sep {
    height: 1px;
    margin: 0.3rem 0.2rem;
    background: var(--color-border-color);
}
.ad-menu-lbl {
    padding: 0.4rem 0.55rem 0.15rem;
    font-size: 0.58rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--color-gray-400, #94a3b8);
}

/* Drawer */
.ad-drawer {
    position: fixed;
    inset: 0;
    z-index: 1200;
    visibility: hidden;
}
.ad-drawer.open {
    visibility: visible;
}
.ad-drawer-back {
    position: absolute;
    inset: 0;
    background: rgba(8, 12, 30, 0.5);
    opacity: 0;
    transition: opacity 0.3s ease;
}
.ad-drawer.open .ad-drawer-back {
    opacity: 1;
}
.ad-drawer-panel {
    position: absolute;
    top: 0;
    right: 0;
    height: 100%;
    width: min(460px, 94vw);
    background: var(--color-white);
    box-shadow: -30px 0 60px -30px rgba(2, 12, 40, 0.55);
    transform: translateX(100%);
    transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1);
    display: flex;
    flex-direction: column;
}
.ad-drawer.open .ad-drawer-panel {
    transform: translateX(0);
}
.ad-drawer-panel.left {
    right: auto;
    left: 0;
    transform: translateX(-100%);
    box-shadow: 30px 0 60px -30px rgba(2, 12, 40, 0.55);
}
.ad-drawer.open .ad-drawer-panel.left {
    transform: translateX(0);
}
.ad-drawer-hero {
    position: relative;
    padding: 1.5rem;
    color: #fff;
    background:
        radial-gradient(
            120% 130% at 100% 0%,
            rgba(20, 184, 166, 0.6),
            transparent 55%
        ),
        linear-gradient(135deg, #4f46e5, #0f172a);
}

/* Modal */
.ad-modal {
    position: fixed;
    inset: 0;
    z-index: 1300;
    display: none;
    align-items: center;
    justify-content: center;
    padding: 1rem;
}
.ad-modal.open {
    display: flex;
}
.ad-modal-back {
    position: absolute;
    inset: 0;
    background: rgba(8, 12, 30, 0.5);
    -webkit-backdrop-filter: blur(3px);
    backdrop-filter: blur(3px);
    animation: ad-fadein 0.2s ease;
}
@keyframes ad-fadein {
    from {
        opacity: 0;
    }
}
.ad-modal-panel {
    position: relative;
    width: 100%;
    max-width: 36rem;
    max-height: 90vh;
    overflow-y: auto;
    border-radius: 1.25rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 40px 80px -30px rgba(2, 12, 40, 0.6);
    animation: ad-modin 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes ad-modin {
    from {
        opacity: 0;
        transform: translateY(16px) scale(0.97);
    }
}
.ad-doc-ico {
    display: grid;
    place-items: center;
    width: 2.75rem;
    height: 2.75rem;
    border-radius: 0.8rem;
    color: var(--ad-c);
    font-size: 1.15rem;
    background: color-mix(in oklab, var(--ad-c) 14%, transparent);
}

/* Bulk */
.ad-bulk {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.55rem;
    padding: 0.7rem 0.9rem;
    border-radius: 1.25rem;
    background: color-mix(in oklab, var(--color-white) 85%, transparent);
    -webkit-backdrop-filter: blur(16px);
    backdrop-filter: blur(16px);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 12px 28px -18px rgba(15, 23, 42, 0.45);
    animation: ad-bulk-in 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes ad-bulk-in {
    from {
        opacity: 0;
        transform: translateY(-8px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}
.ad-bulk-btn {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.4rem 0.7rem;
    border-radius: 0.7rem;
    font-size: 0.76rem;
    font-weight: 700;
    color: var(--color-gray-700, #374151);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.15s ease;
    white-space: nowrap;
}
.dark .ad-bulk-btn {
    color: var(--color-gray-900);
}
.ad-bulk-btn:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.ad-bulk-btn.danger {
    color: #e11d48;
}
.ad-bulk-btn.danger:hover {
    border-color: #e11d48;
    background: rgba(244, 63, 94, 0.08);
}

/* Pagination */
.ad-pg {
    display: grid;
    place-items: center;
    min-width: 2.1rem;
    height: 2.1rem;
    padding: 0 0.5rem;
    border-radius: 0.6rem;
    font-size: 0.8rem;
    font-weight: 700;
    color: var(--color-gray-600, #475569);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.15s ease;
    cursor: pointer;
}
.ad-pg:hover:not(:disabled) {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.ad-pg.is-active {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    border-color: transparent;
}
.ad-pg:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

/* Workflow stepper */
.ad-wf {
    display: flex;
    align-items: center;
    gap: 0.25rem;
    overflow-x: auto;
    scrollbar-width: none;
}
.ad-wf::-webkit-scrollbar {
    display: none;
}
.ad-wf-step {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.4rem;
    min-width: 5.5rem;
    text-align: center;
}
.ad-wf-node {
    display: grid;
    place-items: center;
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 9999px;
    font-size: 0.85rem;
    color: var(--color-gray-500);
    background: color-mix(in oklab, var(--color-gray-500) 14%, transparent);
}
.ad-wf-step.done .ad-wf-node {
    background: linear-gradient(135deg, #10b981, #059669);
    color: #fff;
}
.ad-wf-step.active .ad-wf-node {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    box-shadow: 0 10px 20px -8px var(--color-primary);
}
.ad-wf-line {
    flex: 1 1 1rem;
    min-width: 1rem;
    height: 2px;
    border-radius: 2px;
    background: var(--color-border-color);
}
.ad-wf-line.done {
    background: linear-gradient(90deg, #10b981, #059669);
}

/* Timeline */
.ad-tl {
    position: relative;
    padding-left: 1.75rem;
}
.ad-tl::before {
    content: "";
    position: absolute;
    left: 0.72rem;
    top: 0.35rem;
    bottom: 0.35rem;
    width: 2px;
    background: linear-gradient(
        180deg,
        var(--ad-c, var(--color-primary)),
        color-mix(in oklab, var(--ad-c, var(--color-primary)) 20%, transparent)
    );
}
.ad-tl-item {
    position: relative;
    padding-bottom: 1.1rem;
}
.ad-tl-item:last-child {
    padding-bottom: 0;
}
.ad-tl-node {
    position: absolute;
    left: -1.75rem;
    top: 0.05rem;
    display: grid;
    place-items: center;
    width: 1.5rem;
    height: 1.5rem;
    border-radius: 9999px;
    color: #fff;
    font-size: 0.62rem;
    background: linear-gradient(
        135deg,
        var(--ad-c, var(--color-primary)),
        color-mix(in oklab, var(--ad-c, var(--color-primary)) 55%, #6366f1)
    );
    box-shadow: 0 0 0 3px
        color-mix(in oklab, var(--ad-c, var(--color-primary)) 16%, transparent);
}

/* Bed grid */
.ad-bedcell {
    position: relative;
    aspect-ratio: 1;
    border-radius: 0.7rem;
    display: grid;
    place-items: center;
    font-size: 0.66rem;
    font-weight: 800;
    cursor: pointer;
    border: 1.5px solid transparent;
    transition:
        transform 0.15s ease,
        box-shadow 0.15s ease;
}
.ad-bedcell:hover {
    transform: translateY(-2px);
}
.ad-bedcell.available {
    color: #059669;
    background: rgba(16, 185, 129, 0.14);
}
.ad-bedcell.occupied {
    color: #e11d48;
    background: rgba(244, 63, 94, 0.14);
    cursor: not-allowed;
}
.ad-bedcell.reserved {
    color: #d97706;
    background: rgba(245, 158, 11, 0.16);
}
.ad-bedcell.icu {
    color: #8b5cf6;
    background: rgba(139, 92, 246, 0.16);
}
.ad-bedcell.selected {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 2px
        color-mix(in oklab, var(--color-primary) 35%, transparent);
    color: #fff;
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
}

/* Bars / mini charts */
.ad-bar {
    height: 0.5rem;
    border-radius: 9999px;
    background: color-mix(in oklab, var(--ad-c) 14%, transparent);
    overflow: hidden;
}
.ad-bar > i {
    display: block;
    height: 100%;
    border-radius: 9999px;
    background: linear-gradient(
        90deg,
        var(--ad-c),
        color-mix(in oklab, var(--ad-c) 55%, #6366f1)
    );
}

/* Inputs */
.ad-in {
    width: 100%;
    padding: 0.65rem 0.8rem;
    border-radius: 0.7rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.85rem;
    font-weight: 600;
    outline: none;
    transition:
        border-color 0.16s ease,
        box-shadow 0.16s ease;
}
.ad-in:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 4px
        color-mix(in oklab, var(--color-primary) 14%, transparent);
}
.ad-lbl {
    display: block;
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--color-gray-500);
    margin-bottom: 0.3rem;
}

.ad-side-hero {
    position: relative;
    overflow: hidden;
    padding: 1.25rem;
    color: #fff;
    background:
        radial-gradient(
            120% 130% at 100% 0%,
            rgba(20, 184, 166, 0.6),
            transparent 55%
        ),
        linear-gradient(135deg, #4f46e5, #0f172a);
}
.ad-recent {
    display: flex;
    align-items: center;
    gap: 0.7rem;
    padding: 0.6rem;
    border-radius: 0.8rem;
    transition: background 0.15s ease;
}
.ad-recent:hover {
    background: color-mix(in oklab, var(--color-primary) 6%, transparent);
}

/* Accents */
.ad-c-indigo {
    --ad-c: #6366f1;
}
.ad-c-sky {
    --ad-c: #0ea5e9;
}
.ad-c-rose {
    --ad-c: #f43f5e;
}
.ad-c-amber {
    --ad-c: #f59e0b;
}
.ad-c-emerald {
    --ad-c: #10b981;
}
.ad-c-violet {
    --ad-c: #8b5cf6;
}
.ad-c-teal {
    --ad-c: #14b8a6;
}
.ad-c-primary {
    --ad-c: var(--color-primary);
}

/* Skeleton */
.ad-sk {
    position: relative;
    overflow: hidden;
    background: color-mix(in oklab, var(--color-gray-500) 12%, transparent);
    border-radius: 0.75rem;
}
.ad-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in oklab, var(--color-white) 55%, transparent),
        transparent
    );
    animation: ad-shimmer 1.4s infinite;
}
.dark .ad-sk::after {
    background: linear-gradient(
        90deg,
        transparent,
        rgba(255, 255, 255, 0.06),
        transparent
    );
}
@keyframes ad-shimmer {
    100% {
        transform: translateX(100%);
    }
}

/* Per-instance overrides (unlayered, placed after the base classes above so
               source-order tie-breaking lets them win — see CASCADE-SAFE OVERRIDE UTILITIES) */
.ad-sk-r125 {
    border-radius: 1.25rem;
}
.ad-sk-r150 {
    border-radius: 1.5rem;
}
.ad-hbadge-teal {
    background: rgba(20, 184, 166, 0.18);
    border-color: rgba(20, 184, 166, 0.4);
}
.ad-tool-compact {
    padding: 0.35rem 0.6rem;
}
.ad-tool-compact-sm {
    padding: 0.35rem 0.5rem;
}

.ad-toast {
    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    z-index: 2000;
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.8rem 1.1rem;
    border-radius: 0.9rem;
    font-size: 0.85rem;
    font-weight: 700;
    color: #fff;
    box-shadow: 0 20px 45px -18px rgba(0, 0, 0, 0.5);
    animation: ad-toastin 0.25s ease;
}
@keyframes ad-toastin {
    from {
        opacity: 0;
        transform: translateY(12px);
    }
}
.ad-toast.success {
