/* ---------- HERO ---------- */
.ss-hero {
    position: relative;
    overflow: hidden;
    border-radius: 1.5rem;
    padding: 1.75rem;
    color: #fff;
    background:
        radial-gradient(
            120% 140% at 0% 0%,
            rgba(99, 102, 241, 0.5),
            transparent 55%
        ),
        radial-gradient(
            120% 160% at 100% 0%,
            rgba(236, 72, 153, 0.5),
            transparent 50%
        ),
        linear-gradient(135deg, #0f172a, #1a1440 55%, #0b1220);
    box-shadow: 0 30px 60px -30px rgba(15, 23, 42, 0.7);
}
.ss-hero::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image: radial-gradient(
        rgba(255, 255, 255, 0.08) 1px,
        transparent 1px
    );
    background-size: 22px 22px;
    -webkit-mask-image: linear-gradient(180deg, #000, transparent 75%);
    mask-image: linear-gradient(180deg, #000, transparent 75%);
}
.ss-hero > * {
    position: relative;
    z-index: 1;
}
@media (min-width: 1024px) {
    .ss-hero {
        padding: 2rem 2.25rem;
    }
}
.ss-hbadge {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.28rem 0.7rem;
    border-radius: 9999px;
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    background: rgba(255, 255, 255, 0.14);
    border: 1px solid rgba(255, 255, 255, 0.22);
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
}
.ss-hmeta {
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
    padding: 0.5rem 0.85rem;
    border-radius: 0.85rem;
    background: rgba(255, 255, 255, 0.1);
    border: 1px solid rgba(255, 255, 255, 0.16);
    font-size: 0.74rem;
    font-weight: 700;
}
.ss-dot {
    width: 0.5rem;
    height: 0.5rem;
    border-radius: 9999px;
    background: #818cf8;
    box-shadow: 0 0 0 4px rgba(129, 140, 248, 0.25);
    animation: ss-pulse 2s ease-in-out infinite;
}
@keyframes ss-pulse {
    0%,
    100% {
        opacity: 1;
    }
    50% {
        opacity: 0.4;
    }
}
.ss-liveblink {
    width: 0.5rem;
    height: 0.5rem;
    border-radius: 9999px;
    background: #34d399;
    box-shadow: 0 0 0 3px rgba(52, 211, 153, 0.3);
    animation: ss-blink 1.2s ease-in-out infinite;
}
@keyframes ss-blink {
    0%,
    100% {
        opacity: 1;
    }
    50% {
        opacity: 0.3;
    }
}

/* ---------- BUTTONS ---------- */
.ss-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    padding: 0.55rem 0.9rem;
    border-radius: 0.8rem;
    font-size: 0.8rem;
    font-weight: 700;
    cursor: pointer;
    border: 1px solid transparent;
    white-space: nowrap;
    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease,
        background 0.2s ease,
        color 0.2s ease,
        border-color 0.2s ease;
}
.ss-btn:hover {
    transform: translateY(-2px);
}
.ss-btn-primary {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    box-shadow: 0 12px 24px -12px var(--color-primary);
}
.ss-btn-indigo {
    background: linear-gradient(135deg, #6366f1, #8b5cf6);
    color: #fff;
    box-shadow: 0 12px 24px -12px #6366f1;
}
.ss-btn-glass {
    background: rgba(255, 255, 255, 0.12);
    color: #fff;
    border-color: rgba(255, 255, 255, 0.24);
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
}
.ss-btn-glass:hover {
    background: rgba(255, 255, 255, 0.2);
}
.ss-btn-soft {
    background: var(--color-gray-100);
    color: var(--color-gray-700);
    border-color: var(--color-border-color);
}
.ss-btn-soft:hover {
    background: var(--color-gray-200);
}

/* ---------- KPI ---------- */
.ss-kpi {
    position: relative;
    overflow: hidden;
    padding: 1.1rem;
    border-radius: 1.2rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 16px 30px -28px rgba(15, 23, 42, 0.5);
    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease;
}
.ss-kpi:hover {
    transform: translateY(-4px);
    box-shadow: 0 26px 48px -30px rgba(15, 23, 42, 0.55);
}
.ss-kpi::after {
    content: "";
    position: absolute;
    right: -30px;
    top: -30px;
    width: 90px;
    height: 90px;
    border-radius: 9999px;
    background: var(--kc, #6366f1);
    opacity: 0.08;
}
.ss-kpi-ic {
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 0.85rem;
    display: flex;
    align-items: center;
    justify-content: center;
}
.ss-kpi-v {
    font-size: 1.55rem;
    font-weight: 800;
    line-height: 1;
    color: var(--color-gray-900);
}
.ss-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.18rem 0.5rem;
    border-radius: 9999px;
    font-size: 0.66rem;
    font-weight: 800;
}
.ss-ring {
    transform: rotate(-90deg);
}
.ss-ring .bar {
    stroke-dasharray: 100 100;
    stroke-dashoffset: calc(100 - var(--p, 0));
    transition: stroke-dashoffset 1.1s cubic-bezier(0.34, 1.56, 0.64, 1);
}

/* ---------- INPUTS ---------- */
.ss-inp {
    width: 100%;
    padding: 0.55rem 0.7rem;
    border-radius: 0.7rem;
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.8rem;
}
.ss-inp:focus {
    outline: none;
    border-color: var(--color-primary);
    box-shadow: 0 0 0 3px
        color-mix(in srgb, var(--color-primary) 20%, transparent);
}
.ss-lbl {
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--color-gray-600);
    margin-bottom: 0.3rem;
    display: block;
}
.ss-seg {
    display: inline-flex;
    padding: 0.2rem;
    border-radius: 0.7rem;
    background: var(--color-gray-100);
    border: 1px solid var(--color-border-color);
}
.ss-segb {
    padding: 0.4rem 0.7rem;
    border-radius: 0.5rem;
    font-size: 0.76rem;
    font-weight: 700;
    color: var(--color-gray-600);
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
}
.ss-segb.active {
    background: var(--color-white);
    color: var(--color-primary-text);
    box-shadow: 0 6px 14px -10px rgba(15, 23, 42, 0.5);
}

/* ---------- TABLE ---------- */
.ss-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0;
}
.ss-table th {
    text-align: left;
    font-size: 0.7rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.04em;
    color: var(--color-gray-500);
    padding: 0.65rem 0.75rem;
    border-bottom: 1px solid var(--color-border-color);
    white-space: nowrap;
}
.ss-table td {
    padding: 0.7rem 0.75rem;
    border-bottom: 1px solid var(--color-border-color);
    font-size: 0.82rem;
}
.ss-table tbody tr {
    transition: background 0.15s ease;
}
.ss-table tbody tr:hover {
    background: var(--color-gray-100);
}
.ss-hidecol {
    display: none;
}

/* ---------- CALENDAR ---------- */
.ss-cal {
    display: grid;
    grid-template-columns: repeat(7, 1fr);
    gap: 0.4rem;
}
.ss-cal-hd {
    text-align: center;
    font-size: 0.68rem;
    font-weight: 800;
    text-transform: uppercase;
    color: var(--color-gray-500);
    padding: 0.3rem 0;
}
.ss-cal-cell {
    min-height: 92px;
    border: 1px solid var(--color-border-color);
    border-radius: 0.7rem;
    padding: 0.35rem;
    background: var(--color-white);
    transition: border-color 0.15s ease;
    overflow: hidden;
}
.ss-cal-cell.other {
    background: var(--color-gray-100);
    opacity: 0.55;
}
.ss-cal-cell.today {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 2px
        color-mix(in srgb, var(--color-primary) 25%, transparent);
}
.ss-cal-daynum {
    font-size: 0.72rem;
    font-weight: 800;
    color: var(--color-gray-700);
}
.ss-cal-ev {
    display: flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.12rem 0.3rem;
    border-radius: 0.35rem;
    font-size: 0.6rem;
    font-weight: 700;
    margin-top: 0.2rem;
    cursor: pointer;
    overflow: hidden;
    white-space: nowrap;
}

/* ---------- TIMELINE ---------- */
.ss-tl-card {
    position: relative;
    display: flex;
    gap: 0.85rem;
    padding: 0.85rem 1rem;
    border: 1px solid var(--color-border-color);
    border-radius: 1rem;
    margin-bottom: 0.7rem;
    transition:
        transform 0.15s ease,
        box-shadow 0.15s ease;
    cursor: pointer;
}
.ss-tl-card:hover {
    transform: translateX(3px);
    box-shadow: 0 12px 26px -22px rgba(15, 23, 42, 0.5);
}
.ss-tl-time {
    text-align: center;
    flex: none;
    width: 64px;
}

.ss-av {
    width: 2.4rem;
    height: 2.4rem;
    border-radius: 0.7rem;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.7rem;
    font-weight: 800;
    color: #fff;
    flex: none;
    border: 2px solid var(--color-white);
    object-fit: cover;
}
.ss-av-sm {
    width: 2rem;
    height: 2rem;
    border-radius: 0.55rem;
    font-size: 0.6rem;
}

.ss-tag {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.24rem 0.55rem;
    border-radius: 9999px;
    font-size: 0.66rem;
    font-weight: 700;
}
.ss-bar {
    height: 0.5rem;
    border-radius: 9999px;
    background: var(--color-gray-200);
    overflow: hidden;
}
.ss-bar > span {
    display: block;
    height: 100%;
    border-radius: 9999px;
}
.ss-dotstat {
    width: 0.55rem;
    height: 0.55rem;
    border-radius: 9999px;
    flex: none;
}

/* ---------- ACTION MENU ---------- */
.ss-menu {
    position: fixed;
    z-index: 80;
    width: 216px;
    max-height: 70vh;
    overflow: auto;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    border-radius: 0.85rem;
    box-shadow: 0 30px 60px -20px rgba(15, 23, 42, 0.5);
    padding: 0.35rem;
    display: none;
}
.ss-menu.open {
    display: block;
    animation: ss-pop 0.18s ease;
}
.ss-mi {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    padding: 0.5rem 0.6rem;
    border-radius: 0.55rem;
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--color-gray-700);
    cursor: pointer;
}
.ss-mi:hover {
    background: var(--color-gray-100);
}
.ss-mi.danger {
    color: #dc2626;
}
.ss-mi.danger:hover {
    background: color-mix(in srgb, #ef4444 12%, transparent);
}
.ss-mi.ok {
    color: #059669;
}
.ss-mi.ok:hover {
    background: color-mix(in srgb, #10b981 12%, transparent);
}
.ss-sep {
    height: 1px;
    background: var(--color-border-color);
    margin: 0.3rem 0.2rem;
}

/* ---------- SKELETON ---------- */
.ss-sk {
    position: relative;
    overflow: hidden;
    background: var(--color-gray-100);
    border-radius: 1rem;
}
.ss-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in srgb, var(--color-gray-300) 55%, transparent),
        transparent
    );
    animation: ss-sh 1.4s infinite;
}
@keyframes ss-sh {
    100% {
        transform: translateX(100%);
    }
}

/* ---------- DRAWER ---------- */
.ss-drawer {
    position: fixed;
    inset: 0;
    z-index: 70;
    display: none;
}
.ss-drawer.open {
    display: block;
}
.ss-mask {
    position: absolute;
    inset: 0;
    background: rgba(15, 23, 42, 0.55);
    -webkit-backdrop-filter: blur(3px);
    backdrop-filter: blur(3px);
    animation: ss-fade 0.25s ease;
}
@keyframes ss-fade {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}
.ss-panel {
    position: absolute;
    top: 0;
    right: 0;
    height: 100%;
    width: min(480px, 100vw);
    background: var(--color-white);
    border-left: 1px solid var(--color-border-color);
    box-shadow: -30px 0 60px -30px rgba(15, 23, 42, 0.6);
    overflow-y: auto;
    animation: ss-slide 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
@keyframes ss-slide {
    from {
        transform: translateX(100%);
    }
    to {
        transform: none;
    }
}

/* ---------- MODAL ---------- */
.ss-modal {
    position: fixed;
    inset: 0;
    z-index: 75;
    display: none;
}
.ss-modal.open {
    display: block;
}
.ss-dialog {
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
    width: min(560px, 94vw);
    max-height: 90vh;
    overflow: auto;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    border-radius: 1.25rem;
    box-shadow: 0 40px 80px -30px rgba(15, 23, 42, 0.7);
    animation: ss-pop 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}
@keyframes ss-pop {
    from {
        opacity: 0;
        transform: translate(-50%, -46%) scale(0.96);
    }
    to {
        opacity: 1;
        transform: translate(-50%, -50%) scale(1);
    }
}
.ss-drop {
    border: 2px dashed var(--color-border-color);
    border-radius: 1rem;
    padding: 1.6rem;
    text-align: center;
    transition: all 0.2s ease;
    cursor: pointer;
}
.ss-drop:hover,
.ss-drop.drag {
    border-color: var(--color-primary);
    background: color-mix(in srgb, var(--color-primary) 6%, transparent);
}

/* ---------- BULK BAR ---------- */
.ss-bulk {
    position: fixed;
    left: 50%;
    bottom: 1.25rem;
    transform: translateX(-50%) translateY(160%);
    z-index: 60;
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.6rem 0.6rem 0.6rem 1rem;
    border-radius: 1rem;
    background: var(--color-gray-900);
    color: #fff;
    box-shadow: 0 30px 60px -20px rgba(0, 0, 0, 0.6);
    transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
    flex-wrap: wrap;
    max-width: 94vw;
}
.ss-bulk.show {
    transform: translateX(-50%) translateY(0);
}

/* ---------- TOAST ---------- */
#ss-toast {
    position: fixed;
    right: 1rem;
    bottom: 1rem;
    z-index: 90;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}
.ss-toast {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    padding: 0.7rem 0.95rem;
    border-radius: 0.8rem;
    background: var(--color-gray-900);
    color: #fff;
    font-size: 0.8rem;
    font-weight: 700;
    box-shadow: 0 18px 40px -18px rgba(0, 0, 0, 0.6);
    animation: ss-tin 0.3s ease;
}
@keyframes ss-tin {
    from {
        opacity: 0;
        transform: translateY(12px);
    }
    to {
        opacity: 1;
        transform: none;
    }
}

input[type="checkbox"].ss-cb {
    width: 1.05rem;
    height: 1.05rem;
    border-radius: 0.35rem;
    accent-color: var(--color-primary);
    cursor: pointer;
}

