    align-items: center;
    justify-content: center;
    font-size: 0.7rem;
    font-weight: 800;
    color: #fff;
    flex: none;
    border: 2px solid var(--color-white);
}
.tm-av-sm {
    width: 2rem;
    height: 2rem;
    border-radius: 0.55rem;
    font-size: 0.6rem;
}

.tm-tag {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.24rem 0.55rem;
    border-radius: 9999px;
    font-size: 0.66rem;
    font-weight: 700;
}
.tm-bar {
    height: 0.5rem;
    border-radius: 9999px;
    background: var(--color-gray-200);
    overflow: hidden;
}
.tm-bar > span {
    display: block;
    height: 100%;
    border-radius: 9999px;
}
.tm-dotstat {
    width: 0.55rem;
    height: 0.55rem;
    border-radius: 9999px;
    flex: none;
}

/* ---------- ACTION MENU ---------- */
.tm-menu {
    position: fixed;
    z-index: 80;
    width: 212px;
    max-height: 70vh;
    overflow: auto;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    border-radius: 0.85rem;
    box-shadow: 0 30px 60px -20px rgba(15, 23, 42, 0.5);
    padding: 0.35rem;
    display: none;
}
.tm-menu.open {
    display: block;
    animation: tm-pop 0.18s ease;
}
.tm-mi {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    padding: 0.5rem 0.6rem;
    border-radius: 0.55rem;
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--color-gray-700);
    cursor: pointer;
}
.tm-mi:hover {
    background: var(--color-gray-100);
}
.tm-mi.danger {
    color: #dc2626;
}
.tm-mi.danger:hover {
    background: color-mix(in srgb, #ef4444 12%, transparent);
}
.tm-mi.video {
    color: #6366f1;
}
.tm-mi.video:hover {
    background: color-mix(in srgb, #6366f1 12%, transparent);
}
.tm-sep {
    height: 1px;
    background: var(--color-border-color);
    margin: 0.3rem 0.2rem;
}

/* ---------- SKELETON ---------- */
.tm-sk {
    position: relative;
    overflow: hidden;
    background: var(--color-gray-100);
    border-radius: 1rem;
}
.tm-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in srgb, var(--color-gray-300) 55%, transparent),
        transparent
    );
    animation: tm-sh 1.4s infinite;
}
@keyframes tm-sh {
    100% {
        transform: translateX(100%);
    }
}

/* ---------- DRAWER ---------- */
.tm-drawer {
    position: fixed;
    inset: 0;
    z-index: 70;
    display: none;
}
.tm-drawer.open {
    display: block;
}
.tm-mask {
    position: absolute;
    inset: 0;
    background: rgba(15, 23, 42, 0.55);
    -webkit-backdrop-filter: blur(3px);
    backdrop-filter: blur(3px);
    animation: tm-fade 0.25s ease;
}
@keyframes tm-fade {
    from {
        opacity: 0;
    }
    to {
        opacity: 1;
    }
}
.tm-panel {
    position: absolute;
    top: 0;
    right: 0;
    height: 100%;
    width: min(480px, 100vw);
    background: var(--color-white);
    border-left: 1px solid var(--color-border-color);
    box-shadow: -30px 0 60px -30px rgba(15, 23, 42, 0.6);
    overflow-y: auto;
    animation: tm-slide 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
@keyframes tm-slide {
    from {
        transform: translateX(100%);
    }
    to {
        transform: none;
    }
}

/* ---------- MODAL ---------- */
.tm-modal {
    position: fixed;
    inset: 0;
    z-index: 75;
    display: none;
}
.tm-modal.open {
    display: block;
}
.tm-dialog {
    position: absolute;
    left: 50%;
    top: 50%;
    transform: translate(-50%, -50%);
    width: min(560px, 94vw);
    max-height: 90vh;
    overflow: auto;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    border-radius: 1.25rem;
    box-shadow: 0 40px 80px -30px rgba(15, 23, 42, 0.7);
    animation: tm-pop 0.3s cubic-bezier(0.34, 1.56, 0.64, 1);
}
@keyframes tm-pop {
    from {
        opacity: 0;
        transform: translate(-50%, -46%) scale(0.96);
    }
    to {
        opacity: 1;
        transform: translate(-50%, -50%) scale(1);
    }
}
.tm-drop {
    border: 2px dashed var(--color-border-color);
    border-radius: 1rem;
    padding: 1.6rem;
    text-align: center;
    transition: all 0.2s ease;
    cursor: pointer;
}
.tm-drop:hover,
.tm-drop.drag {
    border-color: var(--color-primary);
    background: color-mix(in srgb, var(--color-primary) 6%, transparent);
}

/* ---------- VIDEO WORKSPACE ---------- */
.tm-vc {
    position: fixed;
    inset: 0;
    z-index: 100;
    display: none;
    background: #0b1020;
}
.tm-vc.open {
    display: flex;
    flex-direction: column;
    animation: tm-fade 0.3s ease;
}
.tm-vc-main {
    flex: 1;
    display: grid;
    grid-template-columns: 1fr;
    gap: 0.75rem;
    padding: 0.75rem;
    overflow: hidden;
}
@media (min-width: 1024px) {
    .tm-vc-main.with-side {
        grid-template-columns: 1fr 320px;
    }
}
.tm-stage {
    position: relative;
    border-radius: 1.1rem;
    overflow: hidden;
    background: linear-gradient(135deg, #1e293b, #0f172a);
    min-height: 280px;
    display: flex;
    align-items: center;
    justify-content: center;
}
.tm-stage::before {
    content: "";
    position: absolute;
    inset: 0;
    background: radial-gradient(
        circle at 50% 40%,
        rgba(99, 102, 241, 0.25),
        transparent 60%
    );
}
.tm-bigav {
    width: 120px;
    height: 120px;
    border-radius: 9999px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 3rem;
    font-weight: 800;
    color: #fff;
    box-shadow: 0 20px 50px -10px rgba(0, 0, 0, 0.6);
    position: relative;
    z-index: 1;
}
.tm-pip {
    position: absolute;
    right: 1rem;
    bottom: 1rem;
    width: 150px;
    height: 104px;
    border-radius: 0.9rem;
    overflow: hidden;
    border: 2px solid rgba(255, 255, 255, 0.2);
    background: linear-gradient(135deg, #334155, #1e293b);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 2;
    box-shadow: 0 14px 30px -10px rgba(0, 0, 0, 0.6);
}
.tm-vc-badge {
    position: absolute;
    top: 1rem;
    left: 1rem;
    z-index: 2;
    display: flex;
    gap: 0.5rem;
    flex-wrap: wrap;
}
.tm-glass {
    background: rgba(15, 23, 42, 0.55);
    -webkit-backdrop-filter: blur(10px);
    backdrop-filter: blur(10px);
    border: 1px solid rgba(255, 255, 255, 0.12);
    color: #fff;
}
.tm-vc-side {
    display: none;
    background: rgba(15, 23, 42, 0.6);
    border: 1px solid rgba(255, 255, 255, 0.1);
    border-radius: 1.1rem;
    overflow: hidden;
    flex-direction: column;
}
.tm-vc-side.show {
    display: flex;
}
.tm-chatmsg {
    max-width: 85%;
    padding: 0.5rem 0.7rem;
    border-radius: 0.8rem;
    font-size: 0.78rem;
    margin-bottom: 0.5rem;
}
.tm-chatmsg-in {
    background: rgba(255, 255, 255, 0.08);
}
.tm-ctrl {
    width: 3rem;
    height: 3rem;
    border-radius: 9999px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.15rem;
    cursor: pointer;
    transition: all 0.15s ease;
    border: 1px solid rgba(255, 255, 255, 0.15);
    background: rgba(255, 255, 255, 0.1);
    color: #fff;
}
.tm-ctrl:hover {
    background: rgba(255, 255, 255, 0.2);
    transform: translateY(-2px);
}
.tm-ctrl.off {
    background: #ef4444;
    border-color: #ef4444;
}
.tm-ctrl.end {
    width: auto;
    padding: 0 1.4rem;
    border-radius: 9999px;
    background: #ef4444;
    border-color: #ef4444;
    font-weight: 800;
    font-size: 0.85rem;
    gap: 0.4rem;
}
.tm-net span {
    display: inline-block;
    width: 3px;
    border-radius: 2px;
    background: #34d399;
    margin-right: 1px;
    vertical-align: bottom;
}

/* ---------- BULK BAR ---------- */
.tm-bulk {
    position: fixed;
    left: 50%;
    bottom: 1.25rem;
    transform: translateX(-50%) translateY(160%);
    z-index: 60;
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.6rem 0.6rem 0.6rem 1rem;
    border-radius: 1rem;
    background: var(--color-gray-900);
    color: #fff;
