    transform: translateX(-50%) translateY(0);
}

/* ---------- TOAST ---------- */
#tm-toast {
    position: fixed;
    right: 1rem;
    bottom: 1rem;
    z-index: 110;
    display: flex;
    flex-direction: column;
    gap: 0.5rem;
}
.tm-toast {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    padding: 0.7rem 0.95rem;
