    100% {
        opacity: 1;
    }
    50% {
        opacity: 0.4;
    }
}
.ins-hava {
    width: 3.5rem;
    height: 3.5rem;
    border-radius: 1rem;
    display: grid;
    place-items: center;
    font-weight: 800;
    font-size: 1.1rem;
    color: #fff;
    background: rgba(255, 255, 255, 0.16);
    border: 1px solid rgba(255, 255, 255, 0.28);
}

.ins-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    padding: 0.55rem 0.9rem;
    border-radius: 0.8rem;
    font-size: 0.8rem;
    font-weight: 700;
    cursor: pointer;
    border: 1px solid transparent;
    white-space: nowrap;
    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease,
        background 0.2s ease,
        color 0.2s ease,
        border-color 0.2s ease;
}
.ins-btn:hover {
    transform: translateY(-2px);
}
.ins-btn-primary {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    box-shadow: 0 12px 24px -12px var(--color-primary);
}
.ins-btn-success {
    background: linear-gradient(135deg, #3b82f6, #2563eb);
    color: #fff;
    box-shadow: 0 12px 24px -12px #3b82f6;
}
.ins-btn-glass {
    background: rgba(255, 255, 255, 0.12);
    color: #fff;
    border-color: rgba(255, 255, 255, 0.24);
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
}
.ins-btn-glass:hover {
    background: rgba(255, 255, 255, 0.2);
}
.ins-btn-solid {
    background: var(--color-white);
    color: var(--color-gray-900);
    border-color: var(--color-border-color);
}
.ins-btn-solid:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.ins-btn-danger {
    background: #e11d48;
    color: #fff;
}
.ins-icobtn {
    display: grid;
    place-items: center;
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 0.75rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-500);
    cursor: pointer;
    transition: all 0.16s ease;
    flex-shrink: 0;
}
.ins-icobtn:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
    transform: translateY(-1px);
}

.ins-stat {
    position: relative;
    overflow: hidden;
    border-radius: 1.25rem;
    padding: 1.1rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 18px 40px -30px rgba(15, 23, 42, 0.45);
    transition:
        transform 0.25s ease,
        box-shadow 0.25s ease,
        border-color 0.25s ease;
}
.ins-stat::after {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(
        135deg,
        color-mix(in oklab, var(--ins-c) 12%, transparent),
        transparent 60%
    );
    pointer-events: none;
}
.ins-stat:hover {
    transform: translateY(-4px);
    box-shadow: 0 26px 50px -26px
        color-mix(in oklab, var(--ins-c) 55%, rgba(15, 23, 42, 0.5));
    border-color: color-mix(
        in oklab,
        var(--ins-c) 40%,
        var(--color-border-color)
    );
}
.ins-stat > * {
    position: relative;
    z-index: 1;
}
.ins-stat-ico {
    display: grid;
    place-items: center;
    width: 2.9rem;
    height: 2.9rem;
    border-radius: 0.9rem;
    color: #fff;
    font-size: 1.15rem;
    background: linear-gradient(
        135deg,
        var(--ins-c),
        color-mix(in oklab, var(--ins-c) 55%, #6366f1)
    );
    box-shadow: 0 10px 20px -10px var(--ins-c);
}
.ins-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.15rem 0.5rem;
    border-radius: 9999px;
    font-size: 0.62rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    color: color-mix(in oklab, var(--ins-c) 70%, #1e293b);
    background: color-mix(in oklab, var(--ins-c) 16%, transparent);
}
.dark .ins-chip {
    color: color-mix(in oklab, var(--ins-c) 55%, #fff);
}
.ins-ring {
    --p: 0;
    width: 3rem;
    height: 3rem;
    transform: rotate(-90deg);
}
.ins-ring circle {
    fill: none;
    stroke-width: 4;
}
.ins-ring .trk {
    stroke: color-mix(in oklab, var(--ins-c) 16%, transparent);
}
.ins-ring .bar {
    stroke: var(--ins-c);
    stroke-linecap: round;
    stroke-dasharray: 100 100;
    stroke-dashoffset: calc(100 - var(--p));
    transition: stroke-dashoffset 0.9s cubic-bezier(0.16, 1, 0.3, 1);
}

.ins-head {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 1rem 1.15rem;
    border-bottom: 1px solid var(--color-border-color);
}
.ins-head .ico {
    display: grid;
    place-items: center;
    width: 2.3rem;
    height: 2.3rem;
    border-radius: 0.75rem;
    color: #fff;
    font-size: 0.95rem;
    background: linear-gradient(
        135deg,
        color-mix(in oklab, var(--ins-c) 90%, #000),
        color-mix(in oklab, var(--ins-c) 55%, #6366f1)
    );
    box-shadow: 0 10px 18px -12px var(--ins-c);
    flex-shrink: 0;
}
.ins-t {
    font-weight: 800;
    color: var(--color-gray-900);
    font-size: 0.9rem;
}

.ins-search {
    position: relative;
    flex: 1 1 220px;
    min-width: 180px;
}
.ins-search input {
    width: 100%;
    padding: 0.6rem 0.9rem 0.6rem 2.5rem;
    border-radius: 0.85rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.85rem;
    font-weight: 600;
    outline: none;
    transition:
        border-color 0.18s ease,
        box-shadow 0.18s ease;
}
.ins-search input:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 4px
        color-mix(in oklab, var(--color-primary) 14%, transparent);
}
.ins-search .ico {
    position: absolute;
    left: 0.85rem;
    top: 50%;
    transform: translateY(-50%);
    color: var(--color-gray-400, #94a3b8);
    pointer-events: none;
}
.ins-tool {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.55rem 0.8rem;
    border-radius: 0.8rem;
    font-size: 0.8rem;
    font-weight: 700;
    cursor: pointer;
    white-space: nowrap;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-600, #475569);
    transition:
        border-color 0.18s ease,
        color 0.18s ease,
        transform 0.18s ease;
}
.ins-tool:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
    transform: translateY(-1px);
}
.ins-seg {
    display: inline-flex;
    padding: 0.25rem;
    border-radius: 0.85rem;
    background: color-mix(in oklab, var(--color-gray-500) 14%, transparent);
}
.ins-seg button {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.4rem 0.7rem;
    border-radius: 0.65rem;
    font-size: 0.78rem;
    font-weight: 700;
    color: var(--color-gray-500);
    transition: all 0.18s ease;
}
.ins-seg button.is-active {
    background: var(--color-white);
    color: var(--color-primary-text);
    box-shadow: 0 4px 10px -6px rgba(15, 23, 42, 0.4);
}

.ins-card {
    position: relative;
    overflow: hidden;
    border-radius: 1.25rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 18px 40px -32px rgba(15, 23, 42, 0.5);
    transition:
        transform 0.25s ease,
        box-shadow 0.25s ease,
        border-color 0.25s ease;
}
.ins-card::before {
    content: "";
    position: absolute;
    inset: 0 0 auto 0;
    height: 3px;
    background: linear-gradient(
        90deg,
        var(--ins-c),
        color-mix(in oklab, var(--ins-c) 40%, #6366f1)
    );
}
.ins-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 26px 48px -26px
        color-mix(in oklab, var(--ins-c) 45%, rgba(15, 23, 42, 0.5));
    border-color: color-mix(
        in oklab,
        var(--ins-c) 35%,
        var(--color-border-color)
    );
}
.ins-card.is-selected {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 2px
        color-mix(in oklab, var(--color-primary) 40%, transparent);
}
.ins-logo {
    display: grid;
    place-items: center;
    width: 2.9rem;
    height: 2.9rem;
    border-radius: 0.85rem;
    font-weight: 900;
    font-size: 0.9rem;
    color: #fff;
    background: linear-gradient(
        135deg,
        var(--ins-c),
        color-mix(in oklab, var(--ins-c) 55%, #6366f1)
    );
    box-shadow: 0 10px 20px -10px var(--ins-c);
    flex-shrink: 0;
}

.ins-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.15rem 0.55rem;
    border-radius: 9999px;
    font-size: 0.62rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    white-space: nowrap;
}
.ins-badge.approved {
    color: #059669;
    background: rgba(16, 185, 129, 0.15);
}
.ins-badge.pending {
    color: #d97706;
    background: rgba(245, 158, 11, 0.15);
}
.ins-badge.processing {
    color: var(--color-primary-text);
    background: color-mix(in oklab, var(--color-primary) 15%, transparent);
}
.ins-badge.submitted {
    color: #0284c7;
    background: rgba(14, 165, 233, 0.15);
}
.ins-badge.rejected {
    color: #e11d48;
    background: rgba(244, 63, 94, 0.15);
}
.ins-tag {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.1rem 0.45rem;
    border-radius: 0.5rem;
    font-size: 0.62rem;
    font-weight: 700;
    background: color-mix(in oklab, var(--ins-c) 14%, transparent);
    color: var(--ins-c);
}
.ins-mini {
    display: grid;
    place-items: center;
    width: 2rem;
    height: 2rem;
    border-radius: 0.6rem;
    color: var(--color-gray-500);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.16s ease;
}
.ins-mini:hover {
    border-color: var(--ins-c);
    color: var(--ins-c);
    transform: translateY(-1px);
}
.ins-kv {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    font-size: 0.72rem;
    color: var(--color-gray-500);
    min-width: 0;
}
.ins-kv b {
    color: var(--color-gray-900);
    font-weight: 700;
}

.ins-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0;
}
.ins-table thead th {
    text-align: left;
    font-size: 0.66rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--color-gray-400, #94a3b8);
    padding: 0.75rem 1rem;
    border-bottom: 1px solid var(--color-border-color);
    white-space: nowrap;
    background: color-mix(in oklab, var(--color-gray-500) 5%, transparent);
}
.ins-table tbody td {
    padding: 0.7rem 1rem;
    border-bottom: 1px solid var(--color-border-color);
    font-size: 0.82rem;
    color: var(--color-gray-900);
    vertical-align: middle;
    white-space: nowrap;
}
.ins-table tbody tr {
    transition: background 0.15s ease;
}
.ins-table tbody tr:hover {
    background: color-mix(in oklab, var(--color-primary) 5%, transparent);
}
.ins-table tbody tr.is-selected {
    background: color-mix(in oklab, var(--color-primary) 9%, transparent);
}
.ins-check {
    width: 1.05rem;
    height: 1.05rem;
    border-radius: 0.35rem;
    accent-color: var(--color-primary);
    cursor: pointer;
}

.ins-menu {
    position: absolute;
    z-index: 1100;
    min-width: 14rem;
    max-height: 26rem;
    overflow-y: auto;
    padding: 0.4rem;
    border-radius: 1rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 30px 60px -24px rgba(2, 12, 40, 0.5);
    animation: ins-pop 0.16s ease;
}
@keyframes ins-pop {
    from {
        opacity: 0;
        transform: translateY(-6px) scale(0.97);
    }
}
.ins-menu button,
.ins-menu a {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    width: 100%;
    padding: 0.45rem 0.55rem;
    border-radius: 0.55rem;
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--color-gray-900);
    text-align: left;
    transition:
        background 0.14s ease,
        color 0.14s ease;
}
.ins-menu button:hover,
.ins-menu a:hover {
    background: color-mix(in oklab, var(--color-primary) 8%, transparent);
    color: var(--color-primary-text);
}
.ins-menu .danger {
    color: #e11d48;
}
.ins-menu .danger:hover {
    background: rgba(244, 63, 94, 0.1);
}
.ins-menu-sep {
    height: 1px;
    margin: 0.3rem 0.2rem;
    background: var(--color-border-color);
}
.ins-menu-lbl {
    padding: 0.4rem 0.55rem 0.15rem;
    font-size: 0.58rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--color-gray-400, #94a3b8);
}

.ins-drawer {
    position: fixed;
    inset: 0;
    z-index: 1200;
    visibility: hidden;
}
.ins-drawer.open {
    visibility: visible;
}
.ins-drawer-back {
    position: absolute;
    inset: 0;
    background: rgba(8, 12, 30, 0.5);
    opacity: 0;
    transition: opacity 0.3s ease;
}
.ins-drawer.open .ins-drawer-back {
    opacity: 1;
}
.ins-drawer-panel {
    position: absolute;
    top: 0;
    right: 0;
    height: 100%;
    width: min(490px, 94vw);
    background: var(--color-white);
    box-shadow: -30px 0 60px -30px rgba(2, 12, 40, 0.55);
    transform: translateX(100%);
    transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1);
    display: flex;
    flex-direction: column;
}
.ins-drawer.open .ins-drawer-panel {
    transform: translateX(0);
}
.ins-drawer-panel.left {
    right: auto;
    left: 0;
    transform: translateX(-100%);
    box-shadow: 30px 0 60px -30px rgba(2, 12, 40, 0.55);
}
.ins-drawer.open .ins-drawer-panel.left {
    transform: translateX(0);
}
.ins-drawer-hero {
    position: relative;
    padding: 1.5rem;
    color: #fff;
    background:
        radial-gradient(
            120% 130% at 100% 0%,
            rgba(16, 185, 129, 0.55),
            transparent 55%
        ),
        linear-gradient(135deg, #2563eb, #0f172a);
}

.ins-modal {
    position: fixed;
    inset: 0;
    z-index: 1300;
    display: none;
    align-items: center;
    justify-content: center;
    padding: 1rem;
}
.ins-modal.open {
    display: flex;
}
.ins-modal-back {
    position: absolute;
    inset: 0;
    background: rgba(8, 12, 30, 0.5);
    -webkit-backdrop-filter: blur(3px);
    backdrop-filter: blur(3px);
    animation: ins-fadein 0.2s ease;
}
@keyframes ins-fadein {
    from {
        opacity: 0;
    }
}
.ins-modal-panel {
    position: relative;
    width: 100%;
    max-width: 38rem;
    max-height: 90vh;
    overflow-y: auto;
    border-radius: 1.25rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 40px 80px -30px rgba(2, 12, 40, 0.6);
    animation: ins-modin 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes ins-modin {
    from {
        opacity: 0;
        transform: translateY(16px) scale(0.97);
    }
}
.ins-doc-ico {
    display: grid;
    place-items: center;
    width: 2.75rem;
    height: 2.75rem;
    border-radius: 0.8rem;
    color: var(--ins-c);
    font-size: 1.15rem;
    background: color-mix(in oklab, var(--ins-c) 14%, transparent);
}

.ins-bulk {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.55rem;
    padding: 0.7rem 0.9rem;
    border-radius: 1.25rem;
    background: color-mix(in oklab, var(--color-white) 85%, transparent);
    -webkit-backdrop-filter: blur(16px);
    backdrop-filter: blur(16px);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 12px 28px -18px rgba(15, 23, 42, 0.45);
    animation: ins-bulk-in 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes ins-bulk-in {
    from {
        opacity: 0;
        transform: translateY(-8px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}
.ins-bulk-btn {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.4rem 0.7rem;
    border-radius: 0.7rem;
    font-size: 0.76rem;
    font-weight: 700;
    color: var(--color-gray-700, #374151);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.15s ease;
    white-space: nowrap;
}
.dark .ins-bulk-btn {
    color: var(--color-gray-900);
}
.ins-bulk-btn:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.ins-bulk-btn.danger {
    color: #e11d48;
}
.ins-bulk-btn.danger:hover {
    border-color: #e11d48;
    background: rgba(244, 63, 94, 0.08);
}

.ins-pg {
    display: grid;
    place-items: center;
    min-width: 2.1rem;
    height: 2.1rem;
    padding: 0 0.5rem;
    border-radius: 0.6rem;
    font-size: 0.8rem;
    font-weight: 700;
    color: var(--color-gray-600, #475569);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.15s ease;
    cursor: pointer;
}
.ins-pg:hover:not(:disabled) {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.ins-pg.is-active {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    border-color: transparent;
}
.ins-pg:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

.ins-bar {
    height: 0.5rem;
    border-radius: 9999px;
    background: color-mix(in oklab, var(--ins-c) 14%, transparent);
    overflow: hidden;
}
.ins-bar > i {
    display: block;
    height: 100%;
    border-radius: 9999px;
    background: linear-gradient(
        90deg,
        var(--ins-c),
        color-mix(in oklab, var(--ins-c) 55%, #6366f1)
    );
}
.ins-recent {
    display: flex;
    align-items: center;
    gap: 0.7rem;
    padding: 0.6rem;
    border-radius: 0.8rem;
    transition: background 0.15s ease;
}
.ins-recent:hover {
    background: color-mix(in oklab, var(--color-primary) 6%, transparent);
}

/* insurance card visual */
.ins-policy {
    position: relative;
    overflow: hidden;
    border-radius: 1.1rem;
    padding: 1.1rem;
    color: #fff;
    box-shadow: 0 16px 34px -20px rgba(15, 23, 42, 0.6);
    background: linear-gradient(
        135deg,
        var(--ins-c),
        color-mix(in oklab, var(--ins-c) 45%, #0f172a)
    );
}
.ins-policy::after {
    content: "";
    position: absolute;
    right: -2rem;
    top: -2rem;
    width: 8rem;
    height: 8rem;
    border-radius: 9999px;
    background: rgba(255, 255, 255, 0.1);
}
.ins-policy .chip {
    width: 2rem;
    height: 1.4rem;
    border-radius: 0.25rem;
    background: linear-gradient(135deg, #fde68a, #f59e0b);
}

.ins-in {
    width: 100%;
    padding: 0.65rem 0.8rem;
    border-radius: 0.7rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.85rem;
    font-weight: 600;
    outline: none;
    transition:
        border-color 0.16s ease,
