}
.ins-c-sky {
    --ins-c: #0ea5e9;
}
.ins-c-rose {
    --ins-c: #f43f5e;
}
.ins-c-amber {
    --ins-c: #f59e0b;
}
.ins-c-emerald {
    --ins-c: #10b981;
}
.ins-c-violet {
    --ins-c: #8b5cf6;
}
.ins-c-teal {
