}

.ins-sk {
    position: relative;
    overflow: hidden;
    background: color-mix(in oklab, var(--color-gray-500) 12%, transparent);
    border-radius: 0.75rem;
}
.ins-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in oklab, var(--color-white) 55%, transparent),
        transparent
    );
    animation: ins-shimmer 1.4s infinite;
}
.dark .ins-sk::after {
    background: linear-gradient(
        90deg,
        transparent,
        rgba(255, 255, 255, 0.06),
        transparent
    );
}
@keyframes ins-shimmer {
    100% {
        transform: translateX(100%);
    }
}

/* Per-instance overrides (unlayered, placed after the base classes above so
               source-order tie-breaking lets them win — see CASCADE-SAFE OVERRIDE UTILITIES) */
.ins-sk-r125 {
    border-radius: 1.25rem;
}
.ins-sk-r150 {
    border-radius: 1.5rem;
}
.ins-hbadge-amber {
    background: rgba(245, 158, 11, 0.18);
    border-color: rgba(245, 158, 11, 0.4);
}
.ins-hbadge-emerald {
    background: rgba(16, 185, 129, 0.18);
    border-color: rgba(16, 185, 129, 0.4);
}
.ins-ring-lg {
    width: 4.5rem;
    height: 4.5rem;
}
.ins-tool-compact {
    padding: 0.35rem 0.6rem;
}
.ins-tool-compact-sm {
    padding: 0.35rem 0.5rem;
}
.ins-btn-sm {
    padding: 0.45rem 0.8rem;
}

.ins-toast {
    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    z-index: 2000;
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.8rem 1.1rem;
    border-radius: 0.9rem;
    font-size: 0.85rem;
    font-weight: 700;
    color: #fff;
    box-shadow: 0 20px 45px -18px rgba(0, 0, 0, 0.5);
    animation: ins-toastin 0.25s ease;
}
@keyframes ins-toastin {
    from {
        opacity: 0;
        transform: translateY(12px);
    }
}
.ins-toast.success {
    background: linear-gradient(135deg, #3b82f6, #2563eb);
}
.ins-toast.info {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
}
.ins-toast.error {
    background: linear-gradient(135deg, #f43f5e, #e11d48);
}

@media (prefers-reduced-motion: reduce) {
    .ins-btn,
    .ins-stat,
    .ins-card,
    .ins-ring .bar,
    .ins-dot,
    .ins-sk::after,
    .ins-icobtn,
    .ins-mini,
    .ins-drawer-panel,
    .ins-bulk {
        transition: none;
        animation: none;
    }
    .ins-btn:hover,
    .ins-stat:hover,
    .ins-card:hover,
    .ins-icobtn:hover,
    .ins-mini:hover {
        transform: none;
    }
}
@media print {
    .sidebar,
    header.navbar-header,
    .ins-print-hide {
        display: none !important;
    }
}

