    transition: background 0.15s ease;
}
.dc-table tbody tr:hover {
    background: color-mix(in oklab, var(--color-primary) 5%, transparent);
}
.dc-table tbody tr.is-selected {
    background: color-mix(in oklab, var(--color-primary) 9%, transparent);
}
.dc-check {
    width: 1.05rem;
    height: 1.05rem;
    border-radius: 0.35rem;
    accent-color: var(--color-primary);
    cursor: pointer;
}

.dc-menu {
    position: absolute;
    z-index: 1100;
    min-width: 14rem;
    max-height: 24rem;
    overflow-y: auto;
    padding: 0.4rem;
    border-radius: 1rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 30px 60px -24px rgba(2, 12, 40, 0.5);
    animation: dc-pop 0.16s ease;
}
@keyframes dc-pop {
    from {
        opacity: 0;
        transform: translateY(-6px) scale(0.97);
    }
}
.dc-menu button,
.dc-menu a {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    width: 100%;
    padding: 0.45rem 0.55rem;
    border-radius: 0.55rem;
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--color-gray-900);
    text-align: left;
    transition:
        background 0.14s ease,
        color 0.14s ease;
}
.dc-menu button:hover,
.dc-menu a:hover {
    background: color-mix(in oklab, var(--color-primary) 8%, transparent);
    color: var(--color-primary-text);
}
.dc-menu .danger {
    color: #e11d48;
}
.dc-menu .danger:hover {
    background: rgba(244, 63, 94, 0.1);
}
.dc-menu-sep {
    height: 1px;
    margin: 0.3rem 0.2rem;
    background: var(--color-border-color);
}
.dc-menu-lbl {
    padding: 0.4rem 0.55rem 0.15rem;
    font-size: 0.58rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--color-gray-400, #94a3b8);
}

.dc-drawer {
    position: fixed;
    inset: 0;
    z-index: 1200;
    visibility: hidden;
}
.dc-drawer.open {
    visibility: visible;
}
.dc-drawer-back {
    position: absolute;
    inset: 0;
    background: rgba(8, 12, 30, 0.5);
    opacity: 0;
    transition: opacity 0.3s ease;
}
.dc-drawer.open .dc-drawer-back {
    opacity: 1;
}
.dc-drawer-panel {
    position: absolute;
    top: 0;
    right: 0;
    height: 100%;
    width: min(470px, 94vw);
    background: var(--color-white);
    box-shadow: -30px 0 60px -30px rgba(2, 12, 40, 0.55);
    transform: translateX(100%);
    transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1);
    display: flex;
    flex-direction: column;
}
.dc-drawer.open .dc-drawer-panel {
    transform: translateX(0);
}
.dc-drawer-panel.left {
    right: auto;
    left: 0;
    transform: translateX(-100%);
    box-shadow: 30px 0 60px -30px rgba(2, 12, 40, 0.55);
}
.dc-drawer.open .dc-drawer-panel.left {
    transform: translateX(0);
}
.dc-drawer-hero {
    position: relative;
    padding: 1.5rem;
    color: #fff;
    background:
        radial-gradient(
            120% 130% at 100% 0%,
            rgba(16, 185, 129, 0.6),
            transparent 55%
        ),
        linear-gradient(135deg, #4f46e5, #0f172a);
}

.dc-modal {
    position: fixed;
    inset: 0;
    z-index: 1300;
    display: none;
    align-items: center;
    justify-content: center;
    padding: 1rem;
}
.dc-modal.open {
    display: flex;
}
.dc-modal-back {
    position: absolute;
    inset: 0;
    background: rgba(8, 12, 30, 0.5);
    -webkit-backdrop-filter: blur(3px);
    backdrop-filter: blur(3px);
    animation: dc-fadein 0.2s ease;
}
@keyframes dc-fadein {
    from {
        opacity: 0;
    }
}
.dc-modal-panel {
    position: relative;
    width: 100%;
    max-width: 36rem;
    max-height: 90vh;
    overflow-y: auto;
    border-radius: 1.25rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 40px 80px -30px rgba(2, 12, 40, 0.6);
    animation: dc-modin 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes dc-modin {
    from {
        opacity: 0;
        transform: translateY(16px) scale(0.97);
    }
}
.dc-doc-ico {
    display: grid;
    place-items: center;
    width: 2.75rem;
    height: 2.75rem;
    border-radius: 0.8rem;
    color: var(--dc-c);
    font-size: 1.15rem;
    background: color-mix(in oklab, var(--dc-c) 14%, transparent);
}

.dc-bulk {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.55rem;
    padding: 0.7rem 0.9rem;
    border-radius: 1.25rem;
    background: color-mix(in oklab, var(--color-white) 85%, transparent);
    -webkit-backdrop-filter: blur(16px);
    backdrop-filter: blur(16px);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 12px 28px -18px rgba(15, 23, 42, 0.45);
    animation: dc-bulk-in 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes dc-bulk-in {
    from {
        opacity: 0;
        transform: translateY(-8px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}
.dc-bulk-btn {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.4rem 0.7rem;
    border-radius: 0.7rem;
    font-size: 0.76rem;
    font-weight: 700;
    color: var(--color-gray-700, #374151);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.15s ease;
    white-space: nowrap;
}
.dark .dc-bulk-btn {
    color: var(--color-gray-900);
}
.dc-bulk-btn:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.dc-bulk-btn.danger {
    color: #e11d48;
}
.dc-bulk-btn.danger:hover {
    border-color: #e11d48;
    background: rgba(244, 63, 94, 0.08);
}

.dc-pg {
    display: grid;
    place-items: center;
    min-width: 2.1rem;
    height: 2.1rem;
    padding: 0 0.5rem;
    border-radius: 0.6rem;
    font-size: 0.8rem;
    font-weight: 700;
    color: var(--color-gray-600, #475569);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.15s ease;
    cursor: pointer;
}
.dc-pg:hover:not(:disabled) {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.dc-pg.is-active {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    border-color: transparent;
}
.dc-pg:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

.dc-wf {
    display: flex;
    align-items: center;
    gap: 0.25rem;
    overflow-x: auto;
    scrollbar-width: none;
}
.dc-wf::-webkit-scrollbar {
    display: none;
}
.dc-wf-step {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.4rem;
    min-width: 5.5rem;
    text-align: center;
}
.dc-wf-node {
    display: grid;
    place-items: center;
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 9999px;
    font-size: 0.85rem;
    color: var(--color-gray-500);
    background: color-mix(in oklab, var(--color-gray-500) 14%, transparent);
}
.dc-wf-step.done .dc-wf-node {
    background: linear-gradient(135deg, #10b981, #059669);
    color: #fff;
}
.dc-wf-step.active .dc-wf-node {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    box-shadow: 0 10px 20px -8px var(--color-primary);
}
.dc-wf-line {
    flex: 1 1 1rem;
    min-width: 1rem;
    height: 2px;
    border-radius: 2px;
    background: var(--color-border-color);
}
.dc-wf-line.done {
    background: linear-gradient(90deg, #10b981, #059669);
}

.dc-tl {
    position: relative;
    padding-left: 1.75rem;
}
.dc-tl::before {
    content: "";
    position: absolute;
    left: 0.72rem;
    top: 0.35rem;
    bottom: 0.35rem;
    width: 2px;
    background: linear-gradient(
        180deg,
        var(--dc-c, var(--color-primary)),
        color-mix(in oklab, var(--dc-c, var(--color-primary)) 20%, transparent)
    );
}
.dc-tl-item {
    position: relative;
    padding-bottom: 1.1rem;
}
.dc-tl-item:last-child {
    padding-bottom: 0;
}
.dc-tl-node {
    position: absolute;
    left: -1.75rem;
    top: 0.05rem;
    display: grid;
    place-items: center;
    width: 1.5rem;
    height: 1.5rem;
    border-radius: 9999px;
    color: #fff;
    font-size: 0.62rem;
    background: linear-gradient(
        135deg,
        var(--dc-c, var(--color-primary)),
        color-mix(in oklab, var(--dc-c, var(--color-primary)) 55%, #6366f1)
    );
    box-shadow: 0 0 0 3px
        color-mix(in oklab, var(--dc-c, var(--color-primary)) 16%, transparent);
}

.dc-clear {
    display: flex;
    align-items: center;
    gap: 0.7rem;
    padding: 0.65rem;
    border-radius: 0.8rem;
    border: 1px solid var(--color-border-color);
    cursor: pointer;
    transition:
        border-color 0.15s ease,
        background 0.15s ease;
}
.dc-clear:hover {
    border-color: var(--color-primary);
}
.dc-clear-ico {
    display: grid;
    place-items: center;
    width: 2.1rem;
    height: 2.1rem;
    border-radius: 0.6rem;
    font-size: 0.9rem;
    color: var(--dc-c);
    background: color-mix(in oklab, var(--dc-c) 14%, transparent);
    flex-shrink: 0;
}
.dc-clear.done {
    background: color-mix(in oklab, #10b981 7%, transparent);
    border-color: color-mix(in oklab, #10b981 40%, var(--color-border-color));
}
.dc-clear-badge {
    margin-left: auto;
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    font-size: 0.62rem;
    font-weight: 800;
    text-transform: uppercase;
    padding: 0.15rem 0.5rem;
    border-radius: 9999px;
}
.dc-clear.done .dc-clear-badge {
    color: #059669;
    background: rgba(16, 185, 129, 0.16);
}
.dc-clear:not(.done) .dc-clear-badge {
    color: #d97706;
    background: rgba(245, 158, 11, 0.16);
}

.dc-bar {
    height: 0.5rem;
    border-radius: 9999px;
    background: color-mix(in oklab, var(--dc-c) 14%, transparent);
    overflow: hidden;
}
.dc-bar > i {
    display: block;
    height: 100%;
    border-radius: 9999px;
    background: linear-gradient(
        90deg,
        var(--dc-c),
        color-mix(in oklab, var(--dc-c) 55%, #6366f1)
    );
}

.dc-in {
    width: 100%;
    padding: 0.65rem 0.8rem;
    border-radius: 0.7rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.85rem;
    font-weight: 600;
    outline: none;
    transition:
        border-color 0.16s ease,
        box-shadow 0.16s ease;
}
.dc-in:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 4px
        color-mix(in oklab, var(--color-primary) 14%, transparent);
}
.dc-lbl {
    display: block;
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--color-gray-500);
    margin-bottom: 0.3rem;
}
.dc-recent {
    display: flex;
    align-items: center;
    gap: 0.7rem;
    padding: 0.6rem;
    border-radius: 0.8rem;
    transition: background 0.15s ease;
}
.dc-recent:hover {
    background: color-mix(in oklab, var(--color-primary) 6%, transparent);
}

.dc-c-indigo {
    --dc-c: #6366f1;
}
.dc-c-sky {
    --dc-c: #0ea5e9;
}
.dc-c-rose {
    --dc-c: #f43f5e;
}
.dc-c-amber {
    --dc-c: #f59e0b;
}
.dc-c-emerald {
    --dc-c: #10b981;
}
.dc-c-violet {
    --dc-c: #8b5cf6;
}
.dc-c-teal {
    --dc-c: #14b8a6;
}
.dc-c-primary {
    --dc-c: var(--color-primary);
}

.dc-sk {
    position: relative;
    overflow: hidden;
    background: color-mix(in oklab, var(--color-gray-500) 12%, transparent);
    border-radius: 0.75rem;
}
.dc-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in oklab, var(--color-white) 55%, transparent),
        transparent
    );
    animation: dc-shimmer 1.4s infinite;
}
.dark .dc-sk::after {
    background: linear-gradient(
        90deg,
        transparent,
        rgba(255, 255, 255, 0.06),
        transparent
    );
}
@keyframes dc-shimmer {
    100% {
        transform: translateX(100%);
    }
}

/* Per-instance overrides (unlayered, placed after the base classes above so
               source-order tie-breaking lets them win — see CASCADE-SAFE OVERRIDE UTILITIES) */
.dc-sk-r125 {
    border-radius: 1.25rem;
}
.dc-sk-r150 {
    border-radius: 1.5rem;
}
.dc-hbadge-amber {
    background: rgba(245, 158, 11, 0.18);
    border-color: rgba(245, 158, 11, 0.4);
}
.dc-hbadge-emerald {
    background: rgba(16, 185, 129, 0.18);
    border-color: rgba(16, 185, 129, 0.4);
}
.dc-tool-compact {
    padding: 0.35rem 0.6rem;
}
.dc-tool-compact-sm {
    padding: 0.35rem 0.5rem;
}

.dc-toast {
    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    z-index: 2000;
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.8rem 1.1rem;
    border-radius: 0.9rem;
    font-size: 0.85rem;
    font-weight: 700;
    color: #fff;
    box-shadow: 0 20px 45px -18px rgba(0, 0, 0, 0.5);
    animation: dc-toastin 0.25s ease;
}
@keyframes dc-toastin {
    from {
        opacity: 0;
        transform: translateY(12px);
    }
}
.dc-toast.success {
    background: linear-gradient(135deg, #10b981, #059669);
}
.dc-toast.info {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
}
.dc-toast.error {
    background: linear-gradient(135deg, #f43f5e, #e11d48);
}

@media (prefers-reduced-motion: reduce) {
    .dc-btn,
    .dc-stat,
    .dc-card,
    .dc-ring .bar,
    .dc-dot,
    .dc-sk::after,
    .dc-icobtn,
    .dc-mini,
    .dc-drawer-panel,
    .dc-bulk {
        transition: none;
        animation: none;
    }
    .dc-btn:hover,
    .dc-stat:hover,
    .dc-card:hover,
    .dc-icobtn:hover,
    .dc-mini:hover {
        transform: none;
    }
}
@media print {
    .sidebar,
    header.navbar-header,
    .dc-print-hide {
        display: none !important;
    }
}

/* =====================================================================
   PATIENT MEDICAL HISTORY  ·  patient-medical-history.html (page-exclusive)
   ===================================================================== */
/* ================================================================
               PATIENT MEDICAL HISTORY CENTER (EMR) — self-contained (inline).
               Design-system CSS variables → automatic light / dark.
               ================================================================ */
#mh-page {
    --mh-c: var(--color-primary);
}
.mh-surface {
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    border-radius: 1.25rem;
    box-shadow: 0 20px 45px -35px rgba(15, 23, 42, 0.4);
}

.mh-layout {
    display: grid;
    grid-template-columns: 1fr;
    gap: 1.25rem;
    align-items: start;
}
@media (min-width: 1280px) {
    .mh-layout {
        grid-template-columns: minmax(0, 1fr) 340px;
    }
}
.mh-grid {
    display: grid;
    gap: 0.9rem;
}
.mh-g3 {
    grid-template-columns: repeat(1, minmax(0, 1fr));
}
.mh-g6 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
}
@media (min-width: 640px) {
    .mh-g3 {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}
@media (min-width: 900px) {
    .mh-g3 {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
    .mh-g6 {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}
@media (min-width: 1200px) {
    .mh-g6 {
        grid-template-columns: repeat(6, minmax(0, 1fr));
    }
}

.mh-hero {
    position: relative;
    overflow: hidden;
    border-radius: 1.5rem;
    padding: 1.75rem;
    color: #fff;
    background:
        radial-gradient(
            120% 140% at 0% 0%,
            rgba(99, 102, 241, 0.5),
            transparent 55%
        ),
        radial-gradient(
            120% 160% at 100% 0%,
            rgba(236, 72, 153, 0.5),
            transparent 50%
        ),
        linear-gradient(135deg, #0f172a, #221b4b 55%, #0b1220);
    box-shadow: 0 30px 60px -30px rgba(15, 23, 42, 0.7);
}
.mh-hero::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image: radial-gradient(
        rgba(255, 255, 255, 0.08) 1px,
        transparent 1px
    );
    background-size: 22px 22px;
    -webkit-mask-image: linear-gradient(180deg, #000, transparent 75%);
    mask-image: linear-gradient(180deg, #000, transparent 75%);
}
.mh-hero > * {
    position: relative;
    z-index: 1;
}
@media (min-width: 1024px) {
    .mh-hero {
        padding: 2rem 2.25rem;
    }
}
.mh-hbadge {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.25rem 0.7rem;
    border-radius: 9999px;
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    background: rgba(255, 255, 255, 0.14);
    border: 1px solid rgba(255, 255, 255, 0.22);
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
}
.mh-hmeta {
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
    padding: 0.45rem 0.8rem;
    border-radius: 0.8rem;
    background: rgba(255, 255, 255, 0.1);
    border: 1px solid rgba(255, 255, 255, 0.16);
    font-size: 0.72rem;
    font-weight: 700;
}
.mh-dot {
    width: 0.5rem;
    height: 0.5rem;
    border-radius: 9999px;
    background: #a78bfa;
    box-shadow: 0 0 0 4px rgba(167, 139, 250, 0.25);
    animation: mh-pulse 2s ease-in-out infinite;
}
@keyframes mh-pulse {
    0%,
    100% {
        opacity: 1;
    }
    50% {
        opacity: 0.4;
    }
}
.mh-hava {
    width: 3.5rem;
    height: 3.5rem;
    border-radius: 1rem;
    display: grid;
    place-items: center;
    font-weight: 800;
    font-size: 1.1rem;
    color: #fff;
    background: rgba(255, 255, 255, 0.16);
    border: 1px solid rgba(255, 255, 255, 0.28);
}

.mh-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    padding: 0.55rem 0.9rem;
    border-radius: 0.8rem;
    font-size: 0.8rem;
    font-weight: 700;
    cursor: pointer;
    border: 1px solid transparent;
    white-space: nowrap;
    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease,
        background 0.2s ease,
        color 0.2s ease,
        border-color 0.2s ease;
}
.mh-btn:hover {
    transform: translateY(-2px);
}
.mh-btn-primary {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    box-shadow: 0 12px 24px -12px var(--color-primary);
}
.mh-btn-success {
    background: linear-gradient(135deg, #8b5cf6, #6d28d9);
    color: #fff;
    box-shadow: 0 12px 24px -12px #8b5cf6;
}
.mh-btn-glass {
    background: rgba(255, 255, 255, 0.12);
    color: #fff;
    border-color: rgba(255, 255, 255, 0.24);
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
}
.mh-btn-glass:hover {
    background: rgba(255, 255, 255, 0.2);
}
.mh-btn-solid {
    background: var(--color-white);
    color: var(--color-gray-900);
    border-color: var(--color-border-color);
}
.mh-btn-solid:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.mh-btn-danger {
    background: #e11d48;
    color: #fff;
}
.mh-icobtn {
    display: grid;
    place-items: center;
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 0.75rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-500);
    cursor: pointer;
    transition: all 0.16s ease;
    flex-shrink: 0;
}
.mh-icobtn:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
    transform: translateY(-1px);
}

.mh-stat {
    position: relative;
    overflow: hidden;
    border-radius: 1.25rem;
    padding: 1.1rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 18px 40px -30px rgba(15, 23, 42, 0.45);
    transition:
        transform 0.25s ease,
        box-shadow 0.25s ease,
        border-color 0.25s ease;
}
.mh-stat::after {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(
        135deg,
        color-mix(in oklab, var(--mh-c) 12%, transparent),
        transparent 60%
    );
    pointer-events: none;
}
.mh-stat:hover {
    transform: translateY(-4px);
    box-shadow: 0 26px 50px -26px
        color-mix(in oklab, var(--mh-c) 55%, rgba(15, 23, 42, 0.5));
    border-color: color-mix(
        in oklab,
        var(--mh-c) 40%,
        var(--color-border-color)
    );
}
.mh-stat > * {
    position: relative;
    z-index: 1;
}
.mh-stat-ico {
    display: grid;
    place-items: center;
    width: 2.9rem;
    height: 2.9rem;
    border-radius: 0.9rem;
    color: #fff;
    font-size: 1.15rem;
    background: linear-gradient(
        135deg,
        var(--mh-c),
        color-mix(in oklab, var(--mh-c) 55%, #6366f1)
    );
    box-shadow: 0 10px 20px -10px var(--mh-c);
}
.mh-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.15rem 0.5rem;
    border-radius: 9999px;
    font-size: 0.62rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    color: color-mix(in oklab, var(--mh-c) 70%, #1e293b);
    background: color-mix(in oklab, var(--mh-c) 16%, transparent);
}
.dark .mh-chip {
    color: color-mix(in oklab, var(--mh-c) 55%, #fff);
}
.mh-ring {
    --p: 0;
    width: 3rem;
    height: 3rem;
    transform: rotate(-90deg);
}
.mh-ring circle {
    fill: none;
    stroke-width: 4;
}
.mh-ring .trk {
    stroke: color-mix(in oklab, var(--mh-c) 16%, transparent);
}
.mh-ring .bar {
    stroke: var(--mh-c);
    stroke-linecap: round;
    stroke-dasharray: 100 100;
    stroke-dashoffset: calc(100 - var(--p));
    transition: stroke-dashoffset 0.9s cubic-bezier(0.16, 1, 0.3, 1);
}

.mh-head {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 1rem 1.15rem;
    border-bottom: 1px solid var(--color-border-color);
}
.mh-head .ico {
    display: grid;
    place-items: center;
    width: 2.3rem;
    height: 2.3rem;
    border-radius: 0.75rem;
    color: #fff;
    font-size: 0.95rem;
    background: linear-gradient(
        135deg,
        color-mix(in oklab, var(--mh-c) 90%, #000),
        color-mix(in oklab, var(--mh-c) 55%, #6366f1)
    );
    box-shadow: 0 10px 18px -12px var(--mh-c);
    flex-shrink: 0;
}
.mh-title {
    font-weight: 800;
    color: var(--color-gray-900);
    font-size: 0.9rem;
}

.mh-search {
    position: relative;
    flex: 1 1 220px;
    min-width: 180px;
}
.mh-search input {
    width: 100%;
    padding: 0.6rem 0.9rem 0.6rem 2.5rem;
    border-radius: 0.85rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.85rem;
    font-weight: 600;
    outline: none;
    transition:
        border-color 0.18s ease,
        box-shadow 0.18s ease;
}
.mh-search input:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 4px
        color-mix(in oklab, var(--color-primary) 14%, transparent);
}
.mh-search .ico {
    position: absolute;
    left: 0.85rem;
    top: 50%;
    transform: translateY(-50%);
    color: var(--color-gray-400, #94a3b8);
    pointer-events: none;
}
.mh-tool {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.55rem 0.8rem;
    border-radius: 0.8rem;
    font-size: 0.8rem;
    font-weight: 700;
    cursor: pointer;
    white-space: nowrap;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-600, #475569);
    transition:
        border-color 0.18s ease,
        color 0.18s ease,
        transform 0.18s ease;
}
.mh-tool:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
    transform: translateY(-1px);
}
.mh-seg {
    display: inline-flex;
    padding: 0.25rem;
    border-radius: 0.85rem;
    background: color-mix(in oklab, var(--color-gray-500) 14%, transparent);
}
.mh-seg button {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.4rem 0.7rem;
    border-radius: 0.65rem;
    font-size: 0.78rem;
    font-weight: 700;
    color: var(--color-gray-500);
    transition: all 0.18s ease;
}
.mh-seg button.is-active {
    background: var(--color-white);
    color: var(--color-primary-text);
    box-shadow: 0 4px 10px -6px rgba(15, 23, 42, 0.4);
}

.mh-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.15rem 0.55rem;
    border-radius: 9999px;
    font-size: 0.64rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    white-space: nowrap;
}
.mh-badge.active {
    color: var(--color-primary-text);
    background: color-mix(in oklab, var(--color-primary) 15%, transparent);
}
.mh-badge.resolved {
    color: #059669;
    background: rgba(16, 185, 129, 0.15);
}
.mh-badge.ongoing {
    color: #d97706;
    background: rgba(245, 158, 11, 0.15);
}
.mh-badge.chronic {
    color: #e11d48;
    background: rgba(244, 63, 94, 0.15);
}
.mh-tag {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.1rem 0.45rem;
    border-radius: 0.5rem;
    font-size: 0.62rem;
    font-weight: 700;
    background: color-mix(in oklab, var(--mh-c) 14%, transparent);
    color: var(--mh-c);
}
.mh-mini {
    display: grid;
    place-items: center;
    width: 2rem;
    height: 2rem;
    border-radius: 0.6rem;
    color: var(--color-gray-500);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.16s ease;
}
.mh-mini:hover {
    border-color: var(--mh-c);
    color: var(--mh-c);
    transform: translateY(-1px);
}
.mh-kv {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    font-size: 0.72rem;
    color: var(--color-gray-500);
    min-width: 0;
}
.mh-kv b {
    color: var(--color-gray-900);
    font-weight: 700;
}
.mh-att {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.15rem 0.5rem;
    border-radius: 0.5rem;
    font-size: 0.64rem;
    font-weight: 700;
    border: 1px solid var(--color-border-color);
    color: var(--color-gray-600, #475569);
    background: var(--color-white);
}

.mh-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0;
}
.mh-table thead th {
    text-align: left;
    font-size: 0.66rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--color-gray-400, #94a3b8);
    padding: 0.75rem 1rem;
    border-bottom: 1px solid var(--color-border-color);
    white-space: nowrap;
    background: color-mix(in oklab, var(--color-gray-500) 5%, transparent);
}
.mh-table tbody td {
    padding: 0.7rem 1rem;
    border-bottom: 1px solid var(--color-border-color);
    font-size: 0.82rem;
    color: var(--color-gray-900);
    vertical-align: middle;
    white-space: nowrap;
}
.mh-table tbody tr {
    transition: background 0.15s ease;
}
.mh-table tbody tr:hover {
    background: color-mix(in oklab, var(--color-primary) 5%, transparent);
}
.mh-table tbody tr.is-selected {
    background: color-mix(in oklab, var(--color-primary) 9%, transparent);
}
.mh-check {
    width: 1.05rem;
    height: 1.05rem;
    border-radius: 0.35rem;
    accent-color: var(--color-primary);
    cursor: pointer;
}

.mh-menu {
    position: absolute;
    z-index: 1100;
    min-width: 15rem;
    max-height: 26rem;
    overflow-y: auto;
    padding: 0.4rem;
    border-radius: 1rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 30px 60px -24px rgba(2, 12, 40, 0.5);
    animation: mh-pop 0.16s ease;
}
@keyframes mh-pop {
    from {
        opacity: 0;
        transform: translateY(-6px) scale(0.97);
    }
}
.mh-menu button,
.mh-menu a {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    width: 100%;
    padding: 0.45rem 0.55rem;
    border-radius: 0.55rem;
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--color-gray-900);
    text-align: left;
    transition:
        background 0.14s ease,
        color 0.14s ease;
}
.mh-menu button:hover,
.mh-menu a:hover {
    background: color-mix(in oklab, var(--color-primary) 8%, transparent);
    color: var(--color-primary-text);
}
.mh-menu .danger {
    color: #e11d48;
}
.mh-menu .danger:hover {
    background: rgba(244, 63, 94, 0.1);
}
.mh-menu-sep {
    height: 1px;
    margin: 0.3rem 0.2rem;
    background: var(--color-border-color);
}
.mh-menu-lbl {
    padding: 0.4rem 0.55rem 0.15rem;
    font-size: 0.58rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--color-gray-400, #94a3b8);
}

.mh-drawer {
    position: fixed;
    inset: 0;
    z-index: 1200;
    visibility: hidden;
}
.mh-drawer.open {
    visibility: visible;
}
.mh-drawer-back {
    position: absolute;
    inset: 0;
    background: rgba(8, 12, 30, 0.5);
    opacity: 0;
    transition: opacity 0.3s ease;
}
.mh-drawer.open .mh-drawer-back {
    opacity: 1;
}
.mh-drawer-panel {
    position: absolute;
    top: 0;
    right: 0;
    height: 100%;
    width: min(500px, 94vw);
    background: var(--color-white);
    box-shadow: -30px 0 60px -30px rgba(2, 12, 40, 0.55);
    transform: translateX(100%);
    transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1);
    display: flex;
    flex-direction: column;
}
.mh-drawer.open .mh-drawer-panel {
    transform: translateX(0);
}
.mh-drawer-panel.left {
    right: auto;
    left: 0;
    transform: translateX(-100%);
    box-shadow: 30px 0 60px -30px rgba(2, 12, 40, 0.55);
}
.mh-drawer.open .mh-drawer-panel.left {
    transform: translateX(0);
}
.mh-drawer-hero {
    position: relative;
    padding: 1.5rem;
    color: #fff;
    background:
        radial-gradient(
            120% 130% at 100% 0%,
            rgba(236, 72, 153, 0.55),
            transparent 55%
        ),
        linear-gradient(135deg, #6d28d9, #0f172a);
}

.mh-modal {
    position: fixed;
    inset: 0;
    z-index: 1300;
    display: none;
    align-items: center;
    justify-content: center;
    padding: 1rem;
}
.mh-modal.open {
    display: flex;
}
.mh-modal-back {
    position: absolute;
    inset: 0;
    background: rgba(8, 12, 30, 0.5);
    -webkit-backdrop-filter: blur(3px);
    backdrop-filter: blur(3px);
    animation: mh-fadein 0.2s ease;
}
@keyframes mh-fadein {
    from {
        opacity: 0;
    }
}
.mh-modal-panel {
    position: relative;
    width: 100%;
    max-width: 36rem;
    max-height: 90vh;
    overflow-y: auto;
    border-radius: 1.25rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 40px 80px -30px rgba(2, 12, 40, 0.6);
    animation: mh-modin 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes mh-modin {
    from {
        opacity: 0;
        transform: translateY(16px) scale(0.97);
    }
}
.mh-doc-ico {
    display: grid;
    place-items: center;
    width: 2.75rem;
    height: 2.75rem;
    border-radius: 0.8rem;
    color: var(--mh-c);
    font-size: 1.15rem;
    background: color-mix(in oklab, var(--mh-c) 14%, transparent);
}

.mh-bulk {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.55rem;
    padding: 0.7rem 0.9rem;
    border-radius: 1.25rem;
    background: color-mix(in oklab, var(--color-white) 85%, transparent);
    -webkit-backdrop-filter: blur(16px);
    backdrop-filter: blur(16px);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 12px 28px -18px rgba(15, 23, 42, 0.45);
    animation: mh-bulk-in 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes mh-bulk-in {
    from {
        opacity: 0;
        transform: translateY(-8px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}
.mh-bulk-btn {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.4rem 0.7rem;
    border-radius: 0.7rem;
    font-size: 0.76rem;
    font-weight: 700;
    color: var(--color-gray-700, #374151);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.15s ease;
    white-space: nowrap;
}
.dark .mh-bulk-btn {
    color: var(--color-gray-900);
}
.mh-bulk-btn:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.mh-bulk-btn.danger {
    color: #e11d48;
}
.mh-bulk-btn.danger:hover {
    border-color: #e11d48;
    background: rgba(244, 63, 94, 0.08);
}

.mh-pg {
    display: grid;
    place-items: center;
    min-width: 2.1rem;
    height: 2.1rem;
    padding: 0 0.5rem;
    border-radius: 0.6rem;
    font-size: 0.8rem;
    font-weight: 700;
    color: var(--color-gray-600, #475569);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.15s ease;
    cursor: pointer;
}
.mh-pg:hover:not(:disabled) {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.mh-pg.is-active {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    border-color: transparent;
}
.mh-pg:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

/* rich vertical timeline */
.mh-tl {
    position: relative;
    padding-left: 2.5rem;
}
.mh-tl::before {
    content: "";
    position: absolute;
    left: 1.05rem;
    top: 0.5rem;
    bottom: 0.5rem;
    width: 2px;
    background: linear-gradient(
        180deg,
        var(--color-primary),
        color-mix(in oklab, var(--color-primary) 20%, transparent)
    );
}
.mh-tl-item {
    position: relative;
    padding-bottom: 1.1rem;
}
.mh-tl-item:last-child {
    padding-bottom: 0;
}
.mh-tl-node {
    position: absolute;
    left: -2.5rem;
    top: 0.15rem;
    display: grid;
    place-items: center;
    width: 2.1rem;
    height: 2.1rem;
    border-radius: 9999px;
    color: #fff;
    font-size: 0.8rem;
    background: linear-gradient(
        135deg,
        var(--mh-c, var(--color-primary)),
        color-mix(in oklab, var(--mh-c, var(--color-primary)) 55%, #6366f1)
    );
    box-shadow: 0 0 0 4px
        color-mix(in oklab, var(--mh-c, var(--color-primary)) 14%, transparent);
}
.mh-tl-card {
    border-radius: 1rem;
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    padding: 0.9rem 1rem;
    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease,
        border-color 0.2s ease;
    cursor: pointer;
}
.mh-tl-card:hover {
    transform: translateX(3px);
    box-shadow: 0 14px 30px -20px
        color-mix(in oklab, var(--mh-c) 55%, rgba(15, 23, 42, 0.5));
    border-color: color-mix(
        in oklab,
        var(--mh-c) 35%,
        var(--color-border-color)
    );
}
.mh-tl-card.is-selected {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 2px
        color-mix(in oklab, var(--color-primary) 35%, transparent);
}

/* mini journey strip */
.mh-journey {
    display: flex;
    align-items: center;
    gap: 0.25rem;
    overflow-x: auto;
    scrollbar-width: none;
}
.mh-journey::-webkit-scrollbar {
    display: none;
}
.mh-jstep {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.4rem;
    min-width: 5rem;
    text-align: center;
}
.mh-jnode {
    display: grid;
    place-items: center;
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 9999px;
    font-size: 0.85rem;
    color: var(--color-gray-500);
    background: color-mix(in oklab, var(--color-gray-500) 14%, transparent);
}
.mh-jstep.done .mh-jnode {
    background: linear-gradient(135deg, #8b5cf6, #6d28d9);
    color: #fff;
}
.mh-jstep.active .mh-jnode {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    box-shadow: 0 10px 20px -8px var(--color-primary);
}
.mh-jline {
    flex: 1 1 0.75rem;
    min-width: 0.75rem;
    height: 2px;
    border-radius: 2px;
    background: var(--color-border-color);
}
.mh-jline.done {
    background: linear-gradient(90deg, #8b5cf6, #6d28d9);
}

.mh-bar {
    height: 0.5rem;
    border-radius: 9999px;
    background: color-mix(in oklab, var(--mh-c) 14%, transparent);
    overflow: hidden;
}
.mh-bar > i {
    display: block;
    height: 100%;
    border-radius: 9999px;
    background: linear-gradient(
        90deg,
        var(--mh-c),
        color-mix(in oklab, var(--mh-c) 55%, #6366f1)
    );
}

.mh-sec {
    position: relative;
    overflow: hidden;
    border-radius: 1rem;
    padding: 0.9rem;
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition:
        transform 0.2s ease,
        border-color 0.2s ease;
}
.mh-sec:hover {
    transform: translateY(-3px);
    border-color: color-mix(
        in oklab,
        var(--mh-c) 35%,
        var(--color-border-color)
    );
}
.mh-sec-ico {
    display: grid;
    place-items: center;
    width: 2.3rem;
    height: 2.3rem;
    border-radius: 0.7rem;
    font-size: 1rem;
    color: var(--mh-c);
    background: color-mix(in oklab, var(--mh-c) 14%, transparent);
}
.mh-report {
    display: flex;
    align-items: center;
    gap: 0.7rem;
    padding: 0.65rem;
    border-radius: 0.8rem;
    border: 1px solid var(--color-border-color);
    transition:
        border-color 0.15s ease,
        transform 0.15s ease;
}
.mh-report:hover {
    border-color: color-mix(
        in oklab,
        var(--mh-c) 35%,
        var(--color-border-color)
    );
    transform: translateY(-1px);
}
.mh-rx {
    border-radius: 1rem;
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    padding: 0.9rem;
    border-left: 3px solid var(--mh-c);
}

.mh-in {
    width: 100%;
    padding: 0.65rem 0.8rem;
    border-radius: 0.7rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.85rem;
    font-weight: 600;
    outline: none;
    transition:
        border-color 0.16s ease,
        box-shadow 0.16s ease;
}
.mh-in:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 4px
        color-mix(in oklab, var(--color-primary) 14%, transparent);
}
.mh-lbl {
    display: block;
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--color-gray-500);
    margin-bottom: 0.3rem;
}
.mh-recent {
    display: flex;
    align-items: center;
    gap: 0.7rem;
    padding: 0.6rem;
    border-radius: 0.8rem;
    transition: background 0.15s ease;
}
.mh-recent:hover {
    background: color-mix(in oklab, var(--color-primary) 6%, transparent);
}

.mh-acc-head {
    display: flex;
    align-items: center;
    gap: 0.7rem;
    width: 100%;
    padding: 0.9rem 1rem;
    cursor: pointer;
    text-align: left;
}
.mh-acc-body {
    padding: 0 1rem 1rem;
}
.mh-acc.active .mh-acc-chev {
    transform: rotate(90deg);
}
.mh-acc-chev {
    transition: transform 0.2s ease;
}

.mh-c-indigo {
    --mh-c: #6366f1;
}
.mh-c-sky {
    --mh-c: #0ea5e9;
}
.mh-c-rose {
    --mh-c: #f43f5e;
}
.mh-c-amber {
    --mh-c: #f59e0b;
}
.mh-c-emerald {
    --mh-c: #10b981;
}
.mh-c-violet {
    --mh-c: #8b5cf6;
}
.mh-c-teal {
    --mh-c: #14b8a6;
}
.mh-c-primary {
    --mh-c: var(--color-primary);
}
.mh-c-pink {
    --mh-c: #ec4899;
}

.mh-sk {
    position: relative;
    overflow: hidden;
    background: color-mix(in oklab, var(--color-gray-500) 12%, transparent);
    border-radius: 0.75rem;
}
.mh-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in oklab, var(--color-white) 55%, transparent),
        transparent
    );
    animation: mh-shimmer 1.4s infinite;
}
.dark .mh-sk::after {
    background: linear-gradient(
        90deg,
        transparent,
        rgba(255, 255, 255, 0.06),
        transparent
    );
}
@keyframes mh-shimmer {
    100% {
        transform: translateX(100%);
    }
}

.mh-toast {
    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    z-index: 2000;
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.8rem 1.1rem;
    border-radius: 0.9rem;
    font-size: 0.85rem;
    font-weight: 700;
    color: #fff;
    box-shadow: 0 20px 45px -18px rgba(0, 0, 0, 0.5);
    animation: mh-toastin 0.25s ease;
}
@keyframes mh-toastin {
    from {
        opacity: 0;
        transform: translateY(12px);
    }
}
.mh-toast.success {
    background: linear-gradient(135deg, #8b5cf6, #6d28d9);
}
.mh-toast.info {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
}
.mh-toast.error {
    background: linear-gradient(135deg, #f43f5e, #e11d48);
}

@media (prefers-reduced-motion: reduce) {
    .mh-btn,
    .mh-stat,
    .mh-sec,
    .mh-tl-card,
    .mh-ring .bar,
    .mh-dot,
    .mh-sk::after,
    .mh-icobtn,
    .mh-mini,
    .mh-drawer-panel,
    .mh-bulk,
    .mh-report {
        transition: none;
        animation: none;
    }
    .mh-btn:hover,
    .mh-stat:hover,
    .mh-sec:hover,
    .mh-tl-card:hover,
    .mh-icobtn:hover,
    .mh-mini:hover,
    .mh-report:hover {
        transform: none;
    }
}
@media print {
    .sidebar,
    header.navbar-header,
    .mh-print-hide {
        display: none !important;
    }
}

/* cascade-safe per-instance modifiers (unlayered — see CASCADE-SAFE OVERRIDE UTILITIES note) */
.mh-sk.mh-r100 {
    border-radius: 1rem;
}
.mh-sk.mh-r125 {
    border-radius: 1.25rem;
}
.mh-sk.mh-r150 {
    border-radius: 1.5rem;
}
.mh-hbadge.mh-hbadge-amber {
    background: rgba(245, 158, 11, 0.18);
    border-color: rgba(245, 158, 11, 0.4);
}
.mh-hbadge.mh-hbadge-emerald {
    background: rgba(16, 185, 129, 0.18);
    border-color: rgba(16, 185, 129, 0.4);
}
.mh-ring.mh-ring-lg {
    width: 5rem;
    height: 5rem;
}
.mh-tool.mh-tool-compact {
    padding: 0.35rem 0.6rem;
}
.mh-tool.mh-tool-compact-sm {
    padding: 0.35rem 0.5rem;
}

/* =====================================================================
   OPD PATIENTS  ·  opd-patients.html (page-exclusive)
   ===================================================================== */
/* ================================================================
               OUTPATIENT (OPD) MANAGEMENT CENTER — self-contained (inline).
               Design-system CSS variables → automatic light / dark.
               ================================================================ */
#opd-page {
    --opd-c: var(--color-primary);
}
.opd-surface {
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    border-radius: 1.25rem;
    box-shadow: 0 20px 45px -35px rgba(15, 23, 42, 0.4);
}

.opd-layout {
    display: grid;
    grid-template-columns: 1fr;
    gap: 1.25rem;
    align-items: start;
}
@media (min-width: 1280px) {
    .opd-layout {
        grid-template-columns: minmax(0, 1fr) 340px;
    }
}
.opd-grid {
    display: grid;
    gap: 0.9rem;
}
.opd-g3 {
    grid-template-columns: repeat(1, minmax(0, 1fr));
}
.opd-g6 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
}
@media (min-width: 640px) {
    .opd-g3 {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}
@media (min-width: 900px) {
    .opd-g3 {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
    .opd-g6 {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}
@media (min-width: 1200px) {
    .opd-g6 {
        grid-template-columns: repeat(6, minmax(0, 1fr));
    }
}
.opd-cards {
    display: grid;
    gap: 1rem;
    grid-template-columns: 1fr;
}
.opd-cards.hidden {
    display: none;
}
@media (min-width: 700px) {
    .opd-cards {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}
@media (min-width: 1500px) {
    .opd-cards {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}

.opd-hero {
    position: relative;
    overflow: hidden;
    border-radius: 1.5rem;
    padding: 1.75rem;
    color: #fff;
    background:
        radial-gradient(
            120% 140% at 0% 0%,
            rgba(14, 165, 233, 0.5),
            transparent 55%
        ),
        radial-gradient(
            120% 160% at 100% 0%,
            rgba(139, 92, 246, 0.5),
            transparent 50%
        ),
        linear-gradient(135deg, #0f172a, #122447 55%, #0b1220);
    box-shadow: 0 30px 60px -30px rgba(15, 23, 42, 0.7);
}
.opd-hero::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image: radial-gradient(
        rgba(255, 255, 255, 0.08) 1px,
        transparent 1px
    );
    background-size: 22px 22px;
    -webkit-mask-image: linear-gradient(180deg, #000, transparent 75%);
    mask-image: linear-gradient(180deg, #000, transparent 75%);
}
.opd-hero > * {
    position: relative;
    z-index: 1;
}
@media (min-width: 1024px) {
    .opd-hero {
        padding: 2rem 2.25rem;
    }
}
.opd-hbadge {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.25rem 0.7rem;
    border-radius: 9999px;
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    background: rgba(255, 255, 255, 0.14);
    border: 1px solid rgba(255, 255, 255, 0.22);
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
}
.opd-hmeta {
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
    padding: 0.45rem 0.8rem;
    border-radius: 0.8rem;
    background: rgba(255, 255, 255, 0.1);
    border: 1px solid rgba(255, 255, 255, 0.16);
    font-size: 0.72rem;
    font-weight: 700;
}
.opd-dot {
    width: 0.5rem;
    height: 0.5rem;
    border-radius: 9999px;
    background: #38bdf8;
    box-shadow: 0 0 0 4px rgba(56, 189, 248, 0.25);
    animation: opd-pulse 2s ease-in-out infinite;
}
@keyframes opd-pulse {
    0%,
    100% {
        opacity: 1;
    }
    50% {
        opacity: 0.4;
    }
}

.opd-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    padding: 0.55rem 0.9rem;
    border-radius: 0.8rem;
    font-size: 0.8rem;
    font-weight: 700;
    cursor: pointer;
    border: 1px solid transparent;
    white-space: nowrap;
    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease,
        background 0.2s ease,
        color 0.2s ease,
        border-color 0.2s ease;
}
.opd-btn:hover {
    transform: translateY(-2px);
}
.opd-btn-primary {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    box-shadow: 0 12px 24px -12px var(--color-primary);
}
.opd-btn-success {
    background: linear-gradient(135deg, #0ea5e9, #0284c7);
    color: #fff;
    box-shadow: 0 12px 24px -12px #0ea5e9;
}
.opd-btn-glass {
    background: rgba(255, 255, 255, 0.12);
    color: #fff;
    border-color: rgba(255, 255, 255, 0.24);
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
}
.opd-btn-glass:hover {
    background: rgba(255, 255, 255, 0.2);
}
.opd-btn-solid {
    background: var(--color-white);
    color: var(--color-gray-900);
    border-color: var(--color-border-color);
}
.opd-btn-solid:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.opd-btn-danger {
    background: #e11d48;
    color: #fff;
}
.opd-icobtn {
    display: grid;
    place-items: center;
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 0.75rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-500);
    cursor: pointer;
    transition: all 0.16s ease;
    flex-shrink: 0;
}
.opd-icobtn:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
    transform: translateY(-1px);
}

.opd-stat {
    position: relative;
    overflow: hidden;
    border-radius: 1.25rem;
    padding: 1.1rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 18px 40px -30px rgba(15, 23, 42, 0.45);
    transition:
        transform 0.25s ease,
        box-shadow 0.25s ease,
        border-color 0.25s ease;
}
.opd-stat::after {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(
        135deg,
        color-mix(in oklab, var(--opd-c) 12%, transparent),
        transparent 60%
    );
    pointer-events: none;
}
.opd-stat:hover {
    transform: translateY(-4px);
    box-shadow: 0 26px 50px -26px
        color-mix(in oklab, var(--opd-c) 55%, rgba(15, 23, 42, 0.5));
    border-color: color-mix(
        in oklab,
        var(--opd-c) 40%,
        var(--color-border-color)
    );
}
.opd-stat > * {
    position: relative;
    z-index: 1;
}
.opd-stat-ico {
    display: grid;
    place-items: center;
    width: 2.9rem;
    height: 2.9rem;
    border-radius: 0.9rem;
    color: #fff;
    font-size: 1.15rem;
    background: linear-gradient(
        135deg,
        var(--opd-c),
        color-mix(in oklab, var(--opd-c) 55%, #6366f1)
    );
    box-shadow: 0 10px 20px -10px var(--opd-c);
}
.opd-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.15rem 0.5rem;
    border-radius: 9999px;
    font-size: 0.62rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    color: color-mix(in oklab, var(--opd-c) 70%, #1e293b);
    background: color-mix(in oklab, var(--opd-c) 16%, transparent);
}
.dark .opd-chip {
    color: color-mix(in oklab, var(--opd-c) 55%, #fff);
}
.opd-ring {
    --p: 0;
    width: 3rem;
    height: 3rem;
    transform: rotate(-90deg);
}
.opd-ring circle {
    fill: none;
    stroke-width: 4;
}
.opd-ring .trk {
    stroke: color-mix(in oklab, var(--opd-c) 16%, transparent);
}
.opd-ring .bar {
    stroke: var(--opd-c);
    stroke-linecap: round;
    stroke-dasharray: 100 100;
    stroke-dashoffset: calc(100 - var(--p));
    transition: stroke-dashoffset 0.9s cubic-bezier(0.16, 1, 0.3, 1);
}

.opd-head {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 1rem 1.15rem;
    border-bottom: 1px solid var(--color-border-color);
}
.opd-head .ico {
    display: grid;
    place-items: center;
    width: 2.3rem;
    height: 2.3rem;
    border-radius: 0.75rem;
    color: #fff;
    font-size: 0.95rem;
    background: linear-gradient(
        135deg,
        color-mix(in oklab, var(--opd-c) 90%, #000),
        color-mix(in oklab, var(--opd-c) 55%, #6366f1)
    );
    box-shadow: 0 10px 18px -12px var(--opd-c);
    flex-shrink: 0;
}
.opd-title {
    font-weight: 800;
    color: var(--color-gray-900);
    font-size: 0.9rem;
}

.opd-search {
    position: relative;
    flex: 1 1 220px;
    min-width: 180px;
}
.opd-search input {
    width: 100%;
    padding: 0.6rem 0.9rem 0.6rem 2.5rem;
    border-radius: 0.85rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.85rem;
    font-weight: 600;
    outline: none;
    transition:
        border-color 0.18s ease,
        box-shadow 0.18s ease;
}
.opd-search input:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 4px
        color-mix(in oklab, var(--color-primary) 14%, transparent);
}
.opd-search .ico {
    position: absolute;
    left: 0.85rem;
    top: 50%;
    transform: translateY(-50%);
    color: var(--color-gray-400, #94a3b8);
    pointer-events: none;
}
.opd-tool {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.55rem 0.8rem;
    border-radius: 0.8rem;
    font-size: 0.8rem;
    font-weight: 700;
    cursor: pointer;
    white-space: nowrap;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-600, #475569);
    transition:
        border-color 0.18s ease,
        color 0.18s ease,
        transform 0.18s ease;
}
.opd-tool:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
    transform: translateY(-1px);
}
.opd-seg {
    display: inline-flex;
    padding: 0.25rem;
    border-radius: 0.85rem;
    background: color-mix(in oklab, var(--color-gray-500) 14%, transparent);
}
.opd-seg button {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.4rem 0.7rem;
    border-radius: 0.65rem;
    font-size: 0.78rem;
    font-weight: 700;
    color: var(--color-gray-500);
    transition: all 0.18s ease;
}
.opd-seg button.is-active {
    background: var(--color-white);
    color: var(--color-primary-text);
    box-shadow: 0 4px 10px -6px rgba(15, 23, 42, 0.4);
}

.opd-card {
    position: relative;
    overflow: hidden;
    border-radius: 1.25rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 18px 40px -32px rgba(15, 23, 42, 0.5);
    transition:
        transform 0.25s ease,
        box-shadow 0.25s ease,
        border-color 0.25s ease;
}
.opd-card::before {
    content: "";
    position: absolute;
    inset: 0 0 auto 0;
    height: 3px;
    background: linear-gradient(
        90deg,
        var(--opd-c),
        color-mix(in oklab, var(--opd-c) 40%, #6366f1)
    );
}
.opd-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 26px 48px -26px
        color-mix(in oklab, var(--opd-c) 45%, rgba(15, 23, 42, 0.5));
    border-color: color-mix(
        in oklab,
        var(--opd-c) 35%,
        var(--color-border-color)
    );
}
.opd-card.is-selected {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 2px
        color-mix(in oklab, var(--color-primary) 40%, transparent);
}
.opd-ava {
    width: 3rem;
    height: 3rem;
    border-radius: 0.85rem;
    display: grid;
    place-items: center;
    color: #fff;
    font-weight: 800;
    font-size: 0.95rem;
    background: linear-gradient(
        135deg,
        var(--opd-c),
        color-mix(in oklab, var(--opd-c) 55%, #6366f1)
    );
}
.opd-ava-ring {
    padding: 2px;
    border-radius: 1rem;
    background: linear-gradient(
        135deg,
        var(--opd-c),
        color-mix(in oklab, var(--opd-c) 40%, #6366f1)
    );
    flex-shrink: 0;
}

.opd-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.15rem 0.55rem;
    border-radius: 9999px;
    font-size: 0.64rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    white-space: nowrap;
}
.opd-badge.completed {
    color: #059669;
    background: rgba(16, 185, 129, 0.15);
}
.opd-badge.consult {
    color: var(--color-primary-text);
    background: color-mix(in oklab, var(--color-primary) 15%, transparent);
}
.opd-badge.waiting {
    color: #d97706;
    background: rgba(245, 158, 11, 0.15);
}
.opd-badge.lab {
    color: #0d9488;
    background: rgba(20, 184, 166, 0.15);
}
.opd-badge.pharmacy {
    color: #8b5cf6;
    background: rgba(139, 92, 246, 0.15);
}
.opd-badge.cancelled {
    color: #e11d48;
    background: rgba(244, 63, 94, 0.15);
}
.opd-tag {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.1rem 0.45rem;
    border-radius: 0.5rem;
    font-size: 0.62rem;
    font-weight: 700;
    background: color-mix(in oklab, var(--opd-c) 14%, transparent);
    color: var(--opd-c);
}
.opd-token {
    display: inline-grid;
    place-items: center;
    min-width: 2.6rem;
    padding: 0.15rem 0.5rem;
    border-radius: 0.55rem;
    font-size: 0.72rem;
    font-weight: 800;
    font-family: ui-monospace, monospace;
    color: #fff;
    background: linear-gradient(
        135deg,
        var(--opd-c),
        color-mix(in oklab, var(--opd-c) 55%, #6366f1)
    );
    box-shadow: 0 6px 12px -6px var(--opd-c);
}
.opd-mini {
    display: grid;
    place-items: center;
    width: 2rem;
    height: 2rem;
    border-radius: 0.6rem;
    color: var(--color-gray-500);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.16s ease;
}
.opd-mini:hover {
    border-color: var(--opd-c);
    color: var(--opd-c);
    transform: translateY(-1px);
}
.opd-kv {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    font-size: 0.72rem;
    color: var(--color-gray-500);
    min-width: 0;
}
.opd-kv b {
    color: var(--color-gray-900);
    font-weight: 700;
}

.opd-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0;
}
.opd-table thead th {
    text-align: left;
    font-size: 0.66rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--color-gray-400, #94a3b8);
    padding: 0.75rem 1rem;
    border-bottom: 1px solid var(--color-border-color);
    white-space: nowrap;
    background: color-mix(in oklab, var(--color-gray-500) 5%, transparent);
}
.opd-table tbody td {
    padding: 0.7rem 1rem;
    border-bottom: 1px solid var(--color-border-color);
    font-size: 0.82rem;
    color: var(--color-gray-900);
    vertical-align: middle;
    white-space: nowrap;
}
.opd-table tbody tr {
    transition: background 0.15s ease;
}
.opd-table tbody tr:hover {
    background: color-mix(in oklab, var(--color-primary) 5%, transparent);
}
.opd-table tbody tr.is-selected {
    background: color-mix(in oklab, var(--color-primary) 9%, transparent);
}
.opd-check {
    width: 1.05rem;
    height: 1.05rem;
    border-radius: 0.35rem;
    accent-color: var(--color-primary);
    cursor: pointer;
}

.opd-menu {
    position: absolute;
    z-index: 1100;
    min-width: 14.5rem;
    max-height: 26rem;
    overflow-y: auto;
    padding: 0.4rem;
    border-radius: 1rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 30px 60px -24px rgba(2, 12, 40, 0.5);
    animation: opd-pop 0.16s ease;
}
@keyframes opd-pop {
    from {
        opacity: 0;
        transform: translateY(-6px) scale(0.97);
    }
}
.opd-menu button,
.opd-menu a {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    width: 100%;
    padding: 0.45rem 0.55rem;
    border-radius: 0.55rem;
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--color-gray-900);
    text-align: left;
    transition:
        background 0.14s ease,
        color 0.14s ease;
}
.opd-menu button:hover,
.opd-menu a:hover {
    background: color-mix(in oklab, var(--color-primary) 8%, transparent);
    color: var(--color-primary-text);
}
.opd-menu .danger {
    color: #e11d48;
}
.opd-menu .danger:hover {
    background: rgba(244, 63, 94, 0.1);
}
.opd-menu-sep {
    height: 1px;
    margin: 0.3rem 0.2rem;
    background: var(--color-border-color);
}
.opd-menu-lbl {
    padding: 0.4rem 0.55rem 0.15rem;
    font-size: 0.58rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--color-gray-400, #94a3b8);
}

.opd-drawer {
    position: fixed;
    inset: 0;
    z-index: 1200;
    visibility: hidden;
}
.opd-drawer.open {
    visibility: visible;
}
.opd-drawer-back {
    position: absolute;
    inset: 0;
    background: rgba(8, 12, 30, 0.5);
    opacity: 0;
    transition: opacity 0.3s ease;
}
.opd-drawer.open .opd-drawer-back {
    opacity: 1;
}
.opd-drawer-panel {
    position: absolute;
    top: 0;
    right: 0;
    height: 100%;
    width: min(480px, 94vw);
    background: var(--color-white);
    box-shadow: -30px 0 60px -30px rgba(2, 12, 40, 0.55);
    transform: translateX(100%);
    transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1);
    display: flex;
    flex-direction: column;
}
.opd-drawer.open .opd-drawer-panel {
    transform: translateX(0);
}
.opd-drawer-panel.left {
    right: auto;
    left: 0;
    transform: translateX(-100%);
    box-shadow: 30px 0 60px -30px rgba(2, 12, 40, 0.55);
}
.opd-drawer.open .opd-drawer-panel.left {
    transform: translateX(0);
}
.opd-drawer-hero {
    position: relative;
    padding: 1.5rem;
    color: #fff;
    background:
        radial-gradient(
            120% 130% at 100% 0%,
            rgba(14, 165, 233, 0.6),
            transparent 55%
        ),
        linear-gradient(135deg, #4f46e5, #0f172a);
}

.opd-modal {
    position: fixed;
    inset: 0;
    z-index: 1300;
    display: none;
    align-items: center;
    justify-content: center;
    padding: 1rem;
}
.opd-modal.open {
    display: flex;
}
.opd-modal-back {
    position: absolute;
    inset: 0;
    background: rgba(8, 12, 30, 0.5);
    -webkit-backdrop-filter: blur(3px);
    backdrop-filter: blur(3px);
    animation: opd-fadein 0.2s ease;
}
@keyframes opd-fadein {
    from {
        opacity: 0;
    }
}
.opd-modal-panel {
    position: relative;
    width: 100%;
    max-width: 36rem;
    max-height: 90vh;
    overflow-y: auto;
    border-radius: 1.25rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 40px 80px -30px rgba(2, 12, 40, 0.6);
    animation: opd-modin 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes opd-modin {
    from {
        opacity: 0;
        transform: translateY(16px) scale(0.97);
    }
}
.opd-doc-ico {
    display: grid;
    place-items: center;
    width: 2.75rem;
    height: 2.75rem;
    border-radius: 0.8rem;
    color: var(--opd-c);
    font-size: 1.15rem;
    background: color-mix(in oklab, var(--opd-c) 14%, transparent);
}

.opd-bulk {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.55rem;
    padding: 0.7rem 0.9rem;
    border-radius: 1.25rem;
    background: color-mix(in oklab, var(--color-white) 85%, transparent);
    -webkit-backdrop-filter: blur(16px);
    backdrop-filter: blur(16px);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 12px 28px -18px rgba(15, 23, 42, 0.45);
    animation: opd-bulk-in 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes opd-bulk-in {
    from {
        opacity: 0;
        transform: translateY(-8px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}
.opd-bulk-btn {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.4rem 0.7rem;
    border-radius: 0.7rem;
    font-size: 0.76rem;
    font-weight: 700;
    color: var(--color-gray-700, #374151);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.15s ease;
    white-space: nowrap;
}
.dark .opd-bulk-btn {
    color: var(--color-gray-900);
}
.opd-bulk-btn:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.opd-bulk-btn.danger {
    color: #e11d48;
}
.opd-bulk-btn.danger:hover {
    border-color: #e11d48;
    background: rgba(244, 63, 94, 0.08);
}

.opd-pg {
    display: grid;
    place-items: center;
    min-width: 2.1rem;
    height: 2.1rem;
    padding: 0 0.5rem;
    border-radius: 0.6rem;
    font-size: 0.8rem;
    font-weight: 700;
    color: var(--color-gray-600, #475569);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.15s ease;
    cursor: pointer;
}
.opd-pg:hover:not(:disabled) {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.opd-pg.is-active {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    border-color: transparent;
}
.opd-pg:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

.opd-wf {
    display: flex;
    align-items: center;
    gap: 0.25rem;
    overflow-x: auto;
    scrollbar-width: none;
}
.opd-wf::-webkit-scrollbar {
    display: none;
}
.opd-wf-step {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.4rem;
    min-width: 5rem;
    text-align: center;
}
.opd-wf-node {
    display: grid;
    place-items: center;
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 9999px;
    font-size: 0.85rem;
    color: var(--color-gray-500);
    background: color-mix(in oklab, var(--color-gray-500) 14%, transparent);
}
.opd-wf-step.done .opd-wf-node {
    background: linear-gradient(135deg, #0ea5e9, #0284c7);
    color: #fff;
}
.opd-wf-step.active .opd-wf-node {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    box-shadow: 0 10px 20px -8px var(--color-primary);
}
.opd-wf-line {
    flex: 1 1 0.75rem;
    min-width: 0.75rem;
    height: 2px;
    border-radius: 2px;
    background: var(--color-border-color);
}
.opd-wf-line.done {
    background: linear-gradient(90deg, #0ea5e9, #0284c7);
}

.opd-tl {
    position: relative;
    padding-left: 1.75rem;
}
.opd-tl::before {
    content: "";
    position: absolute;
    left: 0.72rem;
    top: 0.35rem;
    bottom: 0.35rem;
    width: 2px;
    background: linear-gradient(
        180deg,
        var(--opd-c, var(--color-primary)),
        color-mix(in oklab, var(--opd-c, var(--color-primary)) 20%, transparent)
    );
}
.opd-tl-item {
    position: relative;
    padding-bottom: 1.1rem;
}
.opd-tl-item:last-child {
    padding-bottom: 0;
}
.opd-tl-node {
    position: absolute;
    left: -1.75rem;
    top: 0.05rem;
    display: grid;
    place-items: center;
    width: 1.5rem;
    height: 1.5rem;
    border-radius: 9999px;
    color: #fff;
    font-size: 0.62rem;
    background: linear-gradient(
        135deg,
        var(--opd-c, var(--color-primary)),
        color-mix(in oklab, var(--opd-c, var(--color-primary)) 55%, #6366f1)
    );
    box-shadow: 0 0 0 3px
        color-mix(in oklab, var(--opd-c, var(--color-primary)) 16%, transparent);
}

.opd-bar {
    height: 0.5rem;
    border-radius: 9999px;
    background: color-mix(in oklab, var(--opd-c) 14%, transparent);
    overflow: hidden;
}
.opd-bar > i {
    display: block;
    height: 100%;
    border-radius: 9999px;
    background: linear-gradient(
        90deg,
        var(--opd-c),
        color-mix(in oklab, var(--opd-c) 55%, #6366f1)
    );
}

/* Live Queue board */
.opd-qboard {
    position: relative;
    overflow: hidden;
    border-radius: 1.5rem;
    padding: 1.25rem;
    color: #fff;
    background:
        radial-gradient(
            120% 140% at 100% 0%,
            rgba(99, 102, 241, 0.55),
            transparent 55%
        ),
        linear-gradient(135deg, #0b1220, #0f2a3a 60%, #0b1220);
    border: 1px solid rgba(255, 255, 255, 0.08);
}
.opd-qtile {
    border-radius: 1rem;
    padding: 0.9rem;
    background: rgba(255, 255, 255, 0.07);
    border: 1px solid rgba(255, 255, 255, 0.12);
    -webkit-backdrop-filter: blur(6px);
    backdrop-filter: blur(6px);
}
.opd-qtile .n {
    font-size: 1.6rem;
    font-weight: 900;
    line-height: 1;
    letter-spacing: -0.02em;
}
.opd-qtile .l {
    font-size: 0.62rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    opacity: 0.75;
}

/* Doctor status card */
.opd-doc {
    position: relative;
    overflow: hidden;
    border-radius: 1.25rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 18px 40px -32px rgba(15, 23, 42, 0.5);
    transition:
        transform 0.25s ease,
        box-shadow 0.25s ease,
        border-color 0.25s ease;
}
.opd-doc:hover {
    transform: translateY(-4px);
    border-color: color-mix(
        in oklab,
        var(--opd-c) 35%,
        var(--color-border-color)
    );
}
.opd-avail {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.12rem 0.5rem;
    border-radius: 9999px;
    font-size: 0.6rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.03em;
}
.opd-avail.on {
    color: #059669;
    background: rgba(16, 185, 129, 0.15);
}
.opd-avail.busy {
    color: #d97706;
    background: rgba(245, 158, 11, 0.15);
}
.opd-avail.off {
    color: #64748b;
    background: rgba(100, 116, 139, 0.15);
}

.opd-in {
    width: 100%;
    padding: 0.65rem 0.8rem;
    border-radius: 0.7rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.85rem;
    font-weight: 600;
    outline: none;
    transition:
        border-color 0.16s ease,
        box-shadow 0.16s ease;
}
.opd-in:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 4px
        color-mix(in oklab, var(--color-primary) 14%, transparent);
}
.opd-lbl {
    display: block;
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--color-gray-500);
    margin-bottom: 0.3rem;
}
.opd-recent {
    display: flex;
    align-items: center;
    gap: 0.7rem;
    padding: 0.6rem;
    border-radius: 0.8rem;
    transition: background 0.15s ease;
}
.opd-recent:hover {
    background: color-mix(in oklab, var(--color-primary) 6%, transparent);
}

.opd-c-indigo {
    --opd-c: #6366f1;
}
.opd-c-sky {
    --opd-c: #0ea5e9;
}
.opd-c-rose {
    --opd-c: #f43f5e;
}
.opd-c-amber {
    --opd-c: #f59e0b;
}
.opd-c-emerald {
    --opd-c: #10b981;
}
.opd-c-violet {
    --opd-c: #8b5cf6;
}
.opd-c-teal {
    --opd-c: #14b8a6;
}
.opd-c-primary {
    --opd-c: var(--color-primary);
}

.opd-sk {
    position: relative;
    overflow: hidden;
    background: color-mix(in oklab, var(--color-gray-500) 12%, transparent);
    border-radius: 0.75rem;
}
.opd-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in oklab, var(--color-white) 55%, transparent),
        transparent
    );
    animation: opd-shimmer 1.4s infinite;
}
.dark .opd-sk::after {
    background: linear-gradient(
        90deg,
        transparent,
        rgba(255, 255, 255, 0.06),
        transparent
    );
}
@keyframes opd-shimmer {
    100% {
        transform: translateX(100%);
    }
}

/* Per-instance overrides (unlayered, placed after the base classes above so
               source-order tie-breaking lets them win — see CASCADE-SAFE OVERRIDE UTILITIES) */
.opd-hbadge-amber {
    background: rgba(245, 158, 11, 0.18);
    border-color: rgba(245, 158, 11, 0.4);
}
.opd-hbadge-sky {
    background: rgba(14, 165, 233, 0.18);
    border-color: rgba(14, 165, 233, 0.4);
}
.opd-tool-compact {
    padding: 0.35rem 0.6rem;
}
.opd-tool-compact-sm {
    padding: 0.35rem 0.5rem;
}

.opd-toast {
    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    z-index: 2000;
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.8rem 1.1rem;
    border-radius: 0.9rem;
    font-size: 0.85rem;
    font-weight: 700;
    color: #fff;
    box-shadow: 0 20px 45px -18px rgba(0, 0, 0, 0.5);
    animation: opd-toastin 0.25s ease;
}
@keyframes opd-toastin {
    from {
        opacity: 0;
        transform: translateY(12px);
    }
}
.opd-toast.success {
    background: linear-gradient(135deg, #0ea5e9, #0284c7);
}
.opd-toast.info {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
}
.opd-toast.error {
    background: linear-gradient(135deg, #f43f5e, #e11d48);
}

@media (prefers-reduced-motion: reduce) {
    .opd-btn,
    .opd-stat,
    .opd-card,
    .opd-doc,
    .opd-ring .bar,
    .opd-dot,
    .opd-sk::after,
    .opd-icobtn,
    .opd-mini,
    .opd-drawer-panel,
    .opd-bulk {
        transition: none;
        animation: none;
    }
    .opd-btn:hover,
    .opd-stat:hover,
    .opd-card:hover,
    .opd-doc:hover,
    .opd-icobtn:hover,
    .opd-mini:hover {
        transform: none;
    }
}
@media print {
    .sidebar,
    header.navbar-header,
    .opd-print-hide {
        display: none !important;
    }
}

/* =====================================================================
   IPD PATIENTS  ·  ipd-patients.html (page-exclusive)
   ===================================================================== */
/* ================================================================
               INPATIENT (IPD) MANAGEMENT CENTER — self-contained (inline).
               Design-system CSS variables → automatic light / dark.
               ================================================================ */
#ipd-page {
    --ipd-c: var(--color-primary);
}
.ipd-surface {
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    border-radius: 1.25rem;
    box-shadow: 0 20px 45px -35px rgba(15, 23, 42, 0.4);
}

.ipd-layout {
    display: grid;
    grid-template-columns: 1fr;
    gap: 1.25rem;
    align-items: start;
}
@media (min-width: 1280px) {
    .ipd-layout {
        grid-template-columns: minmax(0, 1fr) 340px;
    }
}
.ipd-grid {
    display: grid;
    gap: 0.9rem;
}
.ipd-g3 {
    grid-template-columns: repeat(1, minmax(0, 1fr));
}
.ipd-g6 {
    grid-template-columns: repeat(2, minmax(0, 1fr));
}
@media (min-width: 640px) {
    .ipd-g3 {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}
@media (min-width: 900px) {
    .ipd-g3 {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
    .ipd-g6 {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}
@media (min-width: 1200px) {
    .ipd-g6 {
        grid-template-columns: repeat(6, minmax(0, 1fr));
    }
}
.ipd-cards {
    display: grid;
    gap: 1rem;
    grid-template-columns: 1fr;
}
.ipd-cards.hidden {
    display: none;
}
@media (min-width: 700px) {
    .ipd-cards {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}
@media (min-width: 1500px) {
    .ipd-cards {
        grid-template-columns: repeat(3, minmax(0, 1fr));
    }
}

.ipd-hero {
    position: relative;
    overflow: hidden;
    border-radius: 1.5rem;
    padding: 1.75rem;
    color: #fff;
    background:
        radial-gradient(
            120% 140% at 0% 0%,
            rgba(244, 63, 94, 0.5),
            transparent 55%
        ),
        radial-gradient(
            120% 160% at 100% 0%,
            rgba(99, 102, 241, 0.55),
            transparent 50%
        ),
        linear-gradient(135deg, #0f172a, #1e1b4b 55%, #0b1220);
    box-shadow: 0 30px 60px -30px rgba(15, 23, 42, 0.7);
}
.ipd-hero::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image: radial-gradient(
        rgba(255, 255, 255, 0.08) 1px,
        transparent 1px
    );
    background-size: 22px 22px;
    -webkit-mask-image: linear-gradient(180deg, #000, transparent 75%);
    mask-image: linear-gradient(180deg, #000, transparent 75%);
}
.ipd-hero > * {
    position: relative;
    z-index: 1;
}
@media (min-width: 1024px) {
    .ipd-hero {
        padding: 2rem 2.25rem;
    }
}
.ipd-hbadge {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.25rem 0.7rem;
    border-radius: 9999px;
    font-size: 0.68rem;
    font-weight: 800;
    letter-spacing: 0.03em;
    text-transform: uppercase;
    background: rgba(255, 255, 255, 0.14);
    border: 1px solid rgba(255, 255, 255, 0.22);
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
}
.ipd-hbadge-indigo {
    background: rgba(99, 102, 241, 0.18);
    border-color: rgba(99, 102, 241, 0.4);
}
.ipd-hbadge-rose {
    background: rgba(244, 63, 94, 0.18);
    border-color: rgba(244, 63, 94, 0.4);
}
.ipd-hmeta {
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
    padding: 0.45rem 0.8rem;
    border-radius: 0.8rem;
    background: rgba(255, 255, 255, 0.1);
    border: 1px solid rgba(255, 255, 255, 0.16);
    font-size: 0.72rem;
    font-weight: 700;
}
.ipd-dot {
    width: 0.5rem;
    height: 0.5rem;
    border-radius: 9999px;
    background: #fb7185;
    box-shadow: 0 0 0 4px rgba(251, 113, 133, 0.25);
    animation: ipd-pulse 2s ease-in-out infinite;
}
@keyframes ipd-pulse {
    0%,
    100% {
        opacity: 1;
    }
    50% {
        opacity: 0.4;
    }
}

.ipd-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.4rem;
    padding: 0.55rem 0.9rem;
    border-radius: 0.8rem;
    font-size: 0.8rem;
    font-weight: 700;
    cursor: pointer;
    border: 1px solid transparent;
    white-space: nowrap;
    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease,
        background 0.2s ease,
        color 0.2s ease,
        border-color 0.2s ease;
}
.ipd-btn:hover {
    transform: translateY(-2px);
}
.ipd-btn-primary {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    box-shadow: 0 12px 24px -12px var(--color-primary);
}
.ipd-btn-success {
    background: linear-gradient(135deg, #f43f5e, #e11d48);
    color: #fff;
    box-shadow: 0 12px 24px -12px #f43f5e;
}
.ipd-btn-glass {
    background: rgba(255, 255, 255, 0.12);
    color: #fff;
    border-color: rgba(255, 255, 255, 0.24);
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
}
.ipd-btn-glass:hover {
    background: rgba(255, 255, 255, 0.2);
}
.ipd-btn-solid {
    background: var(--color-white);
    color: var(--color-gray-900);
    border-color: var(--color-border-color);
}
.ipd-btn-solid:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.ipd-btn-danger {
    background: #e11d48;
    color: #fff;
}
.ipd-icobtn {
    display: grid;
    place-items: center;
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 0.75rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-500);
    cursor: pointer;
    transition: all 0.16s ease;
    flex-shrink: 0;
}
.ipd-icobtn:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
    transform: translateY(-1px);
}

.ipd-stat {
    position: relative;
    overflow: hidden;
    border-radius: 1.25rem;
    padding: 1.1rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 18px 40px -30px rgba(15, 23, 42, 0.45);
    transition:
        transform 0.25s ease,
        box-shadow 0.25s ease,
        border-color 0.25s ease;
}
.ipd-stat::after {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(
        135deg,
        color-mix(in oklab, var(--ipd-c) 12%, transparent),
        transparent 60%
    );
    pointer-events: none;
}
.ipd-stat:hover {
    transform: translateY(-4px);
    box-shadow: 0 26px 50px -26px
        color-mix(in oklab, var(--ipd-c) 55%, rgba(15, 23, 42, 0.5));
    border-color: color-mix(
        in oklab,
        var(--ipd-c) 40%,
        var(--color-border-color)
    );
}
.ipd-stat > * {
    position: relative;
    z-index: 1;
}
.ipd-stat-ico {
    display: grid;
    place-items: center;
    width: 2.9rem;
    height: 2.9rem;
    border-radius: 0.9rem;
    color: #fff;
    font-size: 1.15rem;
    background: linear-gradient(
        135deg,
        var(--ipd-c),
        color-mix(in oklab, var(--ipd-c) 55%, #6366f1)
    );
    box-shadow: 0 10px 20px -10px var(--ipd-c);
}
.ipd-chip {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.15rem 0.5rem;
    border-radius: 9999px;
    font-size: 0.62rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    color: color-mix(in oklab, var(--ipd-c) 70%, #1e293b);
    background: color-mix(in oklab, var(--ipd-c) 16%, transparent);
}
.dark .ipd-chip {
    color: color-mix(in oklab, var(--ipd-c) 55%, #fff);
}
.ipd-ring {
    --p: 0;
    width: 3rem;
    height: 3rem;
    transform: rotate(-90deg);
}
.ipd-ring-lg {
    width: 4.5rem;
    height: 4.5rem;
}
.ipd-ring circle {
    fill: none;
    stroke-width: 4;
}
.ipd-ring .trk {
    stroke: color-mix(in oklab, var(--ipd-c) 16%, transparent);
}
.ipd-ring .bar {
    stroke: var(--ipd-c);
    stroke-linecap: round;
    stroke-dasharray: 100 100;
    stroke-dashoffset: calc(100 - var(--p));
    transition: stroke-dashoffset 0.9s cubic-bezier(0.16, 1, 0.3, 1);
}

.ipd-head {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 1rem 1.15rem;
    border-bottom: 1px solid var(--color-border-color);
}
.ipd-head .ico {
    display: grid;
    place-items: center;
    width: 2.3rem;
    height: 2.3rem;
    border-radius: 0.75rem;
    color: #fff;
    font-size: 0.95rem;
    background: linear-gradient(
        135deg,
        color-mix(in oklab, var(--ipd-c) 90%, #000),
        color-mix(in oklab, var(--ipd-c) 55%, #6366f1)
    );
    box-shadow: 0 10px 18px -12px var(--ipd-c);
    flex-shrink: 0;
}
.ipd-title {
    font-weight: 800;
    color: var(--color-gray-900);
    font-size: 0.9rem;
}

.ipd-search {
    position: relative;
    flex: 1 1 220px;
    min-width: 180px;
}
.ipd-search input {
    width: 100%;
    padding: 0.6rem 0.9rem 0.6rem 2.5rem;
    border-radius: 0.85rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.85rem;
    font-weight: 600;
    outline: none;
    transition:
        border-color 0.18s ease,
        box-shadow 0.18s ease;
}
.ipd-search input:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 4px
        color-mix(in oklab, var(--color-primary) 14%, transparent);
}
.ipd-search .ico {
    position: absolute;
    left: 0.85rem;
    top: 50%;
    transform: translateY(-50%);
    color: var(--color-gray-400, #94a3b8);
    pointer-events: none;
}
.ipd-tool {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.55rem 0.8rem;
    border-radius: 0.8rem;
    font-size: 0.8rem;
    font-weight: 700;
    cursor: pointer;
    white-space: nowrap;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-600, #475569);
    transition:
        border-color 0.18s ease,
        color 0.18s ease,
        transform 0.18s ease;
}
.ipd-tool:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
    transform: translateY(-1px);
}
.ipd-seg {
    display: inline-flex;
    padding: 0.25rem;
    border-radius: 0.85rem;
    background: color-mix(in oklab, var(--color-gray-500) 14%, transparent);
}
.ipd-seg button {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.4rem 0.7rem;
    border-radius: 0.65rem;
    font-size: 0.78rem;
    font-weight: 700;
    color: var(--color-gray-500);
    transition: all 0.18s ease;
}
.ipd-seg button.is-active {
    background: var(--color-white);
    color: var(--color-primary-text);
    box-shadow: 0 4px 10px -6px rgba(15, 23, 42, 0.4);
}

.ipd-card {
    position: relative;
    overflow: hidden;
    border-radius: 1.25rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 18px 40px -32px rgba(15, 23, 42, 0.5);
    transition:
        transform 0.25s ease,
        box-shadow 0.25s ease,
        border-color 0.25s ease;
}
.ipd-card::before {
    content: "";
    position: absolute;
    inset: 0 0 auto 0;
    height: 3px;
    background: linear-gradient(
        90deg,
        var(--ipd-c),
        color-mix(in oklab, var(--ipd-c) 40%, #6366f1)
    );
}
.ipd-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 26px 48px -26px
        color-mix(in oklab, var(--ipd-c) 45%, rgba(15, 23, 42, 0.5));
    border-color: color-mix(
        in oklab,
        var(--ipd-c) 35%,
        var(--color-border-color)
    );
}
.ipd-card.is-selected {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 2px
        color-mix(in oklab, var(--color-primary) 40%, transparent);
}
.ipd-ava {
    width: 3rem;
    height: 3rem;
    border-radius: 0.85rem;
    display: grid;
    place-items: center;
    color: #fff;
    font-weight: 800;
    font-size: 0.95rem;
    background: linear-gradient(
        135deg,
        var(--ipd-c),
        color-mix(in oklab, var(--ipd-c) 55%, #6366f1)
    );
}
.ipd-ava-ring {
    padding: 2px;
    border-radius: 1rem;
    background: linear-gradient(
        135deg,
        var(--ipd-c),
        color-mix(in oklab, var(--ipd-c) 40%, #6366f1)
    );
    flex-shrink: 0;
}

.ipd-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.15rem 0.55rem;
    border-radius: 9999px;
    font-size: 0.64rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    white-space: nowrap;
}
.ipd-badge.stable {
    color: #059669;
    background: rgba(16, 185, 129, 0.15);
}
.ipd-badge.recovering {
    color: #0284c7;
    background: rgba(14, 165, 233, 0.15);
}
.ipd-badge.serious {
    color: #d97706;
    background: rgba(245, 158, 11, 0.15);
}
.ipd-badge.critical {
    color: #e11d48;
    background: rgba(244, 63, 94, 0.15);
}
.ipd-tag {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.1rem 0.45rem;
    border-radius: 0.5rem;
    font-size: 0.62rem;
    font-weight: 700;
    background: color-mix(in oklab, var(--ipd-c) 14%, transparent);
    color: var(--ipd-c);
}
.ipd-los {
    display: inline-grid;
    place-items: center;
    min-width: 2rem;
    padding: 0.1rem 0.4rem;
    border-radius: 0.5rem;
    font-size: 0.7rem;
    font-weight: 800;
    color: var(--color-primary-text);
    background: color-mix(in oklab, var(--color-primary) 12%, transparent);
}
.ipd-mini {
    display: grid;
    place-items: center;
    width: 2rem;
    height: 2rem;
    border-radius: 0.6rem;
    color: var(--color-gray-500);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.16s ease;
}
.ipd-mini:hover {
    border-color: var(--ipd-c);
    color: var(--ipd-c);
    transform: translateY(-1px);
}
.ipd-kv {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    font-size: 0.72rem;
    color: var(--color-gray-500);
    min-width: 0;
}
.ipd-kv b {
    color: var(--color-gray-900);
    font-weight: 700;
}

.ipd-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0;
}
.ipd-table thead th {
    text-align: left;
    font-size: 0.66rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--color-gray-400, #94a3b8);
    padding: 0.75rem 1rem;
    border-bottom: 1px solid var(--color-border-color);
    white-space: nowrap;
    background: color-mix(in oklab, var(--color-gray-500) 5%, transparent);
}
.ipd-table tbody td {
    padding: 0.7rem 1rem;
    border-bottom: 1px solid var(--color-border-color);
    font-size: 0.82rem;
    color: var(--color-gray-900);
    vertical-align: middle;
    white-space: nowrap;
}
.ipd-table tbody tr {
    transition: background 0.15s ease;
}
.ipd-table tbody tr:hover {
    background: color-mix(in oklab, var(--color-primary) 5%, transparent);
}
.ipd-table tbody tr.is-selected {
    background: color-mix(in oklab, var(--color-primary) 9%, transparent);
}
.ipd-check {
    width: 1.05rem;
    height: 1.05rem;
    border-radius: 0.35rem;
    accent-color: var(--color-primary);
    cursor: pointer;
}

.ipd-menu {
    position: absolute;
    z-index: 1100;
    min-width: 15rem;
    max-height: 26rem;
    overflow-y: auto;
    padding: 0.4rem;
    border-radius: 1rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 30px 60px -24px rgba(2, 12, 40, 0.5);
    animation: ipd-pop 0.16s ease;
}
@keyframes ipd-pop {
    from {
        opacity: 0;
        transform: translateY(-6px) scale(0.97);
    }
}
.ipd-menu button,
.ipd-menu a {
    display: flex;
    align-items: center;
    gap: 0.55rem;
    width: 100%;
    padding: 0.45rem 0.55rem;
    border-radius: 0.55rem;
    font-size: 0.8rem;
    font-weight: 600;
    color: var(--color-gray-900);
    text-align: left;
    transition:
        background 0.14s ease,
        color 0.14s ease;
}
.ipd-menu button:hover,
.ipd-menu a:hover {
    background: color-mix(in oklab, var(--color-primary) 8%, transparent);
    color: var(--color-primary-text);
}
.ipd-menu .danger {
    color: #e11d48;
}
.ipd-menu .danger:hover {
    background: rgba(244, 63, 94, 0.1);
}
.ipd-menu-sep {
    height: 1px;
    margin: 0.3rem 0.2rem;
    background: var(--color-border-color);
}
.ipd-menu-lbl {
    padding: 0.4rem 0.55rem 0.15rem;
    font-size: 0.58rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    color: var(--color-gray-400, #94a3b8);
}

.ipd-drawer {
    position: fixed;
    inset: 0;
    z-index: 1200;
    visibility: hidden;
}
.ipd-drawer.open {
    visibility: visible;
}
.ipd-drawer-back {
    position: absolute;
    inset: 0;
    background: rgba(8, 12, 30, 0.5);
    opacity: 0;
    transition: opacity 0.3s ease;
}
.ipd-drawer.open .ipd-drawer-back {
    opacity: 1;
}
.ipd-drawer-panel {
    position: absolute;
    top: 0;
    right: 0;
    height: 100%;
    width: min(490px, 94vw);
    background: var(--color-white);
    box-shadow: -30px 0 60px -30px rgba(2, 12, 40, 0.55);
    transform: translateX(100%);
    transition: transform 0.35s cubic-bezier(0.16, 1, 0.3, 1);
    display: flex;
    flex-direction: column;
}
.ipd-drawer.open .ipd-drawer-panel {
    transform: translateX(0);
}
.ipd-drawer-panel.left {
    right: auto;
    left: 0;
    transform: translateX(-100%);
    box-shadow: 30px 0 60px -30px rgba(2, 12, 40, 0.55);
}
.ipd-drawer.open .ipd-drawer-panel.left {
    transform: translateX(0);
}
.ipd-drawer-hero {
    position: relative;
    padding: 1.5rem;
    color: #fff;
    background:
        radial-gradient(
            120% 130% at 100% 0%,
            rgba(244, 63, 94, 0.6),
            transparent 55%
        ),
        linear-gradient(135deg, #4f46e5, #0f172a);
}

.ipd-modal {
    position: fixed;
    inset: 0;
    z-index: 1300;
    display: none;
    align-items: center;
    justify-content: center;
    padding: 1rem;
}
.ipd-modal.open {
    display: flex;
}
.ipd-modal-back {
    position: absolute;
    inset: 0;
    background: rgba(8, 12, 30, 0.5);
    -webkit-backdrop-filter: blur(3px);
    backdrop-filter: blur(3px);
    animation: ipd-fadein 0.2s ease;
}
@keyframes ipd-fadein {
    from {
        opacity: 0;
    }
}
.ipd-modal-panel {
    position: relative;
    width: 100%;
    max-width: 36rem;
    max-height: 90vh;
    overflow-y: auto;
    border-radius: 1.25rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 40px 80px -30px rgba(2, 12, 40, 0.6);
    animation: ipd-modin 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes ipd-modin {
    from {
        opacity: 0;
        transform: translateY(16px) scale(0.97);
    }
}
.ipd-doc-ico {
    display: grid;
    place-items: center;
    width: 2.75rem;
    height: 2.75rem;
    border-radius: 0.8rem;
    color: var(--ipd-c);
    font-size: 1.15rem;
    background: color-mix(in oklab, var(--ipd-c) 14%, transparent);
}

.ipd-bulk {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 0.55rem;
    padding: 0.7rem 0.9rem;
    border-radius: 1.25rem;
    background: color-mix(in oklab, var(--color-white) 85%, transparent);
    -webkit-backdrop-filter: blur(16px);
    backdrop-filter: blur(16px);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 12px 28px -18px rgba(15, 23, 42, 0.45);
    animation: ipd-bulk-in 0.25s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes ipd-bulk-in {
    from {
        opacity: 0;
        transform: translateY(-8px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}
.ipd-bulk-btn {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.4rem 0.7rem;
    border-radius: 0.7rem;
    font-size: 0.76rem;
    font-weight: 700;
    color: var(--color-gray-700, #374151);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.15s ease;
    white-space: nowrap;
}
.dark .ipd-bulk-btn {
    color: var(--color-gray-900);
}
.ipd-bulk-btn:hover {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.ipd-bulk-btn.danger {
    color: #e11d48;
}
.ipd-bulk-btn.danger:hover {
    border-color: #e11d48;
    background: rgba(244, 63, 94, 0.08);
}

.ipd-pg {
    display: grid;
    place-items: center;
    min-width: 2.1rem;
    height: 2.1rem;
    padding: 0 0.5rem;
    border-radius: 0.6rem;
    font-size: 0.8rem;
    font-weight: 700;
    color: var(--color-gray-600, #475569);
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition: all 0.15s ease;
    cursor: pointer;
}
.ipd-pg:hover:not(:disabled) {
    border-color: var(--color-primary);
    color: var(--color-primary-text);
}
.ipd-pg.is-active {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    border-color: transparent;
}
.ipd-pg:disabled {
    opacity: 0.4;
    cursor: not-allowed;
}

.ipd-wf {
    display: flex;
    align-items: center;
    gap: 0.25rem;
    overflow-x: auto;
    scrollbar-width: none;
}
.ipd-wf::-webkit-scrollbar {
    display: none;
}
.ipd-wf-step {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.4rem;
    min-width: 4.75rem;
    text-align: center;
}
.ipd-wf-node {
    display: grid;
    place-items: center;
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 9999px;
    font-size: 0.85rem;
    color: var(--color-gray-500);
    background: color-mix(in oklab, var(--color-gray-500) 14%, transparent);
}
.ipd-wf-step.done .ipd-wf-node {
    background: linear-gradient(135deg, #f43f5e, #e11d48);
    color: #fff;
}
.ipd-wf-step.active .ipd-wf-node {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    box-shadow: 0 10px 20px -8px var(--color-primary);
}
.ipd-wf-line {
    flex: 1 1 0.6rem;
    min-width: 0.6rem;
    height: 2px;
    border-radius: 2px;
    background: var(--color-border-color);
}
.ipd-wf-line.done {
    background: linear-gradient(90deg, #f43f5e, #e11d48);
}

.ipd-tl {
    position: relative;
    padding-left: 1.75rem;
}
.ipd-tl::before {
    content: "";
    position: absolute;
    left: 0.72rem;
    top: 0.35rem;
    bottom: 0.35rem;
    width: 2px;
    background: linear-gradient(
        180deg,
        var(--ipd-c, var(--color-primary)),
        color-mix(in oklab, var(--ipd-c, var(--color-primary)) 20%, transparent)
    );
}
.ipd-tl-item {
    position: relative;
    padding-bottom: 1.1rem;
}
.ipd-tl-item:last-child {
    padding-bottom: 0;
}
.ipd-tl-node {
    position: absolute;
    left: -1.75rem;
    top: 0.05rem;
    display: grid;
    place-items: center;
    width: 1.5rem;
    height: 1.5rem;
    border-radius: 9999px;
    color: #fff;
    font-size: 0.62rem;
    background: linear-gradient(
        135deg,
        var(--ipd-c, var(--color-primary)),
        color-mix(in oklab, var(--ipd-c, var(--color-primary)) 55%, #6366f1)
    );
    box-shadow: 0 0 0 3px
        color-mix(in oklab, var(--ipd-c, var(--color-primary)) 16%, transparent);
}

.ipd-bar {
    height: 0.5rem;
    border-radius: 9999px;
    background: color-mix(in oklab, var(--ipd-c) 14%, transparent);
    overflow: hidden;
}
.ipd-bar > i {
    display: block;
    height: 100%;
    border-radius: 9999px;
    background: linear-gradient(
        90deg,
        var(--ipd-c),
        color-mix(in oklab, var(--ipd-c) 55%, #6366f1)
    );
}

/* Bed map */
.ipd-bedmap {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(3.1rem, 1fr));
    gap: 0.5rem;
}
.ipd-bed {
    position: relative;
    aspect-ratio: 1;
    border-radius: 0.7rem;
    display: grid;
    place-items: center;
    font-size: 0.62rem;
    font-weight: 800;
    cursor: pointer;
    border: 1.5px solid transparent;
    transition:
        transform 0.15s ease,
        box-shadow 0.15s ease;
}
.ipd-bed:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 16px -8px rgba(15, 23, 42, 0.4);
}
.ipd-bed.occ {
    background: color-mix(in oklab, var(--color-primary) 16%, transparent);
    color: var(--color-primary-text);
    border-color: color-mix(in oklab, var(--color-primary) 30%, transparent);
}
.ipd-bed.free {
    background: color-mix(in oklab, #10b981 14%, transparent);
    color: #059669;
    border-color: color-mix(in oklab, #10b981 30%, transparent);
}
.ipd-bed.icu {
    background: color-mix(in oklab, #f43f5e 16%, transparent);
    color: #e11d48;
    border-color: color-mix(in oklab, #f43f5e 30%, transparent);
}
.ipd-bed.iso {
    background: color-mix(in oklab, #f59e0b 16%, transparent);
    color: #d97706;
    border-color: color-mix(in oklab, #f59e0b 30%, transparent);
}
.ipd-bed.res {
    background: color-mix(in oklab, #8b5cf6 16%, transparent);
    color: #7c3aed;
    border-color: color-mix(in oklab, #8b5cf6 30%, transparent);
}
.ipd-legend {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    font-size: 0.66rem;
    font-weight: 700;
    color: var(--color-gray-500);
}
.ipd-legend i {
    width: 0.7rem;
    height: 0.7rem;
    border-radius: 0.25rem;
    display: inline-block;
}

/* monitoring / staff cards */
.ipd-mon {
    position: relative;
    overflow: hidden;
    border-radius: 1rem;
    padding: 0.9rem;
    border: 1px solid var(--color-border-color);
    background: var(--color-white);
    transition:
        transform 0.2s ease,
        border-color 0.2s ease;
}
.ipd-mon:hover {
    transform: translateY(-3px);
    border-color: color-mix(
        in oklab,
        var(--ipd-c) 35%,
        var(--color-border-color)
    );
}
.ipd-mon-ico {
    display: grid;
    place-items: center;
    width: 2.3rem;
    height: 2.3rem;
    border-radius: 0.7rem;
    font-size: 1rem;
    color: var(--ipd-c);
    background: color-mix(in oklab, var(--ipd-c) 14%, transparent);
}
.ipd-avail {
    display: inline-flex;
    align-items: center;
    gap: 0.3rem;
    padding: 0.12rem 0.5rem;
    border-radius: 9999px;
    font-size: 0.6rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.03em;
}
.ipd-avail.on {
    color: #059669;
    background: rgba(16, 185, 129, 0.15);
}
.ipd-avail.busy {
    color: #d97706;
    background: rgba(245, 158, 11, 0.15);
}
.ipd-avail.off {
    color: #64748b;
    background: rgba(100, 116, 139, 0.15);
}

.ipd-in {
    width: 100%;
    padding: 0.65rem 0.8rem;
    border-radius: 0.7rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.85rem;
    font-weight: 600;
    outline: none;
    transition:
        border-color 0.16s ease,
        box-shadow 0.16s ease;
}
.ipd-in:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 4px
        color-mix(in oklab, var(--color-primary) 14%, transparent);
}
.ipd-lbl {
    display: block;
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--color-gray-500);
    margin-bottom: 0.3rem;
}
.ipd-recent {
    display: flex;
    align-items: center;
    gap: 0.7rem;
    padding: 0.6rem;
    border-radius: 0.8rem;
    transition: background 0.15s ease;
}
.ipd-recent:hover {
    background: color-mix(in oklab, var(--color-primary) 6%, transparent);
}

.ipd-c-indigo {
    --ipd-c: #6366f1;
}
.ipd-c-sky {
    --ipd-c: #0ea5e9;
}
.ipd-c-rose {
    --ipd-c: #f43f5e;
}
.ipd-c-amber {
    --ipd-c: #f59e0b;
}
.ipd-c-emerald {
    --ipd-c: #10b981;
}
.ipd-c-violet {
    --ipd-c: #8b5cf6;
}
.ipd-c-teal {
    --ipd-c: #14b8a6;
}
.ipd-c-primary {
    --ipd-c: var(--color-primary);
}

.ipd-sk {
    position: relative;
    overflow: hidden;
    background: color-mix(in oklab, var(--color-gray-500) 12%, transparent);
    border-radius: 0.75rem;
}
.ipd-sk::after {
    content: "";
    position: absolute;
    inset: 0;
    transform: translateX(-100%);
    background: linear-gradient(
        90deg,
        transparent,
        color-mix(in oklab, var(--color-white) 55%, transparent),
        transparent
    );
    animation: ipd-shimmer 1.4s infinite;
}
.dark .ipd-sk::after {
    background: linear-gradient(
        90deg,
        transparent,
        rgba(255, 255, 255, 0.06),
        transparent
    );
}
@keyframes ipd-shimmer {
    100% {
        transform: translateX(100%);
    }
}

.ipd-toast {
    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    z-index: 2000;
    display: flex;
    align-items: center;
    gap: 0.6rem;
    padding: 0.8rem 1.1rem;
    border-radius: 0.9rem;
    font-size: 0.85rem;
    font-weight: 700;
    color: #fff;
    box-shadow: 0 20px 45px -18px rgba(0, 0, 0, 0.5);
    animation: ipd-toastin 0.25s ease;
}
@keyframes ipd-toastin {
    from {
        opacity: 0;
        transform: translateY(12px);
    }
}
.ipd-toast.success {
    background: linear-gradient(135deg, #f43f5e, #e11d48);
}
.ipd-toast.info {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
}
.ipd-toast.error {
    background: linear-gradient(135deg, #f43f5e, #e11d48);
}

@media (prefers-reduced-motion: reduce) {
    .ipd-btn,
    .ipd-stat,
    .ipd-card,
    .ipd-mon,
    .ipd-bed,
    .ipd-ring .bar,
    .ipd-dot,
    .ipd-sk::after,
    .ipd-icobtn,
    .ipd-mini,
    .ipd-drawer-panel,
    .ipd-bulk {
        transition: none;
        animation: none;
    }
    .ipd-btn:hover,
    .ipd-stat:hover,
    .ipd-card:hover,
    .ipd-mon:hover,
    .ipd-bed:hover,
    .ipd-icobtn:hover,
    .ipd-mini:hover {
        transform: none;
    }
}
@media print {
    .sidebar,
    header.navbar-header,
    .ipd-print-hide {
        display: none !important;
    }
}

/* =====================================================================
   FILE MANAGER  ·  file-manager.html (page-exclusive)
   Namespaced `fm-` component system. Top-level (unlayered) like the
   other page-exclusive blocks, so it wins over the components layer.
   Tone classes set --fm-c and inherit down to unclassed children.
   ===================================================================== */

/* ---- Hero ------------------------------------------------------------ */
.fm-hero {
    position: relative;
    overflow: hidden;
    border-radius: 1.5rem;
    padding: 1.75rem;
    color: #fff;
    background:
        radial-gradient(
            120% 140% at 0% 0%,
            rgba(99, 102, 241, 0.5),
            transparent 55%
        ),
        radial-gradient(
            120% 160% at 100% 0%,
            rgba(14, 165, 233, 0.5),
            transparent 50%
        ),
        linear-gradient(135deg, #0f172a, #1e1b4b 60%, #0b1220);
    box-shadow: 0 30px 60px -30px rgba(15, 23, 42, 0.7);
}
.fm-hero::before {
    content: "";
    position: absolute;
    inset: 0;
    background-image: radial-gradient(
        rgba(255, 255, 255, 0.08) 1px,
        transparent 1px
    );
    background-size: 22px 22px;
    -webkit-mask-image: linear-gradient(180deg, #000, transparent 70%);
    mask-image: linear-gradient(180deg, #000, transparent 70%);
    pointer-events: none;
}
.fm-hero > * {
    position: relative;
    z-index: 1;
}
@media (min-width: 1024px) {
    .fm-hero {
        padding: 2.25rem 2.5rem;
    }
}

.fm-hbadge {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.35rem 0.8rem;
    border-radius: 9999px;
    font-size: 0.72rem;
    font-weight: 800;
    background: rgba(255, 255, 255, 0.14);
    border: 1px solid rgba(255, 255, 255, 0.22);
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
}
.fm-hbadge-emerald {
    background: rgba(16, 185, 129, 0.18);
    border-color: rgba(16, 185, 129, 0.4);
}
.fm-hbadge-amber {
    background: rgba(245, 158, 11, 0.18);
    border-color: rgba(245, 158, 11, 0.4);
}
.fm-dot {
    width: 0.45rem;
    height: 0.45rem;
    border-radius: 9999px;
    background: #34d399;
    box-shadow: 0 0 0 4px rgba(52, 211, 153, 0.25);
    animation: fm-pulse 2s ease-in-out infinite;
}
@keyframes fm-pulse {
    0%,
    100% {
        opacity: 1;
    }
    50% {
        opacity: 0.4;
    }
}
.fm-hmeta {
    display: inline-flex;
    align-items: center;
    gap: 0.45rem;
    padding: 0.45rem 0.8rem;
    border-radius: 0.8rem;
    background: rgba(255, 255, 255, 0.1);
    border: 1px solid rgba(255, 255, 255, 0.16);
    font-size: 0.75rem;
    font-weight: 700;
}

/* ---- Buttons ----------------------------------------------------------- */
.fm-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 0.45rem;
    padding: 0.7rem 1rem;
    border-radius: 0.85rem;
    font-size: 0.82rem;
    font-weight: 700;
    cursor: pointer;
    border: 1px solid transparent;
    white-space: nowrap;
    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease,
        background 0.2s ease,
        color 0.2s ease,
        border-color 0.2s ease;
}
.fm-btn:hover {
    transform: translateY(-2px);
}
.fm-btn-glass {
    background: rgba(255, 255, 255, 0.12);
    color: #fff;
    border-color: rgba(255, 255, 255, 0.24);
    -webkit-backdrop-filter: blur(8px);
    backdrop-filter: blur(8px);
}
.fm-btn-glass:hover {
    background: rgba(255, 255, 255, 0.2);
}
.fm-btn-primary {
    background: linear-gradient(135deg, var(--color-primary), #6366f1);
    color: #fff;
    box-shadow: 0 12px 24px -12px var(--color-primary);
}

/* ---- KPI stat cards + progress ring ------------------------------------ */
.fm-stat {
    position: relative;
    overflow: hidden;
    border-radius: 1.1rem;
    padding: 1.1rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 16px 34px -30px rgba(15, 23, 42, 0.5);
    transition:
        transform 0.22s ease,
        box-shadow 0.22s ease,
        border-color 0.22s ease;
}
.fm-stat::before {
    content: "";
    position: absolute;
    inset: 0 0 auto 0;
    height: 3px;
    background: linear-gradient(
        90deg,
        var(--fm-c, var(--color-primary)),
        color-mix(in oklab, var(--fm-c, var(--color-primary)) 40%, #6366f1)
    );
}
.fm-stat:hover {
    transform: translateY(-4px);
    box-shadow: 0 24px 44px -26px
        color-mix(
            in oklab,
            var(--fm-c, var(--color-primary)) 45%,
            rgba(15, 23, 42, 0.5)
        );
    border-color: color-mix(
        in oklab,
        var(--fm-c, var(--color-primary)) 35%,
        var(--color-border-color)
    );
}
.fm-stat-ico {
    display: grid;
    place-items: center;
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 0.8rem;
    color: #fff;
    font-size: 1.05rem;
    background: linear-gradient(
        135deg,
        var(--fm-c, var(--color-primary)),
        color-mix(in oklab, var(--fm-c, var(--color-primary)) 55%, #6366f1)
    );
    box-shadow: 0 10px 18px -10px var(--fm-c, var(--color-primary));
}
.fm-ring {
    --p: 0;
    width: 2.75rem;
    height: 2.75rem;
    transform: rotate(-90deg);
}
.fm-ring circle {
    fill: none;
    stroke-width: 4;
}
.fm-ring .trk {
    stroke: color-mix(
        in oklab,
        var(--fm-c, var(--color-primary)) 16%,
        transparent
    );
}
.fm-ring .bar {
    stroke: var(--fm-c, var(--color-primary));
    stroke-linecap: round;
    stroke-dasharray: 100 100;
    stroke-dashoffset: calc(100 - var(--p));
    transition: stroke-dashoffset 1s cubic-bezier(0.16, 1, 0.3, 1);
}
.fm-chip {
    display: inline-flex;
    align-items: center;
    padding: 0.15rem 0.55rem;
    border-radius: 9999px;
    font-size: 0.64rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    color: var(--color-gray-500);
    background: color-mix(in oklab, var(--color-gray-500) 14%, transparent);
}

/* ---- Two-column workspace layout --------------------------------------- */
.fm-layout {
    display: grid;
    grid-template-columns: 1fr;
    gap: 1.25rem;
    align-items: start;
}
@media (min-width: 1200px) {
    .fm-layout {
        grid-template-columns: 300px minmax(0, 1fr);
    }
}

/* ---- Surface panels (sidebar cards + main toolbar/grid wrap) ---------- */
.fm-surface {
    border-radius: 1.1rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 16px 34px -30px rgba(15, 23, 42, 0.5);
}
.fm-head {
    display: flex;
    align-items: center;
    gap: 0.75rem;
    padding: 1rem 1.15rem;
    border-bottom: 1px solid var(--color-border-color);
}
.fm-head .ico {
    display: grid;
    place-items: center;
    width: 2.3rem;
    height: 2.3rem;
    border-radius: 0.75rem;
    color: #fff;
    font-size: 0.95rem;
    background: linear-gradient(
        135deg,
        color-mix(in oklab, var(--fm-c, var(--color-primary)) 90%, #000),
        color-mix(in oklab, var(--fm-c, var(--color-primary)) 55%, #6366f1)
    );
    box-shadow: 0 10px 18px -12px var(--fm-c, var(--color-primary));
    flex-shrink: 0;
}
.fm-t {
    font-weight: 800;
    color: var(--color-gray-900);
    font-size: 0.92rem;
}

/* ---- Storage breakdown bar ---------------------------------------------- */
.fm-bar {
    display: flex;
    height: 0.6rem;
    width: 100%;
    border-radius: 9999px;
    overflow: hidden;
    background: color-mix(in oklab, var(--color-gray-500) 10%, transparent);
}

/* ---- Quick-access folders + recent files -------------------------------- */
.fm-fold {
    display: flex;
    align-items: center;
    gap: 0.7rem;
    padding: 0.6rem 0.65rem;
    border-radius: 0.85rem;
    cursor: pointer;
    transition: background 0.15s ease;
}
.fm-fold:hover {
    background: color-mix(
        in oklab,
        var(--fm-c, var(--color-primary)) 8%,
        transparent
    );
}
.fm-fold.is-active {
    background: color-mix(
        in oklab,
        var(--fm-c, var(--color-primary)) 12%,
        transparent
    );
}
.fm-fold-ico {
    display: grid;
    place-items: center;
    width: 2.4rem;
    height: 2.4rem;
    border-radius: 0.75rem;
    flex-shrink: 0;
    font-size: 1rem;
    color: var(--fm-c, var(--color-primary));
    background: color-mix(
        in oklab,
        var(--fm-c, var(--color-primary)) 14%,
        transparent
    );
}
.fm-recent {
    display: flex;
    align-items: center;
    gap: 0.65rem;
    padding: 0.55rem 0.6rem;
    border-radius: 0.75rem;
    cursor: pointer;
    transition: background 0.15s ease;
}
.fm-recent:hover {
    background: color-mix(in oklab, var(--color-gray-500) 8%, transparent);
}
.fm-doc-ico {
    display: grid;
    place-items: center;
    width: 2.5rem;
    height: 2.5rem;
    border-radius: 0.75rem;
    flex-shrink: 0;
    font-size: 1rem;
    color: var(--fm-c, var(--color-primary));
    background: color-mix(
        in oklab,
        var(--fm-c, var(--color-primary)) 14%,
        transparent
    );
}
.fm-fileico {
    display: grid;
    place-items: center;
    width: 2.1rem;
    height: 2.1rem;
    border-radius: 0.6rem;
    flex-shrink: 0;
    font-size: 0.85rem;
    color: var(--fm-c, var(--color-primary));
    background: color-mix(
        in oklab,
        var(--fm-c, var(--color-primary)) 14%,
        transparent
    );
}

/* ---- Toolbar: search / sort / grid-list segmented control -------------- */
.fm-search {
    position: relative;
    flex: 1 1 240px;
    min-width: 190px;
}
.fm-search input {
    width: 100%;
    padding: 0.6rem 0.9rem 0.6rem 2.5rem;
    border-radius: 0.85rem;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-900);
    font-size: 0.85rem;
    font-weight: 600;
    outline: none;
    transition:
        border-color 0.18s ease,
        box-shadow 0.18s ease;
}
.fm-search input:focus {
    border-color: var(--color-primary);
    box-shadow: 0 0 0 4px
        color-mix(in oklab, var(--color-primary) 14%, transparent);
}
.fm-search .ico {
    position: absolute;
    left: 0.85rem;
    top: 50%;
    transform: translateY(-50%);
    color: var(--color-gray-400);
    pointer-events: none;
}
.fm-tool {
    display: inline-flex;
    align-items: center;
    gap: 0.4rem;
    padding: 0.55rem 0.8rem;
    border-radius: 0.8rem;
    font-size: 0.8rem;
    font-weight: 700;
    cursor: pointer;
    border: 1.5px solid var(--color-border-color);
    background: var(--color-white);
    color: var(--color-gray-600);
    outline: none;
    transition:
        border-color 0.18s ease,
        color 0.18s ease;
}
.fm-tool:focus {
    border-color: var(--color-primary);
}
.fm-seg {
    display: inline-flex;
    padding: 0.25rem;
    border-radius: 0.85rem;
    background: color-mix(in oklab, var(--color-gray-500) 14%, transparent);
}
.fm-seg button {
    display: inline-flex;
    align-items: center;
    gap: 0.35rem;
    padding: 0.4rem 0.7rem;
    border-radius: 0.65rem;
    font-size: 0.78rem;
    font-weight: 700;
    color: var(--color-gray-500);
    transition: all 0.18s ease;
}
.fm-seg button.is-active {
    background: var(--color-white);
    color: var(--color-primary-text);
    box-shadow: 0 4px 10px -6px rgba(15, 23, 42, 0.4);
}

/* ---- Grid cards (folders + files) --------------------------------------- */
.fm-card {
    position: relative;
    overflow: hidden;
    border-radius: 1.1rem;
    background: var(--color-white);
    border: 1px solid var(--color-border-color);
    box-shadow: 0 16px 34px -30px rgba(15, 23, 42, 0.5);
    transition:
        transform 0.22s ease,
        box-shadow 0.22s ease,
        border-color 0.22s ease;
    cursor: pointer;
}
.fm-card:hover {
    transform: translateY(-4px);
    box-shadow: 0 24px 44px -26px
        color-mix(
            in oklab,
            var(--fm-c, var(--color-primary)) 45%,
            rgba(15, 23, 42, 0.5)
        );
    border-color: color-mix(
        in oklab,
        var(--fm-c, var(--color-primary)) 35%,
        var(--color-border-color)
    );
}
.fm-thumb {
    position: relative;
    display: grid;
    place-items: center;
    aspect-ratio: 1 / 1;
    font-size: 2.25rem;
    color: var(--fm-c, var(--color-primary));
    background: color-mix(
        in oklab,
        var(--fm-c, var(--color-primary)) 10%,
        transparent
    );
}
.fm-thumb i.big {
    font-size: 2.5rem;
}
.fm-mini {
    display: grid;
    place-items: center;
    width: 1.9rem;
    height: 1.9rem;
    border-radius: 0.55rem;
    color: #fff;
    background: rgba(15, 23, 42, 0.55);
    -webkit-backdrop-filter: blur(4px);
    backdrop-filter: blur(4px);
    cursor: pointer;
    transition: all 0.15s ease;
}
.fm-mini:hover {
    background: rgba(15, 23, 42, 0.75);
    transform: translateY(-1px);
}
.fm-mini.fm-del:hover {
    background: #e11d48;
}
.fm-badge {
    display: inline-flex;
    align-items: center;
    gap: 0.25rem;
    padding: 0.15rem 0.5rem;
    border-radius: 9999px;
    font-size: 0.6rem;
    font-weight: 800;
    color: #fff;
    background: color-mix(in oklab, var(--color-primary) 85%, #6366f1);
}

/* ---- List view table ----------------------------------------------------- */
.fm-table {
    width: 100%;
    border-collapse: separate;
    border-spacing: 0;
}
.fm-table thead th {
    text-align: left;
    font-size: 0.66rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--color-gray-400);
    padding: 0.75rem 1rem;
    border-bottom: 1px solid var(--color-border-color);
    white-space: nowrap;
    background: color-mix(in oklab, var(--color-gray-500) 5%, transparent);
}
.fm-table tbody td {
    padding: 0.7rem 1rem;
    border-bottom: 1px solid var(--color-border-color);
    font-size: 0.82rem;
    color: var(--color-gray-900);
    vertical-align: middle;
}
.fm-table tbody tr {
    transition: background 0.15s ease;
}
.fm-table tbody tr:hover {
    background: color-mix(in oklab, var(--color-primary) 5%, transparent);
}
.fm-table tbody tr:last-child td {
    border-bottom: 0;
}

/* ---- Upload dropzone ------------------------------------------------------ */
.fm-drop {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    text-align: center;
    padding: 2rem 1.25rem;
    border-radius: 1rem;
    border: 1.5px dashed var(--color-border-color);
    background: color-mix(in oklab, var(--color-gray-500) 4%, transparent);
    transition:
        border-color 0.18s ease,
        background 0.18s ease;
}
.fm-drop.is-dragover {
    border-color: var(--color-primary);
    background: color-mix(in oklab, var(--color-primary) 6%, transparent);
}

/* ---- Tone accents: set --fm-c, inherited by unclassed children --------- */
.fm-c-primary {
    --fm-c: var(--color-primary);
}
.fm-c-sky {
    --fm-c: #0ea5e9;
}
.fm-c-amber {
    --fm-c: #f59e0b;
}
.fm-c-emerald {
    --fm-c: #10b981;
}
.fm-c-violet {
    --fm-c: #8b5cf6;
}
.fm-c-rose {
    --fm-c: #f43f5e;
}
.fm-c-slate {
    --fm-c: #64748b;
}

@media (prefers-reduced-motion: reduce) {
    .fm-btn,
    .fm-stat,
    .fm-card,
    .fm-fold,
    .fm-mini,
    .fm-ring .bar,
    .fm-dot {
        transition: none;
        animation: none;
    }
    .fm-btn:hover,
    .fm-stat:hover,
    .fm-card:hover,
    .fm-mini:hover {
        transform: none;
    }
}


/* =====================================================================
   DARK MODE CONTRAST FIXES
   Added after rendering every page in dark mode and measuring text
   contrast (WCAG) against the real background. Grouped by root cause.
   ===================================================================== */

/* 1. Default text colour. body never set one, so any text with no colour
      class (table cells, plain labels…) fell back to the browser default,
      black, which is unreadable on the dark surfaces. */
.dark body {
    color: var(--color-gray-900);
}

/* 2. Brand blue used as TEXT is too dim on dark surfaces. The token is
      identical to --color-primary in light mode and lighter in dark (see
      .dark{} above). Backgrounds/borders keep using --color-primary. */
.dark .text-primary:not([class*="dark:text-"]),
.dark .text-\[var\(--color-primary\)\]:not([class*="dark:text-"]),
.dark .\[color\:var\(--color-primary\)\]:not([class*="dark:text-"]),
.dark .hover\:text-primary:hover:not([class*="dark:text-"]),
.dark .group:hover .group-hover\:text-primary:not([class*="dark:text-"]) {
    color: var(--color-primary-text);
}

/* 3. Hard-coded dark accent hues used for chip/label text (light-mode
      values) — lighter tones of the same hue on dark surfaces. Only exact
      class tokens are matched, and never where the author already set a
      dark:text-* colour. */
.dark :is([class~="[color:#15803d]"], [class~="text-[#15803d]"]):not([class*="dark:text-"]) { color: #8decb1; }
.dark :is([class~="[color:#dc2626]"], [class~="text-[#dc2626]"]):not([class*="dark:text-"]) { color: #ed8d8d; }
